  named("oskorek", ["osk\xF3rek", "\u043A\u0443\u0442\u0438\u043A\u0443\u043B\u0430"], ["mocna, nieprzepuszczalna os\u0142ona cia\u0142a nicienia, chroni\u0105ca paso\u017Cyta przed sokami trawiennymi", "\u043F\u0440\u043E\u0447\u043D\u0430\u044F \u043D\u0435\u043F\u0440\u043E\u043D\u0438\u0446\u0430\u0435\u043C\u0430\u044F \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0430 \u0442\u0435\u043B\u0430 \u043A\u0440\u0443\u0433\u043B\u043E\u0433\u043E \u0447\u0435\u0440\u0432\u044F, \u0437\u0430\u0449\u0438\u0449\u0430\u044E\u0449\u0430\u044F \u043F\u0430\u0440\u0430\u0437\u0438\u0442\u0430 \u043E\u0442 \u043F\u0438\u0449\u0435\u0432\u0430\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0441\u043E\u043A\u043E\u0432"], 2, ["kutykula"]),
  named("rozdzielnoplciowosc", ["rozdzielnop\u0142ciowo\u015B\u0107", "\u0440\u0430\u0437\u0434\u0435\u043B\u044C\u043D\u043E\u043F\u043E\u043B\u043E\u0441\u0442\u044C"], ["wyst\u0119powanie osobnych samc\xF3w i samic, r\xF3\u017Cni\u0105cych si\u0119 wygl\u0105dem", "\u043D\u0430\u043B\u0438\u0447\u0438\u0435 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0445 \u0441\u0430\u043C\u0446\u043E\u0432 \u0438 \u0441\u0430\u043C\u043E\u043A, \u043E\u0442\u043B\u0438\u0447\u0430\u044E\u0449\u0438\u0445\u0441\u044F \u0432\u043D\u0435\u0448\u043D\u0435"], 2, ["rozdzielnop\u0142ciowe"], ["\u0440\u0430\u0437\u0434\u0435\u043B\u044C\u043D\u043E\u043F\u043E\u043B\u044B\u0435"]),
  named("mycie-rak", ["mycie r\u0105k", "\u043C\u044B\u0442\u044C\u0451 \u0440\u0443\u043A"], ["najprostszy spos\xF3b zapobiegania zara\u017Ceniu glist\u0105 i owsikiem", "\u043F\u0440\u043E\u0441\u0442\u0435\u0439\u0448\u0438\u0439 \u0441\u043F\u043E\u0441\u043E\u0431 \u0438\u0437\u0431\u0435\u0436\u0430\u0442\u044C \u0437\u0430\u0440\u0430\u0436\u0435\u043D\u0438\u044F \u0430\u0441\u043A\u0430\u0440\u0438\u0434\u043E\u0439 \u0438 \u043E\u0441\u0442\u0440\u0438\u0446\u0435\u0439"], 1, ["mycie r\u0105k przed jedzeniem"], ["\u043C\u044B\u0442\u044C \u0440\u0443\u043A\u0438"]),
  named("nicienie-glebowe", ["nicienie glebowe", "\u043F\u043E\u0447\u0432\u0435\u043D\u043D\u044B\u0435 \u043D\u0435\u043C\u0430\u0442\u043E\u0434\u044B"], ["wolno \u017Cyj\u0105ce nicienie rozk\u0142adaj\u0105ce szcz\u0105tki organiczne w glebie", "\u0441\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u0436\u0438\u0432\u0443\u0449\u0438\u0435 \u043A\u0440\u0443\u0433\u043B\u044B\u0435 \u0447\u0435\u0440\u0432\u0438, \u0440\u0430\u0437\u043B\u0430\u0433\u0430\u044E\u0449\u0438\u0435 \u043E\u0440\u0433\u0430\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u043E\u0441\u0442\u0430\u0442\u043A\u0438 \u0432 \u043F\u043E\u0447\u0432\u0435"], 2, ["nicienie wolno \u017Cyj\u0105ce"], ["\u0441\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u0436\u0438\u0432\u0443\u0449\u0438\u0435 \u043D\u0435\u043C\u0430\u0442\u043E\u0434\u044B"])
