function namedTable(paragraph, rows) {
  return rows.map(([id, namePl, nameRu, rolePl, roleRu, tier4, aliasesPl = [], aliasesRu = []]) => ({
    id,
    paragraph,
    name: { pl: namePl, ru: nameRu },
    role: { pl: rolePl, ru: roleRu },
    aliases: { pl: [...aliasesPl], ru: [...aliasesRu] },
    tier: tier4
  }));
}
