  complication: { pl: "powik\u0142anie innych chor\xF3b", ru: "\u043E\u0441\u043B\u043E\u0436\u043D\u0435\u043D\u0438\u0435 \u0434\u0440\u0443\u0433\u0438\u0445 \u0431\u043E\u043B\u0435\u0437\u043D\u0435\u0439" },
  brain: { pl: "napadowe zaburzenie czynno\u015Bci m\xF3zgu", ru: "\u043F\u0430\u0440\u043E\u043A\u0441\u0438\u0437\u043C\u0430\u043B\u044C\u043D\u043E\u0435 \u0440\u0430\u0441\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u043E \u0440\u0430\u0431\u043E\u0442\u044B \u043C\u043E\u0437\u0433\u0430" },
  acquiredImmunodeficiency: { pl: "nabyty niedob\xF3r odporno\u015Bci", ru: "\u043F\u0440\u0438\u043E\u0431\u0440\u0435\u0442\u0451\u043D\u043D\u044B\u0439 \u0438\u043C\u043C\u0443\u043D\u043E\u0434\u0435\u0444\u0438\u0446\u0438\u0442" },
  congenitalImmunodeficiency: { pl: "wrodzony niedob\xF3r odporno\u015Bci", ru: "\u0432\u0440\u043E\u0436\u0434\u0451\u043D\u043D\u044B\u0439 \u0438\u043C\u043C\u0443\u043D\u043E\u0434\u0435\u0444\u0438\u0446\u0438\u0442" },
