var CLASSIFICATION = namedTable(P.organism.classification, [
  ["strunowce", "strunowce", "\u0445\u043E\u0440\u0434\u043E\u0432\u044B\u0435", "typ zwierz\u0105t, kt\xF3re w rozwoju maj\u0105 strun\u0119 grzbietow\u0105, grzbietow\u0105 cewk\u0119 nerwow\u0105 i szczeliny skrzelowe w gardzieli", "\u0442\u0438\u043F \u0436\u0438\u0432\u043E\u0442\u043D\u044B\u0445, \u0443 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0432 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0438 \u0435\u0441\u0442\u044C \u0445\u043E\u0440\u0434\u0430, \u0441\u043F\u0438\u043D\u043D\u0430\u044F \u043D\u0435\u0440\u0432\u043D\u0430\u044F \u0442\u0440\u0443\u0431\u043A\u0430 \u0438 \u0436\u0430\u0431\u0435\u0440\u043D\u044B\u0435 \u0449\u0435\u043B\u0438 \u0432 \u0433\u043B\u043E\u0442\u043A\u0435", 1, ["Chordata"], ["Chordata"]],
  ["kregowce", "kr\u0119gowce", "\u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u044B\u0435", "podtyp strunowc\xF3w, u kt\xF3rych strun\u0119 grzbietow\u0105 zast\u0119puje kr\u0119gos\u0142up, a m\xF3zgowie chroni czaszka", "\u043F\u043E\u0434\u0442\u0438\u043F \u0445\u043E\u0440\u0434\u043E\u0432\u044B\u0445, \u0443 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0445\u043E\u0440\u0434\u0443 \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442 \u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u0438\u043A, \u0430 \u0433\u043E\u043B\u043E\u0432\u043D\u043E\u0439 \u043C\u043E\u0437\u0433 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u0447\u0435\u0440\u0435\u043F", 1, ["Vertebrata"], ["Vertebrata"]],
  ["ssaki", "ssaki", "\u043C\u043B\u0435\u043A\u043E\u043F\u0438\u0442\u0430\u044E\u0449\u0438\u0435", "gromada sta\u0142ocieplnych kr\u0119gowc\xF3w z w\u0142osami i przepon\u0105, karmi\u0105cych m\u0142ode mlekiem", "\u043A\u043B\u0430\u0441\u0441 \u0442\u0435\u043F\u043B\u043E\u043A\u0440\u043E\u0432\u043D\u044B\u0445 \u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u044B\u0445 \u0441 \u0432\u043E\u043B\u043E\u0441\u044F\u043D\u044B\u043C \u043F\u043E\u043A\u0440\u043E\u0432\u043E\u043C \u0438 \u0434\u0438\u0430\u0444\u0440\u0430\u0433\u043C\u043E\u0439, \u0432\u044B\u043A\u0430\u0440\u043C\u043B\u0438\u0432\u0430\u044E\u0449\u0438\u0445 \u0434\u0435\u0442\u0451\u043D\u044B\u0448\u0435\u0439 \u043C\u043E\u043B\u043E\u043A\u043E\u043C", 1, ["Mammalia"], ["Mammalia"]],
  ["lozyskowce", "\u0142o\u017Cyskowce", "\u043F\u043B\u0430\u0446\u0435\u043D\u0442\u0430\u0440\u043D\u044B\u0435", "ssaki, kt\xF3rych m\u0142ode przed urodzeniem rozwijaj\u0105 si\u0119 w macicy, od\u017Cywiane przez matk\u0119 za po\u015Brednictwem specjalnego narz\u0105du", "\u043C\u043B\u0435\u043A\u043E\u043F\u0438\u0442\u0430\u044E\u0449\u0438\u0435, \u0447\u044C\u0438 \u0434\u0435\u0442\u0451\u043D\u044B\u0448\u0438 \u0434\u043E \u0440\u043E\u0436\u0434\u0435\u043D\u0438\u044F \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u0432 \u043C\u0430\u0442\u043A\u0435 \u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u043F\u0438\u0442\u0430\u043D\u0438\u0435 \u043E\u0442 \u043C\u0430\u0442\u0435\u0440\u0438 \u0447\u0435\u0440\u0435\u0437 \u043E\u0441\u043E\u0431\u044B\u0439 \u043E\u0440\u0433\u0430\u043D", 2, ["ssaki \u0142o\u017Cyskowe"], ["\u043F\u043B\u0430\u0446\u0435\u043D\u0442\u0430\u0440\u043D\u044B\u0435 \u043C\u043B\u0435\u043A\u043E\u043F\u0438\u0442\u0430\u044E\u0449\u0438\u0435"]],
  ["naczelne", "naczelne", "\u043F\u0440\u0438\u043C\u0430\u0442\u044B", "rz\u0105d ssak\xF3w z chwytnymi d\u0142o\u0144mi, przeciwstawnym kciukiem, paznokciami i widzeniem przestrzennym", "\u043E\u0442\u0440\u044F\u0434 \u043C\u043B\u0435\u043A\u043E\u043F\u0438\u0442\u0430\u044E\u0449\u0438\u0445 \u0441 \u0445\u0432\u0430\u0442\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u043C\u0438 \u043A\u0438\u0441\u0442\u044F\u043C\u0438, \u043F\u0440\u043E\u0442\u0438\u0432\u043E\u043F\u043E\u0441\u0442\u0430\u0432\u043B\u0435\u043D\u043D\u044B\u043C \u0431\u043E\u043B\u044C\u0448\u0438\u043C \u043F\u0430\u043B\u044C\u0446\u0435\u043C, \u043D\u043E\u0433\u0442\u044F\u043C\u0438 \u0438 \u043E\u0431\u044A\u0451\u043C\u043D\u044B\u043C \u0437\u0440\u0435\u043D\u0438\u0435\u043C", 1, ["Primates"], ["Primates"]],
  ["czlowiekowate", "cz\u0142owiekowate", "\u0433\u043E\u043C\u0438\u043D\u0438\u0434\u044B", "rodzina naczelnych obejmuj\u0105ca ludzi oraz orangutany, goryle i szympansy", "\u0441\u0435\u043C\u0435\u0439\u0441\u0442\u0432\u043E \u043F\u0440\u0438\u043C\u0430\u0442\u043E\u0432, \u043A \u043A\u043E\u0442\u043E\u0440\u043E\u043C\u0443 \u043E\u0442\u043D\u043E\u0441\u044F\u0442\u0441\u044F \u043B\u044E\u0434\u0438, \u0430 \u0442\u0430\u043A\u0436\u0435 \u043E\u0440\u0430\u043D\u0433\u0443\u0442\u0430\u043D\u044B, \u0433\u043E\u0440\u0438\u043B\u043B\u044B \u0438 \u0448\u0438\u043C\u043F\u0430\u043D\u0437\u0435", 2, ["Hominidae", "hominidy"], ["Hominidae"]],
  ["homo-sapiens", "cz\u0142owiek rozumny", "\u0447\u0435\u043B\u043E\u0432\u0435\u043A \u0440\u0430\u0437\u0443\u043C\u043D\u044B\u0439", "jedyny \u017Cyj\u0105cy gatunek z rodzaju Homo, o dwuno\u017Cnym chodzie i najwi\u0119kszym wzgl\u0119dem cia\u0142a m\xF3zgowiu", "\u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u043D\u044B\u043D\u0435 \u0436\u0438\u0432\u0443\u0449\u0438\u0439 \u0432\u0438\u0434 \u0440\u043E\u0434\u0430 Homo, \u0441 \u043F\u0440\u044F\u043C\u043E\u0445\u043E\u0436\u0434\u0435\u043D\u0438\u0435\u043C \u0438 \u0441\u0430\u043C\u044B\u043C \u043A\u0440\u0443\u043F\u043D\u044B\u043C \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u0442\u0435\u043B\u0430 \u043C\u043E\u0437\u0433\u043E\u043C", 1, ["Homo sapiens"], ["Homo sapiens"]],
  ["dwunoznosc", "dwuno\u017Cno\u015B\u0107", "\u043F\u0440\u044F\u043C\u043E\u0445\u043E\u0436\u0434\u0435\u043D\u0438\u0435", "poruszanie si\u0119 na dw\xF3ch ko\u0144czynach, z kt\xF3rym wi\u0105\u017C\u0105 si\u0119 esowato wygi\u0119ty kr\u0119gos\u0142up i wysklepiona stopa", "\u043F\u0435\u0440\u0435\u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u043D\u0430 \u0434\u0432\u0443\u0445 \u043A\u043E\u043D\u0435\u0447\u043D\u043E\u0441\u0442\u044F\u0445, \u0441 \u043A\u043E\u0442\u043E\u0440\u044B\u043C \u0441\u0432\u044F\u0437\u0430\u043D\u044B S-\u043E\u0431\u0440\u0430\u0437\u043D\u044B\u0439 \u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u0438\u043A \u0438 \u0441\u0432\u043E\u0434\u0447\u0430\u0442\u0430\u044F \u0441\u0442\u043E\u043F\u0430", 2, ["bipedalizm"], ["\u0434\u0432\u0443\u043D\u043E\u0433\u043E\u0441\u0442\u044C", "\u0431\u0438\u043F\u0435\u0434\u0430\u043B\u0438\u0437\u043C"]],
  ["kciuk", "przeciwstawny kciuk", "\u043F\u0440\u043E\u0442\u0438\u0432\u043E\u043F\u043E\u0441\u0442\u0430\u0432\u043B\u0435\u043D\u043D\u044B\u0439 \u0431\u043E\u043B\u044C\u0448\u043E\u0439 \u043F\u0430\u043B\u0435\u0446", "cecha r\u0119ki naczelnych umo\u017Cliwiaj\u0105ca precyzyjny chwyt i pos\u0142ugiwanie si\u0119 narz\u0119dziami", "\u043E\u0441\u043E\u0431\u0435\u043D\u043D\u043E\u0441\u0442\u044C \u043A\u0438\u0441\u0442\u0438 \u043F\u0440\u0438\u043C\u0430\u0442\u043E\u0432, \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u044E\u0449\u0430\u044F \u0442\u043E\u0447\u043D\u044B\u0439 \u0437\u0430\u0445\u0432\u0430\u0442 \u0438 \u0440\u0430\u0431\u043E\u0442\u0443 \u0441 \u043E\u0440\u0443\u0434\u0438\u044F\u043C\u0438", 2, ["kciuk przeciwstawny"], []],
  ["binominalne", "nazewnictwo binominalne", "\u0431\u0438\u043D\u043E\u043C\u0438\u043D\u0430\u043B\u044C\u043D\u0430\u044F \u043D\u043E\u043C\u0435\u043D\u043A\u043B\u0430\u0442\u0443\u0440\u0430", "dwucz\u0142onowa \u0142aci\u0144ska nazwa gatunku: nazwa rodzaju i epitet gatunkowy, np. Homo sapiens", "\u0434\u0432\u043E\u0439\u043D\u043E\u0435 \u043B\u0430\u0442\u0438\u043D\u0441\u043A\u043E\u0435 \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u0432\u0438\u0434\u0430: \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u0440\u043E\u0434\u0430 \u0438 \u0432\u0438\u0434\u043E\u0432\u043E\u0439 \u044D\u043F\u0438\u0442\u0435\u0442, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 Homo sapiens", 2, ["nomenklatura binominalna", "nazewnictwo dwuimienne"], ["\u0431\u0438\u043D\u0430\u0440\u043D\u0430\u044F \u043D\u043E\u043C\u0435\u043D\u043A\u043B\u0430\u0442\u0443\u0440\u0430"]]
]);
var ANIMAL_MOTION = namedTable(P.motion.animals, [
  ["hydroszkielet", "szkielet hydrostatyczny", "\u0433\u0438\u0434\u0440\u043E\u0441\u0442\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0441\u043A\u0435\u043B\u0435\u0442", "p\u0142yn wype\u0142niaj\u0105cy jam\u0119 cia\u0142a pod ci\u015Bnieniem, o kt\xF3ry opieraj\u0105 si\u0119 kurcz\u0105ce si\u0119 mi\u0119\u015Bnie, np. u d\u017Cd\u017Cownicy", "\u0436\u0438\u0434\u043A\u043E\u0441\u0442\u044C \u043F\u043E\u0434 \u0434\u0430\u0432\u043B\u0435\u043D\u0438\u0435\u043C \u0432 \u043F\u043E\u043B\u043E\u0441\u0442\u0438 \u0442\u0435\u043B\u0430, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u043E\u043F\u0438\u0440\u0430\u044E\u0442\u0441\u044F \u0441\u043E\u043A\u0440\u0430\u0449\u0430\u044E\u0449\u0438\u0435\u0441\u044F \u043C\u044B\u0448\u0446\u044B, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0443 \u0434\u043E\u0436\u0434\u0435\u0432\u043E\u0433\u043E \u0447\u0435\u0440\u0432\u044F", 2, ["hydroszkielet"], ["\u0433\u0438\u0434\u0440\u043E\u0441\u043A\u0435\u043B\u0435\u0442"]],
  ["egzoszkielet", "szkielet zewn\u0119trzny", "\u043D\u0430\u0440\u0443\u0436\u043D\u044B\u0439 \u0441\u043A\u0435\u043B\u0435\u0442", "chitynowy pancerz na powierzchni cia\u0142a stawonog\xF3w, do kt\xF3rego od wewn\u0105trz przyczepione s\u0105 mi\u0119\u015Bnie", "\u0445\u0438\u0442\u0438\u043D\u043E\u0432\u044B\u0439 \u043F\u0430\u043D\u0446\u0438\u0440\u044C \u043D\u0430 \u043F\u043E\u0432\u0435\u0440\u0445\u043D\u043E\u0441\u0442\u0438 \u0442\u0435\u043B\u0430 \u0447\u043B\u0435\u043D\u0438\u0441\u0442\u043E\u043D\u043E\u0433\u0438\u0445, \u043A \u043A\u043E\u0442\u043E\u0440\u043E\u043C\u0443 \u0438\u0437\u043D\u0443\u0442\u0440\u0438 \u043F\u0440\u0438\u043A\u0440\u0435\u043F\u043B\u0435\u043D\u044B \u043C\u044B\u0448\u0446\u044B", 1, ["egzoszkielet", "pancerz chitynowy"], ["\u044D\u043A\u0437\u043E\u0441\u043A\u0435\u043B\u0435\u0442"]],
  ["endoszkielet", "szkielet wewn\u0119trzny", "\u0432\u043D\u0443\u0442\u0440\u0435\u043D\u043D\u0438\u0439 \u0441\u043A\u0435\u043B\u0435\u0442", "rusztowanie z ko\u015Bci i chrz\u0105stek wewn\u0105trz cia\u0142a kr\u0119gowc\xF3w, rosn\u0105ce razem z organizmem", "\u043A\u0430\u0440\u043A\u0430\u0441 \u0438\u0437 \u043A\u043E\u0441\u0442\u0435\u0439 \u0438 \u0445\u0440\u044F\u0449\u0435\u0439 \u0432\u043D\u0443\u0442\u0440\u0438 \u0442\u0435\u043B\u0430 \u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u044B\u0445, \u0440\u0430\u0441\u0442\u0443\u0449\u0438\u0439 \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 \u043E\u0440\u0433\u0430\u043D\u0438\u0437\u043C\u043E\u043C", 1, ["endoszkielet"], ["\u044D\u043D\u0434\u043E\u0441\u043A\u0435\u043B\u0435\u0442"]],
  ["linienie", "linienie", "\u043B\u0438\u043D\u044C\u043A\u0430", "zrzucanie zbyt ciasnego osk\xF3rka, kt\xF3re umo\u017Cliwia stawonogom wzrost", "\u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u043D\u0438\u0435 \u0441\u0442\u0430\u0432\u0448\u0435\u0439 \u0442\u0435\u0441\u043D\u043E\u0439 \u043A\u0443\u0442\u0438\u043A\u0443\u043B\u044B, \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u044E\u0449\u0435\u0435 \u0447\u043B\u0435\u043D\u0438\u0441\u0442\u043E\u043D\u043E\u0433\u0438\u043C \u0440\u0430\u0441\u0442\u0438", 1, [], []],
  ["wor", "w\xF3r pow\u0142okowo-mi\u0119\u015Bniowy", "\u043A\u043E\u0436\u043D\u043E-\u043C\u0443\u0441\u043A\u0443\u043B\u044C\u043D\u044B\u0439 \u043C\u0435\u0448\u043E\u043A", "nab\u0142onek zro\u015Bni\u0119ty z warstwami mi\u0119\u015Bni okr\u0119\u017Cnych i pod\u0142u\u017Cnych, poruszaj\u0105cy cia\u0142em robak\xF3w", "\u044D\u043F\u0438\u0442\u0435\u043B\u0438\u0439, \u0441\u0440\u043E\u0441\u0448\u0438\u0439\u0441\u044F \u0441\u043E \u0441\u043B\u043E\u044F\u043C\u0438 \u043A\u043E\u043B\u044C\u0446\u0435\u0432\u044B\u0445 \u0438 \u043F\u0440\u043E\u0434\u043E\u043B\u044C\u043D\u044B\u0445 \u043C\u044B\u0448\u0446, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u0442\u0435\u043B\u043E \u0447\u0435\u0440\u0432\u0435\u0439", 2, [], []],
  ["pelzakowaty", "ruch pe\u0142zakowaty", "\u0430\u043C\u0435\u0431\u043E\u0438\u0434\u043D\u043E\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435", "przemieszczanie si\u0119 dzi\u0119ki nibyn\xF3\u017Ckom powstaj\u0105cym przez przelewanie si\u0119 cytoplazmy, np. u leukocyt\xF3w", "\u043F\u0435\u0440\u0435\u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0441 \u043F\u043E\u043C\u043E\u0449\u044C\u044E \u043B\u043E\u0436\u043D\u043E\u043D\u043E\u0436\u0435\u043A, \u0432\u043E\u0437\u043D\u0438\u043A\u0430\u044E\u0449\u0438\u0445 \u043F\u0440\u0438 \u043F\u0435\u0440\u0435\u0442\u0435\u043A\u0430\u043D\u0438\u0438 \u0446\u0438\u0442\u043E\u043F\u043B\u0430\u0437\u043C\u044B, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0443 \u043B\u0435\u0439\u043A\u043E\u0446\u0438\u0442\u043E\u0432", 2, ["ruch ameboidalny"], ["\u0430\u043C\u0451\u0431\u043E\u0438\u0434\u043D\u043E\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435"]],
  ["rzeskowy", "ruch rz\u0119skowy", "\u0440\u0435\u0441\u043D\u0438\u0447\u043D\u043E\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435", "przemieszczanie si\u0119 dzi\u0119ki zsynchronizowanemu biciu licznych rz\u0119sek, np. u wyp\u0142awka", "\u043F\u0435\u0440\u0435\u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0431\u043B\u0430\u0433\u043E\u0434\u0430\u0440\u044F \u0441\u043E\u0433\u043B\u0430\u0441\u043E\u0432\u0430\u043D\u043D\u043E\u043C\u0443 \u0431\u0438\u0435\u043D\u0438\u044E \u043C\u043D\u043E\u0433\u043E\u0447\u0438\u0441\u043B\u0435\u043D\u043D\u044B\u0445 \u0440\u0435\u0441\u043D\u0438\u0447\u0435\u043A, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0443 \u043F\u043B\u0430\u043D\u0430\u0440\u0438\u0438", 2, [], ["\u043C\u0435\u0440\u0446\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435"]],
  ["odrzutowy", "ruch odrzutowy", "\u0440\u0435\u0430\u043A\u0442\u0438\u0432\u043D\u043E\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435", "wyrzucanie wody z jamy p\u0142aszczowej przez lejek, stosowane przez g\u0142owonogi", "\u0432\u044B\u0442\u0430\u043B\u043A\u0438\u0432\u0430\u043D\u0438\u0435 \u0432\u043E\u0434\u044B \u0438\u0437 \u043C\u0430\u043D\u0442\u0438\u0439\u043D\u043E\u0439 \u043F\u043E\u043B\u043E\u0441\u0442\u0438 \u0447\u0435\u0440\u0435\u0437 \u0432\u043E\u0440\u043E\u043D\u043A\u0443, \u043A\u043E\u0442\u043E\u0440\u044B\u043C \u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442\u0441\u044F \u0433\u043E\u043B\u043E\u0432\u043E\u043D\u043E\u0433\u0438\u0435", 2, [], []],
  ["struna", "struna grzbietowa", "\u0445\u043E\u0440\u0434\u0430", "elastyczny pr\u0119t podporowy wzd\u0142u\u017C grzbietu lancetnika i zarodk\xF3w strunowc\xF3w", "\u0443\u043F\u0440\u0443\u0433\u0438\u0439 \u043E\u043F\u043E\u0440\u043D\u044B\u0439 \u0441\u0442\u0435\u0440\u0436\u0435\u043D\u044C \u0432\u0434\u043E\u043B\u044C \u0441\u043F\u0438\u043D\u044B \u043B\u0430\u043D\u0446\u0435\u0442\u043D\u0438\u043A\u0430 \u0438 \u0437\u0430\u0440\u043E\u0434\u044B\u0448\u0435\u0439 \u0445\u043E\u0440\u0434\u043E\u0432\u044B\u0445", 2, ["chorda"], ["\u0441\u043F\u0438\u043D\u043D\u0430\u044F \u0441\u0442\u0440\u0443\u043D\u0430"]]
]);
var ANIMAL_FEEDING = namedTable(P.digestion.animals, [
  ["roslinozercy", "ro\u015Blino\u017Cercy", "\u0440\u0430\u0441\u0442\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u044F\u0434\u043D\u044B\u0435", "zwierz\u0119ta zjadaj\u0105ce ro\u015Bliny, z d\u0142ugim jelitem, cz\u0119sto z mikroorganizmami rozk\u0142adaj\u0105cymi celuloz\u0119", "\u0436\u0438\u0432\u043E\u0442\u043D\u044B\u0435, \u043F\u043E\u0435\u0434\u0430\u044E\u0449\u0438\u0435 \u0440\u0430\u0441\u0442\u0435\u043D\u0438\u044F, \u0441 \u0434\u043B\u0438\u043D\u043D\u044B\u043C \u043A\u0438\u0448\u0435\u0447\u043D\u0438\u043A\u043E\u043C, \u0447\u0430\u0441\u0442\u043E \u0441 \u043C\u0438\u043A\u0440\u043E\u043E\u0440\u0433\u0430\u043D\u0438\u0437\u043C\u0430\u043C\u0438, \u0440\u0430\u0441\u0449\u0435\u043F\u043B\u044F\u044E\u0449\u0438\u043C\u0438 \u0446\u0435\u043B\u043B\u044E\u043B\u043E\u0437\u0443", 1, ["fitofagi"], ["\u0444\u0438\u0442\u043E\u0444\u0430\u0433\u0438"]],
  ["miesozercy", "mi\u0119so\u017Cercy", "\u043F\u043B\u043E\u0442\u043E\u044F\u0434\u043D\u044B\u0435", "zwierz\u0119ta zjadaj\u0105ce inne zwierz\u0119ta, z ostrymi k\u0142ami i stosunkowo kr\xF3tkim jelitem", "\u0436\u0438\u0432\u043E\u0442\u043D\u044B\u0435, \u043F\u043E\u0435\u0434\u0430\u044E\u0449\u0438\u0435 \u0434\u0440\u0443\u0433\u0438\u0445 \u0436\u0438\u0432\u043E\u0442\u043D\u044B\u0445, \u0441 \u043E\u0441\u0442\u0440\u044B\u043C\u0438 \u043A\u043B\u044B\u043A\u0430\u043C\u0438 \u0438 \u0441\u0440\u0430\u0432\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u043A\u043E\u0440\u043E\u0442\u043A\u0438\u043C \u043A\u0438\u0448\u0435\u0447\u043D\u0438\u043A\u043E\u043C", 1, [], ["\u0445\u0438\u0449\u043D\u0438\u043A\u0438"]],
  ["wszystkozercy", "wszystko\u017Cercy", "\u0432\u0441\u0435\u044F\u0434\u043D\u044B\u0435", "zwierz\u0119ta jedz\u0105ce pokarm ro\u015Blinny i zwierz\u0119cy, o uz\u0119bieniu z cechami po\u015Brednimi", "\u0436\u0438\u0432\u043E\u0442\u043D\u044B\u0435, \u043F\u0438\u0442\u0430\u044E\u0449\u0438\u0435\u0441\u044F \u0440\u0430\u0441\u0442\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0439 \u0438 \u0436\u0438\u0432\u043E\u0442\u043D\u043E\u0439 \u043F\u0438\u0449\u0435\u0439, \u0441 \u0437\u0443\u0431\u0430\u043C\u0438 \u043F\u0440\u043E\u043C\u0435\u0436\u0443\u0442\u043E\u0447\u043D\u043E\u0433\u043E \u0442\u0438\u043F\u0430", 1, [], []],
  ["filtratory", "filtratory", "\u0444\u0438\u043B\u044C\u0442\u0440\u0430\u0442\u043E\u0440\u044B", "zwierz\u0119ta odcedzaj\u0105ce drobne cz\u0105stki pokarmu z wody, np. ma\u0142\u017Ce i fiszbinowce", "\u0436\u0438\u0432\u043E\u0442\u043D\u044B\u0435, \u043E\u0442\u0446\u0435\u0436\u0438\u0432\u0430\u044E\u0449\u0438\u0435 \u043C\u0435\u043B\u043A\u0438\u0435 \u0447\u0430\u0441\u0442\u0438\u0446\u044B \u043F\u0438\u0449\u0438 \u0438\u0437 \u0432\u043E\u0434\u044B, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0434\u0432\u0443\u0441\u0442\u0432\u043E\u0440\u0447\u0430\u0442\u044B\u0435 \u043C\u043E\u043B\u043B\u044E\u0441\u043A\u0438 \u0438 \u0443\u0441\u0430\u0442\u044B\u0435 \u043A\u0438\u0442\u044B", 2, [], []],
  ["zoladek-przezuwaczy", "\u017Co\u0142\u0105dek wielokomorowy", "\u043C\u043D\u043E\u0433\u043E\u043A\u0430\u043C\u0435\u0440\u043D\u044B\u0439 \u0436\u0435\u043B\u0443\u0434\u043E\u043A", "\u017Co\u0142\u0105dek prze\u017Cuwaczy, w kt\xF3rego \u017Cwaczu mikroorganizmy rozk\u0142adaj\u0105 celuloz\u0119", "\u0436\u0435\u043B\u0443\u0434\u043E\u043A \u0436\u0432\u0430\u0447\u043D\u044B\u0445, \u0432 \u0440\u0443\u0431\u0446\u0435 \u043A\u043E\u0442\u043E\u0440\u043E\u0433\u043E \u043C\u0438\u043A\u0440\u043E\u043E\u0440\u0433\u0430\u043D\u0438\u0437\u043C\u044B \u0440\u0430\u0441\u0449\u0435\u043F\u043B\u044F\u044E\u0442 \u0446\u0435\u043B\u043B\u044E\u043B\u043E\u0437\u0443", 2, ["\u017Co\u0142\u0105dek prze\u017Cuwaczy"], ["\u0436\u0435\u043B\u0443\u0434\u043E\u043A \u0436\u0432\u0430\u0447\u043D\u044B\u0445"]],
  ["wole", "wole", "\u0437\u043E\u0431", "rozszerzenie prze\u0142yku ptak\xF3w, w kt\xF3rym pokarm jest gromadzony i rozmi\u0119kczany", "\u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043D\u0438\u0435 \u043F\u0438\u0449\u0435\u0432\u043E\u0434\u0430 \u043F\u0442\u0438\u0446, \u0433\u0434\u0435 \u043F\u0438\u0449\u0430 \u043D\u0430\u043A\u0430\u043F\u043B\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0438 \u0440\u0430\u0437\u043C\u044F\u0433\u0447\u0430\u0435\u0442\u0441\u044F", 2, [], []],
  ["zoladek-miesniowy", "\u017Co\u0142\u0105dek mi\u0119\u015Bniowy", "\u043C\u0443\u0441\u043A\u0443\u043B\u044C\u043D\u044B\u0439 \u0436\u0435\u043B\u0443\u0434\u043E\u043A", "cz\u0119\u015B\u0107 \u017Co\u0142\u0105dka ptak\xF3w, kt\xF3ra rozciera pokarm z pomoc\u0105 po\u0142kni\u0119tych kamyk\xF3w", "\u043E\u0442\u0434\u0435\u043B \u0436\u0435\u043B\u0443\u0434\u043A\u0430 \u043F\u0442\u0438\u0446, \u043F\u0435\u0440\u0435\u0442\u0438\u0440\u0430\u044E\u0449\u0438\u0439 \u043F\u0438\u0449\u0443 \u0441 \u043F\u043E\u043C\u043E\u0449\u044C\u044E \u043F\u0440\u043E\u0433\u043B\u043E\u0447\u0435\u043D\u043D\u044B\u0445 \u043A\u0430\u043C\u0435\u0448\u043A\u043E\u0432", 2, [], []],
  ["jama-chlonaco-trawiaca", "jama ch\u0142on\u0105co-trawi\u0105ca", "\u0433\u0430\u0441\u0442\u0440\u0430\u043B\u044C\u043D\u0430\u044F \u043F\u043E\u043B\u043E\u0441\u0442\u044C", "worek z jednym otworem, w kt\xF3rym trawi\u0105 pokarm parzyde\u0142kowce", "\u043C\u0435\u0448\u043E\u043A \u0441 \u043E\u0434\u043D\u0438\u043C \u043E\u0442\u0432\u0435\u0440\u0441\u0442\u0438\u0435\u043C, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u043F\u0435\u0440\u0435\u0432\u0430\u0440\u0438\u0432\u0430\u044E\u0442 \u043F\u0438\u0449\u0443 \u043A\u0438\u0448\u0435\u0447\u043D\u043E\u043F\u043E\u043B\u043E\u0441\u0442\u043D\u044B\u0435", 2, ["jama gastralna"], ["\u043A\u0438\u0448\u0435\u0447\u043D\u0430\u044F \u043F\u043E\u043B\u043E\u0441\u0442\u044C"]],
  ["trawienie-wewnatrzkomorkowe", "trawienie wewn\u0105trzkom\xF3rkowe", "\u0432\u043D\u0443\u0442\u0440\u0438\u043A\u043B\u0435\u0442\u043E\u0447\u043D\u043E\u0435 \u043F\u0438\u0449\u0435\u0432\u0430\u0440\u0435\u043D\u0438\u0435", "rozk\u0142adanie pokarmu w wodniczkach trawiennych wewn\u0105trz kom\xF3rek, np. u g\u0105bek", "\u0440\u0430\u0441\u0449\u0435\u043F\u043B\u0435\u043D\u0438\u0435 \u043F\u0438\u0449\u0438 \u0432 \u043F\u0438\u0449\u0435\u0432\u0430\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0432\u0430\u043A\u0443\u043E\u043B\u044F\u0445 \u0432\u043D\u0443\u0442\u0440\u0438 \u043A\u043B\u0435\u0442\u043E\u043A, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0443 \u0433\u0443\u0431\u043E\u043A", 2, [], []],
  ["heterodontyzm", "uz\u0119bienie zr\xF3\u017Cnicowane", "\u0434\u0438\u0444\u0444\u0435\u0440\u0435\u043D\u0446\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0435 \u0437\u0443\u0431\u044B", "z\u0119by r\xF3\u017Cnego kszta\u0142tu \u2014 siekacze, k\u0142y, przedtrzonowce i trzonowce \u2014 typowe dla ssak\xF3w", "\u0437\u0443\u0431\u044B \u0440\u0430\u0437\u043D\u043E\u0439 \u0444\u043E\u0440\u043C\u044B \u2014 \u0440\u0435\u0437\u0446\u044B, \u043A\u043B\u044B\u043A\u0438, \u043C\u0430\u043B\u044B\u0435 \u0438 \u0431\u043E\u043B\u044C\u0448\u0438\u0435 \u043A\u043E\u0440\u0435\u043D\u043D\u044B\u0435 \u2014 \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440\u043D\u044B\u0435 \u0434\u043B\u044F \u043C\u043B\u0435\u043A\u043E\u043F\u0438\u0442\u0430\u044E\u0449\u0438\u0445", 2, ["heterodontyzm", "uz\u0119bienie heterodontyczne"], ["\u0433\u0435\u0442\u0435\u0440\u043E\u0434\u043E\u043D\u0442\u043D\u0430\u044F \u0437\u0443\u0431\u043D\u0430\u044F \u0441\u0438\u0441\u0442\u0435\u043C\u0430", "\u0433\u0435\u0442\u0435\u0440\u043E\u0434\u043E\u043D\u0442\u0438\u0437\u043C"]]
]);
var ANIMAL_BREATHING = namedTable(P.respiration.animals, [
  ["skrzela", "skrzela", "\u0436\u0430\u0431\u0440\u044B", "cienko\u015Bcienne, silnie ukrwione wyrostki cia\u0142a s\u0142u\u017C\u0105ce do wymiany gazowej w wodzie", "\u0442\u043E\u043D\u043A\u043E\u0441\u0442\u0435\u043D\u043D\u044B\u0435, \u043E\u0431\u0438\u043B\u044C\u043D\u043E \u0441\u043D\u0430\u0431\u0436\u0451\u043D\u043D\u044B\u0435 \u043A\u0440\u043E\u0432\u044C\u044E \u0432\u044B\u0440\u043E\u0441\u0442\u044B \u0442\u0435\u043B\u0430 \u0434\u043B\u044F \u0433\u0430\u0437\u043E\u043E\u0431\u043C\u0435\u043D\u0430 \u0432 \u0432\u043E\u0434\u0435", 1, [], []],
  ["tchawki", "tchawki", "\u0442\u0440\u0430\u0445\u0435\u0438 \u043D\u0430\u0441\u0435\u043A\u043E\u043C\u044B\u0445", "system rurek doprowadzaj\u0105cych powietrze bezpo\u015Brednio do kom\xF3rek cia\u0142a owad\xF3w", "\u0441\u0438\u0441\u0442\u0435\u043C\u0430 \u0442\u0440\u0443\u0431\u043E\u0447\u0435\u043A, \u043F\u043E\u0434\u0432\u043E\u0434\u044F\u0449\u0438\u0445 \u0432\u043E\u0437\u0434\u0443\u0445 \u043F\u0440\u044F\u043C\u043E \u043A \u043A\u043B\u0435\u0442\u043A\u0430\u043C \u0442\u0435\u043B\u0430 \u043D\u0430\u0441\u0435\u043A\u043E\u043C\u044B\u0445", 1, [], ["\u0442\u0440\u0430\u0445\u0435\u0438", "\u0442\u0440\u0430\u0445\u0435\u0439\u043D\u0430\u044F \u0441\u0438\u0441\u0442\u0435\u043C\u0430"]],
  ["przetchlinki", "przetchlinki", "\u0434\u044B\u0445\u0430\u043B\u044C\u0446\u0430", "otwory na bokach cia\u0142a owad\xF3w, przez kt\xF3re powietrze wnika do tchawek", "\u043E\u0442\u0432\u0435\u0440\u0441\u0442\u0438\u044F \u043F\u043E \u0431\u043E\u043A\u0430\u043C \u0442\u0435\u043B\u0430 \u043D\u0430\u0441\u0435\u043A\u043E\u043C\u044B\u0445, \u0447\u0435\u0440\u0435\u0437 \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0432\u043E\u0437\u0434\u0443\u0445 \u043F\u043E\u043F\u0430\u0434\u0430\u0435\u0442 \u0432 \u0442\u0440\u0430\u0445\u0435\u0438", 1, [], ["\u0441\u0442\u0438\u0433\u043C\u044B"]],
  ["plucotchawki", "p\u0142ucotchawki", "\u043B\u0451\u0433\u043E\u0447\u043D\u044B\u0435 \u043C\u0435\u0448\u043A\u0438", "narz\u0105dy oddechowe paj\u0119czak\xF3w zbudowane z blaszek u\u0142o\u017Conych jak kartki ksi\u0105\u017Cki", "\u043E\u0440\u0433\u0430\u043D\u044B \u0434\u044B\u0445\u0430\u043D\u0438\u044F \u043F\u0430\u0443\u043A\u043E\u043E\u0431\u0440\u0430\u0437\u043D\u044B\u0445 \u0438\u0437 \u043F\u043B\u0430\u0441\u0442\u0438\u043D\u043E\u043A, \u0441\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0445 \u043A\u0430\u043A \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u043A\u043D\u0438\u0433\u0438", 2, [], ["\u043B\u0451\u0433\u043A\u0438\u0435 \u043F\u0430\u0443\u043A\u043E\u043E\u0431\u0440\u0430\u0437\u043D\u044B\u0445"]],
  ["przeciwprad", "wymiana przeciwpr\u0105dowa", "\u043F\u0440\u043E\u0442\u0438\u0432\u043E\u0442\u043E\u0447\u043D\u044B\u0439 \u043E\u0431\u043C\u0435\u043D", "przep\u0142yw krwi w blaszkach skrzelowych w kierunku przeciwnym do wody, kt\xF3ry zwi\u0119ksza pobieranie tlenu", "\u0442\u043E\u043A \u043A\u0440\u043E\u0432\u0438 \u0432 \u0436\u0430\u0431\u0435\u0440\u043D\u044B\u0445 \u043B\u0435\u043F\u0435\u0441\u0442\u043A\u0430\u0445 \u043D\u0430\u0432\u0441\u0442\u0440\u0435\u0447\u0443 \u0432\u043E\u0434\u0435, \u043F\u043E\u0432\u044B\u0448\u0430\u044E\u0449\u0438\u0439 \u043F\u043E\u0433\u043B\u043E\u0449\u0435\u043D\u0438\u0435 \u043A\u0438\u0441\u043B\u043E\u0440\u043E\u0434\u0430", 3, ["przeciwpr\u0105d"], ["\u043F\u0440\u043E\u0442\u0438\u0432\u043E\u0442\u043E\u043A"]],
  ["pokrywa-skrzelowa", "pokrywa skrzelowa", "\u0436\u0430\u0431\u0435\u0440\u043D\u0430\u044F \u043A\u0440\u044B\u0448\u043A\u0430", "kostna p\u0142ytka ryb kostnoszkieletowych chroni\u0105ca skrzela i wspomagaj\u0105ca przep\u0142yw wody", "\u043A\u043E\u0441\u0442\u043D\u0430\u044F \u043F\u043B\u0430\u0441\u0442\u0438\u043D\u043A\u0430 \u043A\u043E\u0441\u0442\u043D\u044B\u0445 \u0440\u044B\u0431, \u0437\u0430\u0449\u0438\u0449\u0430\u044E\u0449\u0430\u044F \u0436\u0430\u0431\u0440\u044B \u0438 \u043F\u043E\u043C\u043E\u0433\u0430\u044E\u0449\u0430\u044F \u043F\u0440\u043E\u043A\u0430\u0447\u0438\u0432\u0430\u0442\u044C \u0432\u043E\u0434\u0443", 1, ["wieczko skrzelowe"], []],
  ["oddychanie-skorne", "oddychanie sk\xF3rne", "\u043A\u043E\u0436\u043D\u043E\u0435 \u0434\u044B\u0445\u0430\u043D\u0438\u0435", "pobieranie tlenu przez wilgotn\u0105, silnie ukrwion\u0105 sk\xF3r\u0119, wa\u017Cne u p\u0142az\xF3w i d\u017Cd\u017Cownic", "\u043F\u043E\u0433\u043B\u043E\u0449\u0435\u043D\u0438\u0435 \u043A\u0438\u0441\u043B\u043E\u0440\u043E\u0434\u0430 \u0447\u0435\u0440\u0435\u0437 \u0432\u043B\u0430\u0436\u043D\u0443\u044E, \u0431\u043E\u0433\u0430\u0442\u0443\u044E \u0441\u043E\u0441\u0443\u0434\u0430\u043C\u0438 \u043A\u043E\u0436\u0443, \u0432\u0430\u0436\u043D\u043E\u0435 \u0443 \u0437\u0435\u043C\u043D\u043E\u0432\u043E\u0434\u043D\u044B\u0445 \u0438 \u0434\u043E\u0436\u0434\u0435\u0432\u044B\u0445 \u0447\u0435\u0440\u0432\u0435\u0439", 1, [], []],
  ["worki-powietrzne", "worki powietrzne", "\u0432\u043E\u0437\u0434\u0443\u0448\u043D\u044B\u0435 \u043C\u0435\u0448\u043A\u0438", "cienko\u015Bcienne uchy\u0142ki p\u0142uc ptak\xF3w zapewniaj\u0105ce jednokierunkowy przep\u0142yw powietrza przez p\u0142uca", "\u0442\u043E\u043D\u043A\u043E\u0441\u0442\u0435\u043D\u043D\u044B\u0435 \u0432\u044B\u0440\u043E\u0441\u0442\u044B \u043B\u0451\u0433\u043A\u0438\u0445 \u043F\u0442\u0438\u0446, \u043E\u0431\u0435\u0441\u043F\u0435\u0447\u0438\u0432\u0430\u044E\u0449\u0438\u0435 \u043E\u0434\u043D\u043E\u0441\u0442\u043E\u0440\u043E\u043D\u043D\u0438\u0439 \u0442\u043E\u043A \u0432\u043E\u0437\u0434\u0443\u0445\u0430 \u0447\u0435\u0440\u0435\u0437 \u043B\u0451\u0433\u043A\u0438\u0435", 2, [], []],
  ["podwojne-oddychanie", "podw\xF3jne oddychanie", "\u0434\u0432\u043E\u0439\u043D\u043E\u0435 \u0434\u044B\u0445\u0430\u043D\u0438\u0435", "wymiana gazowa w p\u0142ucach ptaka zar\xF3wno podczas wdechu, jak i podczas wydechu", "\u0433\u0430\u0437\u043E\u043E\u0431\u043C\u0435\u043D \u0432 \u043B\u0451\u0433\u043A\u0438\u0445 \u043F\u0442\u0438\u0446\u044B \u043A\u0430\u043A \u043F\u0440\u0438 \u0432\u0434\u043E\u0445\u0435, \u0442\u0430\u043A \u0438 \u043F\u0440\u0438 \u0432\u044B\u0434\u043E\u0445\u0435", 2, [], []]
]);
var ANIMAL_CIRCULATION = namedTable(P.circulation.animals, [
  ["otwarty", "otwarty uk\u0142ad krwiono\u015Bny", "\u043D\u0435\u0437\u0430\u043C\u043A\u043D\u0443\u0442\u0430\u044F \u043A\u0440\u043E\u0432\u0435\u043D\u043E\u0441\u043D\u0430\u044F \u0441\u0438\u0441\u0442\u0435\u043C\u0430", "uk\u0142ad, w kt\xF3rym p\u0142yn ustrojowy wylewa si\u0119 z naczy\u0144 do jamy cia\u0142a i omywa narz\u0105dy, np. u owad\xF3w", "\u0441\u0438\u0441\u0442\u0435\u043C\u0430, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u0436\u0438\u0434\u043A\u043E\u0441\u0442\u044C \u0438\u0437\u043B\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0438\u0437 \u0441\u043E\u0441\u0443\u0434\u043E\u0432 \u0432 \u043F\u043E\u043B\u043E\u0441\u0442\u044C \u0442\u0435\u043B\u0430 \u0438 \u043E\u043C\u044B\u0432\u0430\u0435\u0442 \u043E\u0440\u0433\u0430\u043D\u044B, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0443 \u043D\u0430\u0441\u0435\u043A\u043E\u043C\u044B\u0445", 1, ["uk\u0142ad otwarty"], ["\u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F \u043A\u0440\u043E\u0432\u0435\u043D\u043E\u0441\u043D\u0430\u044F \u0441\u0438\u0441\u0442\u0435\u043C\u0430"]],
  ["zamkniety", "zamkni\u0119ty uk\u0142ad krwiono\u015Bny", "\u0437\u0430\u043C\u043A\u043D\u0443\u0442\u0430\u044F \u043A\u0440\u043E\u0432\u0435\u043D\u043E\u0441\u043D\u0430\u044F \u0441\u0438\u0441\u0442\u0435\u043C\u0430", "uk\u0142ad, w kt\xF3rym krew p\u0142ynie ca\u0142y czas w naczyniach, np. u pier\u015Bcienic i kr\u0119gowc\xF3w", "\u0441\u0438\u0441\u0442\u0435\u043C\u0430, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u043A\u0440\u043E\u0432\u044C \u0432\u0441\u0451 \u0432\u0440\u0435\u043C\u044F \u0442\u0435\u0447\u0451\u0442 \u043F\u043E \u0441\u043E\u0441\u0443\u0434\u0430\u043C, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0443 \u043A\u043E\u043B\u044C\u0447\u0430\u0442\u044B\u0445 \u0447\u0435\u0440\u0432\u0435\u0439 \u0438 \u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u044B\u0445", 1, ["uk\u0142ad zamkni\u0119ty"], ["\u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F \u043A\u0440\u043E\u0432\u0435\u043D\u043E\u0441\u043D\u0430\u044F \u0441\u0438\u0441\u0442\u0435\u043C\u0430"]],
  ["hemolimfa", "hemolimfa", "\u0433\u0435\u043C\u043E\u043B\u0438\u043C\u0444\u0430", "p\u0142yn ustrojowy zwierz\u0105t z otwartym uk\u0142adem krwiono\u015Bnym, pe\u0142ni\u0105cy rol\u0119 krwi i limfy", "\u0436\u0438\u0434\u043A\u043E\u0441\u0442\u044C \u0442\u0435\u043B\u0430 \u0436\u0438\u0432\u043E\u0442\u043D\u044B\u0445 \u0441 \u043D\u0435\u0437\u0430\u043C\u043A\u043D\u0443\u0442\u043E\u0439 \u043A\u0440\u043E\u0432\u0435\u043D\u043E\u0441\u043D\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u043E\u0439, \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u044E\u0449\u0430\u044F \u0440\u043E\u043B\u044C \u043A\u0440\u043E\u0432\u0438 \u0438 \u043B\u0438\u043C\u0444\u044B", 2, [], []],
  ["serce-dwujamowe", "serce dwujamowe", "\u0434\u0432\u0443\u0445\u043A\u0430\u043C\u0435\u0440\u043D\u043E\u0435 \u0441\u0435\u0440\u0434\u0446\u0435", "serce ryb z jednym przedsionkiem i jedn\u0105 komor\u0105, przez kt\xF3re p\u0142ynie tylko krew odtlenowana", "\u0441\u0435\u0440\u0434\u0446\u0435 \u0440\u044B\u0431 \u0441 \u043E\u0434\u043D\u0438\u043C \u043F\u0440\u0435\u0434\u0441\u0435\u0440\u0434\u0438\u0435\u043C \u0438 \u043E\u0434\u043D\u0438\u043C \u0436\u0435\u043B\u0443\u0434\u043E\u0447\u043A\u043E\u043C, \u0447\u0435\u0440\u0435\u0437 \u043A\u043E\u0442\u043E\u0440\u043E\u0435 \u0442\u0435\u0447\u0451\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0432\u0435\u043D\u043E\u0437\u043D\u0430\u044F \u043A\u0440\u043E\u0432\u044C", 1, [], []],
  ["serce-trojjamowe", "serce tr\xF3jjamowe", "\u0442\u0440\u0451\u0445\u043A\u0430\u043C\u0435\u0440\u043D\u043E\u0435 \u0441\u0435\u0440\u0434\u0446\u0435", "serce p\u0142az\xF3w z dwoma przedsionkami i jedn\u0105 komor\u0105, w kt\xF3rej krew cz\u0119\u015Bciowo si\u0119 miesza", "\u0441\u0435\u0440\u0434\u0446\u0435 \u0437\u0435\u043C\u043D\u043E\u0432\u043E\u0434\u043D\u044B\u0445 \u0441 \u0434\u0432\u0443\u043C\u044F \u043F\u0440\u0435\u0434\u0441\u0435\u0440\u0434\u0438\u044F\u043C\u0438 \u0438 \u043E\u0434\u043D\u0438\u043C \u0436\u0435\u043B\u0443\u0434\u043E\u0447\u043A\u043E\u043C, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u043A\u0440\u043E\u0432\u044C \u0447\u0430\u0441\u0442\u0438\u0447\u043D\u043E \u0441\u043C\u0435\u0448\u0438\u0432\u0430\u0435\u0442\u0441\u044F", 1, [], []],
  ["serce-czterojamowe", "serce czterojamowe", "\u0447\u0435\u0442\u044B\u0440\u0451\u0445\u043A\u0430\u043C\u0435\u0440\u043D\u043E\u0435 \u0441\u0435\u0440\u0434\u0446\u0435", "serce ptak\xF3w i ssak\xF3w z ca\u0142kowicie rozdzielonymi komorami, w kt\xF3rym krew utlenowana nie miesza si\u0119 z odtlenowan\u0105", "\u0441\u0435\u0440\u0434\u0446\u0435 \u043F\u0442\u0438\u0446 \u0438 \u043C\u043B\u0435\u043A\u043E\u043F\u0438\u0442\u0430\u044E\u0449\u0438\u0445 \u0441 \u043F\u043E\u043B\u043D\u043E\u0441\u0442\u044C\u044E \u0440\u0430\u0437\u0434\u0435\u043B\u0451\u043D\u043D\u044B\u043C\u0438 \u0436\u0435\u043B\u0443\u0434\u043E\u0447\u043A\u0430\u043C\u0438, \u0433\u0434\u0435 \u0430\u0440\u0442\u0435\u0440\u0438\u0430\u043B\u044C\u043D\u0430\u044F \u043A\u0440\u043E\u0432\u044C \u043D\u0435 \u0441\u043C\u0435\u0448\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0441 \u0432\u0435\u043D\u043E\u0437\u043D\u043E\u0439", 1, [], []],
  ["jeden-obieg", "pojedynczy obieg krwi", "\u043E\u0434\u0438\u043D \u043A\u0440\u0443\u0433 \u043A\u0440\u043E\u0432\u043E\u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u044F", "kr\u0105\u017Cenie, w kt\xF3rym krew w czasie pe\u0142nego obiegu cia\u0142a przep\u0142ywa przez serce tylko raz, typowe dla ryb", "\u043A\u0440\u043E\u0432\u043E\u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u0435, \u043F\u0440\u0438 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u0437\u0430 \u043F\u043E\u043B\u043D\u044B\u0439 \u043E\u0431\u043E\u0440\u043E\u0442 \u043A\u0440\u043E\u0432\u044C \u043F\u0440\u043E\u0445\u043E\u0434\u0438\u0442 \u0447\u0435\u0440\u0435\u0437 \u0441\u0435\u0440\u0434\u0446\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0434\u0438\u043D \u0440\u0430\u0437, \u043A\u0430\u043A \u0443 \u0440\u044B\u0431", 2, ["jeden obieg krwi"], []],
  ["podwojny-obieg", "podw\xF3jny obieg krwi", "\u0434\u0432\u0430 \u043A\u0440\u0443\u0433\u0430 \u043A\u0440\u043E\u0432\u043E\u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u044F", "kr\u0105\u017Cenie z krwiobiegiem p\u0142ucnym i ustrojowym, w kt\xF3rym krew dwukrotnie przep\u0142ywa przez serce", "\u043A\u0440\u043E\u0432\u043E\u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u0441 \u043B\u0451\u0433\u043E\u0447\u043D\u044B\u043C \u0438 \u0441\u0438\u0441\u0442\u0435\u043C\u043D\u044B\u043C \u043A\u0440\u0443\u0433\u0430\u043C\u0438, \u043F\u0440\u0438 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u043A\u0440\u043E\u0432\u044C \u0434\u0432\u0430\u0436\u0434\u044B \u043F\u0440\u043E\u0445\u043E\u0434\u0438\u0442 \u0447\u0435\u0440\u0435\u0437 \u0441\u0435\u0440\u0434\u0446\u0435", 2, ["dwa obiegi krwi"], ["\u0434\u0432\u043E\u0439\u043D\u043E\u0435 \u043A\u0440\u043E\u0432\u043E\u043E\u0431\u0440\u0430\u0449\u0435\u043D\u0438\u0435"]],
  ["hemocyjanina", "hemocyjanina", "\u0433\u0435\u043C\u043E\u0446\u0438\u0430\u043D\u0438\u043D", "barwnik oddechowy zawieraj\u0105cy mied\u017A, nadaj\u0105cy niebiesk\u0105 barw\u0119 hemolimfie mi\u0119czak\xF3w i skorupiak\xF3w", "\u0434\u044B\u0445\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043F\u0438\u0433\u043C\u0435\u043D\u0442 \u0441 \u043C\u0435\u0434\u044C\u044E, \u043F\u0440\u0438\u0434\u0430\u044E\u0449\u0438\u0439 \u0433\u043E\u043B\u0443\u0431\u043E\u0439 \u0446\u0432\u0435\u0442 \u0433\u0435\u043C\u043E\u043B\u0438\u043C\u0444\u0435 \u043C\u043E\u043B\u043B\u044E\u0441\u043A\u043E\u0432 \u0438 \u0440\u0430\u043A\u043E\u043E\u0431\u0440\u0430\u0437\u043D\u044B\u0445", 3, [], []]
]);
var ANIMAL_EXCRETION = namedTable(P.urinary.animals, [
  ["amoniak", "amoniak", "\u0430\u043C\u043C\u0438\u0430\u043A", "bardzo toksyczny i dobrze rozpuszczalny w wodzie produkt przemiany bia\u0142ek, wydalany przez zwierz\u0119ta wodne", "\u043E\u0447\u0435\u043D\u044C \u0442\u043E\u043A\u0441\u0438\u0447\u043D\u044B\u0439 \u0438 \u0445\u043E\u0440\u043E\u0448\u043E \u0440\u0430\u0441\u0442\u0432\u043E\u0440\u0438\u043C\u044B\u0439 \u0432 \u0432\u043E\u0434\u0435 \u043F\u0440\u043E\u0434\u0443\u043A\u0442 \u043E\u0431\u043C\u0435\u043D\u0430 \u0431\u0435\u043B\u043A\u043E\u0432, \u0432\u044B\u0432\u043E\u0434\u0438\u043C\u044B\u0439 \u0432\u043E\u0434\u043D\u044B\u043C\u0438 \u0436\u0438\u0432\u043E\u0442\u043D\u044B\u043C\u0438", 1, [], []],
  ["mocznik", "mocznik", "\u043C\u043E\u0447\u0435\u0432\u0438\u043D\u0430", "mniej toksyczny produkt przemiany bia\u0142ek wytwarzany w w\u0105trobie ssak\xF3w i p\u0142az\xF3w, wydalany z umiarkowan\u0105 ilo\u015Bci\u0105 wody", "\u043C\u0435\u043D\u0435\u0435 \u0442\u043E\u043A\u0441\u0438\u0447\u043D\u044B\u0439 \u043F\u0440\u043E\u0434\u0443\u043A\u0442 \u043E\u0431\u043C\u0435\u043D\u0430 \u0431\u0435\u043B\u043A\u043E\u0432, \u043E\u0431\u0440\u0430\u0437\u0443\u0435\u043C\u044B\u0439 \u0432 \u043F\u0435\u0447\u0435\u043D\u0438 \u043C\u043B\u0435\u043A\u043E\u043F\u0438\u0442\u0430\u044E\u0449\u0438\u0445 \u0438 \u0437\u0435\u043C\u043D\u043E\u0432\u043E\u0434\u043D\u044B\u0445 \u0438 \u0432\u044B\u0432\u043E\u0434\u0438\u043C\u044B\u0439 \u0441 \u0443\u043C\u0435\u0440\u0435\u043D\u043D\u044B\u043C \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E\u043C \u0432\u043E\u0434\u044B", 1, [], []],
  ["kwas-moczowy", "kwas moczowy", "\u043C\u043E\u0447\u0435\u0432\u0430\u044F \u043A\u0438\u0441\u043B\u043E\u0442\u0430", "s\u0142abo rozpuszczalny produkt przemiany bia\u0142ek, wydalany prawie bez wody przez ptaki, gady i owady", "\u043F\u043B\u043E\u0445\u043E \u0440\u0430\u0441\u0442\u0432\u043E\u0440\u0438\u043C\u044B\u0439 \u043F\u0440\u043E\u0434\u0443\u043A\u0442 \u043E\u0431\u043C\u0435\u043D\u0430 \u0431\u0435\u043B\u043A\u043E\u0432, \u0432\u044B\u0432\u043E\u0434\u0438\u043C\u044B\u0439 \u043F\u043E\u0447\u0442\u0438 \u0431\u0435\u0437 \u0432\u043E\u0434\u044B \u043F\u0442\u0438\u0446\u0430\u043C\u0438, \u043F\u0440\u0435\u0441\u043C\u044B\u043A\u0430\u044E\u0449\u0438\u043C\u0438\u0441\u044F \u0438 \u043D\u0430\u0441\u0435\u043A\u043E\u043C\u044B\u043C\u0438", 1, [], []],
  ["protonefrydia", "protonefrydia", "\u043F\u0440\u043E\u0442\u043E\u043D\u0435\u0444\u0440\u0438\u0434\u0438\u0438", "kanaliki zako\u0144czone kom\xF3rkami p\u0142omykowymi \u2014 narz\u0105dy wydalnicze p\u0142azi\u0144c\xF3w", "\u043A\u0430\u043D\u0430\u043B\u044C\u0446\u044B, \u043E\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u044E\u0449\u0438\u0435\u0441\u044F \u043F\u043B\u0430\u043C\u0435\u043D\u043D\u044B\u043C\u0438 \u043A\u043B\u0435\u0442\u043A\u0430\u043C\u0438, \u2014 \u043E\u0440\u0433\u0430\u043D\u044B \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u043F\u043B\u043E\u0441\u043A\u0438\u0445 \u0447\u0435\u0440\u0432\u0435\u0439", 2, [], []],
  ["metanefrydia", "metanefrydia", "\u043C\u0435\u0442\u0430\u043D\u0435\u0444\u0440\u0438\u0434\u0438\u0438", "parzyste kanaliki w ka\u017Cdym segmencie cia\u0142a pier\u015Bcienic, zaczynaj\u0105ce si\u0119 lejkiem otwartym do jamy cia\u0142a", "\u043F\u0430\u0440\u043D\u044B\u0435 \u043A\u0430\u043D\u0430\u043B\u044C\u0446\u044B \u0432 \u043A\u0430\u0436\u0434\u043E\u043C \u0441\u0435\u0433\u043C\u0435\u043D\u0442\u0435 \u0442\u0435\u043B\u0430 \u043A\u043E\u043B\u044C\u0447\u0430\u0442\u044B\u0445 \u0447\u0435\u0440\u0432\u0435\u0439, \u043D\u0430\u0447\u0438\u043D\u0430\u044E\u0449\u0438\u0435\u0441\u044F \u0432\u043E\u0440\u043E\u043D\u043A\u043E\u0439, \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u0439 \u0432 \u043F\u043E\u043B\u043E\u0441\u0442\u044C \u0442\u0435\u043B\u0430", 2, [], []],
  ["cewki-malpighiego", "cewki Malpighiego", "\u043C\u0430\u043B\u044C\u043F\u0438\u0433\u0438\u0435\u0432\u044B \u0441\u043E\u0441\u0443\u0434\u044B", "\u015Blepo zako\u0144czone kanaliki uchodz\u0105ce do jelita owad\xF3w, usuwaj\u0105ce produkty przemiany z hemolimfy", "\u0441\u043B\u0435\u043F\u043E \u0437\u0430\u043C\u043A\u043D\u0443\u0442\u044B\u0435 \u043A\u0430\u043D\u0430\u043B\u044C\u0446\u044B, \u0432\u043F\u0430\u0434\u0430\u044E\u0449\u0438\u0435 \u0432 \u043A\u0438\u0448\u0435\u0447\u043D\u0438\u043A \u043D\u0430\u0441\u0435\u043A\u043E\u043C\u044B\u0445 \u0438 \u0443\u0434\u0430\u043B\u044F\u044E\u0449\u0438\u0435 \u043F\u0440\u043E\u0434\u0443\u043A\u0442\u044B \u043E\u0431\u043C\u0435\u043D\u0430 \u0438\u0437 \u0433\u0435\u043C\u043E\u043B\u0438\u043C\u0444\u044B", 2, ["cewki Malpighiego"], ["\u043C\u0430\u043B\u044C\u043F\u0438\u0433\u0438\u0435\u0432\u044B \u0442\u0440\u0443\u0431\u043E\u0447\u043A\u0438"]],
  ["gruczoly-solne", "gruczo\u0142y solne", "\u0441\u043E\u043B\u0435\u0432\u044B\u0435 \u0436\u0435\u043B\u0435\u0437\u044B", "gruczo\u0142y w okolicy oczu lub nozdrzy ptak\xF3w i gad\xF3w morskich, wydalaj\u0105ce nadmiar soli", "\u0436\u0435\u043B\u0435\u0437\u044B \u043E\u043A\u043E\u043B\u043E \u0433\u043B\u0430\u0437 \u0438\u043B\u0438 \u043D\u043E\u0437\u0434\u0440\u0435\u0439 \u043C\u043E\u0440\u0441\u043A\u0438\u0445 \u043F\u0442\u0438\u0446 \u0438 \u043F\u0440\u0435\u0441\u043C\u044B\u043A\u0430\u044E\u0449\u0438\u0445\u0441\u044F, \u0432\u044B\u0432\u043E\u0434\u044F\u0449\u0438\u0435 \u0438\u0437\u0431\u044B\u0442\u043E\u043A \u0441\u043E\u043B\u0438", 2, [], []],
  ["wodniczka-tetniaca", "wodniczka t\u0119tni\u0105ca", "\u0441\u043E\u043A\u0440\u0430\u0442\u0438\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u0432\u0430\u043A\u0443\u043E\u043B\u044C", "organellum pierwotniak\xF3w s\u0142odkowodnych usuwaj\u0105ce z kom\xF3rki nadmiar wody", "\u043E\u0440\u0433\u0430\u043D\u043E\u0438\u0434 \u043F\u0440\u0435\u0441\u043D\u043E\u0432\u043E\u0434\u043D\u044B\u0445 \u043F\u0440\u043E\u0441\u0442\u0435\u0439\u0448\u0438\u0445, \u0443\u0434\u0430\u043B\u044F\u044E\u0449\u0438\u0439 \u0438\u0437 \u043A\u043B\u0435\u0442\u043A\u0438 \u0438\u0437\u0431\u044B\u0442\u043E\u043A \u0432\u043E\u0434\u044B", 2, [], ["\u043F\u0443\u043B\u044C\u0441\u0438\u0440\u0443\u044E\u0449\u0430\u044F \u0432\u0430\u043A\u0443\u043E\u043B\u044C"]],
  ["ryby-slodkowodne", "ryby s\u0142odkowodne", "\u043F\u0440\u0435\u0441\u043D\u043E\u0432\u043E\u0434\u043D\u044B\u0435 \u0440\u044B\u0431\u044B", "kr\u0119gowce oddychaj\u0105ce skrzelami, do kt\xF3rych cia\u0142a woda stale nap\u0142ywa osmotycznie, dlatego nie pij\u0105, wydalaj\u0105 du\u017Co rozcie\u0144czonego moczu i aktywnie pobieraj\u0105 jony przez skrzela", "\u0434\u044B\u0448\u0430\u0449\u0438\u0435 \u0436\u0430\u0431\u0440\u0430\u043C\u0438 \u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u044B\u0435, \u0432 \u0442\u0435\u043B\u043E \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0432\u043E\u0434\u0430 \u043F\u043E\u0441\u0442\u043E\u044F\u043D\u043D\u043E \u043F\u043E\u0441\u0442\u0443\u043F\u0430\u0435\u0442 \u043E\u0441\u043C\u043E\u0442\u0438\u0447\u0435\u0441\u043A\u0438, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u0438 \u043D\u0435 \u043F\u044C\u044E\u0442, \u0432\u044B\u0434\u0435\u043B\u044F\u044E\u0442 \u043C\u043D\u043E\u0433\u043E \u0440\u0430\u0437\u0431\u0430\u0432\u043B\u0435\u043D\u043D\u043E\u0439 \u043C\u043E\u0447\u0438 \u0438 \u0430\u043A\u0442\u0438\u0432\u043D\u043E \u043F\u043E\u0433\u043B\u043E\u0449\u0430\u044E\u0442 \u0438\u043E\u043D\u044B \u0436\u0430\u0431\u0440\u0430\u043C\u0438", 3, [], []],
  ["ryby-morskie", "ryby morskie", "\u043C\u043E\u0440\u0441\u043A\u0438\u0435 \u0440\u044B\u0431\u044B", "kr\u0119gowce oddychaj\u0105ce skrzelami, trac\u0105ce wod\u0119 do otoczenia, dlatego pij\u0105 wod\u0119 morsk\u0105 i usuwaj\u0105 nadmiar soli przez skrzela", "\u0434\u044B\u0448\u0430\u0449\u0438\u0435 \u0436\u0430\u0431\u0440\u0430\u043C\u0438 \u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u044B\u0435, \u0442\u0435\u0440\u044F\u044E\u0449\u0438\u0435 \u0432\u043E\u0434\u0443 \u0432 \u043E\u043A\u0440\u0443\u0436\u0430\u044E\u0449\u0443\u044E \u0441\u0440\u0435\u0434\u0443, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u0438 \u043F\u044C\u044E\u0442 \u043C\u043E\u0440\u0441\u043A\u0443\u044E \u0432\u043E\u0434\u0443 \u0438 \u0432\u044B\u0432\u043E\u0434\u044F\u0442 \u0438\u0437\u0431\u044B\u0442\u043E\u043A \u0441\u043E\u043B\u0438 \u0447\u0435\u0440\u0435\u0437 \u0436\u0430\u0431\u0440\u044B", 3, ["morskie ryby kostnoszkieletowe"], ["\u043C\u043E\u0440\u0441\u043A\u0438\u0435 \u043A\u043E\u0441\u0442\u043D\u044B\u0435 \u0440\u044B\u0431\u044B"]]
]);
var ANIMAL_NERVES = namedTable(P.nervous.animals, [
  ["rozproszony", "rozproszony uk\u0142ad nerwowy", "\u0434\u0438\u0444\u0444\u0443\u0437\u043D\u0430\u044F \u043D\u0435\u0440\u0432\u043D\u0430\u044F \u0441\u0438\u0441\u0442\u0435\u043C\u0430", "sie\u0107 neuron\xF3w rozmieszczonych r\xF3wnomiernie w ca\u0142ym ciele, bez o\u015Brodk\xF3w, typowa dla parzyde\u0142kowc\xF3w", "\u0441\u0435\u0442\u044C \u043D\u0435\u0439\u0440\u043E\u043D\u043E\u0432, \u0440\u0430\u0432\u043D\u043E\u043C\u0435\u0440\u043D\u043E \u0440\u0430\u0441\u0441\u0435\u044F\u043D\u043D\u044B\u0445 \u043F\u043E \u0442\u0435\u043B\u0443 \u0431\u0435\u0437 \u0446\u0435\u043D\u0442\u0440\u043E\u0432, \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440\u043D\u0430\u044F \u0434\u043B\u044F \u043A\u0438\u0448\u0435\u0447\u043D\u043E\u043F\u043E\u043B\u043E\u0441\u0442\u043D\u044B\u0445", 1, ["uk\u0142ad nerwowy siateczkowy"], ["\u0441\u0435\u0442\u0447\u0430\u0442\u0430\u044F \u043D\u0435\u0440\u0432\u043D\u0430\u044F \u0441\u0438\u0441\u0442\u0435\u043C\u0430"]],
  ["drabinkowy", "drabinkowy uk\u0142ad nerwowy", "\u043B\u0435\u0441\u0442\u043D\u0438\u0447\u043D\u0430\u044F \u043D\u0435\u0440\u0432\u043D\u0430\u044F \u0441\u0438\u0441\u0442\u0435\u043C\u0430", "pnie nerwowe po\u0142\u0105czone poprzecznymi spoid\u0142ami, z par\u0105 zwoj\xF3w g\u0142owowych, wyst\u0119puj\u0105ce u p\u0142azi\u0144c\xF3w", "\u043D\u0435\u0440\u0432\u043D\u044B\u0435 \u0441\u0442\u0432\u043E\u043B\u044B, \u0441\u043E\u0435\u0434\u0438\u043D\u0451\u043D\u043D\u044B\u0435 \u043F\u043E\u043F\u0435\u0440\u0435\u0447\u043D\u044B\u043C\u0438 \u043F\u0435\u0440\u0435\u043C\u044B\u0447\u043A\u0430\u043C\u0438, \u0441 \u043F\u0430\u0440\u043E\u0439 \u0433\u043E\u043B\u043E\u0432\u043D\u044B\u0445 \u0433\u0430\u043D\u0433\u043B\u0438\u0435\u0432, \u043A\u0430\u043A \u0443 \u043F\u043B\u043E\u0441\u043A\u0438\u0445 \u0447\u0435\u0440\u0432\u0435\u0439", 2, [], ["\u043E\u0440\u0442\u043E\u0433\u043E\u043D"]],
  ["lancuszek", "\u0142a\u0144cuszek brzuszny", "\u0431\u0440\u044E\u0448\u043D\u0430\u044F \u043D\u0435\u0440\u0432\u043D\u0430\u044F \u0446\u0435\u043F\u043E\u0447\u043A\u0430", "parzyste zwoje w kolejnych segmentach cia\u0142a, po\u0142\u0105czone w \u0142a\u0144cuch pod przewodem pokarmowym, u pier\u015Bcienic i stawonog\xF3w", "\u043F\u0430\u0440\u043D\u044B\u0435 \u0433\u0430\u043D\u0433\u043B\u0438\u0438 \u0432 \u0441\u0435\u0433\u043C\u0435\u043D\u0442\u0430\u0445 \u0442\u0435\u043B\u0430, \u0441\u043E\u0435\u0434\u0438\u043D\u0451\u043D\u043D\u044B\u0435 \u0432 \u0446\u0435\u043F\u043E\u0447\u043A\u0443 \u043F\u043E\u0434 \u043F\u0438\u0449\u0435\u0432\u0430\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u043C \u0442\u0440\u0430\u043A\u0442\u043E\u043C, \u0443 \u043A\u043E\u043B\u044C\u0447\u0430\u0442\u044B\u0445 \u0447\u0435\u0440\u0432\u0435\u0439 \u0438 \u0447\u043B\u0435\u043D\u0438\u0441\u0442\u043E\u043D\u043E\u0433\u0438\u0445", 1, ["brzuszny \u0142a\u0144cuszek nerwowy"], ["\u0431\u0440\u044E\u0448\u043D\u0430\u044F \u0446\u0435\u043F\u043E\u0447\u043A\u0430"]],
  ["zwoj-nadprzelykowy", "zw\xF3j nadprze\u0142ykowy", "\u043D\u0430\u0434\u0433\u043B\u043E\u0442\u043E\u0447\u043D\u044B\u0439 \u0433\u0430\u043D\u0433\u043B\u0438\u0439", "g\u0142\xF3wny o\u015Brodek nerwowy bezkr\u0119gowc\xF3w le\u017C\u0105cy nad gardziel\u0105, pe\u0142ni\u0105cy rol\u0119 m\xF3zgu", "\u0433\u043B\u0430\u0432\u043D\u044B\u0439 \u043D\u0435\u0440\u0432\u043D\u044B\u0439 \u0446\u0435\u043D\u0442\u0440 \u0431\u0435\u0441\u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u044B\u0445, \u043B\u0435\u0436\u0430\u0449\u0438\u0439 \u043D\u0430\u0434 \u0433\u043B\u043E\u0442\u043A\u043E\u0439 \u0438 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u044E\u0449\u0438\u0439 \u0440\u043E\u043B\u044C \u043C\u043E\u0437\u0433\u0430", 2, ["zw\xF3j m\xF3zgowy"], ["\u0433\u043E\u043B\u043E\u0432\u043D\u043E\u0439 \u0433\u0430\u043D\u0433\u043B\u0438\u0439"]],
  ["cewka-nerwowa", "cewka nerwowa", "\u043D\u0435\u0440\u0432\u043D\u0430\u044F \u0442\u0440\u0443\u0431\u043A\u0430", "grzbietowo po\u0142o\u017Cony, pusty w \u015Brodku zawi\u0105zek o\u015Brodkowego uk\u0142adu nerwowego strunowc\xF3w", "\u043B\u0435\u0436\u0430\u0449\u0438\u0439 \u043D\u0430 \u0441\u043F\u0438\u043D\u043D\u043E\u0439 \u0441\u0442\u043E\u0440\u043E\u043D\u0435 \u043F\u043E\u043B\u044B\u0439 \u0437\u0430\u0447\u0430\u0442\u043E\u043A \u0446\u0435\u043D\u0442\u0440\u0430\u043B\u044C\u043D\u043E\u0439 \u043D\u0435\u0440\u0432\u043D\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u044B \u0445\u043E\u0440\u0434\u043E\u0432\u044B\u0445", 2, [], []],
  ["cefalizacja", "cefalizacja", "\u0446\u0435\u0444\u0430\u043B\u0438\u0437\u0430\u0446\u0438\u044F", "skupianie si\u0119 o\u015Brodk\xF3w nerwowych i narz\u0105d\xF3w zmys\u0142\xF3w w przedniej cz\u0119\u015Bci cia\u0142a", "\u0441\u043E\u0441\u0440\u0435\u0434\u043E\u0442\u043E\u0447\u0435\u043D\u0438\u0435 \u043D\u0435\u0440\u0432\u043D\u044B\u0445 \u0446\u0435\u043D\u0442\u0440\u043E\u0432 \u0438 \u043E\u0440\u0433\u0430\u043D\u043E\u0432 \u0447\u0443\u0432\u0441\u0442\u0432 \u0432 \u043F\u0435\u0440\u0435\u0434\u043D\u0435\u0439 \u0447\u0430\u0441\u0442\u0438 \u0442\u0435\u043B\u0430", 2, [], []],
  ["kora-nowa", "kora nowa", "\u043D\u043E\u0432\u0430\u044F \u043A\u043E\u0440\u0430", "zewn\u0119trzna warstwa p\xF3\u0142kul m\xF3zgowych, najsilniej rozwini\u0119ta u ssak\xF3w", "\u043D\u0430\u0440\u0443\u0436\u043D\u044B\u0439 \u0441\u043B\u043E\u0439 \u043F\u043E\u043B\u0443\u0448\u0430\u0440\u0438\u0439 \u0433\u043E\u043B\u043E\u0432\u043D\u043E\u0433\u043E \u043C\u043E\u0437\u0433\u0430, \u0441\u0438\u043B\u044C\u043D\u0435\u0435 \u0432\u0441\u0435\u0433\u043E \u0440\u0430\u0437\u0432\u0438\u0442\u044B\u0439 \u0443 \u043C\u043B\u0435\u043A\u043E\u043F\u0438\u0442\u0430\u044E\u0449\u0438\u0445", 2, [], ["\u043D\u0435\u043E\u043A\u043E\u0440\u0442\u0435\u043A\u0441"]],
  ["platy-wzrokowe", "p\u0142aty wzrokowe", "\u0437\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0434\u043E\u043B\u0438", "silnie rozwini\u0119ta cz\u0119\u015B\u0107 \u015Br\xF3dm\xF3zgowia ryb i ptak\xF3w, przetwarzaj\u0105ca bod\u017Ace wzrokowe", "\u0441\u0438\u043B\u044C\u043D\u043E \u0440\u0430\u0437\u0432\u0438\u0442\u0430\u044F \u0447\u0430\u0441\u0442\u044C \u0441\u0440\u0435\u0434\u043D\u0435\u0433\u043E \u043C\u043E\u0437\u0433\u0430 \u0440\u044B\u0431 \u0438 \u043F\u0442\u0438\u0446, \u043E\u0431\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u044E\u0449\u0430\u044F \u0437\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0441\u0438\u0433\u043D\u0430\u043B\u044B", 3, [], ["\u0437\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0434\u043E\u043B\u0438 \u0441\u0440\u0435\u0434\u043D\u0435\u0433\u043E \u043C\u043E\u0437\u0433\u0430"]]
]);
var ANIMAL_SENSES = namedTable(P.senses.animals, [
  ["oczy-zlozone", "oczy z\u0142o\u017Cone", "\u0444\u0430\u0441\u0435\u0442\u043E\u0447\u043D\u044B\u0435 \u0433\u043B\u0430\u0437\u0430", "narz\u0105dy wzroku owad\xF3w i skorupiak\xF3w zbudowane z wielu omatidi\xF3w", "\u043E\u0440\u0433\u0430\u043D\u044B \u0437\u0440\u0435\u043D\u0438\u044F \u043D\u0430\u0441\u0435\u043A\u043E\u043C\u044B\u0445 \u0438 \u0440\u0430\u043A\u043E\u043E\u0431\u0440\u0430\u0437\u043D\u044B\u0445, \u0441\u043E\u0441\u0442\u043E\u044F\u0449\u0438\u0435 \u0438\u0437 \u043C\u043D\u043E\u0436\u0435\u0441\u0442\u0432\u0430 \u043E\u043C\u043C\u0430\u0442\u0438\u0434\u0438\u0435\u0432", 1, [], ["\u0441\u043B\u043E\u0436\u043D\u044B\u0435 \u0433\u043B\u0430\u0437\u0430"]],
  ["omatidium", "omatidium", "\u043E\u043C\u043C\u0430\u0442\u0438\u0434\u0438\u0439", "pojedyncza jednostka oka z\u0142o\u017Conego z w\u0142asn\u0105 soczewk\u0105 i kom\xF3rkami \u015Bwiat\u0142oczu\u0142ymi", "\u043E\u0442\u0434\u0435\u043B\u044C\u043D\u0430\u044F \u0435\u0434\u0438\u043D\u0438\u0446\u0430 \u0444\u0430\u0441\u0435\u0442\u043E\u0447\u043D\u043E\u0433\u043E \u0433\u043B\u0430\u0437\u0430 \u0441\u043E \u0441\u0432\u043E\u0435\u0439 \u043B\u0438\u043D\u0437\u043E\u0439 \u0438 \u0441\u0432\u0435\u0442\u043E\u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u043C\u0438 \u043A\u043B\u0435\u0442\u043A\u0430\u043C\u0438", 2, ["omatidia"], ["\u043E\u043C\u043C\u0430\u0442\u0438\u0434\u0438\u0438"]],
  ["przyoczka", "przyoczka", "\u0433\u043B\u0430\u0437\u043A\u0438", "proste narz\u0105dy wzroku odbieraj\u0105ce g\u0142\xF3wnie kierunek i nat\u0119\u017Cenie \u015Bwiat\u0142a, np. u wyp\u0142awka", "\u043F\u0440\u043E\u0441\u0442\u044B\u0435 \u043E\u0440\u0433\u0430\u043D\u044B \u0437\u0440\u0435\u043D\u0438\u044F, \u0432\u043E\u0441\u043F\u0440\u0438\u043D\u0438\u043C\u0430\u044E\u0449\u0438\u0435 \u0432 \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u043C \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0438 \u0441\u0438\u043B\u0443 \u0441\u0432\u0435\u0442\u0430, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0443 \u043F\u043B\u0430\u043D\u0430\u0440\u0438\u0438", 2, [], ["\u043F\u0440\u043E\u0441\u0442\u044B\u0435 \u0433\u043B\u0430\u0437\u0430"]],
  ["linia-boczna", "linia boczna", "\u0431\u043E\u043A\u043E\u0432\u0430\u044F \u043B\u0438\u043D\u0438\u044F", "narz\u0105d zmys\u0142u ryb i larw p\u0142az\xF3w odbieraj\u0105cy ruchy wody i drgania", "\u043E\u0440\u0433\u0430\u043D \u0447\u0443\u0432\u0441\u0442\u0432 \u0440\u044B\u0431 \u0438 \u043B\u0438\u0447\u0438\u043D\u043E\u043A \u0437\u0435\u043C\u043D\u043E\u0432\u043E\u0434\u043D\u044B\u0445, \u0432\u043E\u0441\u043F\u0440\u0438\u043D\u0438\u043C\u0430\u044E\u0449\u0438\u0439 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0432\u043E\u0434\u044B \u0438 \u043A\u043E\u043B\u0435\u0431\u0430\u043D\u0438\u044F", 1, [], []],
  ["narzad-jacobsona", "narz\u0105d Jacobsona", "\u044F\u043A\u043E\u0431\u0441\u043E\u043D\u043E\u0432 \u043E\u0440\u0433\u0430\u043D", "narz\u0105d chemiczny w podniebieniu w\u0119\u017Cy i jaszczurek, do kt\xF3rego j\u0119zyk przenosi cz\u0105steczki zapachowe", "\u0445\u0438\u043C\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u043E\u0440\u0433\u0430\u043D \u0432 \u043D\u0451\u0431\u0435 \u0437\u043C\u0435\u0439 \u0438 \u044F\u0449\u0435\u0440\u0438\u0446, \u043A \u043A\u043E\u0442\u043E\u0440\u043E\u043C\u0443 \u044F\u0437\u044B\u043A \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u043F\u0430\u0445\u0443\u0447\u0438\u0435 \u043C\u043E\u043B\u0435\u043A\u0443\u043B\u044B", 3, ["narz\u0105d lemieszowo-nosowy"], ["\u0432\u043E\u043C\u0435\u0440\u043E\u043D\u0430\u0437\u0430\u043B\u044C\u043D\u044B\u0439 \u043E\u0440\u0433\u0430\u043D"]],
  ["dolki", "do\u0142ki policzkowe", "\u043B\u0438\u0446\u0435\u0432\u044B\u0435 \u044F\u043C\u043A\u0438", "narz\u0105dy grzechotnik\xF3w odbieraj\u0105ce promieniowanie podczerwone ciep\u0142ych ofiar", "\u043E\u0440\u0433\u0430\u043D\u044B \u0433\u0440\u0435\u043C\u0443\u0447\u0438\u0445 \u0437\u043C\u0435\u0439, \u0443\u043B\u0430\u0432\u043B\u0438\u0432\u0430\u044E\u0449\u0438\u0435 \u0438\u043D\u0444\u0440\u0430\u043A\u0440\u0430\u0441\u043D\u043E\u0435 \u0438\u0437\u043B\u0443\u0447\u0435\u043D\u0438\u0435 \u0442\u0451\u043F\u043B\u043E\u0439 \u0434\u043E\u0431\u044B\u0447\u0438", 3, ["jamki policzkowe"], ["\u0442\u0435\u0440\u043C\u043E\u043B\u043E\u043A\u0430\u0442\u043E\u0440\u044B"]],
  ["echolokacja", "echolokacja", "\u044D\u0445\u043E\u043B\u043E\u043A\u0430\u0446\u0438\u044F", "okre\u015Blanie po\u0142o\u017Cenia przeszk\xF3d i ofiar na podstawie ech wysy\u0142anych ultrad\u017Awi\u0119k\xF3w, u nietoperzy i delfin\xF3w", "\u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u043F\u0440\u0435\u043F\u044F\u0442\u0441\u0442\u0432\u0438\u0439 \u0438 \u0434\u043E\u0431\u044B\u0447\u0438 \u043F\u043E \u044D\u0445\u0443 \u0438\u0441\u043F\u0443\u0441\u043A\u0430\u0435\u043C\u044B\u0445 \u0443\u043B\u044C\u0442\u0440\u0430\u0437\u0432\u0443\u043A\u043E\u0432, \u0443 \u043B\u0435\u0442\u0443\u0447\u0438\u0445 \u043C\u044B\u0448\u0435\u0439 \u0438 \u0434\u0435\u043B\u044C\u0444\u0438\u043D\u043E\u0432", 1, [], []],
  ["statocysty", "statocysty", "\u0441\u0442\u0430\u0442\u043E\u0446\u0438\u0441\u0442\u044B", "p\u0119cherzyki z ziarenkami odbieraj\u0105ce po\u0142o\u017Cenie cia\u0142a wzgl\u0119dem si\u0142y ci\u0119\u017Cko\u015Bci, np. u meduz i rak\xF3w", "\u043F\u0443\u0437\u044B\u0440\u044C\u043A\u0438 \u0441 \u043A\u0440\u0443\u043F\u0438\u043D\u043A\u0430\u043C\u0438, \u0432\u043E\u0441\u043F\u0440\u0438\u043D\u0438\u043C\u0430\u044E\u0449\u0438\u0435 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0442\u0435\u043B\u0430 \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u0441\u0438\u043B\u044B \u0442\u044F\u0436\u0435\u0441\u0442\u0438, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0443 \u043C\u0435\u0434\u0443\u0437 \u0438 \u0440\u0430\u043A\u043E\u0432", 2, [], []],
  ["blona-odblaskowa", "b\u0142ona odblaskowa", "\u0442\u0430\u043F\u0435\u0442\u0443\u043C", "warstwa za siatk\xF3wk\u0105 odbijaj\u0105ca \u015Bwiat\u0142o, poprawiaj\u0105ca widzenie w nocy, np. u kot\xF3w", "\u0441\u043B\u043E\u0439 \u0437\u0430 \u0441\u0435\u0442\u0447\u0430\u0442\u043A\u043E\u0439, \u043E\u0442\u0440\u0430\u0436\u0430\u044E\u0449\u0438\u0439 \u0441\u0432\u0435\u0442 \u0438 \u0443\u043B\u0443\u0447\u0448\u0430\u044E\u0449\u0438\u0439 \u043D\u043E\u0447\u043D\u043E\u0435 \u0437\u0440\u0435\u043D\u0438\u0435, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0443 \u043A\u043E\u0448\u0435\u043A", 3, ["tapetum lucidum"], ["\u043E\u0442\u0440\u0430\u0436\u0430\u044E\u0449\u0438\u0439 \u0441\u043B\u043E\u0439"]]
]);
var ANIMAL_HORMONES = namedTable(P.hormones.animals, [
  ["ekdyzon", "ekdyzon", "\u044D\u043A\u0434\u0438\u0437\u043E\u043D", "hormon stawonog\xF3w wywo\u0142uj\u0105cy linienie i przeobra\u017Cenie", "\u0433\u043E\u0440\u043C\u043E\u043D \u0447\u043B\u0435\u043D\u0438\u0441\u0442\u043E\u043D\u043E\u0433\u0438\u0445, \u0432\u044B\u0437\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u043B\u0438\u043D\u044C\u043A\u0443 \u0438 \u043F\u0440\u0435\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435", 2, [], []],
  ["juwenilny", "hormon juwenilny", "\u044E\u0432\u0435\u043D\u0438\u043B\u044C\u043D\u044B\u0439 \u0433\u043E\u0440\u043C\u043E\u043D", "hormon owad\xF3w utrzymuj\u0105cy cechy larwalne; spadek jego st\u0119\u017Cenia pozwala na przeobra\u017Cenie w posta\u0107 doros\u0142\u0105", "\u0433\u043E\u0440\u043C\u043E\u043D \u043D\u0430\u0441\u0435\u043A\u043E\u043C\u044B\u0445, \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0449\u0438\u0439 \u043B\u0438\u0447\u0438\u043D\u043E\u0447\u043D\u044B\u0435 \u0447\u0435\u0440\u0442\u044B; \u0441\u043D\u0438\u0436\u0435\u043D\u0438\u0435 \u0435\u0433\u043E \u0443\u0440\u043E\u0432\u043D\u044F \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u043F\u0440\u0435\u0432\u0440\u0430\u0442\u0438\u0442\u044C\u0441\u044F \u0432\u043E \u0432\u0437\u0440\u043E\u0441\u043B\u0443\u044E \u0444\u043E\u0440\u043C\u0443", 2, [], []],
  ["gruczoly-przedpiersiowe", "gruczo\u0142y przedpiersiowe", "\u043F\u0440\u043E\u0442\u043E\u0440\u0430\u043A\u0430\u043B\u044C\u043D\u044B\u0435 \u0436\u0435\u043B\u0435\u0437\u044B", "gruczo\u0142y owad\xF3w wydzielaj\u0105ce ekdyzon", "\u0436\u0435\u043B\u0435\u0437\u044B \u043D\u0430\u0441\u0435\u043A\u043E\u043C\u044B\u0445, \u0432\u044B\u0434\u0435\u043B\u044F\u044E\u0449\u0438\u0435 \u044D\u043A\u0434\u0438\u0437\u043E\u043D", 3, [], ["\u043F\u0435\u0440\u0435\u0434\u043D\u0435\u0433\u0440\u0443\u0434\u043D\u044B\u0435 \u0436\u0435\u043B\u0435\u0437\u044B"]],
  ["neurosekrecyjne", "kom\xF3rki neurosekrecyjne", "\u043D\u0435\u0439\u0440\u043E\u0441\u0435\u043A\u0440\u0435\u0442\u043E\u0440\u043D\u044B\u0435 \u043A\u043B\u0435\u0442\u043A\u0438", "neurony wydzielaj\u0105ce hormony do p\u0142yn\xF3w ustrojowych, wyst\u0119puj\u0105ce u bezkr\u0119gowc\xF3w i w podwzg\xF3rzu", "\u043D\u0435\u0439\u0440\u043E\u043D\u044B, \u0432\u044B\u0434\u0435\u043B\u044F\u044E\u0449\u0438\u0435 \u0433\u043E\u0440\u043C\u043E\u043D\u044B \u0432 \u0436\u0438\u0434\u043A\u043E\u0441\u0442\u0438 \u0442\u0435\u043B\u0430, \u2014 \u0443 \u0431\u0435\u0441\u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u044B\u0445 \u0438 \u0432 \u0433\u0438\u043F\u043E\u0442\u0430\u043B\u0430\u043C\u0443\u0441\u0435", 2, ["neurony neurosekrecyjne"], []],
  ["feromony", "feromony", "\u0444\u0435\u0440\u043E\u043C\u043E\u043D\u044B", "substancje wydzielane na zewn\u0105trz cia\u0142a, wp\u0142ywaj\u0105ce na zachowanie osobnik\xF3w tego samego gatunku", "\u0432\u0435\u0449\u0435\u0441\u0442\u0432\u0430, \u0432\u044B\u0434\u0435\u043B\u044F\u0435\u043C\u044B\u0435 \u0432\u043E \u0432\u043D\u0435\u0448\u043D\u044E\u044E \u0441\u0440\u0435\u0434\u0443 \u0438 \u0432\u043B\u0438\u044F\u044E\u0449\u0438\u0435 \u043D\u0430 \u043F\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435 \u043E\u0441\u043E\u0431\u0435\u0439 \u0442\u043E\u0433\u043E \u0436\u0435 \u0432\u0438\u0434\u0430", 1, [], []],
  ["tyroksyna-plazy", "tyroksyna", "\u0442\u0438\u0440\u043E\u043A\u0441\u0438\u043D", "hormon tarczycy, kt\xF3ry u kijanki wywo\u0142uje przeobra\u017Cenie w doros\u0142\u0105 \u017Cab\u0119", "\u0433\u043E\u0440\u043C\u043E\u043D \u0449\u0438\u0442\u043E\u0432\u0438\u0434\u043D\u043E\u0439 \u0436\u0435\u043B\u0435\u0437\u044B, \u0432\u044B\u0437\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u0443 \u0433\u043E\u043B\u043E\u0432\u0430\u0441\u0442\u0438\u043A\u0430 \u043F\u0440\u0435\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u0432\u043E \u0432\u0437\u0440\u043E\u0441\u043B\u0443\u044E \u043B\u044F\u0433\u0443\u0448\u043A\u0443", 2, ["T4"], ["\u04224"]],
  ["melatonina-zwierzeta", "melatonina", "\u043C\u0435\u043B\u0430\u0442\u043E\u043D\u0438\u043D", "hormon szyszynki reguluj\u0105cy rytm dobowy i sezonowy, np. okres godowy i wymian\u0119 futra", "\u0433\u043E\u0440\u043C\u043E\u043D \u044D\u043F\u0438\u0444\u0438\u0437\u0430, \u0440\u0435\u0433\u0443\u043B\u0438\u0440\u0443\u044E\u0449\u0438\u0439 \u0441\u0443\u0442\u043E\u0447\u043D\u044B\u0435 \u0438 \u0441\u0435\u0437\u043E\u043D\u043D\u044B\u0435 \u0440\u0438\u0442\u043C\u044B, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0431\u0440\u0430\u0447\u043D\u044B\u0439 \u043F\u0435\u0440\u0438\u043E\u0434 \u0438 \u043B\u0438\u043D\u044C\u043A\u0443 \u043C\u0435\u0445\u0430", 2, [], []]
]);
var ANIMAL_REPRODUCTION = namedTable(P.reproduction.animals, [
  ["partenogeneza", "partenogeneza", "\u043F\u0430\u0440\u0442\u0435\u043D\u043E\u0433\u0435\u043D\u0435\u0437", "rozw\xF3j nowego osobnika z niezap\u0142odnionej kom\xF3rki jajowej, np. u mszyc i trutni", "\u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u043D\u043E\u0432\u043E\u0439 \u043E\u0441\u043E\u0431\u0438 \u0438\u0437 \u043D\u0435\u043E\u043F\u043B\u043E\u0434\u043E\u0442\u0432\u043E\u0440\u0451\u043D\u043D\u043E\u0439 \u044F\u0439\u0446\u0435\u043A\u043B\u0435\u0442\u043A\u0438, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0443 \u0442\u043B\u0435\u0439 \u0438 \u0442\u0440\u0443\u0442\u043D\u0435\u0439", 2, ["dziewor\xF3dztwo"], ["\u0434\u0435\u0432\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0435 \u0440\u0430\u0437\u043C\u043D\u043E\u0436\u0435\u043D\u0438\u0435"]],
  ["paczkowanie", "p\u0105czkowanie", "\u043F\u043E\u0447\u043A\u043E\u0432\u0430\u043D\u0438\u0435", "rozmna\u017Canie bezp\u0142ciowe, w kt\xF3rym nowy osobnik wyrasta z cia\u0142a rodzica, np. u stu\u0142bi", "\u0431\u0435\u0441\u043F\u043E\u043B\u043E\u0435 \u0440\u0430\u0437\u043C\u043D\u043E\u0436\u0435\u043D\u0438\u0435, \u043F\u0440\u0438 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u043D\u043E\u0432\u0430\u044F \u043E\u0441\u043E\u0431\u044C \u0432\u044B\u0440\u0430\u0441\u0442\u0430\u0435\u0442 \u0438\u0437 \u0442\u0435\u043B\u0430 \u0440\u043E\u0434\u0438\u0442\u0435\u043B\u044F, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0443 \u0433\u0438\u0434\u0440\u044B", 1, [], []],
  ["fragmentacja", "fragmentacja", "\u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442\u0430\u0446\u0438\u044F", "rozpad cia\u0142a na cz\u0119\u015Bci, z kt\xF3rych ka\u017Cda odtwarza ca\u0142y organizm, np. u wyp\u0142awka", "\u0440\u0430\u0441\u043F\u0430\u0434 \u0442\u0435\u043B\u0430 \u043D\u0430 \u0447\u0430\u0441\u0442\u0438, \u043A\u0430\u0436\u0434\u0430\u044F \u0438\u0437 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442 \u0446\u0435\u043B\u044B\u0439 \u043E\u0440\u0433\u0430\u043D\u0438\u0437\u043C, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0443 \u043F\u043B\u0430\u043D\u0430\u0440\u0438\u0438", 2, [], []],
  ["obojnactwo", "obojnactwo", "\u0433\u0435\u0440\u043C\u0430\u0444\u0440\u043E\u0434\u0438\u0442\u0438\u0437\u043C", "obecno\u015B\u0107 m\u0119skich i \u017Ce\u0144skich narz\u0105d\xF3w rozrodczych w jednym osobniku, np. u d\u017Cd\u017Cownicy", "\u043D\u0430\u043B\u0438\u0447\u0438\u0435 \u043C\u0443\u0436\u0441\u043A\u0438\u0445 \u0438 \u0436\u0435\u043D\u0441\u043A\u0438\u0445 \u043F\u043E\u043B\u043E\u0432\u044B\u0445 \u043E\u0440\u0433\u0430\u043D\u043E\u0432 \u0443 \u043E\u0434\u043D\u043E\u0439 \u043E\u0441\u043E\u0431\u0438, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0443 \u0434\u043E\u0436\u0434\u0435\u0432\u043E\u0433\u043E \u0447\u0435\u0440\u0432\u044F", 1, ["hermafrodytyzm"], []],
  ["zaplodnienie-zewnetrzne", "zap\u0142odnienie zewn\u0119trzne", "\u043D\u0430\u0440\u0443\u0436\u043D\u043E\u0435 \u043E\u043F\u043B\u043E\u0434\u043E\u0442\u0432\u043E\u0440\u0435\u043D\u0438\u0435", "\u0142\u0105czenie si\u0119 gamet poza cia\u0142em samicy, w wodzie, np. u wi\u0119kszo\u015Bci ryb i p\u0142az\xF3w", "\u0441\u043B\u0438\u044F\u043D\u0438\u0435 \u0433\u0430\u043C\u0435\u0442 \u0432\u043D\u0435 \u0442\u0435\u043B\u0430 \u0441\u0430\u043C\u043A\u0438, \u0432 \u0432\u043E\u0434\u0435, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0443 \u0431\u043E\u043B\u044C\u0448\u0438\u043D\u0441\u0442\u0432\u0430 \u0440\u044B\u0431 \u0438 \u0437\u0435\u043C\u043D\u043E\u0432\u043E\u0434\u043D\u044B\u0445", 1, [], []],
  ["zaplodnienie-wewnetrzne", "zap\u0142odnienie wewn\u0119trzne", "\u0432\u043D\u0443\u0442\u0440\u0435\u043D\u043D\u0435\u0435 \u043E\u043F\u043B\u043E\u0434\u043E\u0442\u0432\u043E\u0440\u0435\u043D\u0438\u0435", "\u0142\u0105czenie si\u0119 gamet w drogach rodnych samicy, typowe dla zwierz\u0105t l\u0105dowych", "\u0441\u043B\u0438\u044F\u043D\u0438\u0435 \u0433\u0430\u043C\u0435\u0442 \u0432 \u043F\u043E\u043B\u043E\u0432\u044B\u0445 \u043F\u0443\u0442\u044F\u0445 \u0441\u0430\u043C\u043A\u0438, \u0445\u0430\u0440\u0430\u043A\u0442\u0435\u0440\u043D\u043E\u0435 \u0434\u043B\u044F \u043D\u0430\u0437\u0435\u043C\u043D\u044B\u0445 \u0436\u0438\u0432\u043E\u0442\u043D\u044B\u0445", 1, [], []],
  ["jajorodnosc", "jajorodno\u015B\u0107", "\u044F\u0439\u0446\u0435\u043A\u043B\u0430\u0434\u043D\u043E\u0441\u0442\u044C", "sk\u0142adanie jaj, w kt\xF3rych zarodek rozwija si\u0119 poza cia\u0142em matki", "\u043E\u0442\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u0435 \u044F\u0438\u0446, \u0432 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0437\u0430\u0440\u043E\u0434\u044B\u0448 \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0432\u043D\u0435 \u0442\u0435\u043B\u0430 \u043C\u0430\u0442\u0435\u0440\u0438", 2, [], ["\u044F\u0439\u0446\u0435\u0440\u043E\u0436\u0434\u0435\u043D\u0438\u0435"]],
  ["zyworodnosc", "\u017Cyworodno\u015B\u0107", "\u0436\u0438\u0432\u043E\u0440\u043E\u0436\u0434\u0435\u043D\u0438\u0435", "rodzenie m\u0142odych, kt\xF3re rozwija\u0142y si\u0119 w ciele matki i by\u0142y przez ni\u0105 od\u017Cywiane", "\u0440\u043E\u0436\u0434\u0435\u043D\u0438\u0435 \u0434\u0435\u0442\u0451\u043D\u044B\u0448\u0435\u0439, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u043B\u0438\u0441\u044C \u0432 \u0442\u0435\u043B\u0435 \u043C\u0430\u0442\u0435\u0440\u0438 \u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u043B\u0438 \u043E\u0442 \u043D\u0435\u0451 \u043F\u0438\u0442\u0430\u043D\u0438\u0435", 2, [], []],
  ["rozwoj-zlozony", "rozw\xF3j z\u0142o\u017Cony", "\u043D\u0435\u043F\u0440\u044F\u043C\u043E\u0435 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435", "rozw\xF3j, w kt\xF3rym z jaja wyl\u0119ga si\u0119 larwa wyra\u017Anie r\xF3\u017Cni\u0105ca si\u0119 od postaci doros\u0142ej", "\u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435, \u043F\u0440\u0438 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u0438\u0437 \u044F\u0439\u0446\u0430 \u0432\u044B\u0445\u043E\u0434\u0438\u0442 \u043B\u0438\u0447\u0438\u043D\u043A\u0430, \u0437\u0430\u043C\u0435\u0442\u043D\u043E \u043E\u0442\u043B\u0438\u0447\u0430\u044E\u0449\u0430\u044F\u0441\u044F \u043E\u0442 \u0432\u0437\u0440\u043E\u0441\u043B\u043E\u0439 \u0444\u043E\u0440\u043C\u044B", 2, ["rozw\xF3j po\u015Bredni", "rozw\xF3j z przeobra\u017Ceniem"], ["\u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u0441 \u043F\u0440\u0435\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435\u043C"]],
  ["blony-plodowe", "b\u0142ony p\u0142odowe", "\u0437\u0430\u0440\u043E\u0434\u044B\u0448\u0435\u0432\u044B\u0435 \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0438", "owodnia, kosm\xF3wka i omocznia \u2014 b\u0142ony chroni\u0105ce zarodek gad\xF3w, ptak\xF3w i ssak\xF3w", "\u0430\u043C\u043D\u0438\u043E\u043D, \u0445\u043E\u0440\u0438\u043E\u043D \u0438 \u0430\u043B\u043B\u0430\u043D\u0442\u043E\u0438\u0441 \u2014 \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0438, \u0437\u0430\u0449\u0438\u0449\u0430\u044E\u0449\u0438\u0435 \u0437\u0430\u0440\u043E\u0434\u044B\u0448 \u043F\u0440\u0435\u0441\u043C\u044B\u043A\u0430\u044E\u0449\u0438\u0445\u0441\u044F, \u043F\u0442\u0438\u0446 \u0438 \u043C\u043B\u0435\u043A\u043E\u043F\u0438\u0442\u0430\u044E\u0449\u0438\u0445", 2, ["b\u0142ony zarodkowe"], []]
]);

// packages/trainers/bio/src/server/templates/data/disorders.ts
var MOTION_DISORDERS = disorderTable(P.motion.disorders, [
  ["zlamanie", "z\u0142amanie ko\u015Bci", "\u043F\u0435\u0440\u0435\u043B\u043E\u043C \u043A\u043E\u0441\u0442\u0438", "injury", "uraz mechaniczny przekraczaj\u0105cy wytrzyma\u0142o\u015B\u0107 ko\u015Bci", "\u043C\u0435\u0445\u0430\u043D\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u0442\u0440\u0430\u0432\u043C\u0430, \u043F\u0440\u0435\u0432\u044B\u0448\u0430\u044E\u0449\u0430\u044F \u043F\u0440\u043E\u0447\u043D\u043E\u0441\u0442\u044C \u043A\u043E\u0441\u0442\u0438", "przerwanie ci\u0105g\u0142o\u015Bci ko\u015Bci, silny b\xF3l, obrz\u0119k i nienaturalne ustawienie ko\u0144czyny", "\u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u0435 \u0446\u0435\u043B\u043E\u0441\u0442\u043D\u043E\u0441\u0442\u0438 \u043A\u043E\u0441\u0442\u0438, \u0441\u0438\u043B\u044C\u043D\u0430\u044F \u0431\u043E\u043B\u044C, \u043E\u0442\u0451\u043A \u0438 \u043D\u0435\u0435\u0441\u0442\u0435\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0435 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043A\u043E\u043D\u0435\u0447\u043D\u043E\u0441\u0442\u0438", 1, ["z\u0142amanie"], ["\u043F\u0435\u0440\u0435\u043B\u043E\u043C"]],
  ["zwichniecie", "zwichni\u0119cie", "\u0432\u044B\u0432\u0438\u0445", "injury", "gwa\u0142towny ruch poza zakres ruchomo\u015Bci stawu, po kt\xF3rym powierzchnie stawowe nie wracaj\u0105 na swoje miejsce", "\u0440\u0435\u0437\u043A\u043E\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0437\u0430 \u043F\u0440\u0435\u0434\u0435\u043B\u044B \u043F\u043E\u0434\u0432\u0438\u0436\u043D\u043E\u0441\u0442\u0438 \u0441\u0443\u0441\u0442\u0430\u0432\u0430, \u043F\u043E\u0441\u043B\u0435 \u043A\u043E\u0442\u043E\u0440\u043E\u0433\u043E \u0441\u0443\u0441\u0442\u0430\u0432\u043D\u044B\u0435 \u043F\u043E\u0432\u0435\u0440\u0445\u043D\u043E\u0441\u0442\u0438 \u043D\u0435 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F \u043D\u0430 \u043C\u0435\u0441\u0442\u043E", "przemieszczenie powierzchni stawowych, zniekszta\u0142cenie stawu i brak mo\u017Cliwo\u015Bci ruchu", "\u0441\u043C\u0435\u0449\u0435\u043D\u0438\u0435 \u0441\u0443\u0441\u0442\u0430\u0432\u043D\u044B\u0445 \u043F\u043E\u0432\u0435\u0440\u0445\u043D\u043E\u0441\u0442\u0435\u0439, \u0434\u0435\u0444\u043E\u0440\u043C\u0430\u0446\u0438\u044F \u0441\u0443\u0441\u0442\u0430\u0432\u0430 \u0438 \u043D\u0435\u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u044C \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F", 1, [], []],
  ["skrecenie", "skr\u0119cenie stawu", "\u0440\u0430\u0441\u0442\u044F\u0436\u0435\u043D\u0438\u0435 \u0441\u0432\u044F\u0437\u043E\u043A", "injury", "nag\u0142e wykr\u0119cenie stawu, np. skokowego, po kt\xF3rym powierzchnie stawowe wracaj\u0105 na swoje miejsce", "\u0432\u043D\u0435\u0437\u0430\u043F\u043D\u043E\u0435 \u043F\u043E\u0434\u0432\u043E\u0440\u0430\u0447\u0438\u0432\u0430\u043D\u0438\u0435 \u0441\u0443\u0441\u0442\u0430\u0432\u0430, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0433\u043E\u043B\u0435\u043D\u043E\u0441\u0442\u043E\u043F\u043D\u043E\u0433\u043E, \u043F\u043E\u0441\u043B\u0435 \u043A\u043E\u0442\u043E\u0440\u043E\u0433\u043E \u0441\u0443\u0441\u0442\u0430\u0432\u043D\u044B\u0435 \u043F\u043E\u0432\u0435\u0440\u0445\u043D\u043E\u0441\u0442\u0438 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F \u043D\u0430 \u043C\u0435\u0441\u0442\u043E", "naderwanie wi\u0119zade\u0142, b\xF3l i obrz\u0119k stawu bez przemieszczenia ko\u015Bci", "\u043D\u0430\u0434\u0440\u044B\u0432 \u0441\u0432\u044F\u0437\u043E\u043A, \u0431\u043E\u043B\u044C \u0438 \u043E\u0442\u0451\u043A \u0441\u0443\u0441\u0442\u0430\u0432\u0430 \u0431\u0435\u0437 \u0441\u043C\u0435\u0449\u0435\u043D\u0438\u044F \u043A\u043E\u0441\u0442\u0435\u0439", 1, ["skr\u0119cenie"], ["\u0440\u0430\u0441\u0442\u044F\u0436\u0435\u043D\u0438\u0435"]],
  ["skolioza", "skolioza", "\u0441\u043A\u043E\u043B\u0438\u043E\u0437", "posture", "d\u0142ugotrwa\u0142a nieprawid\u0142owa postawa i nier\xF3wnomierne obci\u0105\u017Canie kr\u0119gos\u0142upa w okresie wzrostu", "\u0434\u043B\u0438\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u043D\u0435\u043F\u0440\u0430\u0432\u0438\u043B\u044C\u043D\u0430\u044F \u043E\u0441\u0430\u043D\u043A\u0430 \u0438 \u043D\u0435\u0440\u0430\u0432\u043D\u043E\u043C\u0435\u0440\u043D\u0430\u044F \u043D\u0430\u0433\u0440\u0443\u0437\u043A\u0430 \u043D\u0430 \u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u0438\u043A \u0432 \u043F\u0435\u0440\u0438\u043E\u0434 \u0440\u043E\u0441\u0442\u0430", "boczne skrzywienie kr\u0119gos\u0142upa, nier\xF3wno ustawione barki i \u0142opatki", "\u0431\u043E\u043A\u043E\u0432\u043E\u0435 \u0438\u0441\u043A\u0440\u0438\u0432\u043B\u0435\u043D\u0438\u0435 \u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u0438\u043A\u0430, \u0440\u0430\u0437\u043D\u0430\u044F \u0432\u044B\u0441\u043E\u0442\u0430 \u043F\u043B\u0435\u0447 \u0438 \u043B\u043E\u043F\u0430\u0442\u043E\u043A", 1, [], []],
  ["kifoza", "pog\u0142\u0119biona kifoza", "\u0433\u0438\u043F\u0435\u0440\u043A\u0438\u0444\u043E\u0437", "posture", "garbienie si\u0119 i s\u0142abe mi\u0119\u015Bnie grzbietu", "\u0441\u0443\u0442\u0443\u043B\u043E\u0441\u0442\u044C \u0438 \u0441\u043B\u0430\u0431\u044B\u0435 \u043C\u044B\u0448\u0446\u044B \u0441\u043F\u0438\u043D\u044B", "nadmierne wygi\u0119cie kr\u0119gos\u0142upa piersiowego ku ty\u0142owi \u2014 plecy okr\u0105g\u0142e", "\u0447\u0440\u0435\u0437\u043C\u0435\u0440\u043D\u044B\u0439 \u0438\u0437\u0433\u0438\u0431 \u0433\u0440\u0443\u0434\u043D\u043E\u0433\u043E \u043E\u0442\u0434\u0435\u043B\u0430 \u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u0438\u043A\u0430 \u043D\u0430\u0437\u0430\u0434 \u2014 \u043A\u0440\u0443\u0433\u043B\u0430\u044F \u0441\u043F\u0438\u043D\u0430", 2, ["plecy okr\u0105g\u0142e", "kifoza"], ["\u043A\u0440\u0443\u0433\u043B\u0430\u044F \u0441\u043F\u0438\u043D\u0430", "\u043A\u0438\u0444\u043E\u0437"]],
  ["lordoza", "pog\u0142\u0119biona lordoza", "\u0433\u0438\u043F\u0435\u0440\u043B\u043E\u0440\u0434\u043E\u0437", "posture", "s\u0142abe mi\u0119\u015Bnie brzucha, nadwaga i cz\u0119ste chodzenie w butach na wysokim obcasie", "\u0441\u043B\u0430\u0431\u044B\u0435 \u043C\u044B\u0448\u0446\u044B \u0436\u0438\u0432\u043E\u0442\u0430, \u043B\u0438\u0448\u043D\u0438\u0439 \u0432\u0435\u0441 \u0438 \u0447\u0430\u0441\u0442\u0430\u044F \u0445\u043E\u0434\u044C\u0431\u0430 \u043D\u0430 \u0432\u044B\u0441\u043E\u043A\u0438\u0445 \u043A\u0430\u0431\u043B\u0443\u043A\u0430\u0445", "nadmierne wygi\u0119cie odcinka l\u0119d\u017Awiowego kr\u0119gos\u0142upa ku przodowi \u2014 plecy wkl\u0119s\u0142e", "\u0447\u0440\u0435\u0437\u043C\u0435\u0440\u043D\u044B\u0439 \u0438\u0437\u0433\u0438\u0431 \u043F\u043E\u044F\u0441\u043D\u0438\u0447\u043D\u043E\u0433\u043E \u043E\u0442\u0434\u0435\u043B\u0430 \u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u0438\u043A\u0430 \u0432\u043F\u0435\u0440\u0451\u0434 \u2014 \u043F\u0440\u043E\u0433\u043D\u0443\u0442\u0430\u044F \u043F\u043E\u044F\u0441\u043D\u0438\u0446\u0430", 2, ["plecy wkl\u0119s\u0142e", "lordoza"], ["\u043B\u043E\u0440\u0434\u043E\u0437"]],
  ["plaskostopie", "p\u0142askostopie", "\u043F\u043B\u043E\u0441\u043A\u043E\u0441\u0442\u043E\u043F\u0438\u0435", "posture", "os\u0142abienie mi\u0119\u015Bni i wi\u0119zade\u0142 utrzymuj\u0105cych wysklepienie stopy", "\u043E\u0441\u043B\u0430\u0431\u043B\u0435\u043D\u0438\u0435 \u043C\u044B\u0448\u0446 \u0438 \u0441\u0432\u044F\u0437\u043E\u043A, \u0443\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u044E\u0449\u0438\u0445 \u0441\u0432\u043E\u0434 \u0441\u0442\u043E\u043F\u044B", "obni\u017Cenie \u0142uku pod\u0142u\u017Cnego stopy i b\xF3l st\xF3p przy d\u0142u\u017Cszym chodzeniu", "\u043E\u043F\u0443\u0449\u0435\u043D\u0438\u0435 \u043F\u0440\u043E\u0434\u043E\u043B\u044C\u043D\u043E\u0433\u043E \u0441\u0432\u043E\u0434\u0430 \u0441\u0442\u043E\u043F\u044B \u0438 \u0431\u043E\u043B\u044C \u0432 \u0441\u0442\u043E\u043F\u0430\u0445 \u043F\u0440\u0438 \u0434\u043E\u043B\u0433\u043E\u0439 \u0445\u043E\u0434\u044C\u0431\u0435", 1, [], []],
  ["krzywica", "krzywica", "\u0440\u0430\u0445\u0438\u0442", "deficiency", "niedob\xF3r witaminy D u dzieci, zaburzaj\u0105cy uwapnienie ko\u015Bci", "\u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u043A \u0432\u0438\u0442\u0430\u043C\u0438\u043D\u0430 D \u0443 \u0434\u0435\u0442\u0435\u0439, \u043D\u0430\u0440\u0443\u0448\u0430\u044E\u0449\u0438\u0439 \u043C\u0438\u043D\u0435\u0440\u0430\u043B\u0438\u0437\u0430\u0446\u0438\u044E \u043A\u043E\u0441\u0442\u0435\u0439", "mi\u0119kkie, wygi\u0119te ko\u015Bci ko\u0144czyn i zniekszta\u0142cona klatka piersiowa", "\u043C\u044F\u0433\u043A\u0438\u0435, \u0438\u0441\u043A\u0440\u0438\u0432\u043B\u0451\u043D\u043D\u044B\u0435 \u043A\u043E\u0441\u0442\u0438 \u043A\u043E\u043D\u0435\u0447\u043D\u043E\u0441\u0442\u0435\u0439 \u0438 \u0434\u0435\u0444\u043E\u0440\u043C\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u0430\u044F \u0433\u0440\u0443\u0434\u043D\u0430\u044F \u043A\u043B\u0435\u0442\u043A\u0430", 1, [], []],
  ["osteoporoza", "osteoporoza", "\u043E\u0441\u0442\u0435\u043E\u043F\u043E\u0440\u043E\u0437", "metabolic", "przewaga niszczenia ko\u015Bci nad jej odbudow\u0105, m.in. po menopauzie przy spadku st\u0119\u017Cenia estrogen\xF3w", "\u043F\u0440\u0435\u043E\u0431\u043B\u0430\u0434\u0430\u043D\u0438\u0435 \u0440\u0430\u0437\u0440\u0443\u0448\u0435\u043D\u0438\u044F \u043A\u043E\u0441\u0442\u0438 \u043D\u0430\u0434 \u0435\u0451 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435\u043C, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u043F\u043E\u0441\u043B\u0435 \u043C\u0435\u043D\u043E\u043F\u0430\u0443\u0437\u044B \u043F\u0440\u0438 \u0441\u043D\u0438\u0436\u0435\u043D\u0438\u0438 \u0443\u0440\u043E\u0432\u043D\u044F \u044D\u0441\u0442\u0440\u043E\u0433\u0435\u043D\u043E\u0432", "kruche ko\u015Bci \u0142ami\u0105ce si\u0119 przy niewielkich urazach, zw\u0142aszcza u starszych kobiet", "\u0445\u0440\u0443\u043F\u043A\u0438\u0435 \u043A\u043E\u0441\u0442\u0438, \u043B\u043E\u043C\u0430\u044E\u0449\u0438\u0435\u0441\u044F \u043F\u0440\u0438 \u043D\u0435\u0437\u043D\u0430\u0447\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0442\u0440\u0430\u0432\u043C\u0430\u0445, \u043E\u0441\u043E\u0431\u0435\u043D\u043D\u043E \u0443 \u043F\u043E\u0436\u0438\u043B\u044B\u0445 \u0436\u0435\u043D\u0449\u0438\u043D", 1, [], []],
  ["dyskopatia", "dyskopatia", "\u043C\u0435\u0436\u043F\u043E\u0437\u0432\u043E\u043D\u043A\u043E\u0432\u0430\u044F \u0433\u0440\u044B\u0436\u0430", "degenerative", "zwyrodnienie kr\u0105\u017Cka mi\u0119dzykr\u0119gowego, kt\xF3rego przemieszczone j\u0105dro mia\u017Cd\u017Cyste uciska korzenie nerw\xF3w rdzeniowych", "\u0434\u0435\u0433\u0435\u043D\u0435\u0440\u0430\u0446\u0438\u044F \u043C\u0435\u0436\u043F\u043E\u0437\u0432\u043E\u043D\u043A\u043E\u0432\u043E\u0433\u043E \u0434\u0438\u0441\u043A\u0430, \u0441\u043C\u0435\u0449\u0451\u043D\u043D\u043E\u0435 \u043F\u0443\u043B\u044C\u043F\u043E\u0437\u043D\u043E\u0435 \u044F\u0434\u0440\u043E \u043A\u043E\u0442\u043E\u0440\u043E\u0433\u043E \u0434\u0430\u0432\u0438\u0442 \u043D\u0430 \u043A\u043E\u0440\u0435\u0448\u043A\u0438 \u0441\u043F\u0438\u043D\u043D\u043E\u043C\u043E\u0437\u0433\u043E\u0432\u044B\u0445 \u043D\u0435\u0440\u0432\u043E\u0432", "b\xF3l plec\xF3w promieniuj\u0105cy do nogi i dr\u0119twienie ko\u0144czyny", "\u0431\u043E\u043B\u044C \u0432 \u0441\u043F\u0438\u043D\u0435, \u043E\u0442\u0434\u0430\u044E\u0449\u0430\u044F \u0432 \u043D\u043E\u0433\u0443, \u0438 \u043E\u043D\u0435\u043C\u0435\u043D\u0438\u0435 \u043A\u043E\u043D\u0435\u0447\u043D\u043E\u0441\u0442\u0438", 2, ["przepuklina kr\u0105\u017Cka mi\u0119dzykr\u0119gowego"], ["\u0433\u0440\u044B\u0436\u0430 \u0434\u0438\u0441\u043A\u0430", "\u043E\u0441\u0442\u0435\u043E\u0445\u043E\u043D\u0434\u0440\u043E\u0437"]],
  ["duchenne", "dystrofia mi\u0119\u015Bniowa Duchenne'a", "\u043C\u0438\u043E\u0434\u0438\u0441\u0442\u0440\u043E\u0444\u0438\u044F \u0414\u044E\u0448\u0435\u043D\u043D\u0430", "genetic", "mutacja genu dystrofiny le\u017C\u0105cego na chromosomie X", "\u043C\u0443\u0442\u0430\u0446\u0438\u044F \u0433\u0435\u043D\u0430 \u0434\u0438\u0441\u0442\u0440\u043E\u0444\u0438\u043D\u0430, \u0440\u0430\u0441\u043F\u043E\u043B\u043E\u0436\u0435\u043D\u043D\u043E\u0433\u043E \u0432 X-\u0445\u0440\u043E\u043C\u043E\u0441\u043E\u043C\u0435", "post\u0119puj\u0105cy zanik i os\u0142abienie mi\u0119\u015Bni u ch\u0142opc\xF3w, od wczesnego dzieci\u0144stwa", "\u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441\u0438\u0440\u0443\u044E\u0449\u0430\u044F \u0430\u0442\u0440\u043E\u0444\u0438\u044F \u0438 \u0441\u043B\u0430\u0431\u043E\u0441\u0442\u044C \u043C\u044B\u0448\u0446 \u0443 \u043C\u0430\u043B\u044C\u0447\u0438\u043A\u043E\u0432 \u0441 \u0440\u0430\u043D\u043D\u0435\u0433\u043E \u0434\u0435\u0442\u0441\u0442\u0432\u0430", 3, ["dystrofia Duchenne'a", "zanik mi\u0119\u015Bni Duchenne'a"], ["\u043C\u044B\u0448\u0435\u0447\u043D\u0430\u044F \u0434\u0438\u0441\u0442\u0440\u043E\u0444\u0438\u044F \u0414\u044E\u0448\u0435\u043D\u043D\u0430"]]
]);
var DIGESTIVE_DISORDERS = disorderTable(P.digestion.disorders, [
  ["prochnica", "pr\xF3chnica z\u0119b\xF3w", "\u043A\u0430\u0440\u0438\u0435\u0441", "bacterial", "kwasy wytwarzane z cukr\xF3w przez bakterie p\u0142ytki naz\u0119bnej", "\u043A\u0438\u0441\u043B\u043E\u0442\u044B, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0431\u0430\u043A\u0442\u0435\u0440\u0438\u0438 \u0437\u0443\u0431\u043D\u043E\u0433\u043E \u043D\u0430\u043B\u0451\u0442\u0430 \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442 \u0438\u0437 \u0441\u0430\u0445\u0430\u0440\u043E\u0432", "ubytki szkliwa i z\u0119biny, b\xF3l z\u0119ba przy s\u0142odkich i zimnych pokarmach", "\u0440\u0430\u0437\u0440\u0443\u0448\u0435\u043D\u0438\u0435 \u044D\u043C\u0430\u043B\u0438 \u0438 \u0434\u0435\u043D\u0442\u0438\u043D\u0430, \u0437\u0443\u0431\u043D\u0430\u044F \u0431\u043E\u043B\u044C \u043E\u0442 \u0441\u043B\u0430\u0434\u043A\u043E\u0433\u043E \u0438 \u0445\u043E\u043B\u043E\u0434\u043D\u043E\u0433\u043E", 1, ["pr\xF3chnica"], ["\u043A\u0430\u0440\u0438\u0435\u0441 \u0437\u0443\u0431\u043E\u0432"]],
  ["wrzody", "choroba wrzodowa \u017Co\u0142\u0105dka i dwunastnicy", "\u044F\u0437\u0432\u0435\u043D\u043D\u0430\u044F \u0431\u043E\u043B\u0435\u0437\u043D\u044C \u0436\u0435\u043B\u0443\u0434\u043A\u0430 \u0438 \u0434\u0432\u0435\u043D\u0430\u0434\u0446\u0430\u0442\u0438\u043F\u0435\u0440\u0441\u0442\u043D\u043E\u0439 \u043A\u0438\u0448\u043A\u0438", "bacterial", "zaka\u017Cenie bakteri\u0105 Helicobacter pylori i nadmiar kwasu solnego uszkadzaj\u0105cy b\u0142on\u0119 \u015Bluzow\u0105", "\u0437\u0430\u0440\u0430\u0436\u0435\u043D\u0438\u0435 \u0431\u0430\u043A\u0442\u0435\u0440\u0438\u0435\u0439 Helicobacter pylori \u0438 \u0438\u0437\u0431\u044B\u0442\u043E\u043A \u0441\u043E\u043B\u044F\u043D\u043E\u0439 \u043A\u0438\u0441\u043B\u043E\u0442\u044B, \u043F\u043E\u0432\u0440\u0435\u0436\u0434\u0430\u044E\u0449\u0438\u0435 \u0441\u043B\u0438\u0437\u0438\u0441\u0442\u0443\u044E \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0443", "b\xF3l w nadbrzuszu, cz\u0119sto na czczo lub w nocy, i zgaga", "\u0431\u043E\u043B\u044C \u0432 \u0432\u0435\u0440\u0445\u043D\u0435\u0439 \u0447\u0430\u0441\u0442\u0438 \u0436\u0438\u0432\u043E\u0442\u0430, \u0447\u0430\u0441\u0442\u043E \u043D\u0430\u0442\u043E\u0449\u0430\u043A \u0438\u043B\u0438 \u043D\u043E\u0447\u044C\u044E, \u0438 \u0438\u0437\u0436\u043E\u0433\u0430", 2, ["wrzody \u017Co\u0142\u0105dka", "wrz\xF3d \u017Co\u0142\u0105dka", "choroba wrzodowa", "choroba wrzodowa \u017Co\u0142\u0105dka", "wrz\xF3d dwunastnicy"], ["\u044F\u0437\u0432\u0430 \u0436\u0435\u043B\u0443\u0434\u043A\u0430", "\u044F\u0437\u0432\u0435\u043D\u043D\u0430\u044F \u0431\u043E\u043B\u0435\u0437\u043D\u044C", "\u044F\u0437\u0432\u0435\u043D\u043D\u0430\u044F \u0431\u043E\u043B\u0435\u0437\u043D\u044C \u0436\u0435\u043B\u0443\u0434\u043A\u0430", "\u044F\u0437\u0432\u0430 \u0434\u0432\u0435\u043D\u0430\u0434\u0446\u0430\u0442\u0438\u043F\u0435\u0440\u0441\u0442\u043D\u043E\u0439 \u043A\u0438\u0448\u043A\u0438"]],
  ["wzw-a", "wirusowe zapalenie w\u0105troby typu A", "\u0433\u0435\u043F\u0430\u0442\u0438\u0442 A", "viral", "wirus przenoszony drog\u0105 pokarmow\u0105 przez brudne r\u0119ce i ska\u017Con\u0105 wod\u0119", "\u0432\u0438\u0440\u0443\u0441, \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0449\u0438\u0439\u0441\u044F \u0447\u0435\u0440\u0435\u0437 \u043F\u0438\u0449\u0443, \u0433\u0440\u044F\u0437\u043D\u044B\u0435 \u0440\u0443\u043A\u0438 \u0438 \u0437\u0430\u0440\u0430\u0436\u0451\u043D\u043D\u0443\u044E \u0432\u043E\u0434\u0443", "za\u017C\xF3\u0142cenie sk\xF3ry i bia\u0142k\xF3wek oczu, ciemny mocz i os\u0142abienie", "\u043F\u043E\u0436\u0435\u043B\u0442\u0435\u043D\u0438\u0435 \u043A\u043E\u0436\u0438 \u0438 \u0431\u0435\u043B\u043A\u043E\u0432 \u0433\u043B\u0430\u0437, \u0442\u0451\u043C\u043D\u0430\u044F \u043C\u043E\u0447\u0430 \u0438 \u0441\u043B\u0430\u0431\u043E\u0441\u0442\u044C", 2, ["WZW A", "\u017C\xF3\u0142taczka pokarmowa"], ["\u0432\u0438\u0440\u0443\u0441\u043D\u044B\u0439 \u0433\u0435\u043F\u0430\u0442\u0438\u0442 A", "\u0431\u043E\u043B\u0435\u0437\u043D\u044C \u0411\u043E\u0442\u043A\u0438\u043D\u0430", "\u0433\u0435\u043F\u0430\u0442\u0438\u0442 \u0410"]],
  ["salmonelloza", "salmonelloza", "\u0441\u0430\u043B\u044C\u043C\u043E\u043D\u0435\u043B\u043B\u0451\u0437", "bacterial", "bakterie z zaka\u017Conych jaj, drobiu i niedogotowanego mi\u0119sa", "\u0431\u0430\u043A\u0442\u0435\u0440\u0438\u0438 \u0438\u0437 \u0437\u0430\u0440\u0430\u0436\u0451\u043D\u043D\u044B\u0445 \u044F\u0438\u0446, \u043F\u0442\u0438\u0446\u044B \u0438 \u043D\u0435\u0434\u043E\u0432\u0430\u0440\u0435\u043D\u043D\u043E\u0433\u043E \u043C\u044F\u0441\u0430", "gor\u0105czka, biegunka, wymioty i b\xF3le brzucha 12\u201336 godzin po posi\u0142ku", "\u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u0430, \u043F\u043E\u043D\u043E\u0441, \u0440\u0432\u043E\u0442\u0430 \u0438 \u0431\u043E\u043B\u0438 \u0432 \u0436\u0438\u0432\u043E\u0442\u0435 \u0447\u0435\u0440\u0435\u0437 12\u201336 \u0447\u0430\u0441\u043E\u0432 \u043F\u043E\u0441\u043B\u0435 \u0435\u0434\u044B", 1, [], ["\u0441\u0430\u043B\u044C\u043C\u043E\u043D\u0435\u043B\u043B\u0435\u0437"]],
  ["glistnica", "glistnica", "\u0430\u0441\u043A\u0430\u0440\u0438\u0434\u043E\u0437", "parasitic", "po\u0142kni\u0119cie jaj glisty ludzkiej z nieumytymi warzywami lub brudnymi r\u0119kami", "\u043F\u0440\u043E\u0433\u043B\u0430\u0442\u044B\u0432\u0430\u043D\u0438\u0435 \u044F\u0438\u0446 \u0447\u0435\u043B\u043E\u0432\u0435\u0447\u0435\u0441\u043A\u043E\u0439 \u0430\u0441\u043A\u0430\u0440\u0438\u0434\u044B \u0441 \u043D\u0435\u043C\u044B\u0442\u044B\u043C\u0438 \u043E\u0432\u043E\u0449\u0430\u043C\u0438 \u0438\u043B\u0438 \u0433\u0440\u044F\u0437\u043D\u044B\u043C\u0438 \u0440\u0443\u043A\u0430\u043C\u0438", "b\xF3le brzucha, nudno\u015Bci, os\u0142abienie i niedo\u017Cywienie", "\u0431\u043E\u043B\u0438 \u0432 \u0436\u0438\u0432\u043E\u0442\u0435, \u0442\u043E\u0448\u043D\u043E\u0442\u0430, \u0441\u043B\u0430\u0431\u043E\u0441\u0442\u044C \u0438 \u0438\u0441\u0442\u043E\u0449\u0435\u043D\u0438\u0435", 1, [], []],
  ["kamica-zolciowa", "kamica \u017C\xF3\u0142ciowa", "\u0436\u0435\u043B\u0447\u043D\u043E\u043A\u0430\u043C\u0435\u043D\u043D\u0430\u044F \u0431\u043E\u043B\u0435\u0437\u043D\u044C", "metabolic", "wytr\u0105canie si\u0119 z\u0142og\xF3w z \u017C\xF3\u0142ci przesyconej cholesterolem", "\u043E\u0431\u0440\u0430\u0437\u043E\u0432\u0430\u043D\u0438\u0435 \u043A\u0430\u043C\u043D\u0435\u0439 \u0438\u0437 \u0436\u0451\u043B\u0447\u0438, \u043F\u0435\u0440\u0435\u043D\u0430\u0441\u044B\u0449\u0435\u043D\u043D\u043E\u0439 \u0445\u043E\u043B\u0435\u0441\u0442\u0435\u0440\u0438\u043D\u043E\u043C", "napadowy silny b\xF3l pod prawym \u0142ukiem \u017Cebrowym po t\u0142ustym posi\u0142ku", "\u043F\u0440\u0438\u0441\u0442\u0443\u043F \u0441\u0438\u043B\u044C\u043D\u043E\u0439 \u0431\u043E\u043B\u0438 \u043F\u043E\u0434 \u043F\u0440\u0430\u0432\u044B\u043C \u0440\u0451\u0431\u0435\u0440\u043D\u044B\u043C \u043A\u0440\u0430\u0435\u043C \u043F\u043E\u0441\u043B\u0435 \u0436\u0438\u0440\u043D\u043E\u0439 \u0435\u0434\u044B", 2, ["kamica p\u0119cherzyka \u017C\xF3\u0142ciowego"], ["\u043A\u0430\u043C\u043D\u0438 \u0432 \u0436\u0451\u043B\u0447\u043D\u043E\u043C \u043F\u0443\u0437\u044B\u0440\u0435"]],
  ["celiakia", "celiakia", "\u0446\u0435\u043B\u0438\u0430\u043A\u0438\u044F", "autoimmune", "reakcja odporno\u015Bciowa na gluten, niszcz\u0105ca kosmki jelitowe", "\u0438\u043C\u043C\u0443\u043D\u043D\u0430\u044F \u0440\u0435\u0430\u043A\u0446\u0438\u044F \u043D\u0430 \u0433\u043B\u044E\u0442\u0435\u043D, \u0440\u0430\u0437\u0440\u0443\u0448\u0430\u044E\u0449\u0430\u044F \u043A\u0438\u0448\u0435\u0447\u043D\u044B\u0435 \u0432\u043E\u0440\u0441\u0438\u043D\u043A\u0438", "biegunki, wzd\u0119cia, niedobory pokarmowe i zahamowanie wzrostu", "\u043F\u043E\u043D\u043E\u0441\u044B, \u0432\u0437\u0434\u0443\u0442\u0438\u0435, \u0434\u0435\u0444\u0438\u0446\u0438\u0442 \u043F\u0438\u0442\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0432\u0435\u0449\u0435\u0441\u0442\u0432 \u0438 \u0437\u0430\u0434\u0435\u0440\u0436\u043A\u0430 \u0440\u043E\u0441\u0442\u0430", 2, ["choroba trzewna"], ["\u0433\u043B\u044E\u0442\u0435\u043D\u043E\u0432\u0430\u044F \u0431\u043E\u043B\u0435\u0437\u043D\u044C"]],
  ["rak-jelita", "rak jelita grubego", "\u0440\u0430\u043A \u0442\u043E\u043B\u0441\u0442\u043E\u0439 \u043A\u0438\u0448\u043A\u0438", "cancer", "niekontrolowane podzia\u0142y kom\xF3rek nab\u0142onka jelita, kt\xF3rym sprzyja dieta uboga w b\u0142onnik", "\u043D\u0435\u043A\u043E\u043D\u0442\u0440\u043E\u043B\u0438\u0440\u0443\u0435\u043C\u043E\u0435 \u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u043A\u043B\u0435\u0442\u043E\u043A \u044D\u043F\u0438\u0442\u0435\u043B\u0438\u044F \u043A\u0438\u0448\u043A\u0438, \u043A\u043E\u0442\u043E\u0440\u043E\u043C\u0443 \u0441\u043F\u043E\u0441\u043E\u0431\u0441\u0442\u0432\u0443\u0435\u0442 \u0431\u0435\u0434\u043D\u0430\u044F \u043A\u043B\u0435\u0442\u0447\u0430\u0442\u043A\u043E\u0439 \u0434\u0438\u0435\u0442\u0430", "krew w stolcu, zmiana rytmu wypr\xF3\u017Cnie\u0144 i spadek masy cia\u0142a", "\u043A\u0440\u043E\u0432\u044C \u0432 \u043A\u0430\u043B\u0435, \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0435 \u0440\u0438\u0442\u043C\u0430 \u043E\u043F\u043E\u0440\u043E\u0436\u043D\u0435\u043D\u0438\u044F \u0438 \u043F\u043E\u0442\u0435\u0440\u044F \u0432\u0435\u0441\u0430", 2, ["rak okr\u0119\u017Cnicy"], ["\u043A\u043E\u043B\u043E\u0440\u0435\u043A\u0442\u0430\u043B\u044C\u043D\u044B\u0439 \u0440\u0430\u043A"]],
  ["marskosc", "marsko\u015B\u0107 w\u0105troby", "\u0446\u0438\u0440\u0440\u043E\u0437 \u043F\u0435\u0447\u0435\u043D\u0438", "toxic", "zast\u0119powanie kom\xF3rek w\u0105troby tkank\u0105 \u0142\u0105czn\u0105, najcz\u0119\u015Bciej wskutek nadu\u017Cywania alkoholu", "\u0437\u0430\u043C\u0435\u0449\u0435\u043D\u0438\u0435 \u043A\u043B\u0435\u0442\u043E\u043A \u043F\u0435\u0447\u0435\u043D\u0438 \u0441\u043E\u0435\u0434\u0438\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0439 \u0442\u043A\u0430\u043D\u044C\u044E, \u0447\u0430\u0449\u0435 \u0432\u0441\u0435\u0433\u043E \u0438\u0437-\u0437\u0430 \u0437\u043B\u043E\u0443\u043F\u043E\u0442\u0440\u0435\u0431\u043B\u0435\u043D\u0438\u044F \u0430\u043B\u043A\u043E\u0433\u043E\u043B\u0435\u043C", "\u017C\xF3\u0142taczka, wodobrzusze i zaburzenia krzepni\u0119cia krwi", "\u0436\u0435\u043B\u0442\u0443\u0445\u0430, \u0441\u043A\u043E\u043F\u043B\u0435\u043D\u0438\u0435 \u0436\u0438\u0434\u043A\u043E\u0441\u0442\u0438 \u0432 \u0436\u0438\u0432\u043E\u0442\u0435 \u0438 \u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u0435 \u0441\u0432\u0451\u0440\u0442\u044B\u0432\u0430\u043D\u0438\u044F \u043A\u0440\u043E\u0432\u0438", 2, [], ["\u0446\u0438\u0440\u0440\u043E\u0437"]],
  ["anoreksja", "jad\u0142owstr\u0119t psychiczny", "\u043D\u0435\u0440\u0432\u043D\u0430\u044F \u0430\u043D\u043E\u0440\u0435\u043A\u0441\u0438\u044F", "psychic", "l\u0119k przed przytyciem i zaburzony obraz w\u0142asnego cia\u0142a", "\u0441\u0442\u0440\u0430\u0445 \u043D\u0430\u0431\u0440\u0430\u0442\u044C \u0432\u0435\u0441 \u0438 \u0438\u0441\u043A\u0430\u0436\u0451\u043D\u043D\u043E\u0435 \u0432\u043E\u0441\u043F\u0440\u0438\u044F\u0442\u0438\u0435 \u0441\u0432\u043E\u0435\u0433\u043E \u0442\u0435\u043B\u0430", "skrajne ograniczanie jedzenia i wyniszczenie organizmu", "\u043A\u0440\u0430\u0439\u043D\u0435\u0435 \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u0435 \u0435\u0434\u044B \u0438 \u0438\u0441\u0442\u043E\u0449\u0435\u043D\u0438\u0435 \u043E\u0440\u0433\u0430\u043D\u0438\u0437\u043C\u0430", 2, ["anoreksja"], ["\u0430\u043D\u043E\u0440\u0435\u043A\u0441\u0438\u044F"]],
  ["bulimia", "\u017Car\u0142oczno\u015B\u0107 psychiczna", "\u043D\u0435\u0440\u0432\u043D\u0430\u044F \u0431\u0443\u043B\u0438\u043C\u0438\u044F", "psychic", "utrata kontroli nad ilo\u015Bci\u0105 jedzenia po\u0142\u0105czona z poczuciem winy i pozbywaniem si\u0119 zjedzonego pokarmu", "\u043F\u043E\u0442\u0435\u0440\u044F \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044F \u043D\u0430\u0434 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E\u043C \u0435\u0434\u044B \u0432 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0438 \u0441 \u0447\u0443\u0432\u0441\u0442\u0432\u043E\u043C \u0432\u0438\u043D\u044B \u0438 \u0438\u0437\u0431\u0430\u0432\u043B\u0435\u043D\u0438\u0435\u043C \u043E\u0442 \u0441\u044A\u0435\u0434\u0435\u043D\u043D\u043E\u0433\u043E", "napady objadania si\u0119, po kt\xF3rych chory prowokuje wymioty", "\u043F\u0440\u0438\u0441\u0442\u0443\u043F\u044B \u043E\u0431\u0436\u043E\u0440\u0441\u0442\u0432\u0430, \u043F\u043E\u0441\u043B\u0435 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0431\u043E\u043B\u044C\u043D\u043E\u0439 \u0432\u044B\u0437\u044B\u0432\u0430\u0435\u0442 \u0440\u0432\u043E\u0442\u0443", 2, ["bulimia"], ["\u0431\u0443\u043B\u0438\u043C\u0438\u044F"]]
]);
var RESPIRATORY_DISORDERS = disorderTable(P.respiration.disorders, [
  ["gruzlica", "gru\u017Alica", "\u0442\u0443\u0431\u0435\u0440\u043A\u0443\u043B\u0451\u0437", "bacterial", "pr\u0105tki gru\u017Alicy przenoszone drog\u0105 kropelkow\u0105", "\u0442\u0443\u0431\u0435\u0440\u043A\u0443\u043B\u0451\u0437\u043D\u044B\u0435 \u043F\u0430\u043B\u043E\u0447\u043A\u0438, \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0449\u0438\u0435\u0441\u044F \u0432\u043E\u0437\u0434\u0443\u0448\u043D\u043E-\u043A\u0430\u043F\u0435\u043B\u044C\u043D\u044B\u043C \u043F\u0443\u0442\u0451\u043C", "d\u0142ugotrwa\u0142y kaszel, czasem z krwi\u0105, stany podgor\u0105czkowe, nocne poty i chudni\u0119cie", "\u0434\u043B\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043A\u0430\u0448\u0435\u043B\u044C, \u0438\u043D\u043E\u0433\u0434\u0430 \u0441 \u043A\u0440\u043E\u0432\u044C\u044E, \u0441\u0443\u0431\u0444\u0435\u0431\u0440\u0438\u043B\u044C\u043D\u0430\u044F \u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u0430, \u043D\u043E\u0447\u043D\u043E\u0439 \u043F\u043E\u0442 \u0438 \u043F\u043E\u0445\u0443\u0434\u0435\u043D\u0438\u0435", 1, [], ["\u0442\u0443\u0431\u0435\u0440\u043A\u0443\u043B\u0435\u0437", "\u0447\u0430\u0445\u043E\u0442\u043A\u0430"]],
  ["zapalenie-pluc", "zapalenie p\u0142uc", "\u043F\u043D\u0435\u0432\u043C\u043E\u043D\u0438\u044F", "bacterial", "zaka\u017Cenie p\u0119cherzyk\xF3w p\u0142ucnych, najcz\u0119\u015Bciej przez dwoinki zapalenia p\u0142uc (pneumokoki)", "\u0438\u043D\u0444\u0435\u043A\u0446\u0438\u044F \u043B\u0451\u0433\u043E\u0447\u043D\u044B\u0445 \u0430\u043B\u044C\u0432\u0435\u043E\u043B, \u0447\u0430\u0449\u0435 \u0432\u0441\u0435\u0433\u043E \u043F\u043D\u0435\u0432\u043C\u043E\u043A\u043E\u043A\u043A\u0430\u043C\u0438", "wysoka gor\u0105czka, kaszel z odkrztuszaniem, duszno\u015B\u0107 i b\xF3l w klatce piersiowej", "\u0432\u044B\u0441\u043E\u043A\u0430\u044F \u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u0430, \u043A\u0430\u0448\u0435\u043B\u044C \u0441 \u043C\u043E\u043A\u0440\u043E\u0442\u043E\u0439, \u043E\u0434\u044B\u0448\u043A\u0430 \u0438 \u0431\u043E\u043B\u044C \u0432 \u0433\u0440\u0443\u0434\u0438", 1, [], ["\u0432\u043E\u0441\u043F\u0430\u043B\u0435\u043D\u0438\u0435 \u043B\u0451\u0433\u043A\u0438\u0445"]],
  ["angina", "angina", "\u0430\u043D\u0433\u0438\u043D\u0430", "bacterial", "paciorkowce zaka\u017Caj\u0105ce migda\u0142ki podniebienne", "\u0441\u0442\u0440\u0435\u043F\u0442\u043E\u043A\u043E\u043A\u043A\u0438, \u043F\u043E\u0440\u0430\u0436\u0430\u044E\u0449\u0438\u0435 \u043D\u0451\u0431\u043D\u044B\u0435 \u043C\u0438\u043D\u0434\u0430\u043B\u0438\u043D\u044B", "silny b\xF3l gard\u0142a, gor\u0105czka i powi\u0119kszone migda\u0142ki z bia\u0142ym nalotem", "\u0441\u0438\u043B\u044C\u043D\u0430\u044F \u0431\u043E\u043B\u044C \u0432 \u0433\u043E\u0440\u043B\u0435, \u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u0430 \u0438 \u0443\u0432\u0435\u043B\u0438\u0447\u0435\u043D\u043D\u044B\u0435 \u043C\u0438\u043D\u0434\u0430\u043B\u0438\u043D\u044B \u0441 \u0431\u0435\u043B\u044B\u043C \u043D\u0430\u043B\u0451\u0442\u043E\u043C", 1, ["angina paciorkowcowa"], ["\u043E\u0441\u0442\u0440\u044B\u0439 \u0442\u043E\u043D\u0437\u0438\u043B\u043B\u0438\u0442"]],
  ["grypa", "grypa", "\u0433\u0440\u0438\u043F\u043F", "viral", "wirus grypy szerz\u0105cy si\u0119 drog\u0105 kropelkow\u0105", "\u0432\u0438\u0440\u0443\u0441 \u0433\u0440\u0438\u043F\u043F\u0430, \u0440\u0430\u0441\u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u044F\u044E\u0449\u0438\u0439\u0441\u044F \u0432\u043E\u0437\u0434\u0443\u0448\u043D\u043E-\u043A\u0430\u043F\u0435\u043B\u044C\u043D\u044B\u043C \u043F\u0443\u0442\u0451\u043C", "nag\u0142a wysoka gor\u0105czka, b\xF3le mi\u0119\u015Bni i g\u0142owy oraz suchy kaszel", "\u0432\u043D\u0435\u0437\u0430\u043F\u043D\u0430\u044F \u0432\u044B\u0441\u043E\u043A\u0430\u044F \u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u0430, \u043B\u043E\u043C\u043E\u0442\u0430 \u0432 \u043C\u044B\u0448\u0446\u0430\u0445, \u0433\u043E\u043B\u043E\u0432\u043D\u0430\u044F \u0431\u043E\u043B\u044C \u0438 \u0441\u0443\u0445\u043E\u0439 \u043A\u0430\u0448\u0435\u043B\u044C", 1, [], []],
  ["covid", "COVID-19", "COVID-19", "viral", "koronawirus SARS-CoV-2 szerz\u0105cy si\u0119 drog\u0105 kropelkow\u0105", "\u043A\u043E\u0440\u043E\u043D\u0430\u0432\u0438\u0440\u0443\u0441 SARS-CoV-2, \u0440\u0430\u0441\u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u044F\u044E\u0449\u0438\u0439\u0441\u044F \u0432\u043E\u0437\u0434\u0443\u0448\u043D\u043E-\u043A\u0430\u043F\u0435\u043B\u044C\u043D\u044B\u043C \u043F\u0443\u0442\u0451\u043C", "gor\u0105czka, kaszel, duszno\u015B\u0107 oraz utrata w\u0119chu i smaku", "\u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u0430, \u043A\u0430\u0448\u0435\u043B\u044C, \u043E\u0434\u044B\u0448\u043A\u0430, \u043F\u043E\u0442\u0435\u0440\u044F \u043E\u0431\u043E\u043D\u044F\u043D\u0438\u044F \u0438 \u0432\u043A\u0443\u0441\u0430", 1, ["covid"], ["\u043A\u043E\u0432\u0438\u0434", "\u043A\u043E\u0440\u043E\u043D\u0430\u0432\u0438\u0440\u0443\u0441\u043D\u0430\u044F \u0438\u043D\u0444\u0435\u043A\u0446\u0438\u044F"]],
  ["astma", "astma oskrzelowa", "\u0431\u0440\u043E\u043D\u0445\u0438\u0430\u043B\u044C\u043D\u0430\u044F \u0430\u0441\u0442\u043C\u0430", "allergic", "przewlek\u0142y stan zapalny i nadwra\u017Cliwo\u015B\u0107 oskrzeli, najcz\u0119\u015Bciej na alergeny", "\u0445\u0440\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u043E\u0435 \u0432\u043E\u0441\u043F\u0430\u043B\u0435\u043D\u0438\u0435 \u0438 \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u043D\u0430\u044F \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C \u0431\u0440\u043E\u043D\u0445\u043E\u0432, \u0447\u0430\u0449\u0435 \u0432\u0441\u0435\u0433\u043E \u043A \u0430\u043B\u043B\u0435\u0440\u0433\u0435\u043D\u0430\u043C", "napady duszno\u015Bci ze \u015Bwiszcz\u0105cym oddechem", "\u043F\u0440\u0438\u0441\u0442\u0443\u043F\u044B \u0443\u0434\u0443\u0448\u044C\u044F \u0441\u043E \u0441\u0432\u0438\u0441\u0442\u044F\u0449\u0438\u043C \u0434\u044B\u0445\u0430\u043D\u0438\u0435\u043C", 1, ["astma"], ["\u0430\u0441\u0442\u043C\u0430"]],
  ["pochp", "przewlek\u0142a obturacyjna choroba p\u0142uc", "\u0445\u0440\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u043E\u0431\u0441\u0442\u0440\u0443\u043A\u0442\u0438\u0432\u043D\u0430\u044F \u0431\u043E\u043B\u0435\u0437\u043D\u044C \u043B\u0451\u0433\u043A\u0438\u0445", "environmental", "wieloletnie wdychanie dymu tytoniowego i zanieczyszcze\u0144 niszcz\u0105cych oskrzeliki i p\u0119cherzyki", "\u043C\u043D\u043E\u0433\u043E\u043B\u0435\u0442\u043D\u0435\u0435 \u0432\u0434\u044B\u0445\u0430\u043D\u0438\u0435 \u0442\u0430\u0431\u0430\u0447\u043D\u043E\u0433\u043E \u0434\u044B\u043C\u0430 \u0438 \u0437\u0430\u0433\u0440\u044F\u0437\u043D\u0435\u043D\u0438\u0439, \u0440\u0430\u0437\u0440\u0443\u0448\u0430\u044E\u0449\u0438\u0445 \u0431\u0440\u043E\u043D\u0445\u0438\u043E\u043B\u044B \u0438 \u0430\u043B\u044C\u0432\u0435\u043E\u043B\u044B", "post\u0119puj\u0105ca duszno\u015B\u0107 i przewlek\u0142y kaszel z odkrztuszaniem", "\u043D\u0430\u0440\u0430\u0441\u0442\u0430\u044E\u0449\u0430\u044F \u043E\u0434\u044B\u0448\u043A\u0430 \u0438 \u0445\u0440\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u043A\u0430\u0448\u0435\u043B\u044C \u0441 \u043C\u043E\u043A\u0440\u043E\u0442\u043E\u0439", 2, ["POChP"], ["\u0425\u041E\u0411\u041B"]],
  ["pylica", "pylica p\u0142uc", "\u043F\u043D\u0435\u0432\u043C\u043E\u043A\u043E\u043D\u0438\u043E\u0437", "environmental", "d\u0142ugotrwa\u0142e wdychanie py\u0142\xF3w w miejscu pracy, np. w kopalni", "\u0434\u043B\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0435 \u0432\u0434\u044B\u0445\u0430\u043D\u0438\u0435 \u043F\u044B\u043B\u0438 \u043D\u0430 \u0440\u0430\u0431\u043E\u0442\u0435, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0432 \u0448\u0430\u0445\u0442\u0435", "zw\u0142\xF3knienie tkanki p\u0142ucnej i post\u0119puj\u0105ca duszno\u015B\u0107", "\u0440\u0430\u0437\u0440\u0430\u0441\u0442\u0430\u043D\u0438\u0435 \u0441\u043E\u0435\u0434\u0438\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0439 \u0442\u043A\u0430\u043D\u0438 \u0432 \u043B\u0451\u0433\u043A\u0438\u0445 \u0438 \u043D\u0430\u0440\u0430\u0441\u0442\u0430\u044E\u0449\u0430\u044F \u043E\u0434\u044B\u0448\u043A\u0430", 2, ["pylica"], ["\u043F\u044B\u043B\u0435\u0432\u043E\u0439 \u0444\u0438\u0431\u0440\u043E\u0437 \u043B\u0451\u0433\u043A\u0438\u0445"]],
  ["rak-pluca", "rak p\u0142uca", "\u0440\u0430\u043A \u043B\u0451\u0433\u043A\u043E\u0433\u043E", "cancer", "niekontrolowane podzia\u0142y kom\xF3rek nab\u0142onka oskrzeli, g\u0142\xF3wnie wskutek palenia tytoniu", "\u043D\u0435\u043A\u043E\u043D\u0442\u0440\u043E\u043B\u0438\u0440\u0443\u0435\u043C\u043E\u0435 \u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u043A\u043B\u0435\u0442\u043E\u043A \u044D\u043F\u0438\u0442\u0435\u043B\u0438\u044F \u0431\u0440\u043E\u043D\u0445\u043E\u0432, \u0433\u043B\u0430\u0432\u043D\u044B\u043C \u043E\u0431\u0440\u0430\u0437\u043E\u043C \u0438\u0437-\u0437\u0430 \u043A\u0443\u0440\u0435\u043D\u0438\u044F", "przewlek\u0142y kaszel, krwioplucie i chudni\u0119cie u wieloletniego palacza, bez gor\u0105czki", "\u0445\u0440\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u043A\u0430\u0448\u0435\u043B\u044C, \u043A\u0440\u043E\u0432\u043E\u0445\u0430\u0440\u043A\u0430\u043D\u044C\u0435 \u0438 \u043F\u043E\u0445\u0443\u0434\u0435\u043D\u0438\u0435 \u0443 \u043A\u0443\u0440\u0438\u043B\u044C\u0449\u0438\u043A\u0430 \u0441 \u043C\u043D\u043E\u0433\u043E\u043B\u0435\u0442\u043D\u0438\u043C \u0441\u0442\u0430\u0436\u0435\u043C, \u0431\u0435\u0437 \u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u044B", 1, [], []],
  ["mukowiscydoza", "mukowiscydoza", "\u043C\u0443\u043A\u043E\u0432\u0438\u0441\u0446\u0438\u0434\u043E\u0437", "genetic", "mutacja genu powoduj\u0105ca wydzielanie g\u0119stego, lepkiego \u015Bluzu", "\u043C\u0443\u0442\u0430\u0446\u0438\u044F \u0433\u0435\u043D\u0430, \u0438\u0437-\u0437\u0430 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u0432\u044B\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u0433\u0443\u0441\u0442\u0430\u044F, \u0432\u044F\u0437\u043A\u0430\u044F \u0441\u043B\u0438\u0437\u044C", "przewlek\u0142y kaszel, nawracaj\u0105ce zapalenia p\u0142uc i zaburzenia trawienia od dzieci\u0144stwa", "\u0445\u0440\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u043A\u0430\u0448\u0435\u043B\u044C, \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u044E\u0449\u0438\u0435\u0441\u044F \u043F\u043D\u0435\u0432\u043C\u043E\u043D\u0438\u0438 \u0438 \u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u044F \u043F\u0438\u0449\u0435\u0432\u0430\u0440\u0435\u043D\u0438\u044F \u0441 \u0434\u0435\u0442\u0441\u0442\u0432\u0430", 2, ["zw\u0142\xF3knienie torbielowate"], ["\u043A\u0438\u0441\u0442\u043E\u0437\u043D\u044B\u0439 \u0444\u0438\u0431\u0440\u043E\u0437"]]
]);
var CIRCULATION_DISORDERS = disorderTable(P.circulation.disorders, [
  ["miazdzyca", "mia\u017Cd\u017Cyca", "\u0430\u0442\u0435\u0440\u043E\u0441\u043A\u043B\u0435\u0440\u043E\u0437", "lifestyle", "odk\u0142adanie si\u0119 cholesterolu i tworzenie blaszek w \u015Bcianach t\u0119tnic", "\u043E\u0442\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0445\u043E\u043B\u0435\u0441\u0442\u0435\u0440\u0438\u043D\u0430 \u0438 \u043E\u0431\u0440\u0430\u0437\u043E\u0432\u0430\u043D\u0438\u0435 \u0431\u043B\u044F\u0448\u0435\u043A \u0432 \u0441\u0442\u0435\u043D\u043A\u0430\u0445 \u0430\u0440\u0442\u0435\u0440\u0438\u0439", "chromanie przestankowe \u2014 b\xF3l \u0142ydek podczas chodzenia, ust\u0119puj\u0105cy w spoczynku", "\u043F\u0435\u0440\u0435\u043C\u0435\u0436\u0430\u044E\u0449\u0430\u044F\u0441\u044F \u0445\u0440\u043E\u043C\u043E\u0442\u0430 \u2014 \u0431\u043E\u043B\u044C \u0432 \u0438\u043A\u0440\u0430\u0445 \u043F\u0440\u0438 \u0445\u043E\u0434\u044C\u0431\u0435, \u043F\u0440\u043E\u0445\u043E\u0434\u044F\u0449\u0430\u044F \u0432 \u043F\u043E\u043A\u043E\u0435", 1, [], []],
  ["choroba-wiencowa", "choroba niedokrwienna serca", "\u0438\u0448\u0435\u043C\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u0431\u043E\u043B\u0435\u0437\u043D\u044C \u0441\u0435\u0440\u0434\u0446\u0430", "lifestyle", "zw\u0119\u017Cenie t\u0119tnic wie\u0144cowych przez blaszki mia\u017Cd\u017Cycowe", "\u0441\u0443\u0436\u0435\u043D\u0438\u0435 \u043A\u043E\u0440\u043E\u043D\u0430\u0440\u043D\u044B\u0445 \u0430\u0440\u0442\u0435\u0440\u0438\u0439 \u0430\u0442\u0435\u0440\u043E\u0441\u043A\u043B\u0435\u0440\u043E\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u043C\u0438 \u0431\u043B\u044F\u0448\u043A\u0430\u043C\u0438", "d\u0142awica piersiowa \u2014 uczucie ucisku i b\xF3l za mostkiem przy wysi\u0142ku", "\u0441\u0442\u0435\u043D\u043E\u043A\u0430\u0440\u0434\u0438\u044F \u2014 \u0434\u0430\u0432\u044F\u0449\u0430\u044F \u0431\u043E\u043B\u044C \u0437\u0430 \u0433\u0440\u0443\u0434\u0438\u043D\u043E\u0439 \u043F\u0440\u0438 \u043D\u0430\u0433\u0440\u0443\u0437\u043A\u0435", 2, ["choroba wie\u0144cowa"], ["\u0418\u0411\u0421", "\u043A\u043E\u0440\u043E\u043D\u0430\u0440\u043D\u0430\u044F \u0431\u043E\u043B\u0435\u0437\u043D\u044C"]],
  ["zawal", "zawa\u0142 serca", "\u0438\u043D\u0444\u0430\u0440\u043A\u0442 \u043C\u0438\u043E\u043A\u0430\u0440\u0434\u0430", "lifestyle", "zamkni\u0119cie t\u0119tnicy wie\u0144cowej przez skrzep i obumarcie fragmentu mi\u0119\u015Bnia sercowego", "\u0437\u0430\u043A\u0443\u043F\u043E\u0440\u043A\u0430 \u043A\u043E\u0440\u043E\u043D\u0430\u0440\u043D\u043E\u0439 \u0430\u0440\u0442\u0435\u0440\u0438\u0438 \u0442\u0440\u043E\u043C\u0431\u043E\u043C \u0438 \u043E\u0442\u043C\u0438\u0440\u0430\u043D\u0438\u0435 \u0443\u0447\u0430\u0441\u0442\u043A\u0430 \u0441\u0435\u0440\u0434\u0435\u0447\u043D\u043E\u0439 \u043C\u044B\u0448\u0446\u044B", "silny, piek\u0105cy b\xF3l za mostkiem promieniuj\u0105cy do lewej r\u0119ki, trwaj\u0105cy ponad 20 minut", "\u0441\u0438\u043B\u044C\u043D\u0430\u044F \u0436\u0433\u0443\u0447\u0430\u044F \u0431\u043E\u043B\u044C \u0437\u0430 \u0433\u0440\u0443\u0434\u0438\u043D\u043E\u0439, \u043E\u0442\u0434\u0430\u044E\u0449\u0430\u044F \u0432 \u043B\u0435\u0432\u0443\u044E \u0440\u0443\u043A\u0443 \u0438 \u0434\u043B\u044F\u0449\u0430\u044F\u0441\u044F \u0431\u043E\u043B\u044C\u0448\u0435 20 \u043C\u0438\u043D\u0443\u0442", 1, ["zawa\u0142 mi\u0119\u015Bnia sercowego"], ["\u0438\u043D\u0444\u0430\u0440\u043A\u0442"]],
  ["nadcisnienie", "nadci\u015Bnienie t\u0119tnicze", "\u0430\u0440\u0442\u0435\u0440\u0438\u0430\u043B\u044C\u043D\u0430\u044F \u0433\u0438\u043F\u0435\u0440\u0442\u0435\u043D\u0437\u0438\u044F", "lifestyle", "nadmiar soli w diecie, oty\u0142o\u015B\u0107, stres i brak ruchu", "\u0438\u0437\u0431\u044B\u0442\u043E\u043A \u0441\u043E\u043B\u0438, \u043E\u0436\u0438\u0440\u0435\u043D\u0438\u0435, \u0441\u0442\u0440\u0435\u0441\u0441 \u0438 \u043C\u0430\u043B\u043E\u043F\u043E\u0434\u0432\u0438\u0436\u043D\u043E\u0441\u0442\u044C", "ci\u015Bnienie krwi stale powy\u017Cej 140/90 mmHg, b\xF3le g\u0142owy", "\u0434\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u043A\u0440\u043E\u0432\u0438 \u043F\u043E\u0441\u0442\u043E\u044F\u043D\u043D\u043E \u0432\u044B\u0448\u0435 140/90 \u043C\u043C \u0440\u0442. \u0441\u0442., \u0433\u043E\u043B\u043E\u0432\u043D\u044B\u0435 \u0431\u043E\u043B\u0438", 1, ["nadci\u015Bnienie"], ["\u0433\u0438\u043F\u0435\u0440\u0442\u043E\u043D\u0438\u044F", "\u0433\u0438\u043F\u0435\u0440\u0442\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u0431\u043E\u043B\u0435\u0437\u043D\u044C"]],
  ["udar", "udar m\xF3zgu", "\u0438\u043D\u0441\u0443\u043B\u044C\u0442", "lifestyle", "zamkni\u0119cie lub p\u0119kni\u0119cie naczynia krwiono\u015Bnego w m\xF3zgu", "\u0437\u0430\u043A\u0443\u043F\u043E\u0440\u043A\u0430 \u0438\u043B\u0438 \u0440\u0430\u0437\u0440\u044B\u0432 \u043A\u0440\u043E\u0432\u0435\u043D\u043E\u0441\u043D\u043E\u0433\u043E \u0441\u043E\u0441\u0443\u0434\u0430 \u0432 \u043C\u043E\u0437\u0433\u0435", "nag\u0142y niedow\u0142ad po\u0142owy cia\u0142a, opadni\u0119ty k\u0105cik ust i zaburzenia mowy", "\u0432\u043D\u0435\u0437\u0430\u043F\u043D\u0430\u044F \u0441\u043B\u0430\u0431\u043E\u0441\u0442\u044C \u043F\u043E\u043B\u043E\u0432\u0438\u043D\u044B \u0442\u0435\u043B\u0430, \u043E\u043F\u0443\u0449\u0435\u043D\u043D\u044B\u0439 \u0443\u0433\u043E\u043B\u043E\u043A \u0440\u0442\u0430 \u0438 \u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u0435 \u0440\u0435\u0447\u0438", 1, ["udar"], ["\u0438\u043D\u0441\u0443\u043B\u044C\u0442 \u043C\u043E\u0437\u0433\u0430"]],
  ["zylaki", "\u017Cylaki ko\u0144czyn dolnych", "\u0432\u0430\u0440\u0438\u043A\u043E\u0437\u043D\u043E\u0435 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043D\u0438\u0435 \u0432\u0435\u043D", "lifestyle", "niewydolno\u015B\u0107 zastawek \u017Cylnych i zast\xF3j krwi przy d\u0142ugim staniu lub siedzeniu", "\u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E\u0441\u0442\u044C \u0432\u0435\u043D\u043E\u0437\u043D\u044B\u0445 \u043A\u043B\u0430\u043F\u0430\u043D\u043E\u0432 \u0438 \u0437\u0430\u0441\u0442\u043E\u0439 \u043A\u0440\u043E\u0432\u0438 \u043F\u0440\u0438 \u0434\u043E\u043B\u0433\u043E\u043C \u0441\u0442\u043E\u044F\u043D\u0438\u0438 \u0438\u043B\u0438 \u0441\u0438\u0434\u0435\u043D\u0438\u0438", "poszerzone, kr\u0119te, uwypuklone \u017Cy\u0142y na \u0142ydkach i uczucie ci\u0119\u017Ckich n\xF3g", "\u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043D\u043D\u044B\u0435, \u0438\u0437\u0432\u0438\u0442\u044B\u0435, \u0432\u044B\u0441\u0442\u0443\u043F\u0430\u044E\u0449\u0438\u0435 \u0432\u0435\u043D\u044B \u043D\u0430 \u0433\u043E\u043B\u0435\u043D\u044F\u0445 \u0438 \u0442\u044F\u0436\u0435\u0441\u0442\u044C \u0432 \u043D\u043E\u0433\u0430\u0445", 1, ["\u017Cylaki"], ["\u0432\u0430\u0440\u0438\u043A\u043E\u0437"]],
  ["anemia", "niedokrwisto\u015B\u0107 z niedoboru \u017Celaza", "\u0436\u0435\u043B\u0435\u0437\u043E\u0434\u0435\u0444\u0438\u0446\u0438\u0442\u043D\u0430\u044F \u0430\u043D\u0435\u043C\u0438\u044F", "deficiency", "zbyt ma\u0142a ilo\u015B\u0107 \u017Celaza do wytwarzania hemoglobiny", "\u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u043A \u0436\u0435\u043B\u0435\u0437\u0430 \u0434\u043B\u044F \u043E\u0431\u0440\u0430\u0437\u043E\u0432\u0430\u043D\u0438\u044F \u0433\u0435\u043C\u043E\u0433\u043B\u043E\u0431\u0438\u043D\u0430", "blado\u015B\u0107, os\u0142abienie, szybkie m\u0119czenie si\u0119 i zadyszka", "\u0431\u043B\u0435\u0434\u043D\u043E\u0441\u0442\u044C, \u0441\u043B\u0430\u0431\u043E\u0441\u0442\u044C, \u0431\u044B\u0441\u0442\u0440\u0430\u044F \u0443\u0442\u043E\u043C\u043B\u044F\u0435\u043C\u043E\u0441\u0442\u044C \u0438 \u043E\u0434\u044B\u0448\u043A\u0430", 1, ["anemia", "niedokrwisto\u015B\u0107"], ["\u0430\u043D\u0435\u043C\u0438\u044F", "\u043C\u0430\u043B\u043E\u043A\u0440\u043E\u0432\u0438\u0435"]],
  ["hemofilia", "hemofilia", "\u0433\u0435\u043C\u043E\u0444\u0438\u043B\u0438\u044F", "genetic", "dziedziczny, sprz\u0119\u017Cony z p\u0142ci\u0105 niedob\xF3r lub brak czynnika krzepni\u0119cia krwi (VIII lub IX)", "\u043D\u0430\u0441\u043B\u0435\u0434\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439, \u0441\u0446\u0435\u043F\u043B\u0435\u043D\u043D\u044B\u0439 \u0441 \u043F\u043E\u043B\u043E\u043C \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u043A \u0438\u043B\u0438 \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u0444\u0430\u043A\u0442\u043E\u0440\u0430 \u0441\u0432\u0451\u0440\u0442\u044B\u0432\u0430\u043D\u0438\u044F \u043A\u0440\u043E\u0432\u0438 (VIII \u0438\u043B\u0438 IX)", "d\u0142ugie krwawienia nawet po drobnych urazach i wylewy krwi do staw\xF3w", "\u0434\u043B\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043A\u0440\u043E\u0432\u043E\u0442\u0435\u0447\u0435\u043D\u0438\u044F \u0434\u0430\u0436\u0435 \u043F\u043E\u0441\u043B\u0435 \u043C\u0435\u043B\u043A\u0438\u0445 \u0442\u0440\u0430\u0432\u043C \u0438 \u043A\u0440\u043E\u0432\u043E\u0438\u0437\u043B\u0438\u044F\u043D\u0438\u044F \u0432 \u0441\u0443\u0441\u0442\u0430\u0432\u044B", 1, [], []],
  ["sierpowata", "niedokrwisto\u015B\u0107 sierpowata", "\u0441\u0435\u0440\u043F\u043E\u0432\u0438\u0434\u043D\u043E\u043A\u043B\u0435\u0442\u043E\u0447\u043D\u0430\u044F \u0430\u043D\u0435\u043C\u0438\u044F", "genetic", "mutacja genu hemoglobiny", "\u043C\u0443\u0442\u0430\u0446\u0438\u044F \u0433\u0435\u043D\u0430 \u0433\u0435\u043C\u043E\u0433\u043B\u043E\u0431\u0438\u043D\u0430", "erytrocyty w kszta\u0142cie p\xF3\u0142ksi\u0119\u017Cyca zatykaj\u0105ce naczynia w\u0142osowate, b\xF3le i niedokrwisto\u015B\u0107", "\u044D\u0440\u0438\u0442\u0440\u043E\u0446\u0438\u0442\u044B \u0432 \u0444\u043E\u0440\u043C\u0435 \u043F\u043E\u043B\u0443\u043C\u0435\u0441\u044F\u0446\u0430, \u0437\u0430\u043A\u0443\u043F\u043E\u0440\u0438\u0432\u0430\u044E\u0449\u0438\u0435 \u043A\u0430\u043F\u0438\u043B\u043B\u044F\u0440\u044B, \u0431\u043E\u043B\u0438 \u0438 \u0430\u043D\u0435\u043C\u0438\u044F", 2, ["anemia sierpowata", "anemia sierpowatokrwinkowa"], ["\u0441\u0435\u0440\u043F\u043E\u0432\u0438\u0434\u043D\u0430\u044F \u0430\u043D\u0435\u043C\u0438\u044F"]],
  ["bialaczka", "bia\u0142aczka", "\u043B\u0435\u0439\u043A\u043E\u0437", "cancer", "nowotworowe namna\u017Canie si\u0119 niedojrza\u0142ych krwinek bia\u0142ych w szpiku", "\u043E\u043F\u0443\u0445\u043E\u043B\u0435\u0432\u043E\u0435 \u0440\u0430\u0437\u043C\u043D\u043E\u0436\u0435\u043D\u0438\u0435 \u043D\u0435\u0437\u0440\u0435\u043B\u044B\u0445 \u043B\u0435\u0439\u043A\u043E\u0446\u0438\u0442\u043E\u0432 \u0432 \u043A\u043E\u0441\u0442\u043D\u043E\u043C \u043C\u043E\u0437\u0433\u0435", "niedokrwisto\u015B\u0107, cz\u0119ste zaka\u017Cenia i sk\u0142onno\u015B\u0107 do krwawie\u0144", "\u0430\u043D\u0435\u043C\u0438\u044F, \u0447\u0430\u0441\u0442\u044B\u0435 \u0438\u043D\u0444\u0435\u043A\u0446\u0438\u0438 \u0438 \u0441\u043A\u043B\u043E\u043D\u043D\u043E\u0441\u0442\u044C \u043A \u043A\u0440\u043E\u0432\u043E\u0442\u0435\u0447\u0435\u043D\u0438\u044F\u043C", 2, ["leukemia"], ["\u043B\u0435\u0439\u043A\u0435\u043C\u0438\u044F", "\u0440\u0430\u043A \u043A\u0440\u043E\u0432\u0438"]]
]);
var IMMUNE_DISORDERS = disorderTable(P.circulation["immune-disorders"], [
  ["alergia", "alergia", "\u0430\u043B\u043B\u0435\u0440\u0433\u0438\u044F", "hypersensitivity", "miejscowa, nadmierna reakcja uk\u0142adu odporno\u015Bciowego na nieszkodliwy antygen \u2014 alergen", "\u043C\u0435\u0441\u0442\u043D\u0430\u044F \u0447\u0440\u0435\u0437\u043C\u0435\u0440\u043D\u0430\u044F \u0440\u0435\u0430\u043A\u0446\u0438\u044F \u0438\u043C\u043C\u0443\u043D\u043D\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u044B \u043D\u0430 \u0431\u0435\u0437\u0432\u0440\u0435\u0434\u043D\u044B\u0439 \u0430\u043D\u0442\u0438\u0433\u0435\u043D \u2014 \u0430\u043B\u043B\u0435\u0440\u0433\u0435\u043D", "katar, \u0142zawienie, wysypka lub duszno\u015B\u0107 po kontakcie np. z py\u0142kiem ro\u015Blin lub sier\u015Bci\u0105", "\u043D\u0430\u0441\u043C\u043E\u0440\u043A, \u0441\u043B\u0435\u0437\u043E\u0442\u0435\u0447\u0435\u043D\u0438\u0435, \u0441\u044B\u043F\u044C \u0438\u043B\u0438 \u0443\u0434\u0443\u0448\u044C\u0435 \u043F\u043E\u0441\u043B\u0435 \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u0430, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0441 \u043F\u044B\u043B\u044C\u0446\u043E\u0439 \u0440\u0430\u0441\u0442\u0435\u043D\u0438\u0439 \u0438\u043B\u0438 \u0448\u0435\u0440\u0441\u0442\u044C\u044E", 1, ["uczulenie"], []],
  ["anafilaksja", "wstrz\u0105s anafilaktyczny", "\u0430\u043D\u0430\u0444\u0438\u043B\u0430\u043A\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0448\u043E\u043A", "hypersensitivity", "ponowny kontakt uczulonego organizmu z alergenem, np. jadem osy, wywo\u0142uj\u0105cy masowe uwolnienie histaminy w ca\u0142ym ciele", "\u043F\u043E\u0432\u0442\u043E\u0440\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0430\u043A\u0442 \u0441\u0435\u043D\u0441\u0438\u0431\u0438\u043B\u0438\u0437\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u043E\u0433\u043E \u043E\u0440\u0433\u0430\u043D\u0438\u0437\u043C\u0430 \u0441 \u0430\u043B\u043B\u0435\u0440\u0433\u0435\u043D\u043E\u043C, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u044F\u0434\u043E\u043C \u043E\u0441\u044B, \u0432\u044B\u0437\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u043C\u0430\u0441\u0441\u043E\u0432\u044B\u0439 \u0432\u044B\u0431\u0440\u043E\u0441 \u0433\u0438\u0441\u0442\u0430\u043C\u0438\u043D\u0430 \u0432\u043E \u0432\u0441\u0451\u043C \u0442\u0435\u043B\u0435", "nag\u0142y spadek ci\u015Bnienia krwi, obrz\u0119k gard\u0142a i duszno\u015B\u0107 zagra\u017Caj\u0105ce \u017Cyciu", "\u0440\u0435\u0437\u043A\u043E\u0435 \u043F\u0430\u0434\u0435\u043D\u0438\u0435 \u0434\u0430\u0432\u043B\u0435\u043D\u0438\u044F, \u043E\u0442\u0451\u043A \u0433\u043E\u0440\u043B\u0430 \u0438 \u0443\u0434\u0443\u0448\u044C\u0435, \u0443\u0433\u0440\u043E\u0436\u0430\u044E\u0449\u0438\u0435 \u0436\u0438\u0437\u043D\u0438", 2, ["anafilaksja"], ["\u0430\u043D\u0430\u0444\u0438\u043B\u0430\u043A\u0441\u0438\u044F"]],
  ["aids", "AIDS", "\u0421\u041F\u0418\u0414", "acquiredImmunodeficiency", "wirus HIV niszcz\u0105cy limfocyty T pomocnicze", "\u0412\u0418\u0427 (\u0432\u0438\u0440\u0443\u0441 \u0438\u043C\u043C\u0443\u043D\u043E\u0434\u0435\u0444\u0438\u0446\u0438\u0442\u0430 \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0430), \u0440\u0430\u0437\u0440\u0443\u0448\u0430\u044E\u0449\u0438\u0439 \u0422-\u0445\u0435\u043B\u043F\u0435\u0440\u044B", "nawracaj\u0105ce zaka\u017Cenia oportunistyczne i nowotwory przy bardzo niskiej liczbie limfocyt\xF3w T", "\u043F\u043E\u0432\u0442\u043E\u0440\u044F\u044E\u0449\u0438\u0435\u0441\u044F \u043E\u043F\u043F\u043E\u0440\u0442\u0443\u043D\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u0438\u043D\u0444\u0435\u043A\u0446\u0438\u0438 \u0438 \u043E\u043F\u0443\u0445\u043E\u043B\u0438 \u043F\u0440\u0438 \u043E\u0447\u0435\u043D\u044C \u043D\u0438\u0437\u043A\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u0422-\u043B\u0438\u043C\u0444\u043E\u0446\u0438\u0442\u043E\u0432", 1, ["zesp\xF3\u0142 nabytego niedoboru odporno\u015Bci"], ["AIDS", "\u0441\u0438\u043D\u0434\u0440\u043E\u043C \u043F\u0440\u0438\u043E\u0431\u0440\u0435\u0442\u0451\u043D\u043D\u043E\u0433\u043E \u0438\u043C\u043C\u0443\u043D\u043E\u0434\u0435\u0444\u0438\u0446\u0438\u0442\u0430"]],
  ["scid", "ci\u0119\u017Cki z\u0142o\u017Cony niedob\xF3r odporno\u015Bci", "\u0442\u044F\u0436\u0451\u043B\u044B\u0439 \u043A\u043E\u043C\u0431\u0438\u043D\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0439 \u0438\u043C\u043C\u0443\u043D\u043E\u0434\u0435\u0444\u0438\u0446\u0438\u0442", "congenitalImmunodeficiency", "wrodzona wada genetyczna uniemo\u017Cliwiaj\u0105ca powstawanie dojrza\u0142ych limfocyt\xF3w T i B", "\u0432\u0440\u043E\u0436\u0434\u0451\u043D\u043D\u044B\u0439 \u0433\u0435\u043D\u0435\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0434\u0435\u0444\u0435\u043A\u0442, \u043F\u0440\u0438 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u043D\u0435 \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442\u0441\u044F \u0437\u0440\u0435\u043B\u044B\u0435 \u0422- \u0438 \u0412-\u043B\u0438\u043C\u0444\u043E\u0446\u0438\u0442\u044B", "ci\u0119\u017Ckie, zagra\u017Caj\u0105ce \u017Cyciu zaka\u017Cenia od pierwszych miesi\u0119cy \u017Cycia", "\u0442\u044F\u0436\u0451\u043B\u044B\u0435, \u043E\u043F\u0430\u0441\u043D\u044B\u0435 \u0434\u043B\u044F \u0436\u0438\u0437\u043D\u0438 \u0438\u043D\u0444\u0435\u043A\u0446\u0438\u0438 \u0441 \u043F\u0435\u0440\u0432\u044B\u0445 \u043C\u0435\u0441\u044F\u0446\u0435\u0432 \u0436\u0438\u0437\u043D\u0438", 3, ["SCID"], ["\u0422\u041A\u0418\u0414", "SCID"]],
  ["cukrzyca-1", "cukrzyca typu 1", "\u0441\u0430\u0445\u0430\u0440\u043D\u044B\u0439 \u0434\u0438\u0430\u0431\u0435\u0442 1 \u0442\u0438\u043F\u0430", "autoimmune", "zniszczenie kom\xF3rek beta wysp trzustkowych przez w\u0142asne limfocyty", "\u0440\u0430\u0437\u0440\u0443\u0448\u0435\u043D\u0438\u0435 \u0431\u0435\u0442\u0430-\u043A\u043B\u0435\u0442\u043E\u043A \u043E\u0441\u0442\u0440\u043E\u0432\u043A\u043E\u0432 \u043F\u043E\u0434\u0436\u0435\u043B\u0443\u0434\u043E\u0447\u043D\u043E\u0439 \u0436\u0435\u043B\u0435\u0437\u044B \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u043C\u0438 \u043B\u0438\u043C\u0444\u043E\u0446\u0438\u0442\u0430\u043C\u0438", "wielomocz, wzmo\u017Cone pragnienie i chudni\u0119cie u dziecka lub m\u0142odej osoby", "\u043E\u0431\u0438\u043B\u044C\u043D\u043E\u0435 \u043C\u043E\u0447\u0435\u0438\u0441\u043F\u0443\u0441\u043A\u0430\u043D\u0438\u0435, \u0441\u0438\u043B\u044C\u043D\u0430\u044F \u0436\u0430\u0436\u0434\u0430 \u0438 \u043F\u043E\u0445\u0443\u0434\u0435\u043D\u0438\u0435 \u0443 \u0440\u0435\u0431\u0451\u043D\u043A\u0430 \u0438\u043B\u0438 \u043C\u043E\u043B\u043E\u0434\u043E\u0433\u043E \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0430", 2, ["cukrzyca insulinozale\u017Cna"], ["\u0434\u0438\u0430\u0431\u0435\u0442 1 \u0442\u0438\u043F\u0430", "\u0438\u043D\u0441\u0443\u043B\u0438\u043D\u043E\u0437\u0430\u0432\u0438\u0441\u0438\u043C\u044B\u0439 \u0434\u0438\u0430\u0431\u0435\u0442"]],
  ["rzs", "reumatoidalne zapalenie staw\xF3w", "\u0440\u0435\u0432\u043C\u0430\u0442\u043E\u0438\u0434\u043D\u044B\u0439 \u0430\u0440\u0442\u0440\u0438\u0442", "autoimmune", "atak uk\u0142adu odporno\u015Bciowego na b\u0142on\u0119 maziow\u0105 staw\xF3w", "\u0430\u0442\u0430\u043A\u0430 \u0438\u043C\u043C\u0443\u043D\u043D\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u044B \u043D\u0430 \u0441\u0438\u043D\u043E\u0432\u0438\u0430\u043B\u044C\u043D\u0443\u044E \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0443 \u0441\u0443\u0441\u0442\u0430\u0432\u043E\u0432", "symetryczny b\xF3l, obrz\u0119k i poranna sztywno\u015B\u0107 drobnych staw\xF3w r\u0105k", "\u0441\u0438\u043C\u043C\u0435\u0442\u0440\u0438\u0447\u043D\u0430\u044F \u0431\u043E\u043B\u044C, \u043E\u0442\u0451\u043A \u0438 \u0443\u0442\u0440\u0435\u043D\u043D\u044F\u044F \u0441\u043A\u043E\u0432\u0430\u043D\u043D\u043E\u0441\u0442\u044C \u043C\u0435\u043B\u043A\u0438\u0445 \u0441\u0443\u0441\u0442\u0430\u0432\u043E\u0432 \u043A\u0438\u0441\u0442\u0435\u0439", 2, ["RZS"], ["\u0420\u0410"]],
  ["sm", "stwardnienie rozsiane", "\u0440\u0430\u0441\u0441\u0435\u044F\u043D\u043D\u044B\u0439 \u0441\u043A\u043B\u0435\u0440\u043E\u0437", "autoimmune", "niszczenie os\u0142onek mielinowych neuron\xF3w m\xF3zgu i rdzenia kr\u0119gowego przez limfocyty", "\u0440\u0430\u0437\u0440\u0443\u0448\u0435\u043D\u0438\u0435 \u043C\u0438\u0435\u043B\u0438\u043D\u043E\u0432\u044B\u0445 \u043E\u0431\u043E\u043B\u043E\u0447\u0435\u043A \u043D\u0435\u0439\u0440\u043E\u043D\u043E\u0432 \u0433\u043E\u043B\u043E\u0432\u043D\u043E\u0433\u043E \u0438 \u0441\u043F\u0438\u043D\u043D\u043E\u0433\u043E \u043C\u043E\u0437\u0433\u0430 \u043B\u0438\u043C\u0444\u043E\u0446\u0438\u0442\u0430\u043C\u0438", "zaburzenia widzenia, dr\u0119twienie i os\u0142abienie ko\u0144czyn pojawiaj\u0105ce si\u0119 rzutami", "\u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u044F \u0437\u0440\u0435\u043D\u0438\u044F, \u043E\u043D\u0435\u043C\u0435\u043D\u0438\u0435 \u0438 \u0441\u043B\u0430\u0431\u043E\u0441\u0442\u044C \u043A\u043E\u043D\u0435\u0447\u043D\u043E\u0441\u0442\u0435\u0439, \u0432\u043E\u0437\u043D\u0438\u043A\u0430\u044E\u0449\u0438\u0435 \u043E\u0431\u043E\u0441\u0442\u0440\u0435\u043D\u0438\u044F\u043C\u0438", 2, ["SM"], ["\u0420\u0421"]],
  ["hashimoto", "choroba Hashimoto", "\u0442\u0438\u0440\u0435\u043E\u0438\u0434\u0438\u0442 \u0425\u0430\u0448\u0438\u043C\u043E\u0442\u043E", "autoimmune", "przeciwcia\u0142a i limfocyty niszcz\u0105ce tarczyc\u0119", "\u0430\u043D\u0442\u0438\u0442\u0435\u043B\u0430 \u0438 \u043B\u0438\u043C\u0444\u043E\u0446\u0438\u0442\u044B, \u0440\u0430\u0437\u0440\u0443\u0448\u0430\u044E\u0449\u0438\u0435 \u0449\u0438\u0442\u043E\u0432\u0438\u0434\u043D\u0443\u044E \u0436\u0435\u043B\u0435\u0437\u0443", "objawy niedoczynno\u015Bci tarczycy: zm\u0119czenie, tycie i marzni\u0119cie", "\u043F\u0440\u0438\u0437\u043D\u0430\u043A\u0438 \u0433\u0438\u043F\u043E\u0442\u0438\u0440\u0435\u043E\u0437\u0430: \u0443\u0441\u0442\u0430\u043B\u043E\u0441\u0442\u044C, \u043D\u0430\u0431\u043E\u0440 \u0432\u0435\u0441\u0430 \u0438 \u0437\u044F\u0431\u043A\u043E\u0441\u0442\u044C", 2, ["zapalenie tarczycy Hashimoto"], ["\u0430\u0443\u0442\u043E\u0438\u043C\u043C\u0443\u043D\u043D\u044B\u0439 \u0442\u0438\u0440\u0435\u043E\u0438\u0434\u0438\u0442", "\u0431\u043E\u043B\u0435\u0437\u043D\u044C \u0425\u0430\u0448\u0438\u043C\u043E\u0442\u043E"]],
  ["odrzucenie", "odrzucenie przeszczepu", "\u043E\u0442\u0442\u043E\u0440\u0436\u0435\u043D\u0438\u0435 \u0442\u0440\u0430\u043D\u0441\u043F\u043B\u0430\u043D\u0442\u0430\u0442\u0430", "rejection", "rozpoznanie antygen\xF3w zgodno\u015Bci tkankowej przeszczepionego narz\u0105du jako obcych", "\u0440\u0430\u0441\u043F\u043E\u0437\u043D\u0430\u0432\u0430\u043D\u0438\u0435 \u0430\u043D\u0442\u0438\u0433\u0435\u043D\u043E\u0432 \u0442\u043A\u0430\u043D\u0435\u0432\u043E\u0439 \u0441\u043E\u0432\u043C\u0435\u0441\u0442\u0438\u043C\u043E\u0441\u0442\u0438 \u043F\u0435\u0440\u0435\u0441\u0430\u0436\u0435\u043D\u043D\u043E\u0433\u043E \u043E\u0440\u0433\u0430\u043D\u0430 \u043A\u0430\u043A \u0447\u0443\u0436\u0438\u0445", "utrata czynno\u015Bci przeszczepionego narz\u0105du mimo udanej operacji", "\u0443\u0442\u0440\u0430\u0442\u0430 \u0444\u0443\u043D\u043A\u0446\u0438\u0438 \u043F\u0435\u0440\u0435\u0441\u0430\u0436\u0435\u043D\u043D\u043E\u0433\u043E \u043E\u0440\u0433\u0430\u043D\u0430, \u043D\u0435\u0441\u043C\u043E\u0442\u0440\u044F \u043D\u0430 \u0443\u0434\u0430\u0447\u043D\u0443\u044E \u043E\u043F\u0435\u0440\u0430\u0446\u0438\u044E", 2, [], ["\u043E\u0442\u0442\u043E\u0440\u0436\u0435\u043D\u0438\u0435"]]
]);
var URINARY_DISORDERS = disorderTable(P.urinary.disorders, [
  ["zum", "zapalenie p\u0119cherza moczowego", "\u0446\u0438\u0441\u0442\u0438\u0442", "bacterial", "bakterie, najcz\u0119\u015Bciej pa\u0142eczki okr\u0119\u017Cnicy, wnikaj\u0105ce przez cewk\u0119 moczow\u0105", "\u0431\u0430\u043A\u0442\u0435\u0440\u0438\u0438, \u0447\u0430\u0449\u0435 \u0432\u0441\u0435\u0433\u043E \u043A\u0438\u0448\u0435\u0447\u043D\u0430\u044F \u043F\u0430\u043B\u043E\u0447\u043A\u0430, \u043F\u0440\u043E\u043D\u0438\u043A\u0430\u044E\u0449\u0438\u0435 \u0447\u0435\u0440\u0435\u0437 \u043C\u043E\u0447\u0435\u0438\u0441\u043F\u0443\u0441\u043A\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043A\u0430\u043D\u0430\u043B", "pieczenie i b\xF3l przy oddawaniu moczu oraz cz\u0119ste parcie na p\u0119cherz", "\u0436\u0436\u0435\u043D\u0438\u0435 \u0438 \u0431\u043E\u043B\u044C \u043F\u0440\u0438 \u043C\u043E\u0447\u0435\u0438\u0441\u043F\u0443\u0441\u043A\u0430\u043D\u0438\u0438, \u0447\u0430\u0441\u0442\u044B\u0435 \u043F\u043E\u0437\u044B\u0432\u044B", 1, ["zapalenie p\u0119cherza"], ["\u0432\u043E\u0441\u043F\u0430\u043B\u0435\u043D\u0438\u0435 \u043C\u043E\u0447\u0435\u0432\u043E\u0433\u043E \u043F\u0443\u0437\u044B\u0440\u044F"]],
  ["odmiedniczkowe", "odmiedniczkowe zapalenie nerek", "\u043F\u0438\u0435\u043B\u043E\u043D\u0435\u0444\u0440\u0438\u0442", "bacterial", "bakterie wst\u0119puj\u0105ce z p\u0119cherza moczowego przez moczowody do miedniczki nerkowej", "\u0431\u0430\u043A\u0442\u0435\u0440\u0438\u0438, \u043F\u043E\u0434\u043D\u0438\u043C\u0430\u044E\u0449\u0438\u0435\u0441\u044F \u0438\u0437 \u043C\u043E\u0447\u0435\u0432\u043E\u0433\u043E \u043F\u0443\u0437\u044B\u0440\u044F \u043F\u043E \u043C\u043E\u0447\u0435\u0442\u043E\u0447\u043D\u0438\u043A\u0430\u043C \u0432 \u043F\u043E\u0447\u0435\u0447\u043D\u0443\u044E \u043B\u043E\u0445\u0430\u043D\u043A\u0443", "wysoka gor\u0105czka z dreszczami i b\xF3l w okolicy l\u0119d\u017Awiowej", "\u0432\u044B\u0441\u043E\u043A\u0430\u044F \u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u0430 \u0441 \u043E\u0437\u043D\u043E\u0431\u043E\u043C \u0438 \u0431\u043E\u043B\u044C \u0432 \u043F\u043E\u044F\u0441\u043D\u0438\u0446\u0435", 2, [], []],
  ["kamica-nerkowa", "kamica nerkowa", "\u043C\u043E\u0447\u0435\u043A\u0430\u043C\u0435\u043D\u043D\u0430\u044F \u0431\u043E\u043B\u0435\u0437\u043D\u044C", "metabolic", "wytr\u0105canie si\u0119 z\u0142og\xF3w soli, np. szczawianu wapnia, z zag\u0119szczonego moczu", "\u0432\u044B\u043F\u0430\u0434\u0435\u043D\u0438\u0435 \u0441\u043E\u043B\u0435\u0439, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u043E\u043A\u0441\u0430\u043B\u0430\u0442\u0430 \u043A\u0430\u043B\u044C\u0446\u0438\u044F, \u0438\u0437 \u043A\u043E\u043D\u0446\u0435\u043D\u0442\u0440\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u043E\u0439 \u043C\u043E\u0447\u0438", "kolka nerkowa \u2014 nag\u0142y, bardzo silny b\xF3l w okolicy l\u0119d\u017Awiowej", "\u043F\u043E\u0447\u0435\u0447\u043D\u0430\u044F \u043A\u043E\u043B\u0438\u043A\u0430 \u2014 \u0432\u043D\u0435\u0437\u0430\u043F\u043D\u0430\u044F, \u043E\u0447\u0435\u043D\u044C \u0441\u0438\u043B\u044C\u043D\u0430\u044F \u0431\u043E\u043B\u044C \u0432 \u043F\u043E\u044F\u0441\u043D\u0438\u0446\u0435", 1, ["kamienie nerkowe"], ["\u043A\u0430\u043C\u043D\u0438 \u0432 \u043F\u043E\u0447\u043A\u0430\u0445", "\u043D\u0435\u0444\u0440\u043E\u043B\u0438\u0442\u0438\u0430\u0437"]],
  ["klebuszkowe", "k\u0142\u0119buszkowe zapalenie nerek", "\u0433\u043B\u043E\u043C\u0435\u0440\u0443\u043B\u043E\u043D\u0435\u0444\u0440\u0438\u0442", "autoimmune", "uszkodzenie k\u0142\u0119buszk\xF3w nerkowych przez kompleksy przeciwcia\u0142 z antygenami odk\u0142adaj\u0105ce si\u0119 w ich \u015Bcianach", "\u043F\u043E\u0432\u0440\u0435\u0436\u0434\u0435\u043D\u0438\u0435 \u043F\u043E\u0447\u0435\u0447\u043D\u044B\u0445 \u043A\u043B\u0443\u0431\u043E\u0447\u043A\u043E\u0432 \u043A\u043E\u043C\u043F\u043B\u0435\u043A\u0441\u0430\u043C\u0438 \u0430\u043D\u0442\u0438\u0442\u0435\u043B \u0441 \u0430\u043D\u0442\u0438\u0433\u0435\u043D\u0430\u043C\u0438, \u043E\u0441\u0435\u0434\u0430\u044E\u0449\u0438\u043C\u0438 \u0432 \u0438\u0445 \u0441\u0442\u0435\u043D\u043A\u0430\u0445", "bia\u0142ko i krew w moczu, obrz\u0119ki i nadci\u015Bnienie", "\u0431\u0435\u043B\u043E\u043A \u0438 \u043A\u0440\u043E\u0432\u044C \u0432 \u043C\u043E\u0447\u0435, \u043E\u0442\u0451\u043A\u0438 \u0438 \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u043D\u043E\u0435 \u0434\u0430\u0432\u043B\u0435\u043D\u0438\u0435", 2, [], []],
  ["niewydolnosc", "przewlek\u0142a niewydolno\u015B\u0107 nerek", "\u0445\u0440\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u043F\u043E\u0447\u0435\u0447\u043D\u0430\u044F \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E\u0441\u0442\u044C", "complication", "stopniowa utrata czynnych nefron\xF3w, najcz\u0119\u015Bciej wskutek cukrzycy i nadci\u015Bnienia", "\u043F\u043E\u0441\u0442\u0435\u043F\u0435\u043D\u043D\u0430\u044F \u043F\u043E\u0442\u0435\u0440\u044F \u0440\u0430\u0431\u043E\u0442\u0430\u044E\u0449\u0438\u0445 \u043D\u0435\u0444\u0440\u043E\u043D\u043E\u0432, \u0447\u0430\u0449\u0435 \u0432\u0441\u0435\u0433\u043E \u0438\u0437-\u0437\u0430 \u0434\u0438\u0430\u0431\u0435\u0442\u0430 \u0438 \u0433\u0438\u043F\u0435\u0440\u0442\u043E\u043D\u0438\u0438", "gromadzenie si\u0119 mocznika we krwi i obrz\u0119ki; w ko\u0144cu potrzebna dializa lub przeszczep", "\u043D\u0430\u043A\u043E\u043F\u043B\u0435\u043D\u0438\u0435 \u043C\u043E\u0447\u0435\u0432\u0438\u043D\u044B \u0432 \u043A\u0440\u043E\u0432\u0438 \u0438 \u043E\u0442\u0451\u043A\u0438; \u0432 \u0438\u0442\u043E\u0433\u0435 \u043D\u0443\u0436\u0435\u043D \u0434\u0438\u0430\u043B\u0438\u0437 \u0438\u043B\u0438 \u043F\u0435\u0440\u0435\u0441\u0430\u0434\u043A\u0430", 2, ["niewydolno\u015B\u0107 nerek"], ["\u043F\u043E\u0447\u0435\u0447\u043D\u0430\u044F \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E\u0441\u0442\u044C"]],
  ["wielotorbielowatosc", "wielotorbielowato\u015B\u0107 nerek", "\u043F\u043E\u043B\u0438\u043A\u0438\u0441\u0442\u043E\u0437 \u043F\u043E\u0447\u0435\u043A", "genetic", "dziedziczna wada powoduj\u0105ca powstawanie licznych torbieli w nerkach", "\u043D\u0430\u0441\u043B\u0435\u0434\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0434\u0435\u0444\u0435\u043A\u0442, \u043F\u0440\u0438 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u0432 \u043F\u043E\u0447\u043A\u0430\u0445 \u043E\u0431\u0440\u0430\u0437\u0443\u0435\u0442\u0441\u044F \u043C\u043D\u043E\u0436\u0435\u0441\u0442\u0432\u043E \u043A\u0438\u0441\u0442", "powi\u0119kszone nerki, nadci\u015Bnienie i stopniowa utrata ich czynno\u015Bci", "\u0443\u0432\u0435\u043B\u0438\u0447\u0435\u043D\u043D\u044B\u0435 \u043F\u043E\u0447\u043A\u0438, \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u043D\u043E\u0435 \u0434\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0438 \u043F\u043E\u0441\u0442\u0435\u043F\u0435\u043D\u043D\u0430\u044F \u0443\u0442\u0440\u0430\u0442\u0430 \u0438\u0445 \u0444\u0443\u043D\u043A\u0446\u0438\u0438", 3, [], ["\u043F\u043E\u043B\u0438\u043A\u0438\u0441\u0442\u043E\u0437\u043D\u0430\u044F \u0431\u043E\u043B\u0435\u0437\u043D\u044C \u043F\u043E\u0447\u0435\u043A"]],
  ["rak-pecherza", "rak p\u0119cherza moczowego", "\u0440\u0430\u043A \u043C\u043E\u0447\u0435\u0432\u043E\u0433\u043E \u043F\u0443\u0437\u044B\u0440\u044F", "cancer", "niekontrolowane podzia\u0142y kom\xF3rek nab\u0142onka p\u0119cherza, kt\xF3rym sprzyja palenie tytoniu", "\u043D\u0435\u043A\u043E\u043D\u0442\u0440\u043E\u043B\u0438\u0440\u0443\u0435\u043C\u043E\u0435 \u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u043A\u043B\u0435\u0442\u043E\u043A \u044D\u043F\u0438\u0442\u0435\u043B\u0438\u044F \u043F\u0443\u0437\u044B\u0440\u044F, \u043A\u043E\u0442\u043E\u0440\u043E\u043C\u0443 \u0441\u043F\u043E\u0441\u043E\u0431\u0441\u0442\u0432\u0443\u0435\u0442 \u043A\u0443\u0440\u0435\u043D\u0438\u0435", "bezbolesny krwiomocz", "\u0431\u0435\u0437\u0431\u043E\u043B\u0435\u0437\u043D\u0435\u043D\u043D\u0430\u044F \u043A\u0440\u043E\u0432\u044C \u0432 \u043C\u043E\u0447\u0435", 2, [], []],
  ["moczowka", "mocz\xF3wka prosta", "\u043D\u0435\u0441\u0430\u0445\u0430\u0440\u043D\u044B\u0439 \u0434\u0438\u0430\u0431\u0435\u0442", "hormonal", "niedob\xF3r wazopresyny lub brak reakcji nerek na ten hormon", "\u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u043A \u0432\u0430\u0437\u043E\u043F\u0440\u0435\u0441\u0441\u0438\u043D\u0430 \u0438\u043B\u0438 \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u0440\u0435\u0430\u043A\u0446\u0438\u0438 \u043F\u043E\u0447\u0435\u043A \u043D\u0430 \u044D\u0442\u043E\u0442 \u0433\u043E\u0440\u043C\u043E\u043D", "wydalanie kilkunastu litr\xF3w rozcie\u0144czonego moczu na dob\u0119 i silne pragnienie", "\u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u0431\u043E\u043B\u0435\u0435 \u0434\u0435\u0441\u044F\u0442\u0438 \u043B\u0438\u0442\u0440\u043E\u0432 \u0440\u0430\u0437\u0431\u0430\u0432\u043B\u0435\u043D\u043D\u043E\u0439 \u043C\u043E\u0447\u0438 \u0432 \u0441\u0443\u0442\u043A\u0438 \u0438 \u0441\u0438\u043B\u044C\u043D\u0430\u044F \u0436\u0430\u0436\u0434\u0430", 2, [], []]
]);
var NERVOUS_DISORDERS = disorderTable(P.nervous.disorders, [
  ["alzheimer", "choroba Alzheimera", "\u0431\u043E\u043B\u0435\u0437\u043D\u044C \u0410\u043B\u044C\u0446\u0433\u0435\u0439\u043C\u0435\u0440\u0430", "degenerative", "obumieranie neuron\xF3w kory m\xF3zgowej z odk\u0142adaniem si\u0119 z\u0142og\xF3w bia\u0142ka", "\u0433\u0438\u0431\u0435\u043B\u044C \u043D\u0435\u0439\u0440\u043E\u043D\u043E\u0432 \u043A\u043E\u0440\u044B \u0433\u043E\u043B\u043E\u0432\u043D\u043E\u0433\u043E \u043C\u043E\u0437\u0433\u0430 \u0441 \u043E\u0442\u043B\u043E\u0436\u0435\u043D\u0438\u0435\u043C \u0431\u0435\u043B\u043A\u043E\u0432\u044B\u0445 \u0431\u043B\u044F\u0448\u0435\u043A", "post\u0119puj\u0105ce zaburzenia pami\u0119ci \u015Bwie\u017Cej, orientacji i mowy u os\xF3b starszych", "\u043D\u0430\u0440\u0430\u0441\u0442\u0430\u044E\u0449\u0438\u0435 \u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u044F \u043F\u0430\u043C\u044F\u0442\u0438 \u043D\u0430 \u043D\u0435\u0434\u0430\u0432\u043D\u0438\u0435 \u0441\u043E\u0431\u044B\u0442\u0438\u044F, \u043E\u0440\u0438\u0435\u043D\u0442\u0430\u0446\u0438\u0438 \u0438 \u0440\u0435\u0447\u0438 \u0443 \u043F\u043E\u0436\u0438\u043B\u044B\u0445", 1, ["Alzheimer"], ["\u0410\u043B\u044C\u0446\u0433\u0435\u0439\u043C\u0435\u0440"]],
  ["parkinson", "choroba Parkinsona", "\u0431\u043E\u043B\u0435\u0437\u043D\u044C \u041F\u0430\u0440\u043A\u0438\u043D\u0441\u043E\u043D\u0430", "degenerative", "obumieranie neuron\xF3w istoty czarnej wytwarzaj\u0105cych dopamin\u0119", "\u0433\u0438\u0431\u0435\u043B\u044C \u043D\u0435\u0439\u0440\u043E\u043D\u043E\u0432 \u0447\u0451\u0440\u043D\u043E\u0439 \u0441\u0443\u0431\u0441\u0442\u0430\u043D\u0446\u0438\u0438, \u0432\u044B\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u044E\u0449\u0438\u0445 \u0434\u043E\u0444\u0430\u043C\u0438\u043D", "dr\u017Cenie spoczynkowe r\u0105k, spowolnienie ruch\xF3w i sztywno\u015B\u0107 mi\u0119\u015Bni", "\u0434\u0440\u043E\u0436\u0430\u043D\u0438\u0435 \u0440\u0443\u043A \u0432 \u043F\u043E\u043A\u043E\u0435, \u0437\u0430\u043C\u0435\u0434\u043B\u0435\u043D\u043D\u043E\u0441\u0442\u044C \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0439 \u0438 \u0441\u043A\u043E\u0432\u0430\u043D\u043D\u043E\u0441\u0442\u044C \u043C\u044B\u0448\u0446", 1, ["Parkinson"], ["\u041F\u0430\u0440\u043A\u0438\u043D\u0441\u043E\u043D"]],
  ["padaczka", "padaczka", "\u044D\u043F\u0438\u043B\u0435\u043F\u0441\u0438\u044F", "brain", "nag\u0142e, nadmierne i zsynchronizowane wy\u0142adowania grup neuron\xF3w w m\xF3zgu", "\u0432\u043D\u0435\u0437\u0430\u043F\u043D\u044B\u0435 \u0447\u0440\u0435\u0437\u043C\u0435\u0440\u043D\u044B\u0435 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u043D\u044B\u0435 \u0440\u0430\u0437\u0440\u044F\u0434\u044B \u0433\u0440\u0443\u043F\u043F \u043D\u0435\u0439\u0440\u043E\u043D\u043E\u0432 \u0432 \u043C\u043E\u0437\u0433\u0435", "nawracaj\u0105ce napady drgawek, cz\u0119sto z utrat\u0105 przytomno\u015Bci", "\u043F\u043E\u0432\u0442\u043E\u0440\u044F\u044E\u0449\u0438\u0435\u0441\u044F \u043F\u0440\u0438\u0441\u0442\u0443\u043F\u044B \u0441\u0443\u0434\u043E\u0440\u043E\u0433, \u0447\u0430\u0441\u0442\u043E \u0441 \u043F\u043E\u0442\u0435\u0440\u0435\u0439 \u0441\u043E\u0437\u043D\u0430\u043D\u0438\u044F", 1, ["epilepsja"], []],
  ["depresja", "depresja", "\u0434\u0435\u043F\u0440\u0435\u0441\u0441\u0438\u044F", "psychic", "zaburzenia przeka\u017Anictwa nerwowego, m.in. serotoninowego, cz\u0119sto po przewlek\u0142ym stresie", "\u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u044F \u043D\u0435\u0440\u0432\u043D\u043E\u0439 \u043F\u0435\u0440\u0435\u0434\u0430\u0447\u0438, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u0441\u0435\u0440\u043E\u0442\u043E\u043D\u0438\u043D\u043E\u0432\u043E\u0439, \u0447\u0430\u0441\u0442\u043E \u043F\u043E\u0441\u043B\u0435 \u0445\u0440\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u043E\u0433\u043E \u0441\u0442\u0440\u0435\u0441\u0441\u0430", "d\u0142ugotrwa\u0142y smutek, utrata zainteresowa\u0144 i zaburzenia snu oraz apetytu", "\u0434\u043B\u0438\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u043F\u043E\u0434\u0430\u0432\u043B\u0435\u043D\u043D\u043E\u0441\u0442\u044C, \u043F\u043E\u0442\u0435\u0440\u044F \u0438\u043D\u0442\u0435\u0440\u0435\u0441\u0430, \u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u044F \u0441\u043D\u0430 \u0438 \u0430\u043F\u043F\u0435\u0442\u0438\u0442\u0430", 1, [], []],
  ["meningitis", "bakteryjne zapalenie opon m\xF3zgowo-rdzeniowych", "\u0431\u0430\u043A\u0442\u0435\u0440\u0438\u0430\u043B\u044C\u043D\u044B\u0439 \u043C\u0435\u043D\u0438\u043D\u0433\u0438\u0442", "bacterial", "zaka\u017Cenie opon m\xF3zgowo-rdzeniowych bakteriami, np. meningokokami", "\u0437\u0430\u0440\u0430\u0436\u0435\u043D\u0438\u0435 \u043C\u043E\u0437\u0433\u043E\u0432\u044B\u0445 \u043E\u0431\u043E\u043B\u043E\u0447\u0435\u043A \u0431\u0430\u043A\u0442\u0435\u0440\u0438\u044F\u043C\u0438, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u043C\u0435\u043D\u0438\u043D\u0433\u043E\u043A\u043E\u043A\u043A\u0430\u043C\u0438", "wysoka gor\u0105czka, silny b\xF3l g\u0142owy, sztywno\u015B\u0107 karku i wysypka", "\u0432\u044B\u0441\u043E\u043A\u0430\u044F \u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u0430, \u0441\u0438\u043B\u044C\u043D\u0430\u044F \u0433\u043E\u043B\u043E\u0432\u043D\u0430\u044F \u0431\u043E\u043B\u044C, \u0440\u0438\u0433\u0438\u0434\u043D\u043E\u0441\u0442\u044C \u0437\u0430\u0442\u044B\u043B\u043E\u0447\u043D\u044B\u0445 \u043C\u044B\u0448\u0446 \u0438 \u0441\u044B\u043F\u044C", 2, ["zapalenie opon m\xF3zgowo-rdzeniowych"], ["\u043C\u0435\u043D\u0438\u043D\u0433\u0438\u0442"]],
  ["kzm", "kleszczowe zapalenie m\xF3zgu", "\u043A\u043B\u0435\u0449\u0435\u0432\u043E\u0439 \u044D\u043D\u0446\u0435\u0444\u0430\u043B\u0438\u0442", "viral", "wirus przenoszony przez uk\u0105szenie kleszcza", "\u0432\u0438\u0440\u0443\u0441, \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0449\u0438\u0439\u0441\u044F \u043F\u0440\u0438 \u0443\u043A\u0443\u0441\u0435 \u043A\u043B\u0435\u0449\u0430", "gor\u0105czka i b\xF3le g\u0142owy, a po kilku dniach zaburzenia \u015Bwiadomo\u015Bci i niedow\u0142ady", "\u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u0430 \u0438 \u0433\u043E\u043B\u043E\u0432\u043D\u0430\u044F \u0431\u043E\u043B\u044C, \u0430 \u0447\u0435\u0440\u0435\u0437 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0434\u043D\u0435\u0439 \u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u044F \u0441\u043E\u0437\u043D\u0430\u043D\u0438\u044F \u0438 \u043F\u0430\u0440\u0430\u043B\u0438\u0447\u0438", 2, ["KZM"], []],
  ["borelioza", "borelioza", "\u0431\u043E\u0440\u0440\u0435\u043B\u0438\u043E\u0437", "bacterial", "kr\u0119tki przenoszone przez kleszcze", "\u0441\u043F\u0438\u0440\u043E\u0445\u0435\u0442\u044B, \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0449\u0438\u0435\u0441\u044F \u043A\u043B\u0435\u0449\u0430\u043C\u0438", "rumie\u0144 w\u0119druj\u0105cy wok\xF3\u0142 miejsca uk\u0105szenia, p\xF3\u017Aniej b\xF3le staw\xF3w i zaburzenia nerwowe", "\u043C\u0438\u0433\u0440\u0438\u0440\u0443\u044E\u0449\u0430\u044F \u044D\u0440\u0438\u0442\u0435\u043C\u0430 \u0432\u043E\u043A\u0440\u0443\u0433 \u043C\u0435\u0441\u0442\u0430 \u0443\u043A\u0443\u0441\u0430, \u043F\u043E\u0437\u0436\u0435 \u0431\u043E\u043B\u0438 \u0432 \u0441\u0443\u0441\u0442\u0430\u0432\u0430\u0445 \u0438 \u043D\u0435\u0440\u0432\u043D\u044B\u0435 \u043D\u0430\u0440\u0443\u0448\u0435\u043D\u0438\u044F", 2, ["choroba z Lyme"], ["\u0431\u043E\u043B\u0435\u0437\u043D\u044C \u041B\u0430\u0439\u043C\u0430", "\u043A\u043B\u0435\u0449\u0435\u0432\u043E\u0439 \u0431\u043E\u0440\u0440\u0435\u043B\u0438\u043E\u0437"]],
  ["wscieklizna", "w\u015Bcieklizna", "\u0431\u0435\u0448\u0435\u043D\u0441\u0442\u0432\u043E", "viral", "wirus przenoszony przez ugryzienie chorego zwierz\u0119cia", "\u0432\u0438\u0440\u0443\u0441, \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0449\u0438\u0439\u0441\u044F \u043F\u0440\u0438 \u0443\u043A\u0443\u0441\u0435 \u0431\u043E\u043B\u044C\u043D\u043E\u0433\u043E \u0436\u0438\u0432\u043E\u0442\u043D\u043E\u0433\u043E", "wodowstr\u0119t, pobudzenie i pora\u017Cenia; bez szczepienia po ugryzieniu choroba ko\u0144czy si\u0119 \u015Bmierci\u0105", "\u0432\u043E\u0434\u043E\u0431\u043E\u044F\u0437\u043D\u044C, \u0432\u043E\u0437\u0431\u0443\u0436\u0434\u0435\u043D\u0438\u0435 \u0438 \u043F\u0430\u0440\u0430\u043B\u0438\u0447\u0438; \u0431\u0435\u0437 \u043F\u0440\u0438\u0432\u0438\u0432\u043A\u0438 \u043F\u043E\u0441\u043B\u0435 \u0443\u043A\u0443\u0441\u0430 \u0431\u043E\u043B\u0435\u0437\u043D\u044C \u0441\u043C\u0435\u0440\u0442\u0435\u043B\u044C\u043D\u0430", 2, [], []]
]);
var REPRODUCTIVE_DISORDERS = disorderTable(P.reproduction.disorders, [
  ["kila", "ki\u0142a", "\u0441\u0438\u0444\u0438\u043B\u0438\u0441", "bacterial", "kr\u0119tek blady przenoszony drog\u0105 p\u0142ciow\u0105", "\u0431\u043B\u0435\u0434\u043D\u0430\u044F \u0442\u0440\u0435\u043F\u043E\u043D\u0435\u043C\u0430, \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0449\u0430\u044F\u0441\u044F \u043F\u043E\u043B\u043E\u0432\u044B\u043C \u043F\u0443\u0442\u0451\u043C", "niebolesne owrzodzenie w miejscu zaka\u017Cenia, p\xF3\u017Aniej wysypka na sk\xF3rze", "\u0431\u0435\u0437\u0431\u043E\u043B\u0435\u0437\u043D\u0435\u043D\u043D\u0430\u044F \u044F\u0437\u0432\u0430 \u043D\u0430 \u043C\u0435\u0441\u0442\u0435 \u0437\u0430\u0440\u0430\u0436\u0435\u043D\u0438\u044F, \u043F\u043E\u0437\u0436\u0435 \u0441\u044B\u043F\u044C \u043D\u0430 \u043A\u043E\u0436\u0435", 2, ["syfilis"], []],
  ["rzezaczka", "rze\u017C\u0105czka", "\u0433\u043E\u043D\u043E\u0440\u0435\u044F", "bacterial", "dwoinki rze\u017C\u0105czki przenoszone drog\u0105 p\u0142ciow\u0105", "\u0433\u043E\u043D\u043E\u043A\u043E\u043A\u043A\u0438, \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0449\u0438\u0435\u0441\u044F \u043F\u043E\u043B\u043E\u0432\u044B\u043C \u043F\u0443\u0442\u0451\u043C", "ropna wydzielina i pieczenie przy oddawaniu moczu", "\u0433\u043D\u043E\u0439\u043D\u044B\u0435 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u0438 \u0436\u0436\u0435\u043D\u0438\u0435 \u043F\u0440\u0438 \u043C\u043E\u0447\u0435\u0438\u0441\u043F\u0443\u0441\u043A\u0430\u043D\u0438\u0438", 2, [], []],
  ["chlamydioza", "chlamydioza", "\u0445\u043B\u0430\u043C\u0438\u0434\u0438\u043E\u0437", "bacterial", "bakterie Chlamydia trachomatis przenoszone drog\u0105 p\u0142ciow\u0105", "\u0431\u0430\u043A\u0442\u0435\u0440\u0438\u0438 Chlamydia trachomatis, \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0449\u0438\u0435\u0441\u044F \u043F\u043E\u043B\u043E\u0432\u044B\u043C \u043F\u0443\u0442\u0451\u043C", "cz\u0119sto brak objaw\xF3w; nieleczona mo\u017Ce prowadzi\u0107 do niep\u0142odno\u015Bci", "\u0447\u0430\u0441\u0442\u043E \u043F\u0440\u043E\u0442\u0435\u043A\u0430\u0435\u0442 \u0431\u0435\u0437 \u0441\u0438\u043C\u043F\u0442\u043E\u043C\u043E\u0432; \u0431\u0435\u0437 \u043B\u0435\u0447\u0435\u043D\u0438\u044F \u043C\u043E\u0436\u0435\u0442 \u043F\u0440\u0438\u0432\u0435\u0441\u0442\u0438 \u043A \u0431\u0435\u0441\u043F\u043B\u043E\u0434\u0438\u044E", 2, [], []],
  ["opryszczka", "opryszczka narz\u0105d\xF3w p\u0142ciowych", "\u0433\u0435\u043D\u0438\u0442\u0430\u043B\u044C\u043D\u044B\u0439 \u0433\u0435\u0440\u043F\u0435\u0441", "viral", "wirus opryszczki pospolitej przenoszony drog\u0105 p\u0142ciow\u0105", "\u0432\u0438\u0440\u0443\u0441 \u043F\u0440\u043E\u0441\u0442\u043E\u0433\u043E \u0433\u0435\u0440\u043F\u0435\u0441\u0430, \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0449\u0438\u0439\u0441\u044F \u043F\u043E\u043B\u043E\u0432\u044B\u043C \u043F\u0443\u0442\u0451\u043C", "bolesne, nawracaj\u0105ce p\u0119cherzyki na narz\u0105dach p\u0142ciowych", "\u0431\u043E\u043B\u0435\u0437\u043D\u0435\u043D\u043D\u044B\u0435 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u044E\u0449\u0438\u0435\u0441\u044F \u043F\u0443\u0437\u044B\u0440\u044C\u043A\u0438 \u043D\u0430 \u043F\u043E\u043B\u043E\u0432\u044B\u0445 \u043E\u0440\u0433\u0430\u043D\u0430\u0445", 2, ["opryszczka genitalna"], ["\u0433\u0435\u0440\u043F\u0435\u0441"]],
  ["hpv", "zaka\u017Cenie HPV", "\u043F\u0430\u043F\u0438\u043B\u043B\u043E\u043C\u0430\u0432\u0438\u0440\u0443\u0441\u043D\u0430\u044F \u0438\u043D\u0444\u0435\u043A\u0446\u0438\u044F", "viral", "wirus brodawczaka ludzkiego przenoszony drog\u0105 p\u0142ciow\u0105", "\u0432\u0438\u0440\u0443\u0441 \u043F\u0430\u043F\u0438\u043B\u043B\u043E\u043C\u044B \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0430, \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0449\u0438\u0439\u0441\u044F \u043F\u043E\u043B\u043E\u0432\u044B\u043C \u043F\u0443\u0442\u0451\u043C", "k\u0142ykciny ko\u0144czyste; niekt\xF3re typy wirusa mog\u0105 wywo\u0142a\u0107 raka szyjki macicy", "\u043E\u0441\u0442\u0440\u043E\u043A\u043E\u043D\u0435\u0447\u043D\u044B\u0435 \u043A\u043E\u043D\u0434\u0438\u043B\u043E\u043C\u044B; \u043D\u0435\u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0442\u0438\u043F\u044B \u0432\u0438\u0440\u0443\u0441\u0430 \u043C\u043E\u0433\u0443\u0442 \u0432\u044B\u0437\u0432\u0430\u0442\u044C \u0440\u0430\u043A \u0448\u0435\u0439\u043A\u0438 \u043C\u0430\u0442\u043A\u0438", 2, ["HPV"], ["\u0412\u041F\u0427", "\u0412\u041F\u0427-\u0438\u043D\u0444\u0435\u043A\u0446\u0438\u044F"]],
  ["rzesistkowica", "rz\u0119sistkowica", "\u0442\u0440\u0438\u0445\u043E\u043C\u043E\u043D\u0438\u0430\u0437", "parasitic", "pierwotniak rz\u0119sistek pochwowy przenoszony drog\u0105 p\u0142ciow\u0105", "\u043F\u0440\u043E\u0441\u0442\u0435\u0439\u0448\u0435\u0435 \u2014 \u0432\u043B\u0430\u0433\u0430\u043B\u0438\u0449\u043D\u0430\u044F \u0442\u0440\u0438\u0445\u043E\u043C\u043E\u043D\u0430\u0434\u0430, \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0449\u0430\u044F\u0441\u044F \u043F\u043E\u043B\u043E\u0432\u044B\u043C \u043F\u0443\u0442\u0451\u043C", "pieniste up\u0142awy, sw\u0119dzenie i pieczenie", "\u043F\u0435\u043D\u0438\u0441\u0442\u044B\u0435 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F, \u0437\u0443\u0434 \u0438 \u0436\u0436\u0435\u043D\u0438\u0435", 3, [], []],
  ["rak-szyjki", "rak szyjki macicy", "\u0440\u0430\u043A \u0448\u0435\u0439\u043A\u0438 \u043C\u0430\u0442\u043A\u0438", "cancer", "niekontrolowane podzia\u0142y kom\xF3rek nab\u0142onka szyjki macicy, wywo\u0142ane najcz\u0119\u015Bciej przewlek\u0142ym zaka\u017Ceniem onkogennymi typami HPV", "\u043D\u0435\u043A\u043E\u043D\u0442\u0440\u043E\u043B\u0438\u0440\u0443\u0435\u043C\u043E\u0435 \u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u043A\u043B\u0435\u0442\u043E\u043A \u044D\u043F\u0438\u0442\u0435\u043B\u0438\u044F \u0448\u0435\u0439\u043A\u0438 \u043C\u0430\u0442\u043A\u0438, \u0432\u044B\u0437\u0432\u0430\u043D\u043D\u043E\u0435 \u0447\u0430\u0449\u0435 \u0432\u0441\u0435\u0433\u043E \u0445\u0440\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u043E\u0439 \u0438\u043D\u0444\u0435\u043A\u0446\u0438\u0435\u0439 \u043E\u043D\u043A\u043E\u0433\u0435\u043D\u043D\u044B\u043C\u0438 \u0442\u0438\u043F\u0430\u043C\u0438 \u0412\u041F\u0427", "nieprawid\u0142owe krwawienia; we wczesnym stadium wykrywany badaniem cytologicznym", "\u043D\u0435\u0442\u0438\u043F\u0438\u0447\u043D\u044B\u0435 \u043A\u0440\u043E\u0432\u043E\u0442\u0435\u0447\u0435\u043D\u0438\u044F; \u043D\u0430 \u0440\u0430\u043D\u043D\u0435\u0439 \u0441\u0442\u0430\u0434\u0438\u0438 \u0432\u044B\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0446\u0438\u0442\u043E\u043B\u043E\u0433\u0438\u0447\u0435\u0441\u043A\u0438\u043C \u043C\u0430\u0437\u043A\u043E\u043C", 2, [], []],
  ["rak-prostaty", "rak gruczo\u0142u krokowego", "\u0440\u0430\u043A \u043F\u0440\u0435\u0434\u0441\u0442\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0439 \u0436\u0435\u043B\u0435\u0437\u044B", "cancer", "niekontrolowane podzia\u0142y kom\xF3rek gruczo\u0142u krokowego, g\u0142\xF3wnie u starszych m\u0119\u017Cczyzn", "\u043D\u0435\u043A\u043E\u043D\u0442\u0440\u043E\u043B\u0438\u0440\u0443\u0435\u043C\u043E\u0435 \u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u043A\u043B\u0435\u0442\u043E\u043A \u043F\u0440\u0435\u0434\u0441\u0442\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0439 \u0436\u0435\u043B\u0435\u0437\u044B, \u0432 \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u043C \u0443 \u043F\u043E\u0436\u0438\u043B\u044B\u0445 \u043C\u0443\u0436\u0447\u0438\u043D", "trudno\u015Bci w oddawaniu moczu i cz\u0119ste parcie na p\u0119cherz", "\u0437\u0430\u0442\u0440\u0443\u0434\u043D\u0451\u043D\u043D\u043E\u0435 \u043C\u043E\u0447\u0435\u0438\u0441\u043F\u0443\u0441\u043A\u0430\u043D\u0438\u0435 \u0438 \u0447\u0430\u0441\u0442\u044B\u0435 \u043F\u043E\u0437\u044B\u0432\u044B", 2, ["rak prostaty"], ["\u0440\u0430\u043A \u043F\u0440\u043E\u0441\u0442\u0430\u0442\u044B"]],
  ["rak-piersi", "rak piersi", "\u0440\u0430\u043A \u043C\u043E\u043B\u043E\u0447\u043D\u043E\u0439 \u0436\u0435\u043B\u0435\u0437\u044B", "cancer", "niekontrolowane podzia\u0142y kom\xF3rek gruczo\u0142u sutkowego", "\u043D\u0435\u043A\u043E\u043D\u0442\u0440\u043E\u043B\u0438\u0440\u0443\u0435\u043C\u043E\u0435 \u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u043A\u043B\u0435\u0442\u043E\u043A \u043C\u043E\u043B\u043E\u0447\u043D\u043E\u0439 \u0436\u0435\u043B\u0435\u0437\u044B", "wyczuwalny guzek w piersi, wci\u0105gni\u0119cie brodawki lub zmiana sk\xF3ry", "\u043F\u0440\u043E\u0449\u0443\u043F\u044B\u0432\u0430\u0435\u043C\u043E\u0435 \u0443\u043F\u043B\u043E\u0442\u043D\u0435\u043D\u0438\u0435 \u0432 \u0433\u0440\u0443\u0434\u0438, \u0432\u0442\u044F\u043D\u0443\u0442\u044B\u0439 \u0441\u043E\u0441\u043E\u043A \u0438\u043B\u0438 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0435 \u043A\u043E\u0436\u0438", 1, [], ["\u0440\u0430\u043A \u0433\u0440\u0443\u0434\u0438"]]
]);

