var ORGANIC_NUTRIENTS = namedTable(P.digestion.organic, [
  ["glukoza", "glukoza", "\u0433\u043B\u044E\u043A\u043E\u0437\u0430", "cukier prosty, g\u0142\xF3wne \u017Ar\xF3d\u0142o energii dla kom\xF3rek, zw\u0142aszcza neuron\xF3w", "\u043F\u0440\u043E\u0441\u0442\u043E\u0439 \u0441\u0430\u0445\u0430\u0440, \u0433\u043B\u0430\u0432\u043D\u044B\u0439 \u0438\u0441\u0442\u043E\u0447\u043D\u0438\u043A \u044D\u043D\u0435\u0440\u0433\u0438\u0438 \u0434\u043B\u044F \u043A\u043B\u0435\u0442\u043E\u043A, \u043E\u0441\u043E\u0431\u0435\u043D\u043D\u043E \u043D\u0435\u0439\u0440\u043E\u043D\u043E\u0432", 1, ["cukier gronowy"], ["\u0432\u0438\u043D\u043E\u0433\u0440\u0430\u0434\u043D\u044B\u0439 \u0441\u0430\u0445\u0430\u0440"]],
  ["skrobia", "skrobia", "\u043A\u0440\u0430\u0445\u043C\u0430\u043B", "wielocukier zapasowy ro\u015Blin, trawiony w przewodzie pokarmowym do glukozy", "\u0437\u0430\u043F\u0430\u0441\u043D\u043E\u0439 \u043F\u043E\u043B\u0438\u0441\u0430\u0445\u0430\u0440\u0438\u0434 \u0440\u0430\u0441\u0442\u0435\u043D\u0438\u0439, \u043F\u0435\u0440\u0435\u0432\u0430\u0440\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0432 \u043F\u0438\u0449\u0435\u0432\u0430\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u043C \u0442\u0440\u0430\u043A\u0442\u0435 \u0434\u043E \u0433\u043B\u044E\u043A\u043E\u0437\u044B", 1, [], []],
  ["blonnik", "b\u0142onnik pokarmowy", "\u043F\u0438\u0449\u0435\u0432\u044B\u0435 \u0432\u043E\u043B\u043E\u043A\u043D\u0430", "nietrawione przez cz\u0142owieka sk\u0142adniki \u015Bcian kom\xF3rek ro\u015Blinnych, pobudzaj\u0105ce perystaltyk\u0119 jelit", "\u043D\u0435\u043F\u0435\u0440\u0435\u0432\u0430\u0440\u0438\u043C\u044B\u0435 \u0434\u043B\u044F \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0430 \u043A\u043E\u043C\u043F\u043E\u043D\u0435\u043D\u0442\u044B \u0441\u0442\u0435\u043D\u043E\u043A \u0440\u0430\u0441\u0442\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u043A\u043B\u0435\u0442\u043E\u043A, \u0443\u0441\u0438\u043B\u0438\u0432\u0430\u044E\u0449\u0438\u0435 \u043F\u0435\u0440\u0438\u0441\u0442\u0430\u043B\u044C\u0442\u0438\u043A\u0443 \u043A\u0438\u0448\u0435\u0447\u043D\u0438\u043A\u0430", 1, ["b\u0142onnik"], ["\u043A\u043B\u0435\u0442\u0447\u0430\u0442\u043A\u0430"]],
  ["glikogen", "glikogen", "\u0433\u043B\u0438\u043A\u043E\u0433\u0435\u043D", "wielocukier zapasowy zwierz\u0105t, magazynowany w w\u0105trobie i mi\u0119\u015Bniach", "\u0437\u0430\u043F\u0430\u0441\u043D\u043E\u0439 \u043F\u043E\u043B\u0438\u0441\u0430\u0445\u0430\u0440\u0438\u0434 \u0436\u0438\u0432\u043E\u0442\u043D\u044B\u0445, \u0445\u0440\u0430\u043D\u044F\u0449\u0438\u0439\u0441\u044F \u0432 \u043F\u0435\u0447\u0435\u043D\u0438 \u0438 \u043C\u044B\u0448\u0446\u0430\u0445", 1, [], []],
  ["laktoza", "laktoza", "\u043B\u0430\u043A\u0442\u043E\u0437\u0430", "dwucukier mleka, rozk\u0142adany w jelicie na glukoz\u0119 i galaktoz\u0119", "\u0434\u0438\u0441\u0430\u0445\u0430\u0440\u0438\u0434 \u043C\u043E\u043B\u043E\u043A\u0430, \u0440\u0430\u0441\u0449\u0435\u043F\u043B\u044F\u0435\u043C\u044B\u0439 \u0432 \u043A\u0438\u0448\u0435\u0447\u043D\u0438\u043A\u0435 \u043D\u0430 \u0433\u043B\u044E\u043A\u043E\u0437\u0443 \u0438 \u0433\u0430\u043B\u0430\u043A\u0442\u043E\u0437\u0443", 2, ["cukier mlekowy"], ["\u043C\u043E\u043B\u043E\u0447\u043D\u044B\u0439 \u0441\u0430\u0445\u0430\u0440"]],
  ["aminokwasy-egzogenne", "aminokwasy egzogenne", "\u043D\u0435\u0437\u0430\u043C\u0435\u043D\u0438\u043C\u044B\u0435 \u0430\u043C\u0438\u043D\u043E\u043A\u0438\u0441\u043B\u043E\u0442\u044B", "sk\u0142adniki bia\u0142ek, kt\xF3rych organizm cz\u0142owieka nie wytwarza i musi otrzyma\u0107 z po\u017Cywieniem", "\u043A\u043E\u043C\u043F\u043E\u043D\u0435\u043D\u0442\u044B \u0431\u0435\u043B\u043A\u043E\u0432, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043E\u0440\u0433\u0430\u043D\u0438\u0437\u043C \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0430 \u043D\u0435 \u0441\u0438\u043D\u0442\u0435\u0437\u0438\u0440\u0443\u0435\u0442 \u0438 \u0434\u043E\u043B\u0436\u0435\u043D \u043F\u043E\u043B\u0443\u0447\u0430\u0442\u044C \u0441 \u043F\u0438\u0449\u0435\u0439", 2, ["aminokwasy niezb\u0119dne"], ["\u044D\u0441\u0441\u0435\u043D\u0446\u0438\u0430\u043B\u044C\u043D\u044B\u0435 \u0430\u043C\u0438\u043D\u043E\u043A\u0438\u0441\u043B\u043E\u0442\u044B"]],
  ["bialko-pelnowartosciowe", "bia\u0142ko pe\u0142nowarto\u015Bciowe", "\u043F\u043E\u043B\u043D\u043E\u0446\u0435\u043D\u043D\u044B\u0439 \u0431\u0435\u043B\u043E\u043A", "sk\u0142adnik pokarmu zawieraj\u0105cy wszystkie aminokwasy egzogenne w odpowiednich proporcjach, np. z jaj i mleka", "\u043A\u043E\u043C\u043F\u043E\u043D\u0435\u043D\u0442 \u043F\u0438\u0449\u0438, \u0441\u043E\u0434\u0435\u0440\u0436\u0430\u0449\u0438\u0439 \u0432\u0441\u0435 \u043D\u0435\u0437\u0430\u043C\u0435\u043D\u0438\u043C\u044B\u0435 \u0430\u043C\u0438\u043D\u043E\u043A\u0438\u0441\u043B\u043E\u0442\u044B \u0432 \u043D\u0443\u0436\u043D\u044B\u0445 \u043F\u0440\u043E\u043F\u043E\u0440\u0446\u0438\u044F\u0445, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0438\u0437 \u044F\u0438\u0446 \u0438 \u043C\u043E\u043B\u043E\u043A\u0430", 2, [], []],
  ["tluszcze", "t\u0142uszcze", "\u0436\u0438\u0440\u044B", "estry glicerolu i wy\u017Cszych kwas\xF3w karboksylowych \u2014 najbardziej kaloryczny materia\u0142 zapasowy organizmu", "\u0441\u043B\u043E\u0436\u043D\u044B\u0435 \u044D\u0444\u0438\u0440\u044B \u0433\u043B\u0438\u0446\u0435\u0440\u0438\u043D\u0430 \u0438 \u0432\u044B\u0441\u0448\u0438\u0445 \u043A\u0430\u0440\u0431\u043E\u043D\u043E\u0432\u044B\u0445 \u043A\u0438\u0441\u043B\u043E\u0442 \u2014 \u0441\u0430\u043C\u044B\u0439 \u043A\u0430\u043B\u043E\u0440\u0438\u0439\u043D\u044B\u0439 \u0437\u0430\u043F\u0430\u0441\u043D\u043E\u0439 \u043C\u0430\u0442\u0435\u0440\u0438\u0430\u043B \u043E\u0440\u0433\u0430\u043D\u0438\u0437\u043C\u0430", 1, ["triglicerydy", "triacyloglicerole"], ["\u0442\u0440\u0438\u0433\u043B\u0438\u0446\u0435\u0440\u0438\u0434\u044B"]],
  ["nienasycone", "nienasycone kwasy t\u0142uszczowe", "\u043D\u0435\u043D\u0430\u0441\u044B\u0449\u0435\u043D\u043D\u044B\u0435 \u0436\u0438\u0440\u043D\u044B\u0435 \u043A\u0438\u0441\u043B\u043E\u0442\u044B", "sk\u0142adniki lipid\xF3w z wi\u0105zaniami podw\xF3jnymi, obecne w olejach ro\u015Blinnych i rybach, korzystne dla uk\u0142adu kr\u0105\u017Cenia", "\u043A\u043E\u043C\u043F\u043E\u043D\u0435\u043D\u0442\u044B \u043B\u0438\u043F\u0438\u0434\u043E\u0432 \u0441 \u0434\u0432\u043E\u0439\u043D\u044B\u043C\u0438 \u0441\u0432\u044F\u0437\u044F\u043C\u0438 \u0438\u0437 \u0440\u0430\u0441\u0442\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u043C\u0430\u0441\u0435\u043B \u0438 \u0440\u044B\u0431\u044B, \u043F\u043E\u043B\u0435\u0437\u043D\u044B\u0435 \u0434\u043B\u044F \u043A\u0440\u043E\u0432\u0435\u043D\u043E\u0441\u043D\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u044B", 2, [], []],
  ["cholesterol", "cholesterol", "\u0445\u043E\u043B\u0435\u0441\u0442\u0435\u0440\u0438\u043D", "lipid buduj\u0105cy b\u0142ony kom\xF3rkowe i substrat do syntezy hormon\xF3w steroidowych, kt\xF3rego nadmiar sprzyja mia\u017Cd\u017Cycy", "\u043B\u0438\u043F\u0438\u0434, \u0432\u0445\u043E\u0434\u044F\u0449\u0438\u0439 \u0432 \u043A\u043B\u0435\u0442\u043E\u0447\u043D\u044B\u0435 \u043C\u0435\u043C\u0431\u0440\u0430\u043D\u044B \u0438 \u0441\u043B\u0443\u0436\u0430\u0449\u0438\u0439 \u0441\u044B\u0440\u044C\u0451\u043C \u0434\u043B\u044F \u0441\u0442\u0435\u0440\u043E\u0438\u0434\u043D\u044B\u0445 \u0433\u043E\u0440\u043C\u043E\u043D\u043E\u0432; \u0435\u0433\u043E \u0438\u0437\u0431\u044B\u0442\u043E\u043A \u0441\u043F\u043E\u0441\u043E\u0431\u0441\u0442\u0432\u0443\u0435\u0442 \u0430\u0442\u0435\u0440\u043E\u0441\u043A\u043B\u0435\u0440\u043E\u0437\u0443", 1, [], ["\u0445\u043E\u043B\u0435\u0441\u0442\u0435\u0440\u043E\u043B"]]
]);
var VITAMINS_MINERALS = namedTable(P.digestion.vitamins, [
  ["wit-a", "witamina A", "\u0432\u0438\u0442\u0430\u043C\u0438\u043D A", "sk\u0142adnik barwnika wzrokowego w pr\u0119cikach; jej niedob\xF3r powoduje kurz\u0105 \u015Blepot\u0119", "\u043A\u043E\u043C\u043F\u043E\u043D\u0435\u043D\u0442 \u0437\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u043F\u0438\u0433\u043C\u0435\u043D\u0442\u0430 \u0432 \u043F\u0430\u043B\u043E\u0447\u043A\u0430\u0445; \u0435\u0451 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u043A \u0432\u044B\u0437\u044B\u0432\u0430\u0435\u0442 \u043A\u0443\u0440\u0438\u043D\u0443\u044E \u0441\u043B\u0435\u043F\u043E\u0442\u0443", 1, ["retinol"], ["\u0440\u0435\u0442\u0438\u043D\u043E\u043B", "\u0432\u0438\u0442\u0430\u043C\u0438\u043D \u0410"]],
  ["wit-d", "witamina D", "\u0432\u0438\u0442\u0430\u043C\u0438\u043D D", "regulacja wch\u0142aniania wapnia i fosforu; jej niedob\xF3r powoduje u dzieci krzywic\u0119", "\u0440\u0435\u0433\u0443\u043B\u044F\u0446\u0438\u044F \u0432\u0441\u0430\u0441\u044B\u0432\u0430\u043D\u0438\u044F \u043A\u0430\u043B\u044C\u0446\u0438\u044F \u0438 \u0444\u043E\u0441\u0444\u043E\u0440\u0430; \u0435\u0451 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u043A \u0432\u044B\u0437\u044B\u0432\u0430\u0435\u0442 \u0443 \u0434\u0435\u0442\u0435\u0439 \u0440\u0430\u0445\u0438\u0442", 1, ["kalcyferol", "cholekalcyferol"], ["\u043A\u0430\u043B\u044C\u0446\u0438\u0444\u0435\u0440\u043E\u043B", "\u0445\u043E\u043B\u0435\u043A\u0430\u043B\u044C\u0446\u0438\u0444\u0435\u0440\u043E\u043B"]],
  ["wit-k", "witamina K", "\u0432\u0438\u0442\u0430\u043C\u0438\u043D K", "udzia\u0142 w wytwarzaniu czynnik\xF3w krzepni\u0119cia krwi; wytwarzaj\u0105 j\u0105 te\u017C bakterie jelitowe", "\u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u0432 \u043E\u0431\u0440\u0430\u0437\u043E\u0432\u0430\u043D\u0438\u0438 \u0444\u0430\u043A\u0442\u043E\u0440\u043E\u0432 \u0441\u0432\u0451\u0440\u0442\u044B\u0432\u0430\u043D\u0438\u044F \u043A\u0440\u043E\u0432\u0438; \u0435\u0451 \u0442\u0430\u043A\u0436\u0435 \u0441\u0438\u043D\u0442\u0435\u0437\u0438\u0440\u0443\u044E\u0442 \u043A\u0438\u0448\u0435\u0447\u043D\u044B\u0435 \u0431\u0430\u043A\u0442\u0435\u0440\u0438\u0438", 2, ["filochinon"], ["\u0444\u0438\u043B\u043B\u043E\u0445\u0438\u043D\u043E\u043D", "\u0432\u0438\u0442\u0430\u043C\u0438\u043D \u041A"]],
  ["wit-e", "witamina E", "\u0432\u0438\u0442\u0430\u043C\u0438\u043D E", "ochrona b\u0142on kom\xF3rkowych przed utlenianiem \u2014 silny przeciwutleniacz", "\u0437\u0430\u0449\u0438\u0442\u0430 \u043A\u043B\u0435\u0442\u043E\u0447\u043D\u044B\u0445 \u043C\u0435\u043C\u0431\u0440\u0430\u043D \u043E\u0442 \u043E\u043A\u0438\u0441\u043B\u0435\u043D\u0438\u044F \u2014 \u0441\u0438\u043B\u044C\u043D\u044B\u0439 \u0430\u043D\u0442\u0438\u043E\u043A\u0441\u0438\u0434\u0430\u043D\u0442", 2, ["tokoferol"], ["\u0442\u043E\u043A\u043E\u0444\u0435\u0440\u043E\u043B", "\u0432\u0438\u0442\u0430\u043C\u0438\u043D \u0415"]],
  ["wit-c", "witamina C", "\u0432\u0438\u0442\u0430\u043C\u0438\u043D C", "udzia\u0142 w wytwarzaniu kolagenu i ochronie antyoksydacyjnej; jej niedob\xF3r powoduje szkorbut", "\u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u0432 \u0441\u0438\u043D\u0442\u0435\u0437\u0435 \u043A\u043E\u043B\u043B\u0430\u0433\u0435\u043D\u0430 \u0438 \u0430\u043D\u0442\u0438\u043E\u043A\u0441\u0438\u0434\u0430\u043D\u0442\u043D\u043E\u0439 \u0437\u0430\u0449\u0438\u0442\u0435; \u0435\u0451 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u043A \u0432\u044B\u0437\u044B\u0432\u0430\u0435\u0442 \u0446\u0438\u043D\u0433\u0443", 1, ["kwas askorbinowy"], ["\u0430\u0441\u043A\u043E\u0440\u0431\u0438\u043D\u043E\u0432\u0430\u044F \u043A\u0438\u0441\u043B\u043E\u0442\u0430", "\u0432\u0438\u0442\u0430\u043C\u0438\u043D \u0421"]],
  ["wit-b12", "witamina B12", "\u0432\u0438\u0442\u0430\u043C\u0438\u043D B12", "udzia\u0142 w wytwarzaniu krwinek czerwonych; jej niedob\xF3r powoduje niedokrwisto\u015B\u0107 z\u0142o\u015Bliw\u0105", "\u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u0432 \u043E\u0431\u0440\u0430\u0437\u043E\u0432\u0430\u043D\u0438\u0438 \u044D\u0440\u0438\u0442\u0440\u043E\u0446\u0438\u0442\u043E\u0432; \u0435\u0451 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u043A \u0432\u044B\u0437\u044B\u0432\u0430\u0435\u0442 \u0437\u043B\u043E\u043A\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0435 \u043C\u0430\u043B\u043E\u043A\u0440\u043E\u0432\u0438\u0435", 2, ["kobalamina"], ["\u043A\u043E\u0431\u0430\u043B\u0430\u043C\u0438\u043D", "\u0432\u0438\u0442\u0430\u043C\u0438\u043D \u041212"]],
  ["kwas-foliowy", "kwas foliowy", "\u0444\u043E\u043B\u0438\u0435\u0432\u0430\u044F \u043A\u0438\u0441\u043B\u043E\u0442\u0430", "udzia\u0142 w podzia\u0142ach kom\xF3rek; jego niedob\xF3r u ci\u0119\u017Carnej grozi wadami cewy nerwowej p\u0142odu", "\u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u0432 \u0434\u0435\u043B\u0435\u043D\u0438\u0438 \u043A\u043B\u0435\u0442\u043E\u043A; \u0435\u0451 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u043A \u0443 \u0431\u0435\u0440\u0435\u043C\u0435\u043D\u043D\u043E\u0439 \u0433\u0440\u043E\u0437\u0438\u0442 \u043F\u043E\u0440\u043E\u043A\u0430\u043C\u0438 \u043D\u0435\u0440\u0432\u043D\u043E\u0439 \u0442\u0440\u0443\u0431\u043A\u0438 \u043F\u043B\u043E\u0434\u0430", 2, ["witamina B9", "foliany"], ["\u0432\u0438\u0442\u0430\u043C\u0438\u043D B9", "\u0444\u043E\u043B\u0430\u0442\u044B"]],
  ["wapn", "wap\u0144", "\u043A\u0430\u043B\u044C\u0446\u0438\u0439", "budowa ko\u015Bci i z\u0119b\xF3w oraz udzia\u0142 w skurczu mi\u0119\u015Bni i krzepni\u0119ciu krwi", "\u043F\u043E\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435 \u043A\u043E\u0441\u0442\u0435\u0439 \u0438 \u0437\u0443\u0431\u043E\u0432, \u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u0432 \u0441\u043E\u043A\u0440\u0430\u0449\u0435\u043D\u0438\u0438 \u043C\u044B\u0448\u0446 \u0438 \u0441\u0432\u0451\u0440\u0442\u044B\u0432\u0430\u043D\u0438\u0438 \u043A\u0440\u043E\u0432\u0438", 1, ["Ca"], ["Ca"]],
  ["zelazo", "\u017Celazo", "\u0436\u0435\u043B\u0435\u0437\u043E", "sk\u0142adnik hemoglobiny przenosz\u0105cej tlen; jego niedob\xF3r powoduje anemi\u0119", "\u043A\u043E\u043C\u043F\u043E\u043D\u0435\u043D\u0442 \u0433\u0435\u043C\u043E\u0433\u043B\u043E\u0431\u0438\u043D\u0430, \u043F\u0435\u0440\u0435\u043D\u043E\u0441\u044F\u0449\u0435\u0433\u043E \u043A\u0438\u0441\u043B\u043E\u0440\u043E\u0434; \u0435\u0433\u043E \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u043A \u0432\u044B\u0437\u044B\u0432\u0430\u0435\u0442 \u0430\u043D\u0435\u043C\u0438\u044E", 1, ["Fe"], ["Fe"]],
  ["jod", "jod", "\u0439\u043E\u0434", "sk\u0142adnik hormon\xF3w tarczycy; jego niedob\xF3r powoduje wole", "\u043A\u043E\u043C\u043F\u043E\u043D\u0435\u043D\u0442 \u0433\u043E\u0440\u043C\u043E\u043D\u043E\u0432 \u0449\u0438\u0442\u043E\u0432\u0438\u0434\u043D\u043E\u0439 \u0436\u0435\u043B\u0435\u0437\u044B; \u0435\u0433\u043E \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u043A \u0432\u044B\u0437\u044B\u0432\u0430\u0435\u0442 \u0437\u043E\u0431", 1, ["I"], []],
  ["fluor", "fluor", "\u0444\u0442\u043E\u0440", "wzmacnianie szkliwa z\u0119b\xF3w i ochrona przed pr\xF3chnic\u0105", "\u0443\u043A\u0440\u0435\u043F\u043B\u0435\u043D\u0438\u0435 \u0437\u0443\u0431\u043D\u043E\u0439 \u044D\u043C\u0430\u043B\u0438 \u0438 \u0437\u0430\u0449\u0438\u0442\u0430 \u043E\u0442 \u043A\u0430\u0440\u0438\u0435\u0441\u0430", 2, ["F"], []],
  ["potas", "potas", "\u043A\u0430\u043B\u0438\u0439", "g\u0142\xF3wny kation wn\u0119trza kom\xF3rek, niezb\u0119dny do przewodzenia impuls\xF3w nerwowych i pracy serca", "\u0433\u043B\u0430\u0432\u043D\u044B\u0439 \u043A\u0430\u0442\u0438\u043E\u043D \u0432\u043D\u0443\u0442\u0440\u0438 \u043A\u043B\u0435\u0442\u043E\u043A, \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u044B\u0439 \u0434\u043B\u044F \u043F\u0440\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u044F \u043D\u0435\u0440\u0432\u043D\u044B\u0445 \u0438\u043C\u043F\u0443\u043B\u044C\u0441\u043E\u0432 \u0438 \u0440\u0430\u0431\u043E\u0442\u044B \u0441\u0435\u0440\u0434\u0446\u0430", 2, ["K"], []]
]);
var DIET_TERMS = namedTable(P.digestion.diet, [
  ["bmi", "wska\u017Anik masy cia\u0142a", "\u0438\u043D\u0434\u0435\u043A\u0441 \u043C\u0430\u0441\u0441\u044B \u0442\u0435\u043B\u0430", "iloraz masy cia\u0142a w kilogramach i kwadratu wzrostu w metrach, s\u0142u\u017C\u0105cy do oceny prawid\u0142owo\u015Bci masy cia\u0142a", "\u043E\u0442\u043D\u043E\u0448\u0435\u043D\u0438\u0435 \u043C\u0430\u0441\u0441\u044B \u0442\u0435\u043B\u0430 \u0432 \u043A\u0438\u043B\u043E\u0433\u0440\u0430\u043C\u043C\u0430\u0445 \u043A \u043A\u0432\u0430\u0434\u0440\u0430\u0442\u0443 \u0440\u043E\u0441\u0442\u0430 \u0432 \u043C\u0435\u0442\u0440\u0430\u0445, \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u044E\u0449\u0435\u0435 \u043E\u0446\u0435\u043D\u0438\u0442\u044C, \u043D\u043E\u0440\u043C\u0430\u043B\u044C\u043D\u0430 \u043B\u0438 \u043C\u0430\u0441\u0441\u0430", 1, ["BMI"], ["\u0418\u041C\u0422", "BMI"]],
  ["ppm", "podstawowa przemiana materii", "\u043E\u0441\u043D\u043E\u0432\u043D\u043E\u0439 \u043E\u0431\u043C\u0435\u043D", "najmniejsza ilo\u015B\u0107 energii potrzebna do podtrzymania funkcji \u017Cyciowych w spoczynku i na czczo", "\u043D\u0430\u0438\u043C\u0435\u043D\u044C\u0448\u0435\u0435 \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u044D\u043D\u0435\u0440\u0433\u0438\u0438, \u043D\u0443\u0436\u043D\u043E\u0435 \u0434\u043B\u044F \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0430\u043D\u0438\u044F \u0436\u0438\u0437\u043D\u0435\u043D\u043D\u044B\u0445 \u0444\u0443\u043D\u043A\u0446\u0438\u0439 \u0432 \u043F\u043E\u043A\u043E\u0435 \u0438 \u043D\u0430\u0442\u043E\u0449\u0430\u043A", 2, ["PPM"], ["\u043E\u0441\u043D\u043E\u0432\u043D\u043E\u0439 \u043E\u0431\u043C\u0435\u043D \u0432\u0435\u0449\u0435\u0441\u0442\u0432"]],
  ["cpm", "ca\u0142kowita przemiana materii", "\u043E\u0431\u0449\u0438\u0439 \u043E\u0431\u043C\u0435\u043D", "podstawowa przemiana materii powi\u0119kszona o energi\u0119 zu\u017Cywan\u0105 na aktywno\u015B\u0107 fizyczn\u0105 i trawienie", "\u043E\u0441\u043D\u043E\u0432\u043D\u043E\u0439 \u043E\u0431\u043C\u0435\u043D \u043F\u043B\u044E\u0441 \u044D\u043D\u0435\u0440\u0433\u0438\u044F, \u0437\u0430\u0442\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u043C\u0430\u044F \u043D\u0430 \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043A\u0443\u044E \u0430\u043A\u0442\u0438\u0432\u043D\u043E\u0441\u0442\u044C \u0438 \u043F\u0438\u0449\u0435\u0432\u0430\u0440\u0435\u043D\u0438\u0435", 2, ["CPM"], ["\u043E\u0431\u0449\u0438\u0439 \u043E\u0431\u043C\u0435\u043D \u0432\u0435\u0449\u0435\u0441\u0442\u0432"]],
  ["wartosc-energetyczna", "warto\u015B\u0107 energetyczna pokarmu", "\u044D\u043D\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u0446\u0435\u043D\u043D\u043E\u0441\u0442\u044C \u043F\u0438\u0449\u0438", "ilo\u015B\u0107 energii uwalnianej z pokarmu w organizmie, podawana w kilokaloriach lub kilod\u017Culach", "\u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u044D\u043D\u0435\u0440\u0433\u0438\u0438, \u043E\u0441\u0432\u043E\u0431\u043E\u0436\u0434\u0430\u044E\u0449\u0435\u0439\u0441\u044F \u0438\u0437 \u043F\u0438\u0449\u0438 \u0432 \u043E\u0440\u0433\u0430\u043D\u0438\u0437\u043C\u0435, \u0432 \u043A\u0438\u043B\u043E\u043A\u0430\u043B\u043E\u0440\u0438\u044F\u0445 \u0438\u043B\u0438 \u043A\u0438\u043B\u043E\u0434\u0436\u043E\u0443\u043B\u044F\u0445", 1, ["kaloryczno\u015B\u0107", "warto\u015B\u0107 energetyczna"], ["\u043A\u0430\u043B\u043E\u0440\u0438\u0439\u043D\u043E\u0441\u0442\u044C", "\u044D\u043D\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u0446\u0435\u043D\u043D\u043E\u0441\u0442\u044C"]],
  ["bilans-dodatni", "dodatni bilans energetyczny", "\u043F\u043E\u043B\u043E\u0436\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u044D\u043D\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0431\u0430\u043B\u0430\u043D\u0441", "sytuacja, gdy z pokarmem dostarczamy wi\u0119cej energii, ni\u017C zu\u017Cywamy, co prowadzi do przyrostu masy cia\u0142a", "\u0441\u0438\u0442\u0443\u0430\u0446\u0438\u044F, \u043A\u043E\u0433\u0434\u0430 \u0441 \u043F\u0438\u0449\u0435\u0439 \u043F\u043E\u0441\u0442\u0443\u043F\u0430\u0435\u0442 \u0431\u043E\u043B\u044C\u0448\u0435 \u044D\u043D\u0435\u0440\u0433\u0438\u0438, \u0447\u0435\u043C \u0442\u0440\u0430\u0442\u0438\u0442\u0441\u044F, \u0447\u0442\u043E \u0432\u0435\u0434\u0451\u0442 \u043A \u0440\u043E\u0441\u0442\u0443 \u043C\u0430\u0441\u0441\u044B \u0442\u0435\u043B\u0430", 2, [], []],
  ["bilans-ujemny", "ujemny bilans energetyczny", "\u043E\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u044D\u043D\u0435\u0440\u0433\u0435\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0431\u0430\u043B\u0430\u043D\u0441", "sytuacja, gdy z pokarmem dostarczamy mniej energii, ni\u017C zu\u017Cywamy, co prowadzi do spadku masy cia\u0142a", "\u0441\u0438\u0442\u0443\u0430\u0446\u0438\u044F, \u043A\u043E\u0433\u0434\u0430 \u0441 \u043F\u0438\u0449\u0435\u0439 \u043F\u043E\u0441\u0442\u0443\u043F\u0430\u0435\u0442 \u043C\u0435\u043D\u044C\u0448\u0435 \u044D\u043D\u0435\u0440\u0433\u0438\u0438, \u0447\u0435\u043C \u0442\u0440\u0430\u0442\u0438\u0442\u0441\u044F, \u0447\u0442\u043E \u0432\u0435\u0434\u0451\u0442 \u043A \u0441\u043D\u0438\u0436\u0435\u043D\u0438\u044E \u043C\u0430\u0441\u0441\u044B \u0442\u0435\u043B\u0430", 2, [], []],
  ["piramida", "piramida zdrowego \u017Cywienia", "\u043F\u0438\u0440\u0430\u043C\u0438\u0434\u0430 \u043F\u0438\u0442\u0430\u043D\u0438\u044F", "graficzny schemat proporcji grup produkt\xF3w w diecie, z aktywno\u015Bci\u0105 fizyczn\u0105 oraz warzywami i owocami u podstawy", "\u0433\u0440\u0430\u0444\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u0441\u0445\u0435\u043C\u0430 \u043F\u0440\u043E\u043F\u043E\u0440\u0446\u0438\u0439 \u0433\u0440\u0443\u043F\u043F \u043F\u0440\u043E\u0434\u0443\u043A\u0442\u043E\u0432 \u0432 \u0440\u0430\u0446\u0438\u043E\u043D\u0435, \u0432 \u043E\u0441\u043D\u043E\u0432\u0430\u043D\u0438\u0438 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u0430\u043A\u0442\u0438\u0432\u043D\u043E\u0441\u0442\u044C, \u043E\u0432\u043E\u0449\u0438 \u0438 \u0444\u0440\u0443\u043A\u0442\u044B", 1, ["piramida \u017Cywieniowa"], ["\u043F\u0438\u0449\u0435\u0432\u0430\u044F \u043F\u0438\u0440\u0430\u043C\u0438\u0434\u0430"]],
  ["indeks-glikemiczny", "indeks glikemiczny", "\u0433\u043B\u0438\u043A\u0435\u043C\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0438\u043D\u0434\u0435\u043A\u0441", "miara tego, jak szybko po zjedzeniu produktu ro\u015Bnie st\u0119\u017Cenie glukozy we krwi", "\u043C\u0435\u0440\u0430 \u0442\u043E\u0433\u043E, \u043A\u0430\u043A \u0431\u044B\u0441\u0442\u0440\u043E \u043F\u043E\u0441\u043B\u0435 \u0435\u0434\u044B \u0440\u0430\u0441\u0442\u0451\u0442 \u0443\u0440\u043E\u0432\u0435\u043D\u044C \u0433\u043B\u044E\u043A\u043E\u0437\u044B \u0432 \u043A\u0440\u043E\u0432\u0438", 2, ["IG"], ["\u0413\u0418"]],
  ["dieta-zbilansowana", "dieta zbilansowana", "\u0441\u0431\u0430\u043B\u0430\u043D\u0441\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u043E\u0435 \u043F\u0438\u0442\u0430\u043D\u0438\u0435", "spos\xF3b od\u017Cywiania dostarczaj\u0105cy wszystkich sk\u0142adnik\xF3w pokarmowych w odpowiednich ilo\u015Bciach i proporcjach", "\u043F\u0438\u0442\u0430\u043D\u0438\u0435, \u043E\u0431\u0435\u0441\u043F\u0435\u0447\u0438\u0432\u0430\u044E\u0449\u0435\u0435 \u0432\u0441\u0435 \u043F\u0438\u0442\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0432\u0435\u0449\u0435\u0441\u0442\u0432\u0430 \u0432 \u043D\u0443\u0436\u043D\u043E\u043C \u043A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u0435 \u0438 \u0441\u043E\u043E\u0442\u043D\u043E\u0448\u0435\u043D\u0438\u0438", 1, ["zbilansowana dieta"], ["\u0441\u0431\u0430\u043B\u0430\u043D\u0441\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u0430\u044F \u0434\u0438\u0435\u0442\u0430"]]
]);

// packages/trainers/bio/src/server/templates/data/systemsMore.ts
var BONE_TISSUE = namedTable(P.motion.skeleton, [
  ["osteocyty", "osteocyty", "\u043E\u0441\u0442\u0435\u043E\u0446\u0438\u0442\u044B", "dojrza\u0142e kom\xF3rki kostne zamkni\u0119te w jamkach istoty mi\u0119dzykom\xF3rkowej", "\u0437\u0440\u0435\u043B\u044B\u0435 \u043A\u043E\u0441\u0442\u043D\u044B\u0435 \u043A\u043B\u0435\u0442\u043A\u0438, \u0437\u0430\u043C\u0443\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0435 \u0432 \u043F\u043E\u043B\u043E\u0441\u0442\u044F\u0445 \u043C\u0435\u0436\u043A\u043B\u0435\u0442\u043E\u0447\u043D\u043E\u0433\u043E \u0432\u0435\u0449\u0435\u0441\u0442\u0432\u0430", 2, [], []],
  ["osteoblasty", "osteoblasty", "\u043E\u0441\u0442\u0435\u043E\u0431\u043B\u0430\u0441\u0442\u044B", "kom\xF3rki ko\u015Bciotw\xF3rcze wytwarzaj\u0105ce istot\u0119 mi\u0119dzykom\xF3rkow\u0105 ko\u015Bci", "\u043A\u043E\u0441\u0442\u0435\u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0449\u0438\u0435 \u043A\u043B\u0435\u0442\u043A\u0438, \u0432\u044B\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u044E\u0449\u0438\u0435 \u043C\u0435\u0436\u043A\u043B\u0435\u0442\u043E\u0447\u043D\u043E\u0435 \u0432\u0435\u0449\u0435\u0441\u0442\u0432\u043E \u043A\u043E\u0441\u0442\u0438", 2, [], []],
  ["osteoklasty", "osteoklasty", "\u043E\u0441\u0442\u0435\u043E\u043A\u043B\u0430\u0441\u0442\u044B", "kom\xF3rki niszcz\u0105ce tkank\u0119 kostn\u0105, dzi\u0119ki kt\xF3rym ko\u015B\u0107 mo\u017Ce si\u0119 przebudowywa\u0107", "\u043A\u043B\u0435\u0442\u043A\u0438, \u0440\u0430\u0437\u0440\u0443\u0448\u0430\u044E\u0449\u0438\u0435 \u043A\u043E\u0441\u0442\u043D\u0443\u044E \u0442\u043A\u0430\u043D\u044C, \u0431\u043B\u0430\u0433\u043E\u0434\u0430\u0440\u044F \u043A\u043E\u0442\u043E\u0440\u044B\u043C \u043A\u043E\u0441\u0442\u044C \u043F\u0435\u0440\u0435\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u0442\u0441\u044F", 2, [], []],
  ["osteon", "osteon", "\u043E\u0441\u0442\u0435\u043E\u043D", "uk\u0142ad blaszek kostnych u\u0142o\u017Conych koncentrycznie wok\xF3\u0142 kana\u0142u z naczyniami krwiono\u015Bnymi", "\u0441\u0438\u0441\u0442\u0435\u043C\u0430 \u043A\u043E\u0441\u0442\u043D\u044B\u0445 \u043F\u043B\u0430\u0441\u0442\u0438\u043D\u043E\u043A, \u043A\u043E\u043D\u0446\u0435\u043D\u0442\u0440\u0438\u0447\u0435\u0441\u043A\u0438 \u0440\u0430\u0441\u043F\u043E\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0445 \u0432\u043E\u043A\u0440\u0443\u0433 \u043A\u0430\u043D\u0430\u043B\u0430 \u0441 \u043A\u0440\u043E\u0432\u0435\u043D\u043E\u0441\u043D\u044B\u043C\u0438 \u0441\u043E\u0441\u0443\u0434\u0430\u043C\u0438", 2, ["system Haversa"], ["\u0433\u0430\u0432\u0435\u0440\u0441\u043E\u0432\u0430 \u0441\u0438\u0441\u0442\u0435\u043C\u0430"]],
  ["chrzastka-nasadowa", "chrz\u0105stka nasadowa", "\u044D\u043F\u0438\u0444\u0438\u0437\u0430\u0440\u043D\u0430\u044F \u043F\u043B\u0430\u0441\u0442\u0438\u043D\u043A\u0430", "warstwa chrz\u0105stki mi\u0119dzy trzonem a nasad\u0105, dzi\u0119ki kt\xF3rej ko\u015B\u0107 d\u0142uga ro\u015Bnie na d\u0142ugo\u015B\u0107", "\u0441\u043B\u043E\u0439 \u0445\u0440\u044F\u0449\u0430 \u043C\u0435\u0436\u0434\u0443 \u0434\u0438\u0430\u0444\u0438\u0437\u043E\u043C \u0438 \u044D\u043F\u0438\u0444\u0438\u0437\u043E\u043C, \u0437\u0430 \u0441\u0447\u0451\u0442 \u043A\u043E\u0442\u043E\u0440\u043E\u0433\u043E \u0434\u043B\u0438\u043D\u043D\u0430\u044F \u043A\u043E\u0441\u0442\u044C \u0440\u0430\u0441\u0442\u0451\u0442 \u0432 \u0434\u043B\u0438\u043D\u0443", 2, ["chrz\u0105stka wzrostowa"], ["\u0437\u043E\u043D\u0430 \u0440\u043E\u0441\u0442\u0430", "\u043F\u043B\u0430\u0441\u0442\u0438\u043D\u043A\u0430 \u0440\u043E\u0441\u0442\u0430"]],
  ["szpik-zolty", "szpik kostny \u017C\xF3\u0142ty", "\u0436\u0451\u043B\u0442\u044B\u0439 \u043A\u043E\u0441\u0442\u043D\u044B\u0439 \u043C\u043E\u0437\u0433", "tkanka t\u0142uszczowa wype\u0142niaj\u0105ca jam\u0119 szpikow\u0105 ko\u015Bci d\u0142ugich u doros\u0142ych", "\u0436\u0438\u0440\u043E\u0432\u0430\u044F \u0442\u043A\u0430\u043D\u044C, \u0437\u0430\u043F\u043E\u043B\u043D\u044F\u044E\u0449\u0430\u044F \u043A\u043E\u0441\u0442\u043D\u043E\u043C\u043E\u0437\u0433\u043E\u0432\u0443\u044E \u043F\u043E\u043B\u043E\u0441\u0442\u044C \u0434\u043B\u0438\u043D\u043D\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u0443 \u0432\u0437\u0440\u043E\u0441\u043B\u044B\u0445", 1, ["szpik \u017C\xF3\u0142ty"], ["\u0436\u0451\u043B\u0442\u044B\u0439 \u043C\u043E\u0437\u0433"]],
  ["osseina", "osseina", "\u043E\u0441\u0441\u0435\u0438\u043D", "bia\u0142ko ko\u015Bci (kolagen) nadaj\u0105ce jej spr\u0119\u017Cysto\u015B\u0107", "\u0431\u0435\u043B\u043E\u043A \u043A\u043E\u0441\u0442\u0438 (\u043A\u043E\u043B\u043B\u0430\u0433\u0435\u043D), \u043F\u0440\u0438\u0434\u0430\u044E\u0449\u0438\u0439 \u0435\u0439 \u0443\u043F\u0440\u0443\u0433\u043E\u0441\u0442\u044C", 2, ["kolagen kostny"], ["\u043A\u043E\u043B\u043B\u0430\u0433\u0435\u043D \u043A\u043E\u0441\u0442\u0438"]],
  ["sole-mineralne", "sole wapnia i fosforu", "\u0441\u043E\u043B\u0438 \u043A\u0430\u043B\u044C\u0446\u0438\u044F \u0438 \u0444\u043E\u0441\u0444\u043E\u0440\u0430", "sk\u0142adniki mineralne nadaj\u0105ce ko\u015Bci twardo\u015B\u0107", "\u043C\u0438\u043D\u0435\u0440\u0430\u043B\u044C\u043D\u044B\u0435 \u043A\u043E\u043C\u043F\u043E\u043D\u0435\u043D\u0442\u044B, \u043F\u0440\u0438\u0434\u0430\u044E\u0449\u0438\u0435 \u043A\u043E\u0441\u0442\u0438 \u0442\u0432\u0451\u0440\u0434\u043E\u0441\u0442\u044C", 1, ["sole mineralne ko\u015Bci", "hydroksyapatyt"], ["\u043C\u0438\u043D\u0435\u0440\u0430\u043B\u044C\u043D\u044B\u0435 \u0432\u0435\u0449\u0435\u0441\u0442\u0432\u0430 \u043A\u043E\u0441\u0442\u0438", "\u0433\u0438\u0434\u0440\u043E\u043A\u0441\u0438\u0430\u043F\u0430\u0442\u0438\u0442"]]
]);
var JOINT_TYPES = namedTable(P.motion.joints, [
  ["szwy", "szwy", "\u0448\u0432\u044B", "po\u0142\u0105czenia \u015Bcis\u0142e ko\u015Bci czaszki za pomoc\u0105 tkanki \u0142\u0105cznej w\u0142\xF3knistej", "\u043D\u0435\u043F\u043E\u0434\u0432\u0438\u0436\u043D\u044B\u0435 \u0441\u043E\u0435\u0434\u0438\u043D\u0435\u043D\u0438\u044F \u043A\u043E\u0441\u0442\u0435\u0439 \u0447\u0435\u0440\u0435\u043F\u0430 \u0441 \u043F\u043E\u043C\u043E\u0449\u044C\u044E \u0432\u043E\u043B\u043E\u043A\u043D\u0438\u0441\u0442\u043E\u0439 \u0441\u043E\u0435\u0434\u0438\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0439 \u0442\u043A\u0430\u043D\u0438", 2, ["szew"], ["\u0448\u043E\u0432"]],
  ["chrzastkozrost", "chrz\u0105stkozrost", "\u0445\u0440\u044F\u0449\u0435\u0432\u043E\u0435 \u0441\u043E\u0435\u0434\u0438\u043D\u0435\u043D\u0438\u0435", "po\u0142\u0105czenie ko\u015Bci za pomoc\u0105 chrz\u0105stki, np. kr\u0119g\xF3w przez kr\u0105\u017Cki mi\u0119dzykr\u0119gowe", "\u0441\u043E\u0435\u0434\u0438\u043D\u0435\u043D\u0438\u0435 \u043A\u043E\u0441\u0442\u0435\u0439 \u0445\u0440\u044F\u0449\u043E\u043C, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u043F\u043E\u0437\u0432\u043E\u043D\u043A\u043E\u0432 \u043C\u0435\u0436\u043F\u043E\u0437\u0432\u043E\u043D\u043A\u043E\u0432\u044B\u043C\u0438 \u0434\u0438\u0441\u043A\u0430\u043C\u0438", 2, [], ["\u0441\u0438\u043D\u0445\u043E\u043D\u0434\u0440\u043E\u0437"]],
  ["koscozrost", "ko\u015Bciozrost", "\u0441\u0438\u043D\u043E\u0441\u0442\u043E\u0437", "zro\u015Bni\u0119cie ko\u015Bci tkank\u0105 kostn\u0105, np. kr\u0119g\xF3w krzy\u017Cowych w ko\u015B\u0107 krzy\u017Cow\u0105", "\u0441\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u043A\u043E\u0441\u0442\u0435\u0439 \u043A\u043E\u0441\u0442\u043D\u043E\u0439 \u0442\u043A\u0430\u043D\u044C\u044E, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u043A\u0440\u0435\u0441\u0442\u0446\u043E\u0432\u044B\u0445 \u043F\u043E\u0437\u0432\u043E\u043D\u043A\u043E\u0432 \u0432 \u043A\u0440\u0435\u0441\u0442\u0435\u0446", 2, [], ["\u043A\u043E\u0441\u0442\u043D\u043E\u0435 \u0441\u0440\u0430\u0449\u0435\u043D\u0438\u0435"]],
  ["torebka-stawowa", "torebka stawowa", "\u0441\u0443\u0441\u0442\u0430\u0432\u043D\u0430\u044F \u043A\u0430\u043F\u0441\u0443\u043B\u0430", "\u0142\u0105cznotkankowa os\u0142ona otaczaj\u0105ca staw i wytwarzaj\u0105ca ma\u017A", "\u0441\u043E\u0435\u0434\u0438\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0442\u043A\u0430\u043D\u043D\u0430\u044F \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0430, \u043E\u043A\u0440\u0443\u0436\u0430\u044E\u0449\u0430\u044F \u0441\u0443\u0441\u0442\u0430\u0432 \u0438 \u0432\u044B\u0434\u0435\u043B\u044F\u044E\u0449\u0430\u044F \u0441\u0438\u043D\u043E\u0432\u0438\u0430\u043B\u044C\u043D\u0443\u044E \u0436\u0438\u0434\u043A\u043E\u0441\u0442\u044C", 1, [], ["\u0441\u0443\u0441\u0442\u0430\u0432\u043D\u0430\u044F \u0441\u0443\u043C\u043A\u0430"]],
  ["jama-stawowa", "jama stawowa", "\u0441\u0443\u0441\u0442\u0430\u0432\u043D\u0430\u044F \u043F\u043E\u043B\u043E\u0441\u0442\u044C", "szczelina mi\u0119dzy powierzchniami stawowymi wype\u0142niona mazi\u0105", "\u0449\u0435\u043B\u044C \u043C\u0435\u0436\u0434\u0443 \u0441\u0443\u0441\u0442\u0430\u0432\u043D\u044B\u043C\u0438 \u043F\u043E\u0432\u0435\u0440\u0445\u043D\u043E\u0441\u0442\u044F\u043C\u0438, \u0437\u0430\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u0430\u044F \u0441\u0438\u043D\u043E\u0432\u0438\u0430\u043B\u044C\u043D\u043E\u0439 \u0436\u0438\u0434\u043A\u043E\u0441\u0442\u044C\u044E", 1, [], []],
  ["glowka", "g\u0142\xF3wka stawowa", "\u0441\u0443\u0441\u0442\u0430\u0432\u043D\u0430\u044F \u0433\u043E\u043B\u043E\u0432\u043A\u0430", "wypuk\u0142a powierzchnia stawowa jednej z ko\u015Bci", "\u0432\u044B\u043F\u0443\u043A\u043B\u0430\u044F \u0441\u0443\u0441\u0442\u0430\u0432\u043D\u0430\u044F \u043F\u043E\u0432\u0435\u0440\u0445\u043D\u043E\u0441\u0442\u044C \u043E\u0434\u043D\u043E\u0439 \u0438\u0437 \u043A\u043E\u0441\u0442\u0435\u0439", 1, [], []],
  ["panewka", "panewka stawowa", "\u0441\u0443\u0441\u0442\u0430\u0432\u043D\u0430\u044F \u0432\u043F\u0430\u0434\u0438\u043D\u0430", "wkl\u0119s\u0142a powierzchnia stawowa, w kt\xF3r\u0105 wchodzi g\u0142\xF3wka", "\u0432\u043E\u0433\u043D\u0443\u0442\u0430\u044F \u0441\u0443\u0441\u0442\u0430\u0432\u043D\u0430\u044F \u043F\u043E\u0432\u0435\u0440\u0445\u043D\u043E\u0441\u0442\u044C, \u0432 \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u0432\u0445\u043E\u0434\u0438\u0442 \u0433\u043E\u043B\u043E\u0432\u043A\u0430", 1, ["panewka"], []],
  ["staw-kulisty", "staw kulisty", "\u0448\u0430\u0440\u043E\u0432\u0438\u0434\u043D\u044B\u0439 \u0441\u0443\u0441\u0442\u0430\u0432", "staw pozwalaj\u0105cy na ruchy we wszystkich p\u0142aszczyznach, np. ramienny i biodrowy", "\u0441\u0443\u0441\u0442\u0430\u0432, \u0434\u043E\u043F\u0443\u0441\u043A\u0430\u044E\u0449\u0438\u0439 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F \u0432\u043E \u0432\u0441\u0435\u0445 \u043F\u043B\u043E\u0441\u043A\u043E\u0441\u0442\u044F\u0445, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u043F\u043B\u0435\u0447\u0435\u0432\u043E\u0439 \u0438 \u0442\u0430\u0437\u043E\u0431\u0435\u0434\u0440\u0435\u043D\u043D\u044B\u0439", 2, [], []],
  ["staw-zawiasowy", "staw zawiasowy", "\u0431\u043B\u043E\u043A\u043E\u0432\u0438\u0434\u043D\u044B\u0439 \u0441\u0443\u0441\u0442\u0430\u0432", "staw pozwalaj\u0105cy na ruch tylko w jednej p\u0142aszczy\u017Anie, np. mi\u0119dzypaliczkowy", "\u0441\u0443\u0441\u0442\u0430\u0432, \u0434\u043E\u043F\u0443\u0441\u043A\u0430\u044E\u0449\u0438\u0439 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u0432 \u043E\u0434\u043D\u043E\u0439 \u043F\u043B\u043E\u0441\u043A\u043E\u0441\u0442\u0438, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u043C\u0435\u0436\u0444\u0430\u043B\u0430\u043D\u0433\u043E\u0432\u044B\u0439", 2, [], ["\u0431\u043B\u043E\u043A\u043E\u0432\u043E\u0439 \u0441\u0443\u0441\u0442\u0430\u0432"]]
]);
var SKELETON_PARTS = namedTable(P.motion.bones, [
  ["mozgoczaszka", "m\xF3zgoczaszka", "\u043C\u043E\u0437\u0433\u043E\u0432\u043E\u0439 \u043E\u0442\u0434\u0435\u043B \u0447\u0435\u0440\u0435\u043F\u0430", "cz\u0119\u015B\u0107 czaszki tworz\u0105ca puszk\u0119 chroni\u0105c\u0105 m\xF3zgowie", "\u0447\u0430\u0441\u0442\u044C \u0447\u0435\u0440\u0435\u043F\u0430, \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0449\u0430\u044F \u043A\u043E\u0440\u043E\u0431\u043A\u0443, \u0437\u0430\u0449\u0438\u0449\u0430\u044E\u0449\u0443\u044E \u0433\u043E\u043B\u043E\u0432\u043D\u043E\u0439 \u043C\u043E\u0437\u0433", 1, [], ["\u043C\u043E\u0437\u0433\u043E\u0432\u043E\u0439 \u0447\u0435\u0440\u0435\u043F"]],
  ["trzewioczaszka", "trzewioczaszka", "\u043B\u0438\u0446\u0435\u0432\u043E\u0439 \u043E\u0442\u0434\u0435\u043B \u0447\u0435\u0440\u0435\u043F\u0430", "cz\u0119\u015B\u0107 czaszki tworz\u0105ca szkielet twarzy, z jedyn\u0105 ruchom\u0105 ko\u015Bci\u0105 \u2014 \u017Cuchw\u0105", "\u0447\u0430\u0441\u0442\u044C \u0447\u0435\u0440\u0435\u043F\u0430, \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0449\u0430\u044F \u0441\u043A\u0435\u043B\u0435\u0442 \u043B\u0438\u0446\u0430, \u0441 \u0435\u0434\u0438\u043D\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0439 \u043F\u043E\u0434\u0432\u0438\u0436\u043D\u043E\u0439 \u043A\u043E\u0441\u0442\u044C\u044E \u2014 \u043D\u0438\u0436\u043D\u0435\u0439 \u0447\u0435\u043B\u044E\u0441\u0442\u044C\u044E", 1, ["twarzoczaszka"], ["\u043B\u0438\u0446\u0435\u0432\u043E\u0439 \u0447\u0435\u0440\u0435\u043F"]],
  ["kregoslup", "kr\u0119gos\u0142up", "\u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u0438\u043A", "o\u015B cia\u0142a z 33\u201334 kr\u0119g\xF3w, chroni\u0105ca rdze\u0144 kr\u0119gowy", "\u043E\u0441\u044C \u0442\u0435\u043B\u0430 \u0438\u0437 33\u201334 \u043F\u043E\u0437\u0432\u043E\u043D\u043A\u043E\u0432, \u0437\u0430\u0449\u0438\u0449\u0430\u044E\u0449\u0430\u044F \u0441\u043F\u0438\u043D\u043D\u043E\u0439 \u043C\u043E\u0437\u0433", 1, [], ["\u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u044B\u0439 \u0441\u0442\u043E\u043B\u0431"]],
  ["krzywizny", "krzywizny kr\u0119gos\u0142upa", "\u0438\u0437\u0433\u0438\u0431\u044B \u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u0438\u043A\u0430", "lordozy i kifozy, kt\xF3re amortyzuj\u0105 wstrz\u0105sy podczas chodzenia", "\u043B\u043E\u0440\u0434\u043E\u0437\u044B \u0438 \u043A\u0438\u0444\u043E\u0437\u044B, \u0441\u043C\u044F\u0433\u0447\u0430\u044E\u0449\u0438\u0435 \u0442\u043E\u043B\u0447\u043A\u0438 \u043F\u0440\u0438 \u0445\u043E\u0434\u044C\u0431\u0435", 2, [], []],
  ["kregi-szyjne", "kr\u0119gi szyjne", "\u0448\u0435\u0439\u043D\u044B\u0435 \u043F\u043E\u0437\u0432\u043E\u043D\u043A\u0438", "siedem kr\u0119g\xF3w, w tym kr\u0119g szczytowy i obrotowy umo\u017Cliwiaj\u0105ce ruchy g\u0142owy", "\u0441\u0435\u043C\u044C \u043F\u043E\u0437\u0432\u043E\u043D\u043A\u043E\u0432, \u0432\u043A\u043B\u044E\u0447\u0430\u044F \u0430\u0442\u043B\u0430\u043D\u0442 \u0438 \u043E\u0441\u0435\u0432\u043E\u0439, \u043E\u0431\u0435\u0441\u043F\u0435\u0447\u0438\u0432\u0430\u044E\u0449\u0438\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F \u0433\u043E\u043B\u043E\u0432\u044B", 2, [], []],
  ["klatka", "klatka piersiowa", "\u0433\u0440\u0443\u0434\u043D\u0430\u044F \u043A\u043B\u0435\u0442\u043A\u0430", "\u017Cebra, mostek i kr\u0119gi piersiowe chroni\u0105ce serce i p\u0142uca", "\u0440\u0451\u0431\u0440\u0430, \u0433\u0440\u0443\u0434\u0438\u043D\u0430 \u0438 \u0433\u0440\u0443\u0434\u043D\u044B\u0435 \u043F\u043E\u0437\u0432\u043E\u043D\u043A\u0438, \u0437\u0430\u0449\u0438\u0449\u0430\u044E\u0449\u0438\u0435 \u0441\u0435\u0440\u0434\u0446\u0435 \u0438 \u043B\u0451\u0433\u043A\u0438\u0435", 1, [], []],
  ["mostek", "mostek", "\u0433\u0440\u0443\u0434\u0438\u043D\u0430", "p\u0142aska ko\u015B\u0107 z przodu klatki piersiowej, do kt\xF3rej przyczepiaj\u0105 si\u0119 \u017Cebra prawdziwe", "\u043F\u043B\u043E\u0441\u043A\u0430\u044F \u043A\u043E\u0441\u0442\u044C \u0441\u043F\u0435\u0440\u0435\u0434\u0438 \u0433\u0440\u0443\u0434\u043D\u043E\u0439 \u043A\u043B\u0435\u0442\u043A\u0438, \u043A \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u043F\u0440\u0438\u043A\u0440\u0435\u043F\u043B\u044F\u044E\u0442\u0441\u044F \u0438\u0441\u0442\u0438\u043D\u043D\u044B\u0435 \u0440\u0451\u0431\u0440\u0430", 1, [], []],
  ["obrecz-barkowa", "obr\u0119cz barkowa", "\u043F\u043B\u0435\u0447\u0435\u0432\u043E\u0439 \u043F\u043E\u044F\u0441", "obojczyki i \u0142opatki \u0142\u0105cz\u0105ce ko\u0144czyny g\xF3rne ze szkieletem osiowym", "\u043A\u043B\u044E\u0447\u0438\u0446\u044B \u0438 \u043B\u043E\u043F\u0430\u0442\u043A\u0438, \u0441\u043E\u0435\u0434\u0438\u043D\u044F\u044E\u0449\u0438\u0435 \u0432\u0435\u0440\u0445\u043D\u0438\u0435 \u043A\u043E\u043D\u0435\u0447\u043D\u043E\u0441\u0442\u0438 \u0441 \u043E\u0441\u0435\u0432\u044B\u043C \u0441\u043A\u0435\u043B\u0435\u0442\u043E\u043C", 2, [], ["\u043F\u043E\u044F\u0441 \u0432\u0435\u0440\u0445\u043D\u0438\u0445 \u043A\u043E\u043D\u0435\u0447\u043D\u043E\u0441\u0442\u0435\u0439"]],
  ["obrecz-miedniczna", "obr\u0119cz miedniczna", "\u0442\u0430\u0437\u043E\u0432\u044B\u0439 \u043F\u043E\u044F\u0441", "ko\u015Bci miedniczne po\u0142\u0105czone z ko\u015Bci\u0105 krzy\u017Cow\u0105, przenosz\u0105ce ci\u0119\u017Car cia\u0142a na ko\u0144czyny dolne", "\u0442\u0430\u0437\u043E\u0432\u044B\u0435 \u043A\u043E\u0441\u0442\u0438, \u0441\u043E\u0435\u0434\u0438\u043D\u0451\u043D\u043D\u044B\u0435 \u0441 \u043A\u0440\u0435\u0441\u0442\u0446\u043E\u043C \u0438 \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0449\u0438\u0435 \u0432\u0435\u0441 \u0442\u0435\u043B\u0430 \u043D\u0430 \u043D\u0438\u0436\u043D\u0438\u0435 \u043A\u043E\u043D\u0435\u0447\u043D\u043E\u0441\u0442\u0438", 2, ["miednica"], ["\u0442\u0430\u0437", "\u043F\u043E\u044F\u0441 \u043D\u0438\u0436\u043D\u0438\u0445 \u043A\u043E\u043D\u0435\u0447\u043D\u043E\u0441\u0442\u0435\u0439"]],
  ["kosc-udowa", "ko\u015B\u0107 udowa", "\u0431\u0435\u0434\u0440\u0435\u043D\u043D\u0430\u044F \u043A\u043E\u0441\u0442\u044C", "najd\u0142u\u017Csza i najmocniejsza ko\u015B\u0107 cia\u0142a cz\u0142owieka", "\u0441\u0430\u043C\u0430\u044F \u0434\u043B\u0438\u043D\u043D\u0430\u044F \u0438 \u043F\u0440\u043E\u0447\u043D\u0430\u044F \u043A\u043E\u0441\u0442\u044C \u0442\u0435\u043B\u0430 \u0447\u0435\u043B\u043E\u0432\u0435\u043A\u0430", 1, [], []]
]);
var MUSCLE_WORK = namedTable(P.motion.muscles, [
  ["wlokno", "w\u0142\xF3kno mi\u0119\u015Bniowe", "\u043C\u044B\u0448\u0435\u0447\u043D\u043E\u0435 \u0432\u043E\u043B\u043E\u043A\u043D\u043E", "wieloj\u0105drowa kom\xF3rka mi\u0119\u015Bnia szkieletowego", "\u043C\u043D\u043E\u0433\u043E\u044F\u0434\u0435\u0440\u043D\u0430\u044F \u043A\u043B\u0435\u0442\u043A\u0430 \u0441\u043A\u0435\u043B\u0435\u0442\u043D\u043E\u0439 \u043C\u044B\u0448\u0446\u044B", 1, [], []],
  ["miofibryle", "miofibryle", "\u043C\u0438\u043E\u0444\u0438\u0431\u0440\u0438\u043B\u043B\u044B", "w\u0142\xF3kienka kurczliwe wype\u0142niaj\u0105ce w\u0142\xF3kno mi\u0119\u015Bniowe", "\u0441\u043E\u043A\u0440\u0430\u0442\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043D\u0438\u0442\u0438, \u0437\u0430\u043F\u043E\u043B\u043D\u044F\u044E\u0449\u0438\u0435 \u043C\u044B\u0448\u0435\u0447\u043D\u043E\u0435 \u0432\u043E\u043B\u043E\u043A\u043D\u043E", 2, ["w\u0142\xF3kienka kurczliwe"], []],
  ["siateczka", "siateczka sarkoplazmatyczna", "\u0441\u0430\u0440\u043A\u043E\u043F\u043B\u0430\u0437\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u0441\u0435\u0442\u044C", "magazyn jon\xF3w wapnia uwalnianych podczas pobudzenia w\u0142\xF3kna mi\u0119\u015Bniowego", "\u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0435 \u0438\u043E\u043D\u043E\u0432 \u043A\u0430\u043B\u044C\u0446\u0438\u044F, \u0432\u044B\u0441\u0432\u043E\u0431\u043E\u0436\u0434\u0430\u0435\u043C\u044B\u0445 \u043F\u0440\u0438 \u0432\u043E\u0437\u0431\u0443\u0436\u0434\u0435\u043D\u0438\u0438 \u043C\u044B\u0448\u0435\u0447\u043D\u043E\u0433\u043E \u0432\u043E\u043B\u043E\u043A\u043D\u0430", 3, [], ["\u0441\u0430\u0440\u043A\u043E\u043F\u043B\u0430\u0437\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0440\u0435\u0442\u0438\u043A\u0443\u043B\u0443\u043C"]],
  ["jony-wapnia", "jony wapnia", "\u0438\u043E\u043D\u044B \u043A\u0430\u043B\u044C\u0446\u0438\u044F", "ods\u0142anianie na aktynie miejsc wi\u0105zania miozyny, co uruchamia skurcz", "\u043E\u0442\u043A\u0440\u044B\u0442\u0438\u0435 \u043D\u0430 \u0430\u043A\u0442\u0438\u043D\u0435 \u043C\u0435\u0441\u0442 \u0441\u0432\u044F\u0437\u044B\u0432\u0430\u043D\u0438\u044F \u043C\u0438\u043E\u0437\u0438\u043D\u0430, \u0447\u0442\u043E \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442 \u0441\u043E\u043A\u0440\u0430\u0449\u0435\u043D\u0438\u0435", 2, ["Ca2+"], ["Ca2+"]],
  ["fosfokreatyna", "fosfokreatyna", "\u043A\u0440\u0435\u0430\u0442\u0438\u043D\u0444\u043E\u0441\u0444\u0430\u0442", "zwi\u0105zek, kt\xF3ry w pierwszych sekundach wysi\u0142ku szybko odtwarza ATP", "\u0441\u043E\u0435\u0434\u0438\u043D\u0435\u043D\u0438\u0435, \u0431\u044B\u0441\u0442\u0440\u043E \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u044E\u0449\u0435\u0435 \u0410\u0422\u0424 \u0432 \u043F\u0435\u0440\u0432\u044B\u0435 \u0441\u0435\u043A\u0443\u043D\u0434\u044B \u043D\u0430\u0433\u0440\u0443\u0437\u043A\u0438", 3, [], ["\u0444\u043E\u0441\u0444\u043E\u043A\u0440\u0435\u0430\u0442\u0438\u043D"]],
  ["izotoniczny", "skurcz izotoniczny", "\u0438\u0437\u043E\u0442\u043E\u043D\u0438\u0447\u0435\u0441\u043A\u043E\u0435 \u0441\u043E\u043A\u0440\u0430\u0449\u0435\u043D\u0438\u0435", "skurcz, w kt\xF3rym mi\u0119sie\u0144 skraca si\u0119 przy sta\u0142ym napi\u0119ciu", "\u0441\u043E\u043A\u0440\u0430\u0449\u0435\u043D\u0438\u0435, \u043F\u0440\u0438 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u043C\u044B\u0448\u0446\u0430 \u0443\u043A\u043E\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u0440\u0438 \u043F\u043E\u0441\u0442\u043E\u044F\u043D\u043D\u043E\u043C \u043D\u0430\u043F\u0440\u044F\u0436\u0435\u043D\u0438\u0438", 2, [], []],
  ["izometryczny", "skurcz izometryczny", "\u0438\u0437\u043E\u043C\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043A\u043E\u0435 \u0441\u043E\u043A\u0440\u0430\u0449\u0435\u043D\u0438\u0435", "skurcz, w kt\xF3rym ro\u015Bnie napi\u0119cie mi\u0119\u015Bnia bez zmiany jego d\u0142ugo\u015Bci", "\u0441\u043E\u043A\u0440\u0430\u0449\u0435\u043D\u0438\u0435, \u043F\u0440\u0438 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u0440\u0430\u0441\u0442\u0451\u0442 \u043D\u0430\u043F\u0440\u044F\u0436\u0435\u043D\u0438\u0435 \u043C\u044B\u0448\u0446\u044B \u0431\u0435\u0437 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F \u0435\u0451 \u0434\u043B\u0438\u043D\u044B", 2, [], []],
  ["dlug-tlenowy", "d\u0142ug tlenowy", "\u043A\u0438\u0441\u043B\u043E\u0440\u043E\u0434\u043D\u044B\u0439 \u0434\u043E\u043B\u0433", "dodatkowa ilo\u015B\u0107 tlenu pobierana po wysi\u0142ku na usuni\u0119cie mleczanu i odtworzenie zapas\xF3w ATP", "\u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043A\u0438\u0441\u043B\u043E\u0440\u043E\u0434, \u043F\u043E\u0442\u0440\u0435\u0431\u043B\u044F\u0435\u043C\u044B\u0439 \u043F\u043E\u0441\u043B\u0435 \u043D\u0430\u0433\u0440\u0443\u0437\u043A\u0438 \u0434\u043B\u044F \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u044F \u043B\u0430\u043A\u0442\u0430\u0442\u0430 \u0438 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u0437\u0430\u043F\u0430\u0441\u043E\u0432 \u0410\u0422\u0424", 2, [], []],
  ["plytka", "p\u0142ytka nerwowo-mi\u0119\u015Bniowa", "\u043D\u0435\u0440\u0432\u043D\u043E-\u043C\u044B\u0448\u0435\u0447\u043D\u044B\u0439 \u0441\u0438\u043D\u0430\u043F\u0441", "po\u0142\u0105czenie zako\u0144czenia neuronu ruchowego z w\u0142\xF3knem mi\u0119\u015Bniowym", "\u043A\u043E\u043D\u0442\u0430\u043A\u0442 \u043E\u043A\u043E\u043D\u0447\u0430\u043D\u0438\u044F \u0434\u0432\u0438\u0433\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u043D\u0435\u0439\u0440\u043E\u043D\u0430 \u0441 \u043C\u044B\u0448\u0435\u0447\u043D\u044B\u043C \u0432\u043E\u043B\u043E\u043A\u043D\u043E\u043C", 2, ["synapsa nerwowo-mi\u0119\u015Bniowa"], ["\u043A\u043E\u043D\u0446\u0435\u0432\u0430\u044F \u043F\u043B\u0430\u0441\u0442\u0438\u043D\u043A\u0430"]],
  ["skurcz-tezcowy", "skurcz t\u0119\u017Ccowy", "\u0442\u0435\u0442\u0430\u043D\u0438\u0447\u0435\u0441\u043A\u043E\u0435 \u0441\u043E\u043A\u0440\u0430\u0449\u0435\u043D\u0438\u0435", "d\u0142ugotrwa\u0142y, silny skurcz mi\u0119\u015Bnia wywo\u0142any szybko nast\u0119puj\u0105cymi po sobie impulsami", "\u0434\u043B\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0435 \u0441\u0438\u043B\u044C\u043D\u043E\u0435 \u0441\u043E\u043A\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u043C\u044B\u0448\u0446\u044B, \u0432\u044B\u0437\u0432\u0430\u043D\u043D\u043E\u0435 \u0431\u044B\u0441\u0442\u0440\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u043C\u0438 \u0434\u0440\u0443\u0433 \u0437\u0430 \u0434\u0440\u0443\u0433\u043E\u043C \u0438\u043C\u043F\u0443\u043B\u044C\u0441\u0430\u043C\u0438", 3, [], ["\u0442\u0435\u0442\u0430\u043D\u0443\u0441 \u043C\u044B\u0448\u0446\u044B"]]
]);
var LYMPH_PARTS = namedTable(P.circulation.lymph, [
  ["plyn-tkankowy", "p\u0142yn tkankowy", "\u0442\u043A\u0430\u043D\u0435\u0432\u0430\u044F \u0436\u0438\u0434\u043A\u043E\u0441\u0442\u044C", "p\u0142yn przes\u0105czony z naczy\u0144 w\u0142osowatych, omywaj\u0105cy kom\xF3rki", "\u0436\u0438\u0434\u043A\u043E\u0441\u0442\u044C, \u043E\u0442\u0444\u0438\u043B\u044C\u0442\u0440\u043E\u0432\u0430\u043D\u043D\u0430\u044F \u0438\u0437 \u043A\u0430\u043F\u0438\u043B\u043B\u044F\u0440\u043E\u0432 \u0438 \u043E\u043C\u044B\u0432\u0430\u044E\u0449\u0430\u044F \u043A\u043B\u0435\u0442\u043A\u0438", 1, ["p\u0142yn mi\u0119dzykom\xF3rkowy"], ["\u043C\u0435\u0436\u043A\u043B\u0435\u0442\u043E\u0447\u043D\u0430\u044F \u0436\u0438\u0434\u043A\u043E\u0441\u0442\u044C"]],
  ["limfa", "limfa", "\u043B\u0438\u043C\u0444\u0430", "p\u0142yn powstaj\u0105cy z p\u0142ynu tkankowego, p\u0142yn\u0105cy naczyniami ch\u0142onnymi do \u017Cy\u0142", "\u0436\u0438\u0434\u043A\u043E\u0441\u0442\u044C, \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0449\u0430\u044F\u0441\u044F \u0438\u0437 \u0442\u043A\u0430\u043D\u0435\u0432\u043E\u0439 \u0438 \u043E\u0442\u0442\u0435\u043A\u0430\u044E\u0449\u0430\u044F \u043F\u043E \u043E\u0441\u043E\u0431\u044B\u043C \u0441\u043E\u0441\u0443\u0434\u0430\u043C \u043A \u0432\u0435\u043D\u0430\u043C", 1, ["ch\u0142onka"], []],
  ["wezly", "w\u0119z\u0142y ch\u0142onne", "\u043B\u0438\u043C\u0444\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u0443\u0437\u043B\u044B", "filtrowanie limfy i namna\u017Canie si\u0119 limfocyt\xF3w", "\u0444\u0438\u043B\u044C\u0442\u0440\u0430\u0446\u0438\u044F \u043B\u0438\u043C\u0444\u044B \u0438 \u0440\u0430\u0437\u043C\u043D\u043E\u0436\u0435\u043D\u0438\u0435 \u043B\u0438\u043C\u0444\u043E\u0446\u0438\u0442\u043E\u0432", 1, ["w\u0119z\u0142y limfatyczne"], ["\u043B\u0438\u043C\u0444\u043E\u0443\u0437\u043B\u044B"]],
  ["sledziona", "\u015Bledziona", "\u0441\u0435\u043B\u0435\u0437\u0451\u043D\u043A\u0430", "usuwanie zu\u017Cytych erytrocyt\xF3w i namna\u017Canie si\u0119 limfocyt\xF3w", "\u0443\u0434\u0430\u043B\u0435\u043D\u0438\u0435 \u0441\u0442\u0430\u0440\u044B\u0445 \u044D\u0440\u0438\u0442\u0440\u043E\u0446\u0438\u0442\u043E\u0432 \u0438 \u0440\u0430\u0437\u043C\u043D\u043E\u0436\u0435\u043D\u0438\u0435 \u043B\u0438\u043C\u0444\u043E\u0446\u0438\u0442\u043E\u0432", 1, [], []],
  ["grasica", "grasica", "\u0442\u0438\u043C\u0443\u0441", "dojrzewanie limfocyt\xF3w T, najaktywniejsza w dzieci\u0144stwie", "\u0441\u043E\u0437\u0440\u0435\u0432\u0430\u043D\u0438\u0435 \u0422-\u043B\u0438\u043C\u0444\u043E\u0446\u0438\u0442\u043E\u0432, \u043D\u0430\u0438\u0431\u043E\u043B\u0435\u0435 \u0430\u043A\u0442\u0438\u0432\u043D\u0430 \u0432 \u0434\u0435\u0442\u0441\u0442\u0432\u0435", 2, [], ["\u0432\u0438\u043B\u043E\u0447\u043A\u043E\u0432\u0430\u044F \u0436\u0435\u043B\u0435\u0437\u0430"]],
  ["migdalki", "migda\u0142ki", "\u043C\u0438\u043D\u0434\u0430\u043B\u0438\u043D\u044B", "skupiska tkanki limfatycznej w gardle, chroni\u0105ce wej\u015Bcie do dr\xF3g oddechowych i pokarmowych", "\u0441\u043A\u043E\u043F\u043B\u0435\u043D\u0438\u044F \u043B\u0438\u043C\u0444\u043E\u0438\u0434\u043D\u043E\u0439 \u0442\u043A\u0430\u043D\u0438 \u0432 \u0433\u043B\u043E\u0442\u043A\u0435, \u0437\u0430\u0449\u0438\u0449\u0430\u044E\u0449\u0438\u0435 \u0432\u0445\u043E\u0434 \u0432 \u0434\u044B\u0445\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0438 \u043F\u0438\u0449\u0435\u0432\u0430\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043F\u0443\u0442\u0438", 1, [], []],
  ["przewod-piersiowy", "przew\xF3d piersiowy", "\u0433\u0440\u0443\u0434\u043D\u043E\u0439 \u043F\u0440\u043E\u0442\u043E\u043A", "najwi\u0119ksze naczynie ch\u0142onne, uchodz\u0105ce do \u017Cy\u0142y w okolicy szyi", "\u0441\u0430\u043C\u044B\u0439 \u043A\u0440\u0443\u043F\u043D\u044B\u0439 \u043B\u0438\u043C\u0444\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0441\u043E\u0441\u0443\u0434, \u0432\u043F\u0430\u0434\u0430\u044E\u0449\u0438\u0439 \u0432 \u0432\u0435\u043D\u0443 \u0432 \u043E\u0431\u043B\u0430\u0441\u0442\u0438 \u0448\u0435\u0438", 2, [], []],
  ["naczynie-centralne", "naczynie ch\u0142onne kosmka", "\u043C\u043B\u0435\u0447\u043D\u044B\u0439 \u0441\u043E\u0441\u0443\u0434", "wch\u0142anianie strawionych t\u0142uszcz\xF3w w kosmkach jelita cienkiego", "\u0432\u0441\u0430\u0441\u044B\u0432\u0430\u043D\u0438\u0435 \u043F\u0435\u0440\u0435\u0432\u0430\u0440\u0435\u043D\u043D\u044B\u0445 \u0436\u0438\u0440\u043E\u0432 \u0432 \u0432\u043E\u0440\u0441\u0438\u043D\u043A\u0430\u0445 \u0442\u043E\u043D\u043A\u043E\u0439 \u043A\u0438\u0448\u043A\u0438", 2, ["naczynie ch\u0142onne centralne"], ["\u0446\u0435\u043D\u0442\u0440\u0430\u043B\u044C\u043D\u044B\u0439 \u043B\u0438\u043C\u0444\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0441\u043E\u0441\u0443\u0434 \u0432\u043E\u0440\u0441\u0438\u043D\u043A\u0438"]]
]);
var IMMUNE_CELLS = namedTable(P.circulation.immune, [
  ["antygen", "antygen", "\u0430\u043D\u0442\u0438\u0433\u0435\u043D", "cz\u0105steczka rozpoznawana przez uk\u0142ad odporno\u015Bciowy jako obca", "\u043C\u043E\u043B\u0435\u043A\u0443\u043B\u0430, \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u0438\u043C\u043C\u0443\u043D\u043D\u0430\u044F \u0441\u0438\u0441\u0442\u0435\u043C\u0430 \u0440\u0430\u0441\u043F\u043E\u0437\u043D\u0430\u0451\u0442 \u043A\u0430\u043A \u0447\u0443\u0436\u0443\u044E", 1, [], []],
  ["przeciwciala", "przeciwcia\u0142a", "\u0430\u043D\u0442\u0438\u0442\u0435\u043B\u0430", "bia\u0142ka wytwarzane przez kom\xF3rki plazmatyczne, swoi\u015Bcie wi\u0105\u017C\u0105ce antygen", "\u0431\u0435\u043B\u043A\u0438, \u0432\u044B\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0435\u043C\u044B\u0435 \u043F\u043B\u0430\u0437\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u043C\u0438 \u043A\u043B\u0435\u0442\u043A\u0430\u043C\u0438 \u0438 \u0441\u043F\u0435\u0446\u0438\u0444\u0438\u0447\u0435\u0441\u043A\u0438 \u0441\u0432\u044F\u0437\u044B\u0432\u0430\u044E\u0449\u0438\u0435 \u0430\u043D\u0442\u0438\u0433\u0435\u043D", 1, ["immunoglobuliny"], ["\u0438\u043C\u043C\u0443\u043D\u043E\u0433\u043B\u043E\u0431\u0443\u043B\u0438\u043D\u044B"]],
  ["plazmatyczne", "kom\xF3rki plazmatyczne", "\u043F\u043B\u0430\u0437\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u043A\u043B\u0435\u0442\u043A\u0438", "zr\xF3\u017Cnicowane limfocyty B wytwarzaj\u0105ce przeciwcia\u0142a", "\u0434\u0438\u0444\u0444\u0435\u0440\u0435\u043D\u0446\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0435 \u0412-\u043B\u0438\u043C\u0444\u043E\u0446\u0438\u0442\u044B, \u0432\u044B\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u044E\u0449\u0438\u0435 \u0430\u043D\u0442\u0438\u0442\u0435\u043B\u0430", 2, ["plazmocyty"], ["\u043F\u043B\u0430\u0437\u043C\u043E\u0446\u0438\u0442\u044B"]],
  ["pamieci", "kom\xF3rki pami\u0119ci", "\u043A\u043B\u0435\u0442\u043A\u0438 \u043F\u0430\u043C\u044F\u0442\u0438", "d\u0142ugowieczne limfocyty zapewniaj\u0105ce szybk\u0105 odpowied\u017A przy ponownym kontakcie z tym samym antygenem", "\u0434\u043E\u043B\u0433\u043E\u0436\u0438\u0432\u0443\u0449\u0438\u0435 \u043B\u0438\u043C\u0444\u043E\u0446\u0438\u0442\u044B, \u043E\u0431\u0435\u0441\u043F\u0435\u0447\u0438\u0432\u0430\u044E\u0449\u0438\u0435 \u0431\u044B\u0441\u0442\u0440\u044B\u0439 \u043E\u0442\u0432\u0435\u0442 \u043F\u0440\u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0439 \u0432\u0441\u0442\u0440\u0435\u0447\u0435 \u0441 \u0442\u0435\u043C \u0436\u0435 \u0430\u043D\u0442\u0438\u0433\u0435\u043D\u043E\u043C", 1, ["limfocyty pami\u0119ci"], ["\u043B\u0438\u043C\u0444\u043E\u0446\u0438\u0442\u044B \u043F\u0430\u043C\u044F\u0442\u0438"]],
  ["neutrofile", "neutrofile", "\u043D\u0435\u0439\u0442\u0440\u043E\u0444\u0438\u043B\u044B", "najliczniejsze granulocyty, pierwsze docieraj\u0105ce do miejsca zaka\u017Cenia i fagocytuj\u0105ce bakterie", "\u0441\u0430\u043C\u044B\u0435 \u043C\u043D\u043E\u0433\u043E\u0447\u0438\u0441\u043B\u0435\u043D\u043D\u044B\u0435 \u0433\u0440\u0430\u043D\u0443\u043B\u043E\u0446\u0438\u0442\u044B, \u043F\u0435\u0440\u0432\u044B\u043C\u0438 \u043F\u0440\u0438\u0431\u044B\u0432\u0430\u044E\u0449\u0438\u0435 \u043A \u043E\u0447\u0430\u0433\u0443 \u0438\u043D\u0444\u0435\u043A\u0446\u0438\u0438 \u0438 \u043F\u043E\u0433\u043B\u043E\u0449\u0430\u044E\u0449\u0438\u0435 \u0431\u0430\u043A\u0442\u0435\u0440\u0438\u0438", 2, ["granulocyty oboj\u0119tnoch\u0142onne"], ["\u043D\u0435\u0439\u0442\u0440\u043E\u0444\u0438\u043B\u044C\u043D\u044B\u0435 \u0433\u0440\u0430\u043D\u0443\u043B\u043E\u0446\u0438\u0442\u044B"]],
  ["tc", "limfocyty T cytotoksyczne", "\u0446\u0438\u0442\u043E\u0442\u043E\u043A\u0441\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u0422-\u043B\u0438\u043C\u0444\u043E\u0446\u0438\u0442\u044B", "swoiste niszczenie kom\xF3rek zaka\u017Conych wirusami po rozpoznaniu antygenu prezentowanego na ich powierzchni", "\u0441\u043F\u0435\u0446\u0438\u0444\u0438\u0447\u0435\u0441\u043A\u043E\u0435 \u0443\u043D\u0438\u0447\u0442\u043E\u0436\u0435\u043D\u0438\u0435 \u0437\u0430\u0440\u0430\u0436\u0451\u043D\u043D\u044B\u0445 \u0432\u0438\u0440\u0443\u0441\u0430\u043C\u0438 \u043A\u043B\u0435\u0442\u043E\u043A \u043F\u043E\u0441\u043B\u0435 \u0440\u0430\u0441\u043F\u043E\u0437\u043D\u0430\u0432\u0430\u043D\u0438\u044F \u0430\u043D\u0442\u0438\u0433\u0435\u043D\u0430 \u043D\u0430 \u0438\u0445 \u043F\u043E\u0432\u0435\u0440\u0445\u043D\u043E\u0441\u0442\u0438", 2, ["limfocyty Tc"], ["\u0422-\u043A\u0438\u043B\u043B\u0435\u0440\u044B"]],
  ["th", "limfocyty T pomocnicze", "\u0422-\u0445\u0435\u043B\u043F\u0435\u0440\u044B", "pobudzanie limfocyt\xF3w B i innych kom\xF3rek odporno\u015Bciowych do dzia\u0142ania", "\u0430\u043A\u0442\u0438\u0432\u0430\u0446\u0438\u044F \u0412-\u043B\u0438\u043C\u0444\u043E\u0446\u0438\u0442\u043E\u0432 \u0438 \u0434\u0440\u0443\u0433\u0438\u0445 \u0438\u043C\u043C\u0443\u043D\u043D\u044B\u0445 \u043A\u043B\u0435\u0442\u043E\u043A", 2, ["limfocyty Th"], ["\u0422-\u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A\u0438"]],
  ["nk", "kom\xF3rki NK", "NK-\u043A\u043B\u0435\u0442\u043A\u0438", "niszczenie kom\xF3rek zaka\u017Conych i nowotworowych bez wcze\u015Bniejszego kontaktu z antygenem", "\u0443\u043D\u0438\u0447\u0442\u043E\u0436\u0435\u043D\u0438\u0435 \u0437\u0430\u0440\u0430\u0436\u0451\u043D\u043D\u044B\u0445 \u0438 \u043E\u043F\u0443\u0445\u043E\u043B\u0435\u0432\u044B\u0445 \u043A\u043B\u0435\u0442\u043E\u043A \u0431\u0435\u0437 \u043F\u0440\u0435\u0434\u0432\u0430\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0439 \u0432\u0441\u0442\u0440\u0435\u0447\u0438 \u0441 \u0430\u043D\u0442\u0438\u0433\u0435\u043D\u043E\u043C", 2, ["naturalni zab\xF3jcy"], ["\u0435\u0441\u0442\u0435\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435 \u043A\u0438\u043B\u043B\u0435\u0440\u044B"]],
  ["interferony", "interferony", "\u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0440\u043E\u043D\u044B", "bia\u0142ka wydzielane przez kom\xF3rki zaka\u017Cone wirusem, chroni\u0105ce kom\xF3rki s\u0105siednie", "\u0431\u0435\u043B\u043A\u0438, \u0432\u044B\u0434\u0435\u043B\u044F\u0435\u043C\u044B\u0435 \u0437\u0430\u0440\u0430\u0436\u0451\u043D\u043D\u044B\u043C\u0438 \u0432\u0438\u0440\u0443\u0441\u043E\u043C \u043A\u043B\u0435\u0442\u043A\u0430\u043C\u0438 \u0438 \u0437\u0430\u0449\u0438\u0449\u0430\u044E\u0449\u0438\u0435 \u0441\u043E\u0441\u0435\u0434\u043D\u0438\u0435 \u043A\u043B\u0435\u0442\u043A\u0438", 2, [], []]
]);
var PERIPHERAL_PARTS = namedTable(P.nervous.peripheral, [
  ["nerwy-czaszkowe", "nerwy czaszkowe", "\u0447\u0435\u0440\u0435\u043F\u043D\u044B\u0435 \u043D\u0435\u0440\u0432\u044B", "12 par nerw\xF3w odchodz\u0105cych od m\xF3zgowia", "12 \u043F\u0430\u0440 \u043D\u0435\u0440\u0432\u043E\u0432, \u043E\u0442\u0445\u043E\u0434\u044F\u0449\u0438\u0445 \u043E\u0442 \u0433\u043E\u043B\u043E\u0432\u043D\u043E\u0433\u043E \u043C\u043E\u0437\u0433\u0430", 1, [], ["\u0447\u0435\u0440\u0435\u043F\u043D\u043E-\u043C\u043E\u0437\u0433\u043E\u0432\u044B\u0435 \u043D\u0435\u0440\u0432\u044B"]],
  ["nerwy-rdzeniowe", "nerwy rdzeniowe", "\u0441\u043F\u0438\u043D\u043D\u043E\u043C\u043E\u0437\u0433\u043E\u0432\u044B\u0435 \u043D\u0435\u0440\u0432\u044B", "31 par nerw\xF3w mieszanych odchodz\u0105cych od rdzenia kr\u0119gowego", "31 \u043F\u0430\u0440\u0430 \u0441\u043C\u0435\u0448\u0430\u043D\u043D\u044B\u0445 \u043D\u0435\u0440\u0432\u043E\u0432, \u043E\u0442\u0445\u043E\u0434\u044F\u0449\u0438\u0445 \u043E\u0442 \u0441\u043F\u0438\u043D\u043D\u043E\u0433\u043E \u043C\u043E\u0437\u0433\u0430", 1, [], []],
  ["korzen-grzbietowy", "korze\u0144 grzbietowy", "\u0437\u0430\u0434\u043D\u0438\u0439 \u043A\u043E\u0440\u0435\u0448\u043E\u043A", "cz\u0119\u015B\u0107 nerwu rdzeniowego z w\u0142\xF3knami czuciowymi i zwojem rdzeniowym", "\u0447\u0430\u0441\u0442\u044C \u0441\u043F\u0438\u043D\u043D\u043E\u043C\u043E\u0437\u0433\u043E\u0432\u043E\u0433\u043E \u043D\u0435\u0440\u0432\u0430 \u0441 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u043C\u0438 \u0432\u043E\u043B\u043E\u043A\u043D\u0430\u043C\u0438 \u0438 \u0441\u043F\u0438\u043D\u043D\u043E\u043C\u043E\u0437\u0433\u043E\u0432\u044B\u043C \u0443\u0437\u043B\u043E\u043C", 2, ["korze\u0144 tylny"], ["\u0434\u043E\u0440\u0441\u0430\u043B\u044C\u043D\u044B\u0439 \u043A\u043E\u0440\u0435\u0448\u043E\u043A"]],
  ["korzen-brzuszny", "korze\u0144 brzuszny", "\u043F\u0435\u0440\u0435\u0434\u043D\u0438\u0439 \u043A\u043E\u0440\u0435\u0448\u043E\u043A", "cz\u0119\u015B\u0107 nerwu rdzeniowego z w\u0142\xF3knami ruchowymi", "\u0447\u0430\u0441\u0442\u044C \u0441\u043F\u0438\u043D\u043D\u043E\u043C\u043E\u0437\u0433\u043E\u0432\u043E\u0433\u043E \u043D\u0435\u0440\u0432\u0430 \u0441 \u0434\u0432\u0438\u0433\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u043C\u0438 \u0432\u043E\u043B\u043E\u043A\u043D\u0430\u043C\u0438", 2, ["korze\u0144 przedni"], ["\u0432\u0435\u043D\u0442\u0440\u0430\u043B\u044C\u043D\u044B\u0439 \u043A\u043E\u0440\u0435\u0448\u043E\u043A"]],
  ["receptor", "receptor", "\u0440\u0435\u0446\u0435\u043F\u0442\u043E\u0440", "element \u0142uku odruchowego odbieraj\u0105cy bodziec", "\u0437\u0432\u0435\u043D\u043E \u0440\u0435\u0444\u043B\u0435\u043A\u0442\u043E\u0440\u043D\u043E\u0439 \u0434\u0443\u0433\u0438, \u0432\u043E\u0441\u043F\u0440\u0438\u043D\u0438\u043C\u0430\u044E\u0449\u0435\u0435 \u0440\u0430\u0437\u0434\u0440\u0430\u0436\u0435\u043D\u0438\u0435", 1, [], []],
  ["efektor", "efektor", "\u044D\u0444\u0444\u0435\u043A\u0442\u043E\u0440", "narz\u0105d wykonawczy \u2014 mi\u0119sie\u0144 lub gruczo\u0142 \u2014 reaguj\u0105cy na impuls nerwowy", "\u0438\u0441\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043E\u0440\u0433\u0430\u043D \u2014 \u043C\u044B\u0448\u0446\u0430 \u0438\u043B\u0438 \u0436\u0435\u043B\u0435\u0437\u0430, \u2014 \u043E\u0442\u0432\u0435\u0447\u0430\u044E\u0449\u0438\u0439 \u043D\u0430 \u043D\u0435\u0440\u0432\u043D\u044B\u0439 \u0438\u043C\u043F\u0443\u043B\u044C\u0441", 1, [], ["\u0440\u0430\u0431\u043E\u0447\u0438\u0439 \u043E\u0440\u0433\u0430\u043D"]],
  ["neuron-czuciowy", "neuron czuciowy", "\u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043D\u0435\u0439\u0440\u043E\u043D", "przewodzenie impuls\xF3w od receptora do o\u015Brodkowego uk\u0142adu nerwowego", "\u043F\u0440\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435 \u0438\u043C\u043F\u0443\u043B\u044C\u0441\u043E\u0432 \u043E\u0442 \u0440\u0435\u0446\u0435\u043F\u0442\u043E\u0440\u0430 \u043A \u0446\u0435\u043D\u0442\u0440\u0430\u043B\u044C\u043D\u043E\u0439 \u043D\u0435\u0440\u0432\u043D\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u0435", 1, ["neuron do\u015Brodkowy", "neuron aferentny"], ["\u0430\u0444\u0444\u0435\u0440\u0435\u043D\u0442\u043D\u044B\u0439 \u043D\u0435\u0439\u0440\u043E\u043D", "\u0446\u0435\u043D\u0442\u0440\u043E\u0441\u0442\u0440\u0435\u043C\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043D\u0435\u0439\u0440\u043E\u043D"]],
  ["neuron-ruchowy", "neuron ruchowy", "\u0434\u0432\u0438\u0433\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043D\u0435\u0439\u0440\u043E\u043D", "przewodzenie impuls\xF3w z o\u015Brodkowego uk\u0142adu nerwowego do efektora", "\u043F\u0440\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435 \u0438\u043C\u043F\u0443\u043B\u044C\u0441\u043E\u0432 \u043E\u0442 \u0446\u0435\u043D\u0442\u0440\u0430\u043B\u044C\u043D\u043E\u0439 \u043D\u0435\u0440\u0432\u043D\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u044B \u043A \u044D\u0444\u0444\u0435\u043A\u0442\u043E\u0440\u0443", 1, ["neuron od\u015Brodkowy", "motoneuron"], ["\u043C\u043E\u0442\u043E\u043D\u0435\u0439\u0440\u043E\u043D", "\u044D\u0444\u0444\u0435\u0440\u0435\u043D\u0442\u043D\u044B\u0439 \u043D\u0435\u0439\u0440\u043E\u043D"]],
  ["bezwarunkowy", "odruch bezwarunkowy", "\u0431\u0435\u0437\u0443\u0441\u043B\u043E\u0432\u043D\u044B\u0439 \u0440\u0435\u0444\u043B\u0435\u043A\u0441", "wrodzona, niezmienna reakcja na bodziec, np. odruch kolanowy", "\u0432\u0440\u043E\u0436\u0434\u0451\u043D\u043D\u0430\u044F \u043D\u0435\u0438\u0437\u043C\u0435\u043D\u043D\u0430\u044F \u0440\u0435\u0430\u043A\u0446\u0438\u044F \u043D\u0430 \u0440\u0430\u0437\u0434\u0440\u0430\u0436\u0438\u0442\u0435\u043B\u044C, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u043A\u043E\u043B\u0435\u043D\u043D\u044B\u0439 \u0440\u0435\u0444\u043B\u0435\u043A\u0441", 1, ["odruch wrodzony"], ["\u0432\u0440\u043E\u0436\u0434\u0451\u043D\u043D\u044B\u0439 \u0440\u0435\u0444\u043B\u0435\u043A\u0441"]],
  ["warunkowy", "odruch warunkowy", "\u0443\u0441\u043B\u043E\u0432\u043D\u044B\u0439 \u0440\u0435\u0444\u043B\u0435\u043A\u0441", "reakcja nabyta w ci\u0105gu \u017Cycia przez skojarzenie bod\u017Ac\xF3w", "\u0440\u0435\u0430\u043A\u0446\u0438\u044F, \u043F\u0440\u0438\u043E\u0431\u0440\u0435\u0442\u0451\u043D\u043D\u0430\u044F \u0432 \u0442\u0435\u0447\u0435\u043D\u0438\u0435 \u0436\u0438\u0437\u043D\u0438 \u043F\u0440\u0438 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0438 \u0440\u0430\u0437\u0434\u0440\u0430\u0436\u0438\u0442\u0435\u043B\u0435\u0439", 1, ["odruch nabyty"], ["\u043F\u0440\u0438\u043E\u0431\u0440\u0435\u0442\u0451\u043D\u043D\u044B\u0439 \u0440\u0435\u0444\u043B\u0435\u043A\u0441"]]
]);
var AUTONOMIC_PARTS = namedTable(P.nervous.autonomic, [
  ["somatyczny", "uk\u0142ad somatyczny", "\u0441\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u043D\u0435\u0440\u0432\u043D\u0430\u044F \u0441\u0438\u0441\u0442\u0435\u043C\u0430", "cz\u0119\u015B\u0107 uk\u0142adu nerwowego kieruj\u0105ca \u015Bwiadomymi ruchami mi\u0119\u015Bni szkieletowych", "\u0447\u0430\u0441\u0442\u044C \u043D\u0435\u0440\u0432\u043D\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u044B, \u0443\u043F\u0440\u0430\u0432\u043B\u044F\u044E\u0449\u0430\u044F \u043F\u0440\u043E\u0438\u0437\u0432\u043E\u043B\u044C\u043D\u044B\u043C\u0438 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F\u043C\u0438 \u0441\u043A\u0435\u043B\u0435\u0442\u043D\u044B\u0445 \u043C\u044B\u0448\u0446", 1, ["somatyczny uk\u0142ad nerwowy"], []],
  ["autonomiczny", "uk\u0142ad autonomiczny", "\u0432\u0435\u0433\u0435\u0442\u0430\u0442\u0438\u0432\u043D\u0430\u044F \u043D\u0435\u0440\u0432\u043D\u0430\u044F \u0441\u0438\u0441\u0442\u0435\u043C\u0430", "cz\u0119\u015B\u0107 uk\u0142adu nerwowego reguluj\u0105ca niezale\u017Cnie od woli prac\u0119 narz\u0105d\xF3w wewn\u0119trznych", "\u0447\u0430\u0441\u0442\u044C \u043D\u0435\u0440\u0432\u043D\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u044B, \u043D\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043C\u043E \u043E\u0442 \u0432\u043E\u043B\u0438 \u0440\u0435\u0433\u0443\u043B\u0438\u0440\u0443\u044E\u0449\u0430\u044F \u0440\u0430\u0431\u043E\u0442\u0443 \u0432\u043D\u0443\u0442\u0440\u0435\u043D\u043D\u0438\u0445 \u043E\u0440\u0433\u0430\u043D\u043E\u0432", 1, ["autonomiczny uk\u0142ad nerwowy", "uk\u0142ad wegetatywny"], ["\u0430\u0432\u0442\u043E\u043D\u043E\u043C\u043D\u0430\u044F \u043D\u0435\u0440\u0432\u043D\u0430\u044F \u0441\u0438\u0441\u0442\u0435\u043C\u0430"]],
  ["acetylocholina", "acetylocholina", "\u0430\u0446\u0435\u0442\u0438\u043B\u0445\u043E\u043B\u0438\u043D", "g\u0142\xF3wny neuroprzeka\u017Anik zako\u0144cze\u0144 cz\u0119\u015Bci przywsp\xF3\u0142czulnej", "\u0433\u043B\u0430\u0432\u043D\u044B\u0439 \u043C\u0435\u0434\u0438\u0430\u0442\u043E\u0440 \u043E\u043A\u043E\u043D\u0447\u0430\u043D\u0438\u0439 \u043F\u0430\u0440\u0430\u0441\u0438\u043C\u043F\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u043E\u0439 \u0447\u0430\u0441\u0442\u0438", 2, [], []],
  ["noradrenalina", "noradrenalina", "\u043D\u043E\u0440\u0430\u0434\u0440\u0435\u043D\u0430\u043B\u0438\u043D", "neuroprzeka\u017Anik zako\u0144cze\u0144 zazwojowych cz\u0119\u015Bci wsp\xF3\u0142czulnej", "\u043C\u0435\u0434\u0438\u0430\u0442\u043E\u0440 \u043F\u043E\u0441\u0442\u0433\u0430\u043D\u0433\u043B\u0438\u043E\u043D\u0430\u0440\u043D\u044B\u0445 \u043E\u043A\u043E\u043D\u0447\u0430\u043D\u0438\u0439 \u0441\u0438\u043C\u043F\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u043E\u0439 \u0447\u0430\u0441\u0442\u0438", 2, [], []],
  ["nerw-bledny", "nerw b\u0142\u0119dny", "\u0431\u043B\u0443\u0436\u0434\u0430\u044E\u0449\u0438\u0439 \u043D\u0435\u0440\u0432", "g\u0142\xF3wny nerw przywsp\xF3\u0142czulny unerwiaj\u0105cy serce, p\u0142uca i przew\xF3d pokarmowy", "\u0433\u043B\u0430\u0432\u043D\u044B\u0439 \u043F\u0430\u0440\u0430\u0441\u0438\u043C\u043F\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u043D\u0435\u0440\u0432, \u0438\u043D\u043D\u0435\u0440\u0432\u0438\u0440\u0443\u044E\u0449\u0438\u0439 \u0441\u0435\u0440\u0434\u0446\u0435, \u043B\u0451\u0433\u043A\u0438\u0435 \u0438 \u043F\u0438\u0449\u0435\u0432\u0430\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u0442\u0440\u0430\u043A\u0442", 2, [], []],
  ["pien-wspolczulny", "pie\u0144 wsp\xF3\u0142czulny", "\u0441\u0438\u043C\u043F\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0441\u0442\u0432\u043E\u043B", "\u0142a\u0144cuch zwoj\xF3w po obu stronach kr\u0119gos\u0142upa", "\u0446\u0435\u043F\u043E\u0447\u043A\u0430 \u0433\u0430\u043D\u0433\u043B\u0438\u0435\u0432 \u043F\u043E \u043E\u0431\u0435 \u0441\u0442\u043E\u0440\u043E\u043D\u044B \u043F\u043E\u0437\u0432\u043E\u043D\u043E\u0447\u043D\u0438\u043A\u0430", 2, [], []],
  ["walcz-uciekaj", "reakcja \u201Ewalcz lub uciekaj\u201D", "\u0440\u0435\u0430\u043A\u0446\u0438\u044F \xAB\u0431\u0435\u0439 \u0438\u043B\u0438 \u0431\u0435\u0433\u0438\xBB", "przyspieszenie pracy serca, rozszerzenie \u017Arenic i oskrzeli pod wp\u0142ywem cz\u0119\u015Bci wsp\xF3\u0142czulnej", "\u0443\u0447\u0430\u0449\u0435\u043D\u0438\u0435 \u0440\u0430\u0431\u043E\u0442\u044B \u0441\u0435\u0440\u0434\u0446\u0430, \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043D\u0438\u0435 \u0437\u0440\u0430\u0447\u043A\u043E\u0432 \u0438 \u0431\u0440\u043E\u043D\u0445\u043E\u0432 \u043F\u043E\u0434 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043C \u0441\u0438\u043C\u043F\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u043E\u0439 \u0447\u0430\u0441\u0442\u0438", 1, ["walcz lub uciekaj"], ["\u0431\u0435\u0439 \u0438\u043B\u0438 \u0431\u0435\u0433\u0438"]],
  ["podwojne-unerwienie", "podw\xF3jne unerwienie", "\u0434\u0432\u043E\u0439\u043D\u0430\u044F \u0438\u043D\u043D\u0435\u0440\u0432\u0430\u0446\u0438\u044F", "unerwienie wi\u0119kszo\u015Bci narz\u0105d\xF3w wewn\u0119trznych przez obie cz\u0119\u015Bci autonomiczne o przeciwnym dzia\u0142aniu", "\u0438\u043D\u043D\u0435\u0440\u0432\u0430\u0446\u0438\u044F \u0431\u043E\u043B\u044C\u0448\u0438\u043D\u0441\u0442\u0432\u0430 \u0432\u043D\u0443\u0442\u0440\u0435\u043D\u043D\u0438\u0445 \u043E\u0440\u0433\u0430\u043D\u043E\u0432 \u043E\u0431\u0435\u0438\u043C\u0438 \u0432\u0435\u0433\u0435\u0442\u0430\u0442\u0438\u0432\u043D\u044B\u043C\u0438 \u0447\u0430\u0441\u0442\u044F\u043C\u0438 \u0441 \u043F\u0440\u043E\u0442\u0438\u0432\u043E\u043F\u043E\u043B\u043E\u0436\u043D\u044B\u043C \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043C", 2, [], []]
]);
var EAR_PARTS = namedTable(P.senses.ear, [
  ["malzowina", "ma\u0142\u017Cowina uszna", "\u0443\u0448\u043D\u0430\u044F \u0440\u0430\u043A\u043E\u0432\u0438\u043D\u0430", "zbieranie fal d\u017Awi\u0119kowych i kierowanie ich do przewodu s\u0142uchowego", "\u0443\u043B\u0430\u0432\u043B\u0438\u0432\u0430\u043D\u0438\u0435 \u0437\u0432\u0443\u043A\u043E\u0432\u044B\u0445 \u0432\u043E\u043B\u043D \u0438 \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0438\u0445 \u0432 \u0441\u043B\u0443\u0445\u043E\u0432\u043E\u0439 \u043F\u0440\u043E\u0445\u043E\u0434", 1, [], []],
  ["przewod", "przew\xF3d s\u0142uchowy zewn\u0119trzny", "\u043D\u0430\u0440\u0443\u0436\u043D\u044B\u0439 \u0441\u043B\u0443\u0445\u043E\u0432\u043E\u0439 \u043F\u0440\u043E\u0445\u043E\u0434", "doprowadzanie d\u017Awi\u0119ku do b\u0142ony b\u0119benkowej", "\u043F\u0440\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435 \u0437\u0432\u0443\u043A\u0430 \u043A \u0431\u0430\u0440\u0430\u0431\u0430\u043D\u043D\u043E\u0439 \u043F\u0435\u0440\u0435\u043F\u043E\u043D\u043A\u0435", 1, ["przew\xF3d s\u0142uchowy"], ["\u0441\u043B\u0443\u0445\u043E\u0432\u043E\u0439 \u043F\u0440\u043E\u0445\u043E\u0434"]],
  ["blona-bebenkowa", "b\u0142ona b\u0119benkowa", "\u0431\u0430\u0440\u0430\u0431\u0430\u043D\u043D\u0430\u044F \u043F\u0435\u0440\u0435\u043F\u043E\u043D\u043A\u0430", "zamiana fal d\u017Awi\u0119kowych na drgania przekazywane kosteczkom s\u0142uchowym", "\u043F\u0440\u0435\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u0437\u0432\u0443\u043A\u043E\u0432\u044B\u0445 \u0432\u043E\u043B\u043D \u0432 \u043A\u043E\u043B\u0435\u0431\u0430\u043D\u0438\u044F, \u043F\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u0435\u043C\u044B\u0435 \u0441\u043B\u0443\u0445\u043E\u0432\u044B\u043C \u043A\u043E\u0441\u0442\u043E\u0447\u043A\u0430\u043C", 1, [], []],
  ["okienko", "okienko owalne", "\u043E\u0432\u0430\u043B\u044C\u043D\u043E\u0435 \u043E\u043A\u043D\u043E", "przekazywanie drga\u0144 strzemi\u0105czka do p\u0142ynu wype\u0142niaj\u0105cego \u015Blimak", "\u043F\u0435\u0440\u0435\u0434\u0430\u0447\u0430 \u043A\u043E\u043B\u0435\u0431\u0430\u043D\u0438\u0439 \u0441\u0442\u0440\u0435\u043C\u0435\u0447\u043A\u0430 \u0436\u0438\u0434\u043A\u043E\u0441\u0442\u0438, \u0437\u0430\u043F\u043E\u043B\u043D\u044F\u044E\u0449\u0435\u0439 \u0443\u043B\u0438\u0442\u043A\u0443", 2, [], []],
  ["komorki-rzeskowe", "kom\xF3rki zmys\u0142owe z rz\u0119skami", "\u0432\u043E\u043B\u043E\u0441\u043A\u043E\u0432\u044B\u0435 \u043A\u043B\u0435\u0442\u043A\u0438", "receptory s\u0142uchu i r\xF3wnowagi zamieniaj\u0105ce ruch p\u0142ynu na impulsy nerwowe", "\u0440\u0435\u0446\u0435\u043F\u0442\u043E\u0440\u044B \u0441\u043B\u0443\u0445\u0430 \u0438 \u0440\u0430\u0432\u043D\u043E\u0432\u0435\u0441\u0438\u044F, \u043F\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u044E\u0449\u0438\u0435 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435 \u0436\u0438\u0434\u043A\u043E\u0441\u0442\u0438 \u0432 \u043D\u0435\u0440\u0432\u043D\u044B\u0435 \u0438\u043C\u043F\u0443\u043B\u044C\u0441\u044B", 2, ["kom\xF3rki rz\u0119sate", "kom\xF3rki w\u0142oskowate"], ["\u0432\u043E\u043B\u043E\u0441\u043A\u043E\u0432\u044B\u0435 \u0440\u0435\u0446\u0435\u043F\u0442\u043E\u0440\u044B"]],
  ["przedsionek", "przedsionek", "\u043F\u0440\u0435\u0434\u0434\u0432\u0435\u0440\u0438\u0435", "odbieranie po\u0142o\u017Cenia g\u0142owy wzgl\u0119dem si\u0142y ci\u0119\u017Cko\u015Bci i ruch\xF3w prostoliniowych", "\u0432\u043E\u0441\u043F\u0440\u0438\u044F\u0442\u0438\u0435 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0433\u043E\u043B\u043E\u0432\u044B \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u0441\u0438\u043B\u044B \u0442\u044F\u0436\u0435\u0441\u0442\u0438 \u0438 \u043F\u0440\u044F\u043C\u043E\u043B\u0438\u043D\u0435\u0439\u043D\u044B\u0445 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0439", 2, ["woreczek i \u0142agiewka"], ["\u043C\u0435\u0448\u043E\u0447\u0435\u043A \u0438 \u043C\u0430\u0442\u043E\u0447\u043A\u0430"]],
  ["otolity", "otolity", "\u043E\u0442\u043E\u043B\u0438\u0442\u044B", "kryszta\u0142ki w\u0119glanu wapnia uciskaj\u0105ce kom\xF3rki zmys\u0142owe przy zmianie po\u0142o\u017Cenia g\u0142owy", "\u043A\u0440\u0438\u0441\u0442\u0430\u043B\u043B\u0438\u043A\u0438 \u043A\u0430\u0440\u0431\u043E\u043D\u0430\u0442\u0430 \u043A\u0430\u043B\u044C\u0446\u0438\u044F, \u0434\u0430\u0432\u044F\u0449\u0438\u0435 \u043D\u0430 \u0440\u0435\u0446\u0435\u043F\u0442\u043E\u0440\u044B \u043F\u0440\u0438 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0438 \u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0433\u043E\u043B\u043E\u0432\u044B", 2, ["kamyczki b\u0142\u0119dnikowe"], ["\u0441\u0442\u0430\u0442\u043E\u043B\u0438\u0442\u044B"]],
  ["ucho-srodkowe", "ucho \u015Brodkowe", "\u0441\u0440\u0435\u0434\u043D\u0435\u0435 \u0443\u0445\u043E", "wype\u0142niona powietrzem jama b\u0119benkowa z kosteczkami s\u0142uchowymi", "\u0437\u0430\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u0430\u044F \u0432\u043E\u0437\u0434\u0443\u0445\u043E\u043C \u0431\u0430\u0440\u0430\u0431\u0430\u043D\u043D\u0430\u044F \u043F\u043E\u043B\u043E\u0441\u0442\u044C \u0441\u043E \u0441\u043B\u0443\u0445\u043E\u0432\u044B\u043C\u0438 \u043A\u043E\u0441\u0442\u043E\u0447\u043A\u0430\u043C\u0438", 1, ["jama b\u0119benkowa"], ["\u0431\u0430\u0440\u0430\u0431\u0430\u043D\u043D\u0430\u044F \u043F\u043E\u043B\u043E\u0441\u0442\u044C"]],
  ["nerw-sluchowy", "nerw przedsionkowo-\u015Blimakowy", "\u043F\u0440\u0435\u0434\u0434\u0432\u0435\u0440\u043D\u043E-\u0443\u043B\u0438\u0442\u043A\u043E\u0432\u044B\u0439 \u043D\u0435\u0440\u0432", "przewodzenie impuls\xF3w s\u0142uchowych i r\xF3wnowagi do m\xF3zgowia", "\u043F\u0440\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435 \u0441\u043B\u0443\u0445\u043E\u0432\u044B\u0445 \u0438\u043C\u043F\u0443\u043B\u044C\u0441\u043E\u0432 \u0438 \u0438\u043C\u043F\u0443\u043B\u044C\u0441\u043E\u0432 \u0440\u0430\u0432\u043D\u043E\u0432\u0435\u0441\u0438\u044F \u043A \u043C\u043E\u0437\u0433\u0443", 2, ["nerw s\u0142uchowy"], ["\u0441\u043B\u0443\u0445\u043E\u0432\u043E\u0439 \u043D\u0435\u0440\u0432"]]
]);
var CHEMICAL_SENSES = namedTable(P.senses["taste-smell"], [
  ["chemoreceptory", "chemoreceptory", "\u0445\u0435\u043C\u043E\u0440\u0435\u0446\u0435\u043F\u0442\u043E\u0440\u044B", "receptory pobudzane przez cz\u0105steczki substancji chemicznych", "\u0440\u0435\u0446\u0435\u043F\u0442\u043E\u0440\u044B, \u0432\u043E\u0437\u0431\u0443\u0436\u0434\u0430\u0435\u043C\u044B\u0435 \u043C\u043E\u043B\u0435\u043A\u0443\u043B\u0430\u043C\u0438 \u0445\u0438\u043C\u0438\u0447\u0435\u0441\u043A\u0438\u0445 \u0432\u0435\u0449\u0435\u0441\u0442\u0432", 1, [], []],
  ["nablonek-wechowy", "nab\u0142onek w\u0119chowy", "\u043E\u0431\u043E\u043D\u044F\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u044D\u043F\u0438\u0442\u0435\u043B\u0438\u0439", "warstwa z receptorami w\u0119chu w g\xF3rnej cz\u0119\u015Bci jamy nosowej", "\u0441\u043B\u043E\u0439 \u0441 \u043E\u0431\u043E\u043D\u044F\u0442\u0435\u043B\u044C\u043D\u044B\u043C\u0438 \u0440\u0435\u0446\u0435\u043F\u0442\u043E\u0440\u0430\u043C\u0438 \u0432 \u0432\u0435\u0440\u0445\u043D\u0435\u0439 \u0447\u0430\u0441\u0442\u0438 \u043D\u043E\u0441\u043E\u0432\u043E\u0439 \u043F\u043E\u043B\u043E\u0441\u0442\u0438", 1, ["okolica w\u0119chowa"], ["\u043E\u0431\u043E\u043D\u044F\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u043E\u0431\u043B\u0430\u0441\u0442\u044C"]],
  ["opuszka", "opuszka w\u0119chowa", "\u043E\u0431\u043E\u043D\u044F\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u043B\u0443\u043A\u043E\u0432\u0438\u0446\u0430", "pierwszy o\u015Brodek przetwarzania bod\u017Ac\xF3w w\u0119chowych w m\xF3zgowiu", "\u043F\u0435\u0440\u0432\u044B\u0439 \u0446\u0435\u043D\u0442\u0440 \u043E\u0431\u0440\u0430\u0431\u043E\u0442\u043A\u0438 \u043E\u0431\u043E\u043D\u044F\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0441\u0438\u0433\u043D\u0430\u043B\u043E\u0432 \u0432 \u0433\u043E\u043B\u043E\u0432\u043D\u043E\u043C \u043C\u043E\u0437\u0433\u0435", 2, [], []],
  ["brodawki", "brodawki j\u0119zykowe", "\u0441\u043E\u0441\u043E\u0447\u043A\u0438 \u044F\u0437\u044B\u043A\u0430", "uwypuklenia b\u0142ony \u015Bluzowej j\u0119zyka, w kt\xF3rych le\u017C\u0105 kubki smakowe", "\u0432\u044B\u0441\u0442\u0443\u043F\u044B \u0441\u043B\u0438\u0437\u0438\u0441\u0442\u043E\u0439 \u044F\u0437\u044B\u043A\u0430, \u0432 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u043D\u0430\u0445\u043E\u0434\u044F\u0442\u0441\u044F \u0432\u043A\u0443\u0441\u043E\u0432\u044B\u0435 \u043F\u043E\u0447\u043A\u0438", 1, [], ["\u0432\u043A\u0443\u0441\u043E\u0432\u044B\u0435 \u0441\u043E\u0441\u043E\u0447\u043A\u0438"]],
  ["slodki", "smak s\u0142odki", "\u0441\u043B\u0430\u0434\u043A\u0438\u0439 \u0432\u043A\u0443\u0441", "smak sygnalizuj\u0105cy obecno\u015B\u0107 cukr\xF3w \u2014 \u017Ar\xF3d\u0142a energii", "\u0432\u043A\u0443\u0441, \u0441\u0438\u0433\u043D\u0430\u043B\u0438\u0437\u0438\u0440\u0443\u044E\u0449\u0438\u0439 \u043E \u0441\u0430\u0445\u0430\u0440\u0430\u0445 \u2014 \u0438\u0441\u0442\u043E\u0447\u043D\u0438\u043A\u0435 \u044D\u043D\u0435\u0440\u0433\u0438\u0438", 1, [], []],
  ["slony", "smak s\u0142ony", "\u0441\u043E\u043B\u0451\u043D\u044B\u0439 \u0432\u043A\u0443\u0441", "smak wywo\u0142ywany przez jony sodu", "\u0432\u043A\u0443\u0441, \u0432\u044B\u0437\u044B\u0432\u0430\u0435\u043C\u044B\u0439 \u0438\u043E\u043D\u0430\u043C\u0438 \u043D\u0430\u0442\u0440\u0438\u044F", 1, [], []],
  ["kwasny", "smak kwa\u015Bny", "\u043A\u0438\u0441\u043B\u044B\u0439 \u0432\u043A\u0443\u0441", "smak wywo\u0142ywany przez jony wodoru", "\u0432\u043A\u0443\u0441, \u0432\u044B\u0437\u044B\u0432\u0430\u0435\u043C\u044B\u0439 \u0438\u043E\u043D\u0430\u043C\u0438 \u0432\u043E\u0434\u043E\u0440\u043E\u0434\u0430", 1, [], []],
  ["gorzki", "smak gorzki", "\u0433\u043E\u0440\u044C\u043A\u0438\u0439 \u0432\u043A\u0443\u0441", "smak ostrzegaj\u0105cy przed potencjalnie truj\u0105cymi substancjami", "\u0432\u043A\u0443\u0441, \u043F\u0440\u0435\u0434\u0443\u043F\u0440\u0435\u0436\u0434\u0430\u044E\u0449\u0438\u0439 \u043E \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E \u044F\u0434\u043E\u0432\u0438\u0442\u044B\u0445 \u0432\u0435\u0449\u0435\u0441\u0442\u0432\u0430\u0445", 1, [], []],
  ["umami", "umami", "\u0443\u043C\u0430\u043C\u0438", "smak glutaminianu, sygnalizuj\u0105cy pokarm bogaty w bia\u0142ko", "\u0432\u043A\u0443\u0441 \u0433\u043B\u0443\u0442\u0430\u043C\u0430\u0442\u0430, \u0441\u0438\u0433\u043D\u0430\u043B\u0438\u0437\u0438\u0440\u0443\u044E\u0449\u0438\u0439 \u043E \u0431\u043E\u0433\u0430\u0442\u043E\u0439 \u0431\u0435\u043B\u043A\u043E\u043C \u043F\u0438\u0449\u0435", 2, ["smak umami"], ["\u0432\u043A\u0443\u0441 \u0443\u043C\u0430\u043C\u0438"]],
  ["adaptacja", "adaptacja w\u0119chowa", "\u043E\u0431\u043E\u043D\u044F\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u0430\u0434\u0430\u043F\u0442\u0430\u0446\u0438\u044F", "s\u0142abni\u0119cie odczuwania zapachu przy d\u0142ugotrwa\u0142ym dzia\u0142aniu tego samego bod\u017Aca", "\u043E\u0441\u043B\u0430\u0431\u043B\u0435\u043D\u0438\u0435 \u043E\u0449\u0443\u0449\u0435\u043D\u0438\u044F \u0437\u0430\u043F\u0430\u0445\u0430 \u043F\u0440\u0438 \u0434\u043B\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u043C \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0438 \u043E\u0434\u043D\u043E\u0433\u043E \u0438 \u0442\u043E\u0433\u043E \u0436\u0435 \u0440\u0430\u0437\u0434\u0440\u0430\u0436\u0438\u0442\u0435\u043B\u044F", 2, [], []]
]);
var MALE_PARTS = namedTable(P.reproduction.male, [
  ["kanaliki-nasienne", "kanaliki nasienne", "\u0441\u0435\u043C\u0435\u043D\u043D\u044B\u0435 \u043A\u0430\u043D\u0430\u043B\u044C\u0446\u044B", "miejsce powstawania plemnik\xF3w w j\u0105drach", "\u043C\u0435\u0441\u0442\u043E \u043E\u0431\u0440\u0430\u0437\u043E\u0432\u0430\u043D\u0438\u044F \u0441\u043F\u0435\u0440\u043C\u0430\u0442\u043E\u0437\u043E\u0438\u0434\u043E\u0432 \u0432 \u0441\u0435\u043C\u0435\u043D\u043D\u0438\u043A\u0430\u0445", 2, ["kanaliki nasienne kr\u0119te"], ["\u0438\u0437\u0432\u0438\u0442\u044B\u0435 \u0441\u0435\u043C\u0435\u043D\u043D\u044B\u0435 \u043A\u0430\u043D\u0430\u043B\u044C\u0446\u044B"]],
  ["leydig", "kom\xF3rki Leydiga", "\u043A\u043B\u0435\u0442\u043A\u0438 \u041B\u0435\u0439\u0434\u0438\u0433\u0430", "wydzielanie testosteronu w j\u0105drach", "\u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u0442\u0435\u0441\u0442\u043E\u0441\u0442\u0435\u0440\u043E\u043D\u0430 \u0432 \u0441\u0435\u043C\u0435\u043D\u043D\u0438\u043A\u0430\u0445", 3, ["kom\xF3rki \u015Br\xF3dmi\u0105\u017Cszowe"], ["\u0438\u043D\u0442\u0435\u0440\u0441\u0442\u0438\u0446\u0438\u0430\u043B\u044C\u043D\u044B\u0435 \u043A\u043B\u0435\u0442\u043A\u0438"]],
  ["sertoli", "kom\xF3rki Sertolego", "\u043A\u043B\u0435\u0442\u043A\u0438 \u0421\u0435\u0440\u0442\u043E\u043B\u0438", "od\u017Cywianie i ochrona rozwijaj\u0105cych si\u0119 plemnik\xF3w", "\u043F\u0438\u0442\u0430\u043D\u0438\u0435 \u0438 \u0437\u0430\u0449\u0438\u0442\u0430 \u0440\u0430\u0437\u0432\u0438\u0432\u0430\u044E\u0449\u0438\u0445\u0441\u044F \u0441\u043F\u0435\u0440\u043C\u0430\u0442\u043E\u0437\u043E\u0438\u0434\u043E\u0432", 3, [], []],
  ["moszna", "moszna", "\u043C\u043E\u0448\u043E\u043D\u043A\u0430", "utrzymywanie j\u0105der w temperaturze o 2\u20133 \xB0C ni\u017Cszej ni\u017C temperatura cia\u0142a", "\u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0430\u043D\u0438\u0435 \u0441\u0435\u043C\u0435\u043D\u043D\u0438\u043A\u043E\u0432 \u043F\u0440\u0438 \u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u0435 \u043D\u0430 2\u20133 \xB0C \u043D\u0438\u0436\u0435 \u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u044B \u0442\u0435\u043B\u0430", 1, [], []],
  ["nasieniowod", "nasieniowody", "\u0441\u0435\u043C\u044F\u0432\u044B\u043D\u043E\u0441\u044F\u0449\u0438\u0435 \u043F\u0440\u043E\u0442\u043E\u043A\u0438", "przewodzenie plemnik\xF3w z naj\u0105drzy do cewki moczowej", "\u043F\u0440\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435 \u0441\u043F\u0435\u0440\u043C\u0430\u0442\u043E\u0437\u043E\u0438\u0434\u043E\u0432 \u0438\u0437 \u043F\u0440\u0438\u0434\u0430\u0442\u043A\u043E\u0432 \u043A \u043C\u043E\u0447\u0435\u0438\u0441\u043F\u0443\u0441\u043A\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u043C\u0443 \u043A\u0430\u043D\u0430\u043B\u0443", 2, ["nasieniow\xF3d"], ["\u0441\u0435\u043C\u044F\u0432\u044B\u043D\u043E\u0441\u044F\u0449\u0438\u0439 \u043F\u0440\u043E\u0442\u043E\u043A"]],
  ["pecherzyki-nasienne", "p\u0119cherzyki nasienne", "\u0441\u0435\u043C\u0435\u043D\u043D\u044B\u0435 \u043F\u0443\u0437\u044B\u0440\u044C\u043A\u0438", "wydzielanie p\u0142ynu bogatego we fruktoz\u0119 \u2014 \u017Ar\xF3d\u0142o energii dla plemnik\xF3w", "\u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u0436\u0438\u0434\u043A\u043E\u0441\u0442\u0438, \u0431\u043E\u0433\u0430\u0442\u043E\u0439 \u0444\u0440\u0443\u043A\u0442\u043E\u0437\u043E\u0439, \u2014 \u0438\u0441\u0442\u043E\u0447\u043D\u0438\u043A\u0430 \u044D\u043D\u0435\u0440\u0433\u0438\u0438 \u0434\u043B\u044F \u0441\u043F\u0435\u0440\u043C\u0430\u0442\u043E\u0437\u043E\u0438\u0434\u043E\u0432", 2, [], []],
  ["prostata", "gruczo\u0142 krokowy", "\u043F\u0440\u0435\u0434\u0441\u0442\u0430\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u0436\u0435\u043B\u0435\u0437\u0430", "wydzielanie p\u0142ynu z enzymami i cynkiem, kt\xF3ry wchodzi w sk\u0142ad nasienia i pobudza ruch plemnik\xF3w", "\u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u0436\u0438\u0434\u043A\u043E\u0441\u0442\u0438 \u0441 \u0444\u0435\u0440\u043C\u0435\u043D\u0442\u0430\u043C\u0438 \u0438 \u0446\u0438\u043D\u043A\u043E\u043C, \u0432\u0445\u043E\u0434\u044F\u0449\u0435\u0439 \u0432 \u0441\u043E\u0441\u0442\u0430\u0432 \u0441\u043F\u0435\u0440\u043C\u044B \u0438 \u0430\u043A\u0442\u0438\u0432\u0438\u0440\u0443\u044E\u0449\u0435\u0439 \u0441\u043F\u0435\u0440\u043C\u0430\u0442\u043E\u0437\u043E\u0438\u0434\u044B", 1, ["prostata"], ["\u043F\u0440\u043E\u0441\u0442\u0430\u0442\u0430"]],
  ["plemnik", "plemnik", "\u0441\u043F\u0435\u0440\u043C\u0430\u0442\u043E\u0437\u043E\u0438\u0434", "m\u0119ska gameta z g\u0142\xF3wk\u0105, wstawk\u0105 pe\u0142n\u0105 mitochondri\xF3w i witk\u0105", "\u043C\u0443\u0436\u0441\u043A\u0430\u044F \u0433\u0430\u043C\u0435\u0442\u0430 \u0441 \u0433\u043E\u043B\u043E\u0432\u043A\u043E\u0439, \u0441\u0440\u0435\u0434\u043D\u0435\u0439 \u0447\u0430\u0441\u0442\u044C\u044E \u0441 \u043C\u0438\u0442\u043E\u0445\u043E\u043D\u0434\u0440\u0438\u044F\u043C\u0438 \u0438 \u0436\u0433\u0443\u0442\u0438\u043A\u043E\u043C", 1, [], []],
  ["akrosom", "akrosom", "\u0430\u043A\u0440\u043E\u0441\u043E\u043C\u0430", "p\u0119cherzyk z enzymami rozpuszczaj\u0105cymi os\u0142onki kom\xF3rki jajowej", "\u043F\u0443\u0437\u044B\u0440\u0451\u043A \u0441 \u0444\u0435\u0440\u043C\u0435\u043D\u0442\u0430\u043C\u0438, \u0440\u0430\u0441\u0442\u0432\u043E\u0440\u044F\u044E\u0449\u0438\u043C\u0438 \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0438 \u044F\u0439\u0446\u0435\u043A\u043B\u0435\u0442\u043A\u0438", 2, [], []],
  ["testosteron", "testosteron", "\u0442\u0435\u0441\u0442\u043E\u0441\u0442\u0435\u0440\u043E\u043D", "m\u0119ski hormon p\u0142ciowy, warunkuj\u0105cy rozw\xF3j drugorz\u0119dowych cech p\u0142ciowych", "\u043C\u0443\u0436\u0441\u043A\u043E\u0439 \u043F\u043E\u043B\u043E\u0432\u043E\u0439 \u0433\u043E\u0440\u043C\u043E\u043D, \u043E\u0431\u0435\u0441\u043F\u0435\u0447\u0438\u0432\u0430\u044E\u0449\u0438\u0439 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u0435 \u0432\u0442\u043E\u0440\u0438\u0447\u043D\u044B\u0445 \u043F\u043E\u043B\u043E\u0432\u044B\u0445 \u043F\u0440\u0438\u0437\u043D\u0430\u043A\u043E\u0432", 1, [], []]
]);
var NEURON_WORK = namedTable(P.nervous.structure, [
  ["neuroprzekaznik", "neuroprzeka\u017Anik", "\u043D\u0435\u0439\u0440\u043E\u043C\u0435\u0434\u0438\u0430\u0442\u043E\u0440", "substancja uwalniana z zako\u0144czenia aksonu do szczeliny synaptycznej, przenosz\u0105ca sygna\u0142 na kolejn\u0105 kom\xF3rk\u0119", "\u0432\u0435\u0449\u0435\u0441\u0442\u0432\u043E, \u0432\u044B\u0434\u0435\u043B\u044F\u0435\u043C\u043E\u0435 \u0438\u0437 \u043E\u043A\u043E\u043D\u0447\u0430\u043D\u0438\u044F \u0430\u043A\u0441\u043E\u043D\u0430 \u0432 \u0441\u0438\u043D\u0430\u043F\u0442\u0438\u0447\u0435\u0441\u043A\u0443\u044E \u0449\u0435\u043B\u044C \u0438 \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0449\u0435\u0435 \u0441\u0438\u0433\u043D\u0430\u043B \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u043A\u043B\u0435\u0442\u043A\u0435", 1, ["neurotransmiter", "mediator"], ["\u043D\u0435\u0439\u0440\u043E\u0442\u0440\u0430\u043D\u0441\u043C\u0438\u0442\u0442\u0435\u0440", "\u043C\u0435\u0434\u0438\u0430\u0442\u043E\u0440"]],
  ["szczelina", "szczelina synaptyczna", "\u0441\u0438\u043D\u0430\u043F\u0442\u0438\u0447\u0435\u0441\u043A\u0430\u044F \u0449\u0435\u043B\u044C", "w\u0105ska przestrze\u0144 mi\u0119dzy b\u0142on\u0105 presynaptyczn\u0105 a postsynaptyczn\u0105", "\u0443\u0437\u043A\u043E\u0435 \u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u0441\u0442\u0432\u043E \u043C\u0435\u0436\u0434\u0443 \u043F\u0440\u0435\u0441\u0438\u043D\u0430\u043F\u0442\u0438\u0447\u0435\u0441\u043A\u043E\u0439 \u0438 \u043F\u043E\u0441\u0442\u0441\u0438\u043D\u0430\u043F\u0442\u0438\u0447\u0435\u0441\u043A\u043E\u0439 \u043C\u0435\u043C\u0431\u0440\u0430\u043D\u0430\u043C\u0438", 1, [], []],
  ["pompa", "pompa sodowo-potasowa", "\u043D\u0430\u0442\u0440\u0438\u0439-\u043A\u0430\u043B\u0438\u0435\u0432\u044B\u0439 \u043D\u0430\u0441\u043E\u0441", "bia\u0142ko b\u0142ony wypompowuj\u0105ce z kom\xF3rki 3 jony Na\u207A i wprowadzaj\u0105ce 2 jony K\u207A kosztem ATP", "\u0431\u0435\u043B\u043E\u043A \u043C\u0435\u043C\u0431\u0440\u0430\u043D\u044B, \u0432\u044B\u043A\u0430\u0447\u0438\u0432\u0430\u044E\u0449\u0438\u0439 \u0438\u0437 \u043A\u043B\u0435\u0442\u043A\u0438 3 \u0438\u043E\u043D\u0430 Na\u207A \u0438 \u0437\u0430\u043A\u0430\u0447\u0438\u0432\u0430\u044E\u0449\u0438\u0439 2 \u0438\u043E\u043D\u0430 K\u207A \u0437\u0430 \u0441\u0447\u0451\u0442 \u0410\u0422\u0424", 2, ["ATP-aza sodowo-potasowa", "pompa Na\u207A/K\u207A"], ["Na/K-\u043D\u0430\u0441\u043E\u0441", "\u043D\u0430\u0442\u0440\u0438\u0439-\u043A\u0430\u043B\u0438\u0435\u0432\u0430\u044F \u0410\u0422\u0424\u0430\u0437\u0430"]],
  ["depolaryzacja", "depolaryzacja", "\u0434\u0435\u043F\u043E\u043B\u044F\u0440\u0438\u0437\u0430\u0446\u0438\u044F", "zmniejszenie r\xF3\u017Cnicy potencja\u0142\xF3w po obu stronach b\u0142ony neuronu wskutek nap\u0142ywu jon\xF3w sodu", "\u0443\u043C\u0435\u043D\u044C\u0448\u0435\u043D\u0438\u0435 \u0440\u0430\u0437\u043D\u043E\u0441\u0442\u0438 \u043F\u043E\u0442\u0435\u043D\u0446\u0438\u0430\u043B\u043E\u0432 \u043F\u043E \u043E\u0431\u0435 \u0441\u0442\u043E\u0440\u043E\u043D\u044B \u043C\u0435\u043C\u0431\u0440\u0430\u043D\u044B \u043D\u0435\u0439\u0440\u043E\u043D\u0430 \u0438\u0437-\u0437\u0430 \u0432\u0445\u043E\u0434\u0430 \u0438\u043E\u043D\u043E\u0432 \u043D\u0430\u0442\u0440\u0438\u044F", 2, [], []],
  ["repolaryzacja", "repolaryzacja", "\u0440\u0435\u043F\u043E\u043B\u044F\u0440\u0438\u0437\u0430\u0446\u0438\u044F", "powr\xF3t potencja\u0142u b\u0142ony do warto\u015Bci spoczynkowej dzi\u0119ki wyp\u0142ywowi jon\xF3w potasu", "\u0432\u043E\u0437\u0432\u0440\u0430\u0442 \u043C\u0435\u043C\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u043F\u043E\u0442\u0435\u043D\u0446\u0438\u0430\u043B\u0430 \u043A \u0443\u0440\u043E\u0432\u043D\u044E \u043F\u043E\u043A\u043E\u044F \u0431\u043B\u0430\u0433\u043E\u0434\u0430\u0440\u044F \u0432\u044B\u0445\u043E\u0434\u0443 \u0438\u043E\u043D\u043E\u0432 \u043A\u0430\u043B\u0438\u044F", 2, [], []],
  ["skokowe", "przewodzenie skokowe", "\u0441\u0430\u043B\u044C\u0442\u0430\u0442\u043E\u0440\u043D\u043E\u0435 \u043F\u0440\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435", "przeskakiwanie impulsu mi\u0119dzy przew\u0119\u017Ceniami w aksonach otoczonych os\u0142onk\u0105 mielinow\u0105", "\u043F\u0435\u0440\u0435\u0441\u043A\u0430\u043A\u0438\u0432\u0430\u043D\u0438\u0435 \u0438\u043C\u043F\u0443\u043B\u044C\u0441\u0430 \u043C\u0435\u0436\u0434\u0443 \u043F\u0435\u0440\u0435\u0445\u0432\u0430\u0442\u0430\u043C\u0438 \u0432 \u0430\u043A\u0441\u043E\u043D\u0430\u0445 \u0441 \u043C\u0438\u0435\u043B\u0438\u043D\u043E\u0432\u043E\u0439 \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u043E\u0439", 2, [], ["\u0441\u043A\u0430\u0447\u043A\u043E\u043E\u0431\u0440\u0430\u0437\u043D\u043E\u0435 \u043F\u0440\u043E\u0432\u0435\u0434\u0435\u043D\u0438\u0435"]],
  ["ranvier", "przew\u0119\u017Cenia Ranviera", "\u043F\u0435\u0440\u0435\u0445\u0432\u0430\u0442\u044B \u0420\u0430\u043D\u0432\u044C\u0435", "kr\xF3tkie odcinki aksonu pozbawione os\u0142onki mielinowej", "\u043A\u043E\u0440\u043E\u0442\u043A\u0438\u0435 \u0443\u0447\u0430\u0441\u0442\u043A\u0438 \u0430\u043A\u0441\u043E\u043D\u0430 \u0431\u0435\u0437 \u043C\u0438\u0435\u043B\u0438\u043D\u043E\u0432\u043E\u0439 \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0438", 2, ["przew\u0119\u017Cenie Ranviera"], ["\u043F\u0435\u0440\u0435\u0445\u0432\u0430\u0442 \u0420\u0430\u043D\u0432\u044C\u0435"]],
  ["refrakcja", "okres refrakcji", "\u0440\u0435\u0444\u0440\u0430\u043A\u0442\u0435\u0440\u043D\u044B\u0439 \u043F\u0435\u0440\u0438\u043E\u0434", "kr\xF3tki czas po impulsie, w kt\xF3rym neuron nie reaguje na kolejny bodziec lub reaguje tylko na bodziec silniejszy ni\u017C zwykle", "\u043A\u043E\u0440\u043E\u0442\u043A\u043E\u0435 \u0432\u0440\u0435\u043C\u044F \u043F\u043E\u0441\u043B\u0435 \u0438\u043C\u043F\u0443\u043B\u044C\u0441\u0430, \u043A\u043E\u0433\u0434\u0430 \u043D\u0435\u0439\u0440\u043E\u043D \u043D\u0435 \u043E\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u043D\u0430 \u043D\u043E\u0432\u043E\u0435 \u0440\u0430\u0437\u0434\u0440\u0430\u0436\u0435\u043D\u0438\u0435 \u0438\u043B\u0438 \u043E\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u043B\u0438\u0448\u044C \u043D\u0430 \u0431\u043E\u043B\u0435\u0435 \u0441\u0438\u043B\u044C\u043D\u043E\u0435", 2, ["refrakcja"], ["\u0440\u0435\u0444\u0440\u0430\u043A\u0442\u0435\u0440\u043D\u043E\u0441\u0442\u044C"]],
  ["wszystko-albo-nic", "zasada \u201Ewszystko albo nic\u201D", "\u0437\u0430\u043A\u043E\u043D \xAB\u0432\u0441\u0451 \u0438\u043B\u0438 \u043D\u0438\u0447\u0435\u0433\u043E\xBB", "impuls powstaje z pe\u0142n\u0105 si\u0142\u0105 tylko po przekroczeniu progu pobudliwo\u015Bci, a s\u0142abszy bodziec go nie wywo\u0142uje", "\u0438\u043C\u043F\u0443\u043B\u044C\u0441 \u0432\u043E\u0437\u043D\u0438\u043A\u0430\u0435\u0442 \u0432 \u043F\u043E\u043B\u043D\u0443\u044E \u0441\u0438\u043B\u0443 \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u0440\u0438 \u043F\u0440\u0435\u0432\u044B\u0448\u0435\u043D\u0438\u0438 \u043F\u043E\u0440\u043E\u0433\u0430 \u0432\u043E\u0437\u0431\u0443\u0434\u0438\u043C\u043E\u0441\u0442\u0438, \u0430 \u0431\u043E\u043B\u0435\u0435 \u0441\u043B\u0430\u0431\u044B\u0439 \u0440\u0430\u0437\u0434\u0440\u0430\u0436\u0438\u0442\u0435\u043B\u044C \u0435\u0433\u043E \u043D\u0435 \u0432\u044B\u0437\u044B\u0432\u0430\u0435\u0442", 2, ["wszystko albo nic", "prawo wszystko albo nic"], ["\u0432\u0441\u0451 \u0438\u043B\u0438 \u043D\u0438\u0447\u0435\u0433\u043E"]],
  ["glej", "kom\xF3rki glejowe", "\u0433\u043B\u0438\u0430\u043B\u044C\u043D\u044B\u0435 \u043A\u043B\u0435\u0442\u043A\u0438", "kom\xF3rki tkanki nerwowej od\u017Cywiaj\u0105ce, chroni\u0105ce i izoluj\u0105ce neurony", "\u043A\u043B\u0435\u0442\u043A\u0438 \u043D\u0435\u0440\u0432\u043D\u043E\u0439 \u0442\u043A\u0430\u043D\u0438, \u043F\u0438\u0442\u0430\u044E\u0449\u0438\u0435, \u0437\u0430\u0449\u0438\u0449\u0430\u044E\u0449\u0438\u0435 \u0438 \u0438\u0437\u043E\u043B\u0438\u0440\u0443\u044E\u0449\u0438\u0435 \u043D\u0435\u0439\u0440\u043E\u043D\u044B", 1, ["glej", "neuroglej"], ["\u0433\u043B\u0438\u044F", "\u043D\u0435\u0439\u0440\u043E\u0433\u043B\u0438\u044F"]]
]);
var BRAIN_PARTS = namedTable(P.nervous.central, [
  ["cialo-modzelowate", "cia\u0142o modzelowate", "\u043C\u043E\u0437\u043E\u043B\u0438\u0441\u0442\u043E\u0435 \u0442\u0435\u043B\u043E", "pasmo w\u0142\xF3kien nerwowych \u0142\u0105cz\u0105ce obie p\xF3\u0142kule m\xF3zgu", "\u043F\u0443\u0447\u043E\u043A \u043D\u0435\u0440\u0432\u043D\u044B\u0445 \u0432\u043E\u043B\u043E\u043A\u043E\u043D, \u0441\u043E\u0435\u0434\u0438\u043D\u044F\u044E\u0449\u0438\u0439 \u043E\u0431\u0430 \u043F\u043E\u043B\u0443\u0448\u0430\u0440\u0438\u044F", 2, [], []],
  ["plat-czolowy", "p\u0142at czo\u0142owy", "\u043B\u043E\u0431\u043D\u0430\u044F \u0434\u043E\u043B\u044F", "planowanie, podejmowanie decyzji i o\u015Brodek ruchowy kory", "\u043F\u043B\u0430\u043D\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0435, \u043F\u0440\u0438\u043D\u044F\u0442\u0438\u0435 \u0440\u0435\u0448\u0435\u043D\u0438\u0439 \u0438 \u0434\u0432\u0438\u0433\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u0446\u0435\u043D\u0442\u0440 \u043A\u043E\u0440\u044B", 2, [], []],
  ["plat-ciemieniowy", "p\u0142at ciemieniowy", "\u0442\u0435\u043C\u0435\u043D\u043D\u0430\u044F \u0434\u043E\u043B\u044F", "o\u015Brodek czucia dotyku, b\xF3lu i temperatury z powierzchni cia\u0142a", "\u0446\u0435\u043D\u0442\u0440 \u043E\u0441\u044F\u0437\u0430\u043D\u0438\u044F, \u0431\u043E\u043B\u0438 \u0438 \u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u044B \u0441 \u043F\u043E\u0432\u0435\u0440\u0445\u043D\u043E\u0441\u0442\u0438 \u0442\u0435\u043B\u0430", 2, [], []],
  ["plat-skroniowy", "p\u0142at skroniowy", "\u0432\u0438\u0441\u043E\u0447\u043D\u0430\u044F \u0434\u043E\u043B\u044F", "o\u015Brodek s\u0142uchu i rozumienia mowy", "\u0446\u0435\u043D\u0442\u0440 \u0441\u043B\u0443\u0445\u0430 \u0438 \u043F\u043E\u043D\u0438\u043C\u0430\u043D\u0438\u044F \u0440\u0435\u0447\u0438", 2, [], []],
  ["plat-potyliczny", "p\u0142at potyliczny", "\u0437\u0430\u0442\u044B\u043B\u043E\u0447\u043D\u0430\u044F \u0434\u043E\u043B\u044F", "o\u015Brodek wzroku", "\u0446\u0435\u043D\u0442\u0440 \u0437\u0440\u0435\u043D\u0438\u044F", 1, [], []],
  ["wzgorze", "wzg\xF3rze", "\u0442\u0430\u043B\u0430\u043C\u0443\u0441", "stacja przeka\u017Anikowa kieruj\u0105ca impulsy czuciowe do kory m\xF3zgu", "\u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0430\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u0441\u0442\u0430\u043D\u0446\u0438\u044F, \u043D\u0430\u043F\u0440\u0430\u0432\u043B\u044F\u044E\u0449\u0430\u044F \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0438\u043C\u043F\u0443\u043B\u044C\u0441\u044B \u0432 \u043A\u043E\u0440\u0443", 2, [], ["\u0437\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u0431\u0443\u0433\u043E\u0440"]],
  ["srodmozgowie", "\u015Br\xF3dm\xF3zgowie", "\u0441\u0440\u0435\u0434\u043D\u0438\u0439 \u043C\u043E\u0437\u0433", "o\u015Brodki odruch\xF3w wzrokowych i s\u0142uchowych, np. zw\u0119\u017Cania \u017Arenicy", "\u0446\u0435\u043D\u0442\u0440\u044B \u0437\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0438 \u0441\u043B\u0443\u0445\u043E\u0432\u044B\u0445 \u0440\u0435\u0444\u043B\u0435\u043A\u0441\u043E\u0432, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0441\u0443\u0436\u0435\u043D\u0438\u044F \u0437\u0440\u0430\u0447\u043A\u0430", 2, [], []],
  ["most", "most", "\u043C\u043E\u0441\u0442", "droga \u0142\u0105cz\u0105ca m\xF3\u017Cd\u017Cek z reszt\u0105 m\xF3zgowia, wsp\xF3\u0142udzia\u0142 w regulacji oddychania", "\u043F\u0443\u0442\u044C, \u0441\u0432\u044F\u0437\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u043C\u043E\u0437\u0436\u0435\u0447\u043E\u043A \u0441 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u043C \u043C\u043E\u0437\u0433\u043E\u043C, \u0443\u0447\u0430\u0441\u0442\u0438\u0435 \u0432 \u0440\u0435\u0433\u0443\u043B\u044F\u0446\u0438\u0438 \u0434\u044B\u0445\u0430\u043D\u0438\u044F", 2, ["most Varola"], ["\u0432\u0430\u0440\u043E\u043B\u0438\u0435\u0432 \u043C\u043E\u0441\u0442"]],
  ["opony", "opony m\xF3zgowo-rdzeniowe", "\u043C\u043E\u0437\u0433\u043E\u0432\u044B\u0435 \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0438", "trzy b\u0142ony z tkanki \u0142\u0105cznej chroni\u0105ce m\xF3zgowie i rdze\u0144 kr\u0119gowy", "\u0442\u0440\u0438 \u0441\u043E\u0435\u0434\u0438\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0442\u043A\u0430\u043D\u043D\u044B\u0435 \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0438, \u0437\u0430\u0449\u0438\u0449\u0430\u044E\u0449\u0438\u0435 \u0433\u043E\u043B\u043E\u0432\u043D\u043E\u0439 \u0438 \u0441\u043F\u0438\u043D\u043D\u043E\u0439 \u043C\u043E\u0437\u0433", 1, ["opony"], ["\u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0438 \u043C\u043E\u0437\u0433\u0430"]],
  ["plyn-mozgowo-rdzeniowy", "p\u0142yn m\xF3zgowo-rdzeniowy", "\u0441\u043F\u0438\u043D\u043D\u043E\u043C\u043E\u0437\u0433\u043E\u0432\u0430\u044F \u0436\u0438\u0434\u043A\u043E\u0441\u0442\u044C", "p\u0142yn amortyzuj\u0105cy wstrz\u0105sy i od\u017Cywiaj\u0105cy tkank\u0119 nerwow\u0105, wype\u0142niaj\u0105cy komory m\xF3zgu", "\u0436\u0438\u0434\u043A\u043E\u0441\u0442\u044C, \u0441\u043C\u044F\u0433\u0447\u0430\u044E\u0449\u0430\u044F \u0442\u043E\u043B\u0447\u043A\u0438 \u0438 \u043F\u0438\u0442\u0430\u044E\u0449\u0430\u044F \u043D\u0435\u0440\u0432\u043D\u0443\u044E \u0442\u043A\u0430\u043D\u044C, \u0437\u0430\u043F\u043E\u043B\u043D\u044F\u044E\u0449\u0430\u044F \u0436\u0435\u043B\u0443\u0434\u043E\u0447\u043A\u0438 \u043C\u043E\u0437\u0433\u0430", 2, [], ["\u043B\u0438\u043A\u0432\u043E\u0440", "\u0446\u0435\u0440\u0435\u0431\u0440\u043E\u0441\u043F\u0438\u043D\u0430\u043B\u044C\u043D\u0430\u044F \u0436\u0438\u0434\u043A\u043E\u0441\u0442\u044C"]],
  ["istota-szara", "istota szara", "\u0441\u0435\u0440\u043E\u0435 \u0432\u0435\u0449\u0435\u0441\u0442\u0432\u043E", "skupiska cia\u0142 neuron\xF3w: w rdzeniu kr\u0119gowym wewn\u0105trz, w m\xF3zgu na powierzchni jako kora", "\u0441\u043A\u043E\u043F\u043B\u0435\u043D\u0438\u044F \u0442\u0435\u043B \u043D\u0435\u0439\u0440\u043E\u043D\u043E\u0432: \u0432 \u0441\u043F\u0438\u043D\u043D\u043E\u043C \u043C\u043E\u0437\u0433\u0435 \u0432\u043D\u0443\u0442\u0440\u0438, \u0432 \u0433\u043E\u043B\u043E\u0432\u043D\u043E\u043C \u043D\u0430 \u043F\u043E\u0432\u0435\u0440\u0445\u043D\u043E\u0441\u0442\u0438 \u0432 \u0432\u0438\u0434\u0435 \u043A\u043E\u0440\u044B", 1, [], []],
  ["istota-biala", "istota bia\u0142a", "\u0431\u0435\u043B\u043E\u0435 \u0432\u0435\u0449\u0435\u0441\u0442\u0432\u043E", "skupiska akson\xF3w otoczonych os\u0142onkami mielinowymi, tworz\u0105ce drogi nerwowe", "\u0441\u043A\u043E\u043F\u043B\u0435\u043D\u0438\u044F \u043F\u043E\u043A\u0440\u044B\u0442\u044B\u0445 \u043C\u0438\u0435\u043B\u0438\u043D\u043E\u043C \u0430\u043A\u0441\u043E\u043D\u043E\u0432, \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0449\u0438\u0435 \u043F\u0440\u043E\u0432\u043E\u0434\u044F\u0449\u0438\u0435 \u043F\u0443\u0442\u0438", 1, [], []]
]);
var DEVELOPMENT_STAGES = namedTable(P.reproduction.development, [
  ["blastocysta", "blastocysta", "\u0431\u043B\u0430\u0441\u0442\u043E\u0446\u0438\u0441\u0442\u0430", "p\u0119cherzyk zarodkowy, kt\xF3ry zagnie\u017Cd\u017Ca si\u0119 w b\u0142onie \u015Bluzowej macicy", "\u0437\u0430\u0440\u043E\u0434\u044B\u0448\u0435\u0432\u044B\u0439 \u043F\u0443\u0437\u044B\u0440\u0451\u043A, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0432\u043D\u0435\u0434\u0440\u044F\u0435\u0442\u0441\u044F \u0432 \u0441\u043B\u0438\u0437\u0438\u0441\u0442\u0443\u044E \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0443 \u043C\u0430\u0442\u043A\u0438", 2, [], []],
  ["implantacja", "implantacja", "\u0438\u043C\u043F\u043B\u0430\u043D\u0442\u0430\u0446\u0438\u044F", "zagnie\u017Cd\u017Cenie si\u0119 zarodka w b\u0142onie \u015Bluzowej macicy ok. tydzie\u0144 po zap\u0142odnieniu", "\u0432\u043D\u0435\u0434\u0440\u0435\u043D\u0438\u0435 \u0437\u0430\u0440\u043E\u0434\u044B\u0448\u0430 \u0432 \u0441\u043B\u0438\u0437\u0438\u0441\u0442\u0443\u044E \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0443 \u043C\u0430\u0442\u043A\u0438 \u043F\u0440\u0438\u043C\u0435\u0440\u043D\u043E \u0447\u0435\u0440\u0435\u0437 \u043D\u0435\u0434\u0435\u043B\u044E \u043F\u043E\u0441\u043B\u0435 \u043E\u043F\u043B\u043E\u0434\u043E\u0442\u0432\u043E\u0440\u0435\u043D\u0438\u044F", 2, ["zagnie\u017Cd\u017Cenie"], []],
  ["gastrulacja", "gastrulacja", "\u0433\u0430\u0441\u0442\u0440\u0443\u043B\u044F\u0446\u0438\u044F", "etap rozwoju zarodkowego, w kt\xF3rym powstaj\u0105 listki zarodkowe", "\u044D\u0442\u0430\u043F \u0437\u0430\u0440\u043E\u0434\u044B\u0448\u0435\u0432\u043E\u0433\u043E \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044F, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442\u0441\u044F \u0437\u0430\u0440\u043E\u0434\u044B\u0448\u0435\u0432\u044B\u0435 \u043B\u0438\u0441\u0442\u043A\u0438", 2, [], []],
  ["organogeneza", "organogeneza", "\u043E\u0440\u0433\u0430\u043D\u043E\u0433\u0435\u043D\u0435\u0437", "powstawanie zawi\u0105zk\xF3w narz\u0105d\xF3w z listk\xF3w zarodkowych, w zasadzie do ko\u0144ca 8. tygodnia rozwoju (licz\u0105c od zap\u0142odnienia)", "\u043E\u0431\u0440\u0430\u0437\u043E\u0432\u0430\u043D\u0438\u0435 \u0437\u0430\u0447\u0430\u0442\u043A\u043E\u0432 \u043E\u0440\u0433\u0430\u043D\u043E\u0432 \u0438\u0437 \u0437\u0430\u0440\u043E\u0434\u044B\u0448\u0435\u0432\u044B\u0445 \u043B\u0438\u0441\u0442\u043A\u043E\u0432, \u0432 \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u043C \u0434\u043E \u043A\u043E\u043D\u0446\u0430 8-\u0439 \u043D\u0435\u0434\u0435\u043B\u0438 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044F (\u043E\u0442 \u043E\u043F\u043B\u043E\u0434\u043E\u0442\u0432\u043E\u0440\u0435\u043D\u0438\u044F)", 2, [], []],
  ["okres-plodowy", "okres p\u0142odowy", "\u043F\u043B\u043E\u0434\u043D\u044B\u0439 \u043F\u0435\u0440\u0438\u043E\u0434", "czas od 9. tygodnia rozwoju do porodu, w kt\xF3rym narz\u0105dy rosn\u0105 i dojrzewaj\u0105", "\u0432\u0440\u0435\u043C\u044F \u043E\u0442 9-\u0439 \u043D\u0435\u0434\u0435\u043B\u0438 \u0440\u0430\u0437\u0432\u0438\u0442\u0438\u044F \u0434\u043E \u0440\u043E\u0434\u043E\u0432, \u043A\u043E\u0433\u0434\u0430 \u043E\u0440\u0433\u0430\u043D\u044B \u0440\u0430\u0441\u0442\u0443\u0442 \u0438 \u0441\u043E\u0437\u0440\u0435\u0432\u0430\u044E\u0442", 2, [], ["\u0444\u0435\u0442\u0430\u043B\u044C\u043D\u044B\u0439 \u043F\u0435\u0440\u0438\u043E\u0434"]],
  ["owodnia", "owodnia", "\u0430\u043C\u043D\u0438\u043E\u043D", "b\u0142ona p\u0142odowa tworz\u0105ca p\u0119cherz z p\u0142ynem, kt\xF3ry chroni zarodek przed wstrz\u0105sami i wysychaniem", "\u0437\u0430\u0440\u043E\u0434\u044B\u0448\u0435\u0432\u0430\u044F \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0430, \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0449\u0430\u044F \u043F\u0443\u0437\u044B\u0440\u044C \u0441 \u0436\u0438\u0434\u043A\u043E\u0441\u0442\u044C\u044E, \u0437\u0430\u0449\u0438\u0449\u0430\u044E\u0449\u0435\u0439 \u0437\u0430\u0440\u043E\u0434\u044B\u0448 \u043E\u0442 \u0442\u043E\u043B\u0447\u043A\u043E\u0432 \u0438 \u0432\u044B\u0441\u044B\u0445\u0430\u043D\u0438\u044F", 1, [], ["\u0432\u043E\u0434\u043D\u0430\u044F \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0430"]],
  ["kosmowka", "kosm\xF3wka", "\u0445\u043E\u0440\u0438\u043E\u043D", "zewn\u0119trzna b\u0142ona p\u0142odowa, kt\xF3rej kosmki tworz\u0105 p\u0142odow\u0105 cz\u0119\u015B\u0107 \u0142o\u017Cyska", "\u043D\u0430\u0440\u0443\u0436\u043D\u0430\u044F \u0437\u0430\u0440\u043E\u0434\u044B\u0448\u0435\u0432\u0430\u044F \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0430, \u0432\u043E\u0440\u0441\u0438\u043D\u043A\u0438 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442 \u043F\u043B\u043E\u0434\u043D\u0443\u044E \u0447\u0430\u0441\u0442\u044C \u043F\u043B\u0430\u0446\u0435\u043D\u0442\u044B", 2, [], ["\u0432\u043E\u0440\u0441\u0438\u043D\u0447\u0430\u0442\u0430\u044F \u043E\u0431\u043E\u043B\u043E\u0447\u043A\u0430"]],
  ["pepowina", "p\u0119powina", "\u043F\u0443\u043F\u043E\u0432\u0438\u043D\u0430", "sznur z naczyniami krwiono\u015Bnymi \u0142\u0105cz\u0105cy p\u0142\xF3d z \u0142o\u017Cyskiem", "\u0442\u044F\u0436 \u0441 \u043A\u0440\u043E\u0432\u0435\u043D\u043E\u0441\u043D\u044B\u043C\u0438 \u0441\u043E\u0441\u0443\u0434\u0430\u043C\u0438, \u0441\u043E\u0435\u0434\u0438\u043D\u044F\u044E\u0449\u0438\u0439 \u043F\u043B\u043E\u0434 \u0441 \u043F\u043B\u0430\u0446\u0435\u043D\u0442\u043E\u0439", 1, [], []],
  ["porod", "por\xF3d", "\u0440\u043E\u0434\u044B", "wydalenie p\u0142odu z macicy dzi\u0119ki skurczom, kt\xF3re nasila oksytocyna", "\u0438\u0437\u0433\u043D\u0430\u043D\u0438\u0435 \u043F\u043B\u043E\u0434\u0430 \u0438\u0437 \u043C\u0430\u0442\u043A\u0438 \u0431\u043B\u0430\u0433\u043E\u0434\u0430\u0440\u044F \u0441\u0445\u0432\u0430\u0442\u043A\u0430\u043C, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0443\u0441\u0438\u043B\u0438\u0432\u0430\u0435\u0442 \u043E\u043A\u0441\u0438\u0442\u043E\u0446\u0438\u043D", 1, [], []],
  ["pokwitanie", "pokwitanie", "\u043F\u043E\u043B\u043E\u0432\u043E\u0435 \u0441\u043E\u0437\u0440\u0435\u0432\u0430\u043D\u0438\u0435", "okres dojrzewania p\u0142ciowego, w kt\xF3rym pojawiaj\u0105 si\u0119 drugorz\u0119dowe cechy p\u0142ciowe", "\u043F\u0435\u0440\u0438\u043E\u0434 \u043F\u043E\u043B\u043E\u0432\u043E\u0433\u043E \u0441\u043E\u0437\u0440\u0435\u0432\u0430\u043D\u0438\u044F, \u043A\u043E\u0433\u0434\u0430 \u043F\u043E\u044F\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u0432\u0442\u043E\u0440\u0438\u0447\u043D\u044B\u0435 \u043F\u043E\u043B\u043E\u0432\u044B\u0435 \u043F\u0440\u0438\u0437\u043D\u0430\u043A\u0438", 1, ["dojrzewanie p\u0142ciowe"], ["\u043F\u0443\u0431\u0435\u0440\u0442\u0430\u0442"]],
  ["antykoncepcja-hormonalna", "antykoncepcja hormonalna", "\u0433\u043E\u0440\u043C\u043E\u043D\u0430\u043B\u044C\u043D\u0430\u044F \u043A\u043E\u043D\u0442\u0440\u0430\u0446\u0435\u043F\u0446\u0438\u044F", "metoda zapobiegania ci\u0105\u017Cy polegaj\u0105ca na hamowaniu owulacji przez syntetyczne hormony", "\u043C\u0435\u0442\u043E\u0434 \u043F\u0440\u0435\u0434\u0443\u043F\u0440\u0435\u0436\u0434\u0435\u043D\u0438\u044F \u0431\u0435\u0440\u0435\u043C\u0435\u043D\u043D\u043E\u0441\u0442\u0438, \u043E\u0441\u043D\u043E\u0432\u0430\u043D\u043D\u044B\u0439 \u043D\u0430 \u043F\u043E\u0434\u0430\u0432\u043B\u0435\u043D\u0438\u0438 \u043E\u0432\u0443\u043B\u044F\u0446\u0438\u0438 \u0441\u0438\u043D\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u043C\u0438 \u0433\u043E\u0440\u043C\u043E\u043D\u0430\u043C\u0438", 2, ["tabletki antykoncepcyjne"], ["\u043F\u0440\u043E\u0442\u0438\u0432\u043E\u0437\u0430\u0447\u0430\u0442\u043E\u0447\u043D\u044B\u0435 \u0442\u0430\u0431\u043B\u0435\u0442\u043A\u0438"]],
  ["prezerwatywa", "prezerwatywa", "\u043F\u0440\u0435\u0437\u0435\u0440\u0432\u0430\u0442\u0438\u0432", "mechaniczna metoda antykoncepcji, kt\xF3ra chroni te\u017C przed chorobami przenoszonymi drog\u0105 p\u0142ciow\u0105", "\u0431\u0430\u0440\u044C\u0435\u0440\u043D\u044B\u0439 \u043C\u0435\u0442\u043E\u0434 \u043A\u043E\u043D\u0442\u0440\u0430\u0446\u0435\u043F\u0446\u0438\u0438, \u0437\u0430\u0449\u0438\u0449\u0430\u044E\u0449\u0438\u0439 \u0442\u0430\u043A\u0436\u0435 \u043E\u0442 \u0431\u043E\u043B\u0435\u0437\u043D\u0435\u0439, \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0449\u0438\u0445\u0441\u044F \u043F\u043E\u043B\u043E\u0432\u044B\u043C \u043F\u0443\u0442\u0451\u043C", 1, [], []]
]);
var IMMUNITY_MECHANISMS = namedTable(P.circulation.immunity, [
  ["szczepionka", "szczepionka", "\u0432\u0430\u043A\u0446\u0438\u043D\u0430", "preparat z os\u0142abionych lub zabitych drobnoustroj\xF3w albo ich antygen\xF3w, wywo\u0142uj\u0105cy odporno\u015B\u0107 czynn\u0105", "\u043F\u0440\u0435\u043F\u0430\u0440\u0430\u0442 \u0438\u0437 \u043E\u0441\u043B\u0430\u0431\u043B\u0435\u043D\u043D\u044B\u0445 \u0438\u043B\u0438 \u0443\u0431\u0438\u0442\u044B\u0445 \u043C\u0438\u043A\u0440\u043E\u0431\u043E\u0432 \u043B\u0438\u0431\u043E \u0438\u0445 \u0430\u043D\u0442\u0438\u0433\u0435\u043D\u043E\u0432, \u0432\u044B\u0437\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u0430\u043A\u0442\u0438\u0432\u043D\u044B\u0439 \u0438\u043C\u043C\u0443\u043D\u0438\u0442\u0435\u0442", 1, [], []],
  ["surowica", "surowica odporno\u015Bciowa", "\u043B\u0435\u0447\u0435\u0431\u043D\u0430\u044F \u0441\u044B\u0432\u043E\u0440\u043E\u0442\u043A\u0430", "preparat z gotowymi przeciwcia\u0142ami, daj\u0105cy natychmiastow\u0105, ale kr\xF3tkotrwa\u0142\u0105 odporno\u015B\u0107 biern\u0105", "\u043F\u0440\u0435\u043F\u0430\u0440\u0430\u0442 \u0441 \u0433\u043E\u0442\u043E\u0432\u044B\u043C\u0438 \u0430\u043D\u0442\u0438\u0442\u0435\u043B\u0430\u043C\u0438, \u0434\u0430\u044E\u0449\u0438\u0439 \u043D\u0435\u043C\u0435\u0434\u043B\u0435\u043D\u043D\u044B\u0439, \u043D\u043E \u043A\u0440\u0430\u0442\u043A\u043E\u0432\u0440\u0435\u043C\u0435\u043D\u043D\u044B\u0439 \u043F\u0430\u0441\u0441\u0438\u0432\u043D\u044B\u0439 \u0438\u043C\u043C\u0443\u043D\u0438\u0442\u0435\u0442", 1, ["surowica"], ["\u0438\u043C\u043C\u0443\u043D\u043D\u0430\u044F \u0441\u044B\u0432\u043E\u0440\u043E\u0442\u043A\u0430"]],
  ["humoralna", "odpowied\u017A humoralna", "\u0433\u0443\u043C\u043E\u0440\u0430\u043B\u044C\u043D\u044B\u0439 \u0438\u043C\u043C\u0443\u043D\u043D\u044B\u0439 \u043E\u0442\u0432\u0435\u0442", "odpowied\u017A swoista z udzia\u0142em przeciwcia\u0142 wytwarzanych przez kom\xF3rki plazmatyczne", "\u0441\u043F\u0435\u0446\u0438\u0444\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u043E\u0442\u0432\u0435\u0442 \u0441 \u0443\u0447\u0430\u0441\u0442\u0438\u0435\u043C \u0430\u043D\u0442\u0438\u0442\u0435\u043B, \u0432\u044B\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0435\u043C\u044B\u0445 \u043F\u043B\u0430\u0437\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u043C\u0438 \u043A\u043B\u0435\u0442\u043A\u0430\u043C\u0438", 2, ["odporno\u015B\u0107 humoralna"], ["\u0433\u0443\u043C\u043E\u0440\u0430\u043B\u044C\u043D\u044B\u0439 \u0438\u043C\u043C\u0443\u043D\u0438\u0442\u0435\u0442"]],
  ["komorkowa", "odpowied\u017A kom\xF3rkowa", "\u043A\u043B\u0435\u0442\u043E\u0447\u043D\u044B\u0439 \u0438\u043C\u043C\u0443\u043D\u043D\u044B\u0439 \u043E\u0442\u0432\u0435\u0442", "odpowied\u017A swoista, w kt\xF3rej limfocyty T bezpo\u015Brednio niszcz\u0105 zaka\u017Cone kom\xF3rki", "\u0441\u043F\u0435\u0446\u0438\u0444\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u043E\u0442\u0432\u0435\u0442, \u043F\u0440\u0438 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u0422-\u043B\u0438\u043C\u0444\u043E\u0446\u0438\u0442\u044B \u043D\u0435\u043F\u043E\u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0435\u043D\u043D\u043E \u0443\u043D\u0438\u0447\u0442\u043E\u0436\u0430\u044E\u0442 \u0437\u0430\u0440\u0430\u0436\u0451\u043D\u043D\u044B\u0435 \u043A\u043B\u0435\u0442\u043A\u0438", 2, ["odporno\u015B\u0107 kom\xF3rkowa"], ["\u043A\u043B\u0435\u0442\u043E\u0447\u043D\u044B\u0439 \u0438\u043C\u043C\u0443\u043D\u0438\u0442\u0435\u0442"]],
  ["fagocytoza", "fagocytoza", "\u0444\u0430\u0433\u043E\u0446\u0438\u0442\u043E\u0437", "poch\u0142anianie i trawienie drobnoustroj\xF3w przez makrofagi i neutrofile", "\u043F\u043E\u0433\u043B\u043E\u0449\u0435\u043D\u0438\u0435 \u0438 \u043F\u0435\u0440\u0435\u0432\u0430\u0440\u0438\u0432\u0430\u043D\u0438\u0435 \u043C\u0438\u043A\u0440\u043E\u0431\u043E\u0432 \u043C\u0430\u043A\u0440\u043E\u0444\u0430\u0433\u0430\u043C\u0438 \u0438 \u043D\u0435\u0439\u0442\u0440\u043E\u0444\u0438\u043B\u0430\u043C\u0438", 1, [], []],
  ["zapalenie", "stan zapalny", "\u0432\u043E\u0441\u043F\u0430\u043B\u0435\u043D\u0438\u0435", "miejscowa reakcja obronna z zaczerwienieniem, obrz\u0119kiem, b\xF3lem i ociepleniem tkanki", "\u043C\u0435\u0441\u0442\u043D\u0430\u044F \u0437\u0430\u0449\u0438\u0442\u043D\u0430\u044F \u0440\u0435\u0430\u043A\u0446\u0438\u044F \u0441 \u043F\u043E\u043A\u0440\u0430\u0441\u043D\u0435\u043D\u0438\u0435\u043C, \u043E\u0442\u0451\u043A\u043E\u043C, \u0431\u043E\u043B\u044C\u044E \u0438 \u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u0435\u043C \u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u044B \u0442\u043A\u0430\u043D\u0438", 1, ["zapalenie"], ["\u0432\u043E\u0441\u043F\u0430\u043B\u0438\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u0440\u0435\u0430\u043A\u0446\u0438\u044F"]],
  ["goraczka", "gor\u0105czka", "\u043B\u0438\u0445\u043E\u0440\u0430\u0434\u043A\u0430", "podwy\u017Cszenie temperatury cia\u0142a, kt\xF3re hamuje namna\u017Canie si\u0119 drobnoustroj\xF3w", "\u043F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u0435 \u0442\u0435\u043C\u043F\u0435\u0440\u0430\u0442\u0443\u0440\u044B \u0442\u0435\u043B\u0430, \u0442\u043E\u0440\u043C\u043E\u0437\u044F\u0449\u0435\u0435 \u0440\u0430\u0437\u043C\u043D\u043E\u0436\u0435\u043D\u0438\u0435 \u043C\u0438\u043A\u0440\u043E\u0431\u043E\u0432", 1, [], ["\u0436\u0430\u0440"]],
  ["odpowiedz-wtorna", "odpowied\u017A wt\xF3rna", "\u0432\u0442\u043E\u0440\u0438\u0447\u043D\u044B\u0439 \u0438\u043C\u043C\u0443\u043D\u043D\u044B\u0439 \u043E\u0442\u0432\u0435\u0442", "szybsza i silniejsza reakcja przy ponownym kontakcie z antygenem dzi\u0119ki kom\xF3rkom pami\u0119ci", "\u0431\u043E\u043B\u0435\u0435 \u0431\u044B\u0441\u0442\u0440\u0430\u044F \u0438 \u0441\u0438\u043B\u044C\u043D\u0430\u044F \u0440\u0435\u0430\u043A\u0446\u0438\u044F \u043F\u0440\u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0439 \u0432\u0441\u0442\u0440\u0435\u0447\u0435 \u0441 \u0430\u043D\u0442\u0438\u0433\u0435\u043D\u043E\u043C \u0431\u043B\u0430\u0433\u043E\u0434\u0430\u0440\u044F \u043A\u043B\u0435\u0442\u043A\u0430\u043C \u043F\u0430\u043C\u044F\u0442\u0438", 2, ["wt\xF3rna odpowied\u017A immunologiczna"], ["\u0432\u0442\u043E\u0440\u0438\u0447\u043D\u044B\u0439 \u043E\u0442\u0432\u0435\u0442"]],
  ["odpornosc-zbiorowiskowa", "odporno\u015B\u0107 populacyjna", "\u043A\u043E\u043B\u043B\u0435\u043A\u0442\u0438\u0432\u043D\u044B\u0439 \u0438\u043C\u043C\u0443\u043D\u0438\u0442\u0435\u0442", "ochrona os\xF3b niezaszczepionych dzi\u0119ki zaszczepieniu wi\u0119kszo\u015Bci populacji", "\u0437\u0430\u0449\u0438\u0442\u0430 \u043D\u0435\u043F\u0440\u0438\u0432\u0438\u0442\u044B\u0445 \u043B\u044E\u0434\u0435\u0439 \u0431\u043B\u0430\u0433\u043E\u0434\u0430\u0440\u044F \u0432\u0430\u043A\u0446\u0438\u043D\u0430\u0446\u0438\u0438 \u0431\u043E\u043B\u044C\u0448\u0438\u043D\u0441\u0442\u0432\u0430 \u043D\u0430\u0441\u0435\u043B\u0435\u043D\u0438\u044F", 2, ["odporno\u015B\u0107 zbiorowiskowa", "odporno\u015B\u0107 stadna"], ["\u043F\u043E\u043F\u0443\u043B\u044F\u0446\u0438\u043E\u043D\u043D\u044B\u0439 \u0438\u043C\u043C\u0443\u043D\u0438\u0442\u0435\u0442"]]
]);

