function disorders({ chapter, slug, rows, subtopic, shift }) {
  const topicId = `bio.lo3.${chapter}`;
  const tags = ["choroby"];
  const kind = (r, lang) => KINDS[r.kind][lang];
  return [
    choiceFromTable({
      id: `${topicId}.${slug}-to-cause`,
      topicId,
      rows,
      subtopic,
      tags,
      difficulty: (r) => r.tier,
      shift,
      question: (r, lang) => lang === "pl" ? `Schorzenie: ${r.name.pl}. Co je wywo\u0142uje?` : `\u0417\u0430\u0431\u043E\u043B\u0435\u0432\u0430\u043D\u0438\u0435: ${r.name.ru}. \u0427\u0442\u043E \u0435\u0433\u043E \u0432\u044B\u0437\u044B\u0432\u0430\u0435\u0442?`,
      optionText: (r, lang) => r.cause[lang],
      misconception: { pl: "przyczyna innego schorzenia tego samego uk\u0142adu", ru: "\u043F\u0440\u0438\u0447\u0438\u043D\u0430 \u0434\u0440\u0443\u0433\u043E\u0433\u043E \u0437\u0430\u0431\u043E\u043B\u0435\u0432\u0430\u043D\u0438\u044F \u0442\u043E\u0439 \u0436\u0435 \u0441\u0438\u0441\u0442\u0435\u043C\u044B" },
      hint: (r, lang) => lang === "pl" ? `Rodzaj: ${kind(r, "pl")}.` : `\u0412\u0438\u0434: ${kind(r, "ru")}.`,
      solution: (r, lang) => lang === "pl" ? `${cap(r.name.pl)}: ${r.cause.pl}. Objawy: ${r.sign.pl}.` : `${cap(r.name.ru)}: ${r.cause.ru}. \u0421\u0438\u043C\u043F\u0442\u043E\u043C\u044B: ${r.sign.ru}.`
    }),
    termFromTable({
      id: `${topicId}.sign-to-${slug}`,
      topicId,
      rows,
      subtopic,
      tags,
      difficulty: (r) => r.tier,
      question: (r, lang) => lang === "pl" ? `Objawy: ${r.sign.pl}. Podaj nazw\u0119 schorzenia.` : `\u0421\u0438\u043C\u043F\u0442\u043E\u043C\u044B: ${r.sign.ru}. \u041D\u0430\u0437\u043E\u0432\u0438 \u0437\u0430\u0431\u043E\u043B\u0435\u0432\u0430\u043D\u0438\u0435.`,
      term: (r, lang) => r.name[lang],
      aliases: (r) => [r.name.pl, r.name.ru, ...r.aliases.pl, ...r.aliases.ru],
      hint: (r, lang) => lang === "pl" ? `Rodzaj: ${kind(r, "pl")}.` : `\u0412\u0438\u0434: ${kind(r, "ru")}.`,
      solution: (r, lang) => lang === "pl" ? `Odpowied\u017A: ${r.name.pl}. Przyczyna: ${r.cause.pl}.` : `\u041E\u0442\u0432\u0435\u0442: ${r.name.ru}. \u041F\u0440\u0438\u0447\u0438\u043D\u0430: ${r.cause.ru}.`
    }),
    choiceFromTable({
      id: `${topicId}.${slug}-to-kind`,
      topicId,
      rows,
      subtopic,
      tags,
      difficulty: (r) => r.tier,
      shift: shift + 2,
      question: (r, lang) => lang === "pl" ? `Schorzenie: ${r.name.pl}. Do jakiej grupy schorze\u0144 nale\u017Cy?` : `\u0417\u0430\u0431\u043E\u043B\u0435\u0432\u0430\u043D\u0438\u0435: ${r.name.ru}. \u041A \u043A\u0430\u043A\u043E\u0439 \u0433\u0440\u0443\u043F\u043F\u0435 \u0437\u0430\u0431\u043E\u043B\u0435\u0432\u0430\u043D\u0438\u0439 \u043E\u043D\u043E \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0441\u044F?`,
      // rows of the same kind collide on this text; pickDistractors skips them
      optionText: (r, lang) => kind(r, lang),
      misconception: { pl: "rodzaj innego schorzenia tego samego uk\u0142adu", ru: "\u0432\u0438\u0434 \u0434\u0440\u0443\u0433\u043E\u0433\u043E \u0437\u0430\u0431\u043E\u043B\u0435\u0432\u0430\u043D\u0438\u044F \u0442\u043E\u0439 \u0436\u0435 \u0441\u0438\u0441\u0442\u0435\u043C\u044B" },
      solution: (r, lang) => lang === "pl" ? `${cap(r.name.pl)} \u2014 ${kind(r, "pl")}: ${r.cause.pl}.` : `${cap(r.name.ru)} \u2014 ${kind(r, "ru")}: ${r.cause.ru}.`
    })
  ];
}
