var bmi = calcTemplate({
  id: "bio.lo3.digestion.bmi",
  topicId: "bio.lo3.digestion",
  paragraph: P.digestion.diet,
  subtopic: DIET,
  tags: ["obliczenia"],
  difficulty: 1,
  params: { k: choiceParam(...BODIES.map((_, i) => i)) },
  decimals: 1,
  formula: (p) => `${BODIES[p.k][0]} / (${BODIES[p.k][1]} / 100)^2`,
  value: (p) => {
    const [m, h] = BODIES[p.k];
    const metres = h / 100;
    return m / (metres * metres);
  },
  question: (p, lang) => {
    const [m, h] = BODIES[p.k];
    return lang === "pl" ? `Osoba wa\u017Cy ${m} kg i ma ${h} cm wzrostu. Oblicz jej wska\u017Anik BMI z dok\u0142adno\u015Bci\u0105 do 0,1.` : `\u0427\u0435\u043B\u043E\u0432\u0435\u043A \u0432\u0435\u0441\u0438\u0442 ${m} \u043A\u0433 \u043F\u0440\u0438 \u0440\u043E\u0441\u0442\u0435 ${h} \u0441\u043C. \u0412\u044B\u0447\u0438\u0441\u043B\u0438 \u0435\u0433\u043E \u0438\u043D\u0434\u0435\u043A\u0441 \u043C\u0430\u0441\u0441\u044B \u0442\u0435\u043B\u0430 \u0441 \u0442\u043E\u0447\u043D\u043E\u0441\u0442\u044C\u044E \u0434\u043E 0,1.`;
  },
  hint: (_p, lang) => lang === "pl" ? "BMI = masa [kg] / (wzrost [m])\xB2. Wzrost zamie\u0144 najpierw na metry." : "\u0418\u041C\u0422 = \u043C\u0430\u0441\u0441\u0430 [\u043A\u0433] / (\u0440\u043E\u0441\u0442 [\u043C])\xB2. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u0435\u0440\u0435\u0432\u0435\u0434\u0438 \u0440\u043E\u0441\u0442 \u0432 \u043C\u0435\u0442\u0440\u044B.",
  solution: (p, answer, lang) => {
    const [m, h] = BODIES[p.k];
    const metres = String(h / 100).replace(".", ",");
    const value = m / (h / 100) ** 2;
    const verdict = bmiClass(value)[lang];
    return lang === "pl" ? `BMI = ${m} / ${metres}\xB2 = ${answer}. Wed\u0142ug WHO to ${verdict} (norma: 18,5\u201324,9).` : `\u0418\u041C\u0422 = ${m} / ${metres}\xB2 = ${answer}. \u041F\u043E \u043A\u0440\u0438\u0442\u0435\u0440\u0438\u044F\u043C \u0412\u041E\u0417 \u044D\u0442\u043E ${verdict} (\u043D\u043E\u0440\u043C\u0430: 18,5\u201324,9).`;
  }
});
