  dated("cortes-1521", ["podb\xF3j pa\u0144stwa Aztek\xF3w przez Cort\xE9sa", "\u0437\u0430\u0432\u043E\u0435\u0432\u0430\u043D\u0438\u0435 \u0433\u043E\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0430 \u0430\u0446\u0442\u0435\u043A\u043E\u0432 \u041A\u043E\u0440\u0442\u0435\u0441\u043E\u043C"], 1521, ["Hiszpanie zdobyli Tenochtitl\xE1n, stolic\u0119 Aztek\xF3w.", "\u0418\u0441\u043F\u0430\u043D\u0446\u044B \u0432\u0437\u044F\u043B\u0438 \u0422\u0435\u043D\u043E\u0447\u0442\u0438\u0442\u043B\u0430\u043D, \u0441\u0442\u043E\u043B\u0438\u0446\u0443 \u0430\u0446\u0442\u0435\u043A\u043E\u0432."], 2),
  dated("magellan-1522", ["zako\u0144czenie pierwszej podr\xF3\u017Cy dooko\u0142a \u015Bwiata", "\u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0435 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u043A\u0440\u0443\u0433\u043E\u0441\u0432\u0435\u0442\u043D\u043E\u0433\u043E \u043F\u043B\u0430\u0432\u0430\u043D\u0438\u044F"], 1522, ["Statek \u201EVictoria\u201D wr\xF3ci\u0142 do Hiszpanii \u2014 dow\xF3d, \u017Ce Ziemia jest kul\u0105.", "\u041A\u043E\u0440\u0430\u0431\u043B\u044C \xAB\u0412\u0438\u043A\u0442\u043E\u0440\u0438\u044F\xBB \u0432\u0435\u0440\u043D\u0443\u043B\u0441\u044F \u0432 \u0418\u0441\u043F\u0430\u043D\u0438\u044E \u2014 \u0434\u043E\u043A\u0430\u0437\u0430\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u043E, \u0447\u0442\u043E \u0417\u0435\u043C\u043B\u044F \u0448\u0430\u0440."], 2)
