  named2("radziwill", ["Miko\u0142aj Radziwi\u0142\u0142 Rudy", "\u041D\u0438\u043A\u043E\u043B\u0430\u0439 \u0420\u0430\u0434\u0437\u0438\u0432\u0438\u043B\u043B \u0420\u044B\u0436\u0438\u0439"], ["przyw\xF3dca litewskich magnat\xF3w, kt\xF3rzy sprzeciwiali si\u0119 unii i opu\u015Bcili obrady w Lublinie", "\u043F\u0440\u0435\u0434\u0432\u043E\u0434\u0438\u0442\u0435\u043B\u044C \u043B\u0438\u0442\u043E\u0432\u0441\u043A\u0438\u0445 \u043C\u0430\u0433\u043D\u0430\u0442\u043E\u0432, \u0432\u044B\u0441\u0442\u0443\u043F\u0430\u0432\u0448\u0438\u0445 \u043F\u0440\u043E\u0442\u0438\u0432 \u0443\u043D\u0438\u0438 \u0438 \u043F\u043E\u043A\u0438\u043D\u0443\u0432\u0448\u0438\u0445 \u0437\u0430\u0441\u0435\u0434\u0430\u043D\u0438\u044F \u0432 \u041B\u044E\u0431\u043B\u0438\u043D\u0435"], 3, ["Radziwi\u0142\u0142 Rudy", "Radziwi\u0142\u0142"], ["\u0420\u0430\u0434\u0437\u0438\u0432\u0438\u043B\u043B \u0420\u044B\u0436\u0438\u0439", "\u0420\u0430\u0434\u0437\u0438\u0432\u0438\u043B\u043B"]),
  named2("magnaci", ["magnaci", "\u043C\u0430\u0433\u043D\u0430\u0442\u044B"], ["najbogatsi i najpot\u0119\u017Cniejsi panowie, zw\u0142aszcza litewscy, kt\xF3rzy bali si\u0119 utraty w\u0142adzy po unii", "\u0441\u0430\u043C\u044B\u0435 \u0431\u043E\u0433\u0430\u0442\u044B\u0435 \u0438 \u043C\u043E\u0433\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435 \u043F\u0430\u043D\u044B, \u043E\u0441\u043E\u0431\u0435\u043D\u043D\u043E \u043B\u0438\u0442\u043E\u0432\u0441\u043A\u0438\u0435, \u0431\u043E\u044F\u0432\u0448\u0438\u0435\u0441\u044F \u043F\u043E\u0442\u0435\u0440\u044F\u0442\u044C \u0432\u043B\u0430\u0441\u0442\u044C \u043F\u043E\u0441\u043B\u0435 \u0443\u043D\u0438\u0438"], 2, ["magnat", "magnateria"], ["\u043C\u0430\u0433\u043D\u0430\u0442", "\u043C\u0430\u0433\u043D\u0430\u0442\u0435\u0440\u0438\u044F"])
