  named2("wisniowiecki", ["Jeremi Wi\u015Bniowiecki", "\u0418\u0435\u0440\u0435\u043C\u0438\u044F \u0412\u0438\u0448\u043D\u0435\u0432\u0435\u0446\u043A\u0438\u0439"], ["ksi\u0105\u017C\u0119 i pot\u0119\u017Cny magnat kresowy, bezwzgl\u0119dny pogromca Kozak\xF3w, obro\u0144ca Zbara\u017Ca", "\u043A\u043D\u044F\u0437\u044C \u0438 \u043C\u043E\u0433\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u043E\u043A\u0440\u0430\u0438\u043D\u043D\u044B\u0439 \u043C\u0430\u0433\u043D\u0430\u0442, \u0431\u0435\u0441\u043F\u043E\u0449\u0430\u0434\u043D\u044B\u0439 \u0443\u0441\u043C\u0438\u0440\u0438\u0442\u0435\u043B\u044C \u043A\u0430\u0437\u0430\u043A\u043E\u0432, \u0437\u0430\u0449\u0438\u0442\u043D\u0438\u043A \u0417\u0431\u0430\u0440\u0430\u0436\u0430"], 2, ["Wi\u015Bniowiecki", "Jarema Wi\u015Bniowiecki"], ["\u0412\u0438\u0448\u043D\u0435\u0432\u0435\u0446\u043A\u0438\u0439", "\u042F\u0440\u0435\u043C\u0430 \u0412\u0438\u0448\u043D\u0435\u0432\u0435\u0446\u043A\u0438\u0439"]),
  named2("jan-kazimierz", ["Jan Kazimierz", "\u042F\u043D \u041A\u0430\u0437\u0438\u043C\u0438\u0440"], ["kr\xF3l Polski od 1648 roku, brat W\u0142adys\u0142awa IV, zwyci\u0119zca spod Beresteczka", "\u043A\u043E\u0440\u043E\u043B\u044C \u041F\u043E\u043B\u044C\u0448\u0438 \u0441 1648 \u0433\u043E\u0434\u0430, \u0431\u0440\u0430\u0442 \u0412\u043B\u0430\u0434\u0438\u0441\u043B\u0430\u0432\u0430 IV, \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u043F\u043E\u0434 \u0411\u0435\u0440\u0435\u0441\u0442\u0435\u0447\u043A\u043E\u043C"], 1, ["Jan II Kazimierz", "Jan Kazimierz Waza"], ["\u042F\u043D II \u041A\u0430\u0437\u0438\u043C\u0438\u0440", "\u042F\u043D \u041A\u0430\u0437\u0438\u043C\u0438\u0440 \u0412\u0430\u0437\u0430"])
