  dated("zborow-1649", ["ugoda zborowska", "\u0417\u0431\u043E\u0440\u043E\u0432\u0441\u043A\u0438\u0439 \u0434\u043E\u0433\u043E\u0432\u043E\u0440"], 1649, ["Po obronie Zbara\u017Ca kr\xF3l zgodzi\u0142 si\u0119 na rejestr 40 tysi\u0119cy Kozak\xF3w.", "\u041F\u043E\u0441\u043B\u0435 \u043E\u0431\u043E\u0440\u043E\u043D\u044B \u0417\u0431\u0430\u0440\u0430\u0436\u0430 \u043A\u043E\u0440\u043E\u043B\u044C \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u043B\u0441\u044F \u043D\u0430 \u0440\u0435\u0435\u0441\u0442\u0440 \u0432 40 \u0442\u044B\u0441\u044F\u0447 \u043A\u0430\u0437\u0430\u043A\u043E\u0432."], 2, ["ugoda w Zborowie"], ["\u0417\u0431\u043E\u0440\u043E\u0432\u0441\u043A\u043E\u0435 \u0441\u043E\u0433\u043B\u0430\u0448\u0435\u043D\u0438\u0435"]),
  dated("beresteczko-1651", ["bitwa pod Beresteczkiem", "\u0431\u0438\u0442\u0432\u0430 \u043F\u043E\u0434 \u0411\u0435\u0440\u0435\u0441\u0442\u0435\u0447\u043A\u043E\u043C"], 1651, ["Trzydniowa bitwa, w kt\xF3rej armia Jana Kazimierza rozbi\u0142a Kozak\xF3w i Tatar\xF3w.", "\u0422\u0440\u0451\u0445\u0434\u043D\u0435\u0432\u043D\u0430\u044F \u0431\u0438\u0442\u0432\u0430, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u0430\u0440\u043C\u0438\u044F \u042F\u043D\u0430 \u041A\u0430\u0437\u0438\u043C\u0438\u0440\u0430 \u0440\u0430\u0437\u0431\u0438\u043B\u0430 \u043A\u0430\u0437\u0430\u043A\u043E\u0432 \u0438 \u0442\u0430\u0442\u0430\u0440."], 1, ["Beresteczko"], ["\u0411\u0435\u0440\u0435\u0441\u0442\u0435\u0447\u043A\u043E"]),
  dated("perejaslaw-1654", ["ugoda perejas\u0142awska", "\u041F\u0435\u0440\u0435\u044F\u0441\u043B\u0430\u0432\u0441\u043A\u0430\u044F \u0440\u0430\u0434\u0430"], 1654, ["Chmielnicki podda\u0142 Kozak\xF3w carowi; zacz\u0119\u0142a si\u0119 wojna Rzeczypospolitej z Rosj\u0105.", "\u0425\u043C\u0435\u043B\u044C\u043D\u0438\u0446\u043A\u0438\u0439 \u043E\u0442\u0434\u0430\u043B \u043A\u0430\u0437\u0430\u043A\u043E\u0432 \u043F\u043E\u0434 \u0432\u043B\u0430\u0441\u0442\u044C \u0446\u0430\u0440\u044F; \u043D\u0430\u0447\u0430\u043B\u0430\u0441\u044C \u0432\u043E\u0439\u043D\u0430 \u0420\u0435\u0447\u0438 \u041F\u043E\u0441\u043F\u043E\u043B\u0438\u0442\u043E\u0439 \u0441 \u0420\u043E\u0441\u0441\u0438\u0435\u0439."], 1, ["ugoda w Perejas\u0142awiu"], ["\u041F\u0435\u0440\u0435\u044F\u0441\u043B\u0430\u0432\u0441\u043A\u043E\u0435 \u0441\u043E\u0433\u043B\u0430\u0448\u0435\u043D\u0438\u0435"]),
  dated("chmielnicki-1657", ["\u015Bmier\u0107 Bohdana Chmielnickiego", "\u0441\u043C\u0435\u0440\u0442\u044C \u0411\u043E\u0433\u0434\u0430\u043D\u0430 \u0425\u043C\u0435\u043B\u044C\u043D\u0438\u0446\u043A\u043E\u0433\u043E"], 1657, ["Po \u015Bmierci hetmana cz\u0119\u015B\u0107 starszyzny kozackiej szuka\u0142a zgody z Rzecz\u0105pospolit\u0105.", "\u041F\u043E\u0441\u043B\u0435 \u0441\u043C\u0435\u0440\u0442\u0438 \u0433\u0435\u0442\u043C\u0430\u043D\u0430 \u0447\u0430\u0441\u0442\u044C \u043A\u0430\u0437\u0430\u0446\u043A\u043E\u0439 \u0441\u0442\u0430\u0440\u0448\u0438\u043D\u044B \u0438\u0441\u043A\u0430\u043B\u0430 \u0441\u043E\u0433\u043B\u0430\u0441\u0438\u044F \u0441 \u0420\u0435\u0447\u044C\u044E \u041F\u043E\u0441\u043F\u043E\u043B\u0438\u0442\u043E\u0439."], 3),
  dated("hadziacz-1658", ["unia hadziacka", "\u0413\u0430\u0434\u044F\u0447\u0441\u043A\u0430\u044F \u0443\u043D\u0438\u044F"], 1658, ["Hetman Wyhowski podpisa\u0142 uk\u0142ad o Ukrainie jako trzecim cz\u0142onie Rzeczypospolitej; nie wszed\u0142 w \u017Cycie.", "\u0413\u0435\u0442\u043C\u0430\u043D \u0412\u044B\u0433\u043E\u0432\u0441\u043A\u0438\u0439 \u043F\u043E\u0434\u043F\u0438\u0441\u0430\u043B \u0441\u043E\u0433\u043B\u0430\u0448\u0435\u043D\u0438\u0435 \u043E\u0431 \u0423\u043A\u0440\u0430\u0438\u043D\u0435 \u043A\u0430\u043A \u0442\u0440\u0435\u0442\u044C\u0435\u0439 \u0447\u0430\u0441\u0442\u0438 \u0420\u0435\u0447\u0438 \u041F\u043E\u0441\u043F\u043E\u043B\u0438\u0442\u043E\u0439; \u043E\u043D\u043E \u043D\u0435 \u0432\u0441\u0442\u0443\u043F\u0438\u043B\u043E \u0432 \u0441\u0438\u043B\u0443."], 2, ["ugoda hadziacka"], ["\u0413\u0430\u0434\u044F\u0447\u0441\u043A\u0438\u0439 \u0434\u043E\u0433\u043E\u0432\u043E\u0440"])
