  named2("radziejowski", ["Hieronim Radziejowski", "\u0418\u0435\u0440\u043E\u043D\u0438\u043C \u0420\u0430\u0434\u0437\u0435\u0451\u0432\u0441\u043A\u0438\u0439"], ["by\u0142y podkanclerzy skazany na banicj\u0119, kt\xF3ry nam\xF3wi\u0142 kr\xF3la Szwecji do najazdu na Polsk\u0119", "\u0431\u044B\u0432\u0448\u0438\u0439 \u043F\u043E\u0434\u043A\u0430\u043D\u0446\u043B\u0435\u0440, \u043F\u0440\u0438\u0433\u043E\u0432\u043E\u0440\u0451\u043D\u043D\u044B\u0439 \u043A \u0438\u0437\u0433\u043D\u0430\u043D\u0438\u044E, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0443\u0433\u043E\u0432\u043E\u0440\u0438\u043B \u043A\u043E\u0440\u043E\u043B\u044F \u0428\u0432\u0435\u0446\u0438\u0438 \u043D\u0430\u043F\u0430\u0441\u0442\u044C \u043D\u0430 \u041F\u043E\u043B\u044C\u0448\u0443"], 3, ["Radziejowski"], ["\u0420\u0430\u0434\u0437\u0435\u0451\u0432\u0441\u043A\u0438\u0439"]),
  named2("ujscie", ["kapitulacja pod Uj\u015Bciem", "\u043A\u0430\u043F\u0438\u0442\u0443\u043B\u044F\u0446\u0438\u044F \u043F\u043E\u0434 \u0423\u0439\u0441\u044C\u0446\u0435"], ["poddanie si\u0119 pospolitego ruszenia Wielkopolski Szwedom bez walki w lipcu 1655 roku", "\u0441\u0434\u0430\u0447\u0430 \u0432\u0435\u043B\u0438\u043A\u043E\u043F\u043E\u043B\u044C\u0441\u043A\u043E\u0433\u043E \u043E\u043F\u043E\u043B\u0447\u0435\u043D\u0438\u044F \u0448\u0432\u0435\u0434\u0430\u043C \u0431\u0435\u0437 \u0431\u043E\u044F \u0432 \u0438\u044E\u043B\u0435 1655 \u0433\u043E\u0434\u0430"], 2, ["Uj\u015Bcie"], ["\u0423\u0439\u0441\u044C\u0446\u0435"]),
  named2("kiejdany", ["uk\u0142ad w Kiejdanach", "\u041A\u0435\u0439\u0434\u0430\u043D\u0441\u043A\u0430\u044F \u0443\u043D\u0438\u044F"], ["uk\u0142ad, w kt\xF3rym Janusz Radziwi\u0142\u0142 odda\u0142 Litw\u0119 pod w\u0142adz\u0119 kr\xF3la Szwecji w 1655 roku", "\u0434\u043E\u0433\u043E\u0432\u043E\u0440, \u043F\u043E \u043A\u043E\u0442\u043E\u0440\u043E\u043C\u0443 \u042F\u043D\u0443\u0448 \u0420\u0430\u0434\u0437\u0438\u0432\u0438\u043B\u043B \u043E\u0442\u0434\u0430\u043B \u041B\u0438\u0442\u0432\u0443 \u043F\u043E\u0434 \u0432\u043B\u0430\u0441\u0442\u044C \u043A\u043E\u0440\u043E\u043B\u044F \u0428\u0432\u0435\u0446\u0438\u0438 \u0432 1655 \u0433\u043E\u0434\u0443"], 2, ["Kiejdany", "ugoda kiejda\u0144ska"], ["\u041A\u0435\u0439\u0434\u0430\u043D\u044B", "\u0434\u043E\u0433\u043E\u0432\u043E\u0440 \u0432 \u041A\u0435\u0439\u0434\u0430\u043D\u0430\u0445"]),
  named2("radziwill", ["Janusz Radziwi\u0142\u0142", "\u042F\u043D\u0443\u0448 \u0420\u0430\u0434\u0437\u0438\u0432\u0438\u043B\u043B"], ["hetman wielki litewski, kt\xF3ry zdradzi\u0142 kr\xF3la i podda\u0142 Litw\u0119 Szwedom", "\u0432\u0435\u043B\u0438\u043A\u0438\u0439 \u0433\u0435\u0442\u043C\u0430\u043D \u043B\u0438\u0442\u043E\u0432\u0441\u043A\u0438\u0439, \u043F\u0440\u0435\u0434\u0430\u0432\u0448\u0438\u0439 \u043A\u043E\u0440\u043E\u043B\u044F \u0438 \u043E\u0442\u0434\u0430\u0432\u0448\u0438\u0439 \u041B\u0438\u0442\u0432\u0443 \u0448\u0432\u0435\u0434\u0430\u043C"], 2, ["Radziwi\u0142\u0142"], ["\u0420\u0430\u0434\u0437\u0438\u0432\u0438\u043B\u043B"]),
  named2("jasna-gora", ["obrona Jasnej G\xF3ry", "\u043E\u0431\u043E\u0440\u043E\u043D\u0430 \u042F\u0441\u043D\u043E\u0439 \u0413\u043E\u0440\u044B"], ["sze\u015Bciotygodniowa obrona klasztoru w Cz\u0119stochowie przed Szwedami na prze\u0142omie 1655 i 1656 roku", "\u0448\u0435\u0441\u0442\u0438\u043D\u0435\u0434\u0435\u043B\u044C\u043D\u0430\u044F \u043E\u0431\u043E\u0440\u043E\u043D\u0430 \u043C\u043E\u043D\u0430\u0441\u0442\u044B\u0440\u044F \u0432 \u0427\u0435\u043D\u0441\u0442\u043E\u0445\u043E\u0432\u0435 \u043E\u0442 \u0448\u0432\u0435\u0434\u043E\u0432 \u043D\u0430 \u0440\u0443\u0431\u0435\u0436\u0435 1655 \u0438 1656 \u0433\u043E\u0434\u043E\u0432"], 1, ["Jasna G\xF3ra", "obrona Cz\u0119stochowy"], ["\u042F\u0441\u043D\u0430\u044F \u0413\u043E\u0440\u0430", "\u043E\u0431\u043E\u0440\u043E\u043D\u0430 \u0427\u0435\u043D\u0441\u0442\u043E\u0445\u043E\u0432\u044B"]),
  named2("kordecki", ["Augustyn Kordecki", "\u0410\u0432\u0433\u0443\u0441\u0442\u0438\u043D \u041A\u043E\u0440\u0434\u0435\u0446\u043A\u0438\u0439"], ["przeor paulin\xF3w, kt\xF3ry kierowa\u0142 obron\u0105 Jasnej G\xF3ry", "\u043D\u0430\u0441\u0442\u043E\u044F\u0442\u0435\u043B\u044C \u043F\u0430\u0443\u043B\u0438\u043D\u043E\u0432, \u0440\u0443\u043A\u043E\u0432\u043E\u0434\u0438\u0432\u0448\u0438\u0439 \u043E\u0431\u043E\u0440\u043E\u043D\u043E\u0439 \u042F\u0441\u043D\u043E\u0439 \u0413\u043E\u0440\u044B"], 2, ["Kordecki", "ksi\u0105dz Kordecki"], ["\u041A\u043E\u0440\u0434\u0435\u0446\u043A\u0438\u0439"]),
  named2("sluby-lwowskie", ["\u015Bluby lwowskie", "\u041B\u044C\u0432\u043E\u0432\u0441\u043A\u0438\u0435 \u043E\u0431\u0435\u0442\u044B"], ["uroczyste \u015Blubowanie Jana Kazimierza w katedrze lwowskiej w 1656 roku, w kt\xF3rym og\u0142osi\u0142 Matk\u0119 Bosk\u0105 Kr\xF3low\u0105 Polski", "\u0442\u043E\u0440\u0436\u0435\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u043E\u0431\u0435\u0442 \u042F\u043D\u0430 \u041A\u0430\u0437\u0438\u043C\u0438\u0440\u0430 \u0432\u043E \u043B\u044C\u0432\u043E\u0432\u0441\u043A\u043E\u043C \u0441\u043E\u0431\u043E\u0440\u0435 \u0432 1656 \u0433\u043E\u0434\u0443, \u0433\u0434\u0435 \u043E\u043D \u043F\u0440\u043E\u0432\u043E\u0437\u0433\u043B\u0430\u0441\u0438\u043B \u0411\u043E\u0433\u043E\u043C\u0430\u0442\u0435\u0440\u044C \u041A\u043E\u0440\u043E\u043B\u0435\u0432\u043E\u0439 \u041F\u043E\u043B\u044C\u0448\u0438"], 1, ["\u015Bluby Jana Kazimierza"], ["\u043E\u0431\u0435\u0442\u044B \u042F\u043D\u0430 \u041A\u0430\u0437\u0438\u043C\u0438\u0440\u0430"]),
  named2("czarniecki", ["Stefan Czarniecki", "\u0421\u0442\u0435\u0444\u0430\u043D \u0427\u0430\u0440\u043D\u0435\u0446\u043A\u0438\u0439"], ["dow\xF3dca wojny szarpanej ze Szwedami, wspomniany w \u201EMazurku D\u0105browskiego\u201D", "\u043F\u0440\u0435\u0434\u0432\u043E\u0434\u0438\u0442\u0435\u043B\u044C \u043F\u0430\u0440\u0442\u0438\u0437\u0430\u043D\u0441\u043A\u043E\u0439 \u0432\u043E\u0439\u043D\u044B \u0441\u043E \u0448\u0432\u0435\u0434\u0430\u043C\u0438, \u0443\u043F\u043E\u043C\u044F\u043D\u0443\u0442\u044B\u0439 \u0432 \xAB\u041C\u0430\u0437\u0443\u0440\u043A\u0435 \u0414\u043E\u043C\u0431\u0440\u043E\u0432\u0441\u043A\u043E\u0433\u043E\xBB"], 1, ["Czarniecki"], ["\u0427\u0430\u0440\u043D\u0435\u0446\u043A\u0438\u0439"]),
  named2("wojna-szarpana", ["wojna szarpana", "\u043F\u0430\u0440\u0442\u0438\u0437\u0430\u043D\u0441\u043A\u0430\u044F \u0432\u043E\u0439\u043D\u0430"], ["spos\xF3b walki Czarnieckiego: nag\u0142e napady ma\u0142ych oddzia\u0142\xF3w na Szwed\xF3w zamiast wielkich bitew", "\u0441\u043F\u043E\u0441\u043E\u0431 \u0432\u043E\u0439\u043D\u044B \u0427\u0430\u0440\u043D\u0435\u0446\u043A\u043E\u0433\u043E: \u0432\u043D\u0435\u0437\u0430\u043F\u043D\u044B\u0435 \u043D\u0430\u043B\u0451\u0442\u044B \u043C\u0430\u043B\u044B\u0445 \u043E\u0442\u0440\u044F\u0434\u043E\u0432 \u043D\u0430 \u0448\u0432\u0435\u0434\u043E\u0432 \u0432\u043C\u0435\u0441\u0442\u043E \u0431\u043E\u043B\u044C\u0448\u0438\u0445 \u0441\u0440\u0430\u0436\u0435\u043D\u0438\u0439"], 2, ["wojna podjazdowa"], ["\u043C\u0430\u043B\u0430\u044F \u0432\u043E\u0439\u043D\u0430", "\u0432\u043E\u0439\u043D\u0430 \u043D\u0430\u0441\u043A\u043E\u043A\u0430\u043C\u0438"]),
  named2("warka", ["bitwa pod Wark\u0105", "\u0431\u0438\u0442\u0432\u0430 \u043F\u043E\u0434 \u0412\u0430\u0440\u043A\u043E\u0439"], ["pierwsze zwyci\u0119stwo Polak\xF3w nad Szwedami w otwartej bitwie, wiosn\u0105 1656 roku", "\u043F\u0435\u0440\u0432\u0430\u044F \u043F\u043E\u0431\u0435\u0434\u0430 \u043F\u043E\u043B\u044F\u043A\u043E\u0432 \u043D\u0430\u0434 \u0448\u0432\u0435\u0434\u0430\u043C\u0438 \u0432 \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u043C \u0441\u0440\u0430\u0436\u0435\u043D\u0438\u0438, \u0432\u0435\u0441\u043D\u043E\u0439 1656 \u0433\u043E\u0434\u0430"], 3, ["Warka"], ["\u0412\u0430\u0440\u043A\u0430"]),
  named2("radnot", ["traktat w Radnot", "\u0420\u0430\u0434\u043D\u043E\u0442\u0441\u043A\u0438\u0439 \u0434\u043E\u0433\u043E\u0432\u043E\u0440"], ["plan rozbioru Rzeczypospolitej z 1656 roku, uzgodniony przez Szwecj\u0119, Siedmiogr\xF3d, Brandenburgi\u0119, Radziwi\u0142\u0142a i Kozak\xF3w", "\u043F\u043B\u0430\u043D \u0440\u0430\u0437\u0434\u0435\u043B\u0430 \u0420\u0435\u0447\u0438 \u041F\u043E\u0441\u043F\u043E\u043B\u0438\u0442\u043E\u0439 1656 \u0433\u043E\u0434\u0430, \u0441\u043E\u0433\u043B\u0430\u0441\u043E\u0432\u0430\u043D\u043D\u044B\u0439 \u0428\u0432\u0435\u0446\u0438\u0435\u0439, \u0422\u0440\u0430\u043D\u0441\u0438\u043B\u044C\u0432\u0430\u043D\u0438\u0435\u0439, \u0411\u0440\u0430\u043D\u0434\u0435\u043D\u0431\u0443\u0440\u0433\u043E\u043C, \u0420\u0430\u0434\u0437\u0438\u0432\u0438\u043B\u043B\u043E\u043C \u0438 \u043A\u0430\u0437\u0430\u043A\u0430\u043C\u0438"], 3, ["Radnot", "uk\u0142ad w Radnot"], ["\u0434\u043E\u0433\u043E\u0432\u043E\u0440 \u0432 \u0420\u0430\u0434\u043D\u043E\u0442\u0435", "\u0420\u0430\u0434\u043D\u043E\u0442"]),
  named2("rakoczy", ["Jerzy II Rakoczy", "\u0414\u044C\u0451\u0440\u0434\u044C II \u0420\u0430\u043A\u043E\u0446\u0438"], ["ksi\u0105\u017C\u0119 Siedmiogrodu, kt\xF3ry w 1657 roku najecha\u0142 Polsk\u0119 jako sojusznik Szwed\xF3w", "\u043A\u043D\u044F\u0437\u044C \u0422\u0440\u0430\u043D\u0441\u0438\u043B\u044C\u0432\u0430\u043D\u0438\u0438, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0432 1657 \u0433\u043E\u0434\u0443 \u0432\u0442\u043E\u0440\u0433\u0441\u044F \u0432 \u041F\u043E\u043B\u044C\u0448\u0443 \u043A\u0430\u043A \u0441\u043E\u044E\u0437\u043D\u0438\u043A \u0448\u0432\u0435\u0434\u043E\u0432"], 2, ["Rakoczy"], ["\u0420\u0430\u043A\u043E\u0446\u0438", "\u042E\u0440\u0438\u0439 II \u0420\u0430\u043A\u043E\u0446\u0438"]),
  named2("welawa", ["traktaty welawsko-bydgoskie", "\u0412\u0435\u043B\u044F\u0432\u0441\u043A\u043E-\u0411\u044B\u0434\u0433\u043E\u0449\u0441\u043A\u0438\u0435 \u0442\u0440\u0430\u043A\u0442\u0430\u0442\u044B"], ["uk\u0142ady z 1657 roku, w kt\xF3rych Polska zrzek\u0142a si\u0119 zwierzchnictwa nad Prusami Ksi\u0105\u017C\u0119cymi", "\u0441\u043E\u0433\u043B\u0430\u0448\u0435\u043D\u0438\u044F 1657 \u0433\u043E\u0434\u0430, \u043F\u043E \u043A\u043E\u0442\u043E\u0440\u044B\u043C \u041F\u043E\u043B\u044C\u0448\u0430 \u043E\u0442\u043A\u0430\u0437\u0430\u043B\u0430\u0441\u044C \u043E\u0442 \u0432\u0435\u0440\u0445\u043E\u0432\u043D\u043E\u0439 \u0432\u043B\u0430\u0441\u0442\u0438 \u043D\u0430\u0434 \u041A\u043D\u044F\u0436\u0435\u0441\u043A\u043E\u0439 \u041F\u0440\u0443\u0441\u0441\u0438\u0435\u0439"], 2, ["traktat welawski", "Welawa"], ["\u0412\u0435\u043B\u044F\u0432\u0441\u043A\u0438\u0439 \u0434\u043E\u0433\u043E\u0432\u043E\u0440", "\u0412\u0435\u043B\u044F\u0432\u0430"]),
  named2("oliwa-1660", ["pok\xF3j w Oliwie", "\u041E\u043B\u0438\u0432\u0441\u043A\u0438\u0439 \u043C\u0438\u0440"], ["pok\xF3j ko\u0144cz\u0105cy potop w 1660 roku: Jan Kazimierz zrzek\u0142 si\u0119 praw do tronu Szwecji, granice pozosta\u0142y bez zmian", "\u043C\u0438\u0440, \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0432\u0448\u0438\u0439 \u043F\u043E\u0442\u043E\u043F \u0432 1660 \u0433\u043E\u0434\u0443: \u042F\u043D \u041A\u0430\u0437\u0438\u043C\u0438\u0440 \u043E\u0442\u043A\u0430\u0437\u0430\u043B\u0441\u044F \u043E\u0442 \u043F\u0440\u0430\u0432 \u043D\u0430 \u0448\u0432\u0435\u0434\u0441\u043A\u0438\u0439 \u0442\u0440\u043E\u043D, \u0433\u0440\u0430\u043D\u0438\u0446\u044B \u043E\u0441\u0442\u0430\u043B\u0438\u0441\u044C \u043F\u0440\u0435\u0436\u043D\u0438\u043C\u0438"], 1, ["pok\xF3j oliwski"], ["\u043C\u0438\u0440 \u0432 \u041E\u043B\u0438\u0432\u0435"])
