  named2("ksiegi-elementarne", ["Towarzystwo do Ksi\u0105g Elementarnych", "\u041E\u0431\u0449\u0435\u0441\u0442\u0432\u043E \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u0430\u0440\u043D\u044B\u0445 \u043A\u043D\u0438\u0433"], ["instytucja KEN opracowuj\u0105ca nowe podr\u0119czniki i programy nauczania dla szk\xF3\u0142", "\u0443\u0447\u0440\u0435\u0436\u0434\u0435\u043D\u0438\u0435 \u041A\u042D\u041D, \u0440\u0430\u0437\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0432\u0448\u0435\u0435 \u043D\u043E\u0432\u044B\u0435 \u0443\u0447\u0435\u0431\u043D\u0438\u043A\u0438 \u0438 \u043F\u0440\u043E\u0433\u0440\u0430\u043C\u043C\u044B \u043E\u0431\u0443\u0447\u0435\u043D\u0438\u044F \u0434\u043B\u044F \u0448\u043A\u043E\u043B"], 2, ["Towarzystwo Ksi\u0105g Elementarnych"], ["\u041E\u0431\u0449\u0435\u0441\u0442\u0432\u043E \u0443\u0447\u0435\u0431\u043D\u0438\u043A\u043E\u0432"]),
  named2("kollataj", ["Hugo Ko\u0142\u0142\u0105taj", "\u0413\u0443\u0433\u043E \u041A\u043E\u043B\u043B\u043E\u043D\u0442\u0430\u0439"], ["ksi\u0105dz i dzia\u0142acz o\u015Bwiecenia, kt\xF3ry z polecenia KEN zreformowa\u0142 Akademi\u0119 Krakowsk\u0105", "\u0441\u0432\u044F\u0449\u0435\u043D\u043D\u0438\u043A \u0438 \u0434\u0435\u044F\u0442\u0435\u043B\u044C \u041F\u0440\u043E\u0441\u0432\u0435\u0449\u0435\u043D\u0438\u044F, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u043F\u043E \u043F\u043E\u0440\u0443\u0447\u0435\u043D\u0438\u044E \u041A\u042D\u041D \u0440\u0435\u0444\u043E\u0440\u043C\u0438\u0440\u043E\u0432\u0430\u043B \u041A\u0440\u0430\u043A\u043E\u0432\u0441\u043A\u0443\u044E \u0430\u043A\u0430\u0434\u0435\u043C\u0438\u044E"], 1, ["Ko\u0142\u0142\u0105taj", "ksi\u0105dz Ko\u0142\u0142\u0105taj"], ["\u041A\u043E\u043B\u043B\u043E\u043D\u0442\u0430\u0439", "\u043A\u0441\u0451\u043D\u0434\u0437 \u041A\u043E\u043B\u043B\u043E\u043D\u0442\u0430\u0439"]),
  named2("kasata", ["kasata zakonu jezuit\xF3w", "\u0443\u043F\u0440\u0430\u0437\u0434\u043D\u0435\u043D\u0438\u0435 \u043E\u0440\u0434\u0435\u043D\u0430 \u0438\u0435\u0437\u0443\u0438\u0442\u043E\u0432"], ["rozwi\u0105zanie zakonu przez papie\u017Ca w 1773 roku; maj\u0105tek jezuit\xF3w przeznaczono na szko\u0142y KEN", "\u0440\u043E\u0441\u043F\u0443\u0441\u043A \u043E\u0440\u0434\u0435\u043D\u0430 \u043F\u0430\u043F\u043E\u0439 \u0432 1773 \u0433\u043E\u0434\u0443; \u0438\u043C\u0443\u0449\u0435\u0441\u0442\u0432\u043E \u0438\u0435\u0437\u0443\u0438\u0442\u043E\u0432 \u043F\u0435\u0440\u0435\u0434\u0430\u043B\u0438 \u043D\u0430 \u0448\u043A\u043E\u043B\u044B \u041A\u042D\u041D"], 3, ["kasata jezuit\xF3w", "likwidacja zakonu jezuit\xF3w"], ["\u0440\u043E\u0441\u043F\u0443\u0441\u043A \u043E\u0440\u0434\u0435\u043D\u0430 \u0438\u0435\u0437\u0443\u0438\u0442\u043E\u0432", "\u043B\u0438\u043A\u0432\u0438\u0434\u0430\u0446\u0438\u044F \u043E\u0440\u0434\u0435\u043D\u0430 \u0438\u0435\u0437\u0443\u0438\u0442\u043E\u0432"]),
  named2("rada-nieustajaca", ["Rada Nieustaj\u0105ca", "\u041F\u043E\u0441\u0442\u043E\u044F\u043D\u043D\u044B\u0439 \u0441\u043E\u0432\u0435\u0442"], ["sta\u0142y rz\u0105d z kr\xF3lem na czele, powo\u0142any w 1775 roku i nadzorowany przez pos\u0142a rosyjskiego", "\u043F\u043E\u0441\u0442\u043E\u044F\u043D\u043D\u043E\u0435 \u043F\u0440\u0430\u0432\u0438\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u043E \u0432\u043E \u0433\u043B\u0430\u0432\u0435 \u0441 \u043A\u043E\u0440\u043E\u043B\u0451\u043C, \u0441\u043E\u0437\u0434\u0430\u043D\u043D\u043E\u0435 \u0432 1775 \u0433\u043E\u0434\u0443 \u0438 \u043F\u043E\u0434\u043A\u043E\u043D\u0442\u0440\u043E\u043B\u044C\u043D\u043E\u0435 \u0440\u0443\u0441\u0441\u043A\u043E\u043C\u0443 \u043F\u043E\u0441\u043B\u0443"], 2, ["Rada"], ["\u041D\u0435\u043F\u0440\u0435\u0440\u044B\u0432\u043D\u044B\u0439 \u0441\u043E\u0432\u0435\u0442"]),
  named2("zamek", ["Zamek Kr\xF3lewski w Warszawie", "\u041A\u043E\u0440\u043E\u043B\u0435\u0432\u0441\u043A\u0438\u0439 \u0437\u0430\u043C\u043E\u043A \u0432 \u0412\u0430\u0440\u0448\u0430\u0432\u0435"], ["siedziba kr\xF3la przebudowana za Stanis\u0142awa Augusta; tu odbywa\u0142y si\u0119 obiady czwartkowe i obrady sejmu", "\u0440\u0435\u0437\u0438\u0434\u0435\u043D\u0446\u0438\u044F \u043A\u043E\u0440\u043E\u043B\u044F, \u043F\u0435\u0440\u0435\u0441\u0442\u0440\u043E\u0435\u043D\u043D\u0430\u044F \u043F\u0440\u0438 \u0421\u0442\u0430\u043D\u0438\u0441\u043B\u0430\u0432\u0435 \u0410\u0432\u0433\u0443\u0441\u0442\u0435; \u0437\u0434\u0435\u0441\u044C \u043F\u0440\u043E\u0445\u043E\u0434\u0438\u043B\u0438 \u0447\u0435\u0442\u0432\u0435\u0440\u0433\u043E\u0432\u044B\u0435 \u043E\u0431\u0435\u0434\u044B \u0438 \u0437\u0430\u0441\u0435\u0434\u0430\u043D\u0438\u044F \u0441\u0435\u0439\u043C\u0430"], 2, ["Zamek Kr\xF3lewski", "zamek warszawski"], ["\u041A\u043E\u0440\u043E\u043B\u0435\u0432\u0441\u043A\u0438\u0439 \u0437\u0430\u043C\u043E\u043A", "\u0412\u0430\u0440\u0448\u0430\u0432\u0441\u043A\u0438\u0439 \u0437\u0430\u043C\u043E\u043A"]),
  named2("lazienki", ["\u0141azienki Kr\xF3lewskie", "\u041A\u043E\u0440\u043E\u043B\u0435\u0432\u0441\u043A\u0438\u0435 \u041B\u0430\u0437\u0435\u043D\u043A\u0438"], ["letnia rezydencja Stanis\u0142awa Augusta w Warszawie z Pa\u0142acem na Wyspie, wzorcowy zesp\xF3\u0142 klasycystyczny", "\u043B\u0435\u0442\u043D\u044F\u044F \u0440\u0435\u0437\u0438\u0434\u0435\u043D\u0446\u0438\u044F \u0421\u0442\u0430\u043D\u0438\u0441\u043B\u0430\u0432\u0430 \u0410\u0432\u0433\u0443\u0441\u0442\u0430 \u0432 \u0412\u0430\u0440\u0448\u0430\u0432\u0435 \u0441 \u0414\u0432\u043E\u0440\u0446\u043E\u043C \u043D\u0430 \u043E\u0441\u0442\u0440\u043E\u0432\u0435, \u043E\u0431\u0440\u0430\u0437\u0446\u043E\u0432\u044B\u0439 \u0430\u043D\u0441\u0430\u043C\u0431\u043B\u044C \u043A\u043B\u0430\u0441\u0441\u0438\u0446\u0438\u0437\u043C\u0430"], 1, ["\u0141azienki", "Pa\u0142ac na Wyspie"], ["\u041B\u0430\u0437\u0435\u043D\u043A\u0438", "\u0414\u0432\u043E\u0440\u0435\u0446 \u043D\u0430 \u043E\u0441\u0442\u0440\u043E\u0432\u0435"]),
  named2("teatr-narodowy", ["Teatr Narodowy", "\u041D\u0430\u0446\u0438\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0439 \u0442\u0435\u0430\u0442\u0440"], ["pierwsza sta\u0142a publiczna scena polska, otwarta w Warszawie w 1765 roku z inicjatywy kr\xF3la", "\u043F\u0435\u0440\u0432\u0430\u044F \u043F\u043E\u0441\u0442\u043E\u044F\u043D\u043D\u0430\u044F \u043F\u0443\u0431\u043B\u0438\u0447\u043D\u0430\u044F \u043F\u043E\u043B\u044C\u0441\u043A\u0430\u044F \u0441\u0446\u0435\u043D\u0430, \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F \u0432 \u0412\u0430\u0440\u0448\u0430\u0432\u0435 \u0432 1765 \u0433\u043E\u0434\u0443 \u043F\u043E \u0438\u043D\u0438\u0446\u0438\u0430\u0442\u0438\u0432\u0435 \u043A\u043E\u0440\u043E\u043B\u044F"], 1, ["teatr publiczny"], ["\u043F\u0443\u0431\u043B\u0438\u0447\u043D\u044B\u0439 \u0442\u0435\u0430\u0442\u0440"]),
  named2("boguslawski", ["Wojciech Bogus\u0142awski", "\u0412\u043E\u0439\u0446\u0435\u0445 \u0411\u043E\u0433\u0443\u0441\u043B\u0430\u0432\u0441\u043A\u0438\u0439"], ["aktor, re\u017Cyser i dyrektor Teatru Narodowego, nazywany ojcem teatru polskiego, autor \u201EKrakowiak\xF3w i G\xF3rali\u201D", "\u0430\u043A\u0442\u0451\u0440, \u0440\u0435\u0436\u0438\u0441\u0441\u0451\u0440 \u0438 \u0434\u0438\u0440\u0435\u043A\u0442\u043E\u0440 \u041D\u0430\u0446\u0438\u043E\u043D\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u0442\u0435\u0430\u0442\u0440\u0430, \u043A\u043E\u0442\u043E\u0440\u043E\u0433\u043E \u043D\u0430\u0437\u044B\u0432\u0430\u044E\u0442 \u043E\u0442\u0446\u043E\u043C \u043F\u043E\u043B\u044C\u0441\u043A\u043E\u0433\u043E \u0442\u0435\u0430\u0442\u0440\u0430, \u0430\u0432\u0442\u043E\u0440 \xAB\u041A\u0440\u0430\u043A\u043E\u0432\u044F\u043A\u043E\u0432 \u0438 \u0433\u043E\u0440\u0446\u0435\u0432\xBB"], 2, ["Bogus\u0142awski"], ["\u0411\u043E\u0433\u0443\u0441\u043B\u0430\u0432\u0441\u043A\u0438\u0439"]),
  named2("monitor", ["\u201EMonitor\u201D", "\xAB\u041C\u043E\u043D\u0438\u0442\u043E\u0440\xBB"], ["czasopismo wydawane od 1765 roku z poparciem kr\xF3la, krytykuj\u0105ce wady szlachty i szerz\u0105ce idee o\u015Bwiecenia", "\u0436\u0443\u0440\u043D\u0430\u043B, \u0432\u044B\u0445\u043E\u0434\u0438\u0432\u0448\u0438\u0439 \u0441 1765 \u0433\u043E\u0434\u0430 \u043F\u0440\u0438 \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u043A\u0435 \u043A\u043E\u0440\u043E\u043B\u044F, \u043A\u0440\u0438\u0442\u0438\u043A\u043E\u0432\u0430\u0432\u0448\u0438\u0439 \u043F\u043E\u0440\u043E\u043A\u0438 \u0448\u043B\u044F\u0445\u0442\u044B \u0438 \u0440\u0430\u0441\u043F\u0440\u043E\u0441\u0442\u0440\u0430\u043D\u044F\u0432\u0448\u0438\u0439 \u0438\u0434\u0435\u0438 \u041F\u0440\u043E\u0441\u0432\u0435\u0449\u0435\u043D\u0438\u044F"], 2, ["Monitor"], ["\u041C\u043E\u043D\u0438\u0442\u043E\u0440"]),
  named2("krasicki", ["Ignacy Krasicki", "\u0418\u0433\u043D\u0430\u0446\u0438\u0439 \u041A\u0440\u0430\u0441\u0438\u0446\u043A\u0438\u0439"], ["biskup i poeta zwany ksi\u0119ciem poet\xF3w polskich, autor bajek, satyr i poematu \u201EMonachomachia\u201D", "\u0435\u043F\u0438\u0441\u043A\u043E\u043F \u0438 \u043F\u043E\u044D\u0442, \u043F\u0440\u043E\u0437\u0432\u0430\u043D\u043D\u044B\u0439 \u043A\u043D\u044F\u0437\u0435\u043C \u043F\u043E\u043B\u044C\u0441\u043A\u0438\u0445 \u043F\u043E\u044D\u0442\u043E\u0432, \u0430\u0432\u0442\u043E\u0440 \u0431\u0430\u0441\u0435\u043D, \u0441\u0430\u0442\u0438\u0440 \u0438 \u043F\u043E\u044D\u043C\u044B \xAB\u041C\u043E\u043D\u0430\u0445\u043E\u043C\u0430\u0445\u0438\u044F\xBB"], 1, ["Krasicki", "biskup Krasicki"], ["\u041A\u0440\u0430\u0441\u0438\u0446\u043A\u0438\u0439", "\u0435\u043F\u0438\u0441\u043A\u043E\u043F \u041A\u0440\u0430\u0441\u0438\u0446\u043A\u0438\u0439"]),
  named2("monachomachia", ["\u201EMonachomachia\u201D", "\xAB\u041C\u043E\u043D\u0430\u0445\u043E\u043C\u0430\u0445\u0438\u044F\xBB"], ["\u017Cartobliwy poemat Krasickiego wy\u015Bmiewaj\u0105cy leniwych i k\u0142\xF3tliwych mnich\xF3w", "\u0448\u0443\u0442\u043B\u0438\u0432\u0430\u044F \u043F\u043E\u044D\u043C\u0430 \u041A\u0440\u0430\u0441\u0438\u0446\u043A\u043E\u0433\u043E, \u0432\u044B\u0441\u043C\u0435\u0438\u0432\u0430\u044E\u0449\u0430\u044F \u043B\u0435\u043D\u0438\u0432\u044B\u0445 \u0438 \u0432\u0437\u0434\u043E\u0440\u043D\u044B\u0445 \u043C\u043E\u043D\u0430\u0445\u043E\u0432"], 3, ["Monachomachia", "Wojna mnich\xF3w"], ["\u041C\u043E\u043D\u0430\u0445\u043E\u043C\u0430\u0445\u0438\u044F", "\u0412\u043E\u0439\u043D\u0430 \u043C\u043E\u043D\u0430\u0445\u043E\u0432"]),
  named2("karpinski", ["Franciszek Karpi\u0144ski", "\u0424\u0440\u0430\u043D\u0446\u0438\u0448\u0435\u043A \u041A\u0430\u0440\u043F\u0438\u043D\u0441\u043A\u0438\u0439"], ["poeta sentymentalny, autor kol\u0119dy \u201EB\xF3g si\u0119 rodzi\u201D i sielanki \u201ELaura i Filon\u201D", "\u043F\u043E\u044D\u0442-\u0441\u0435\u043D\u0442\u0438\u043C\u0435\u043D\u0442\u0430\u043B\u0438\u0441\u0442, \u0430\u0432\u0442\u043E\u0440 \u043A\u043E\u043B\u044F\u0434\u043A\u0438 \xAB\u0411\u043E\u0433 \u0440\u043E\u0436\u0434\u0430\u0435\u0442\u0441\u044F\xBB \u0438 \u0438\u0434\u0438\u043B\u043B\u0438\u0438 \xAB\u041B\u0430\u0443\u0440\u0430 \u0438 \u0424\u0438\u043B\u043E\u043D\xBB"], 2, ["Karpi\u0144ski"], ["\u041A\u0430\u0440\u043F\u0438\u043D\u0441\u043A\u0438\u0439"]),
  named2("staszic", ["Stanis\u0142aw Staszic", "\u0421\u0442\u0430\u043D\u0438\u0441\u043B\u0430\u0432 \u0421\u0442\u0430\u0448\u0438\u0446"], ["ksi\u0105dz i pisarz polityczny mieszcza\u0144skiego pochodzenia, autor \u201EUwag nad \u017Cyciem Jana Zamoyskiego\u201D z projektem naprawy pa\u0144stwa", "\u0441\u0432\u044F\u0449\u0435\u043D\u043D\u0438\u043A \u0438 \u043F\u043E\u043B\u0438\u0442\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u043F\u0438\u0441\u0430\u0442\u0435\u043B\u044C \u043C\u0435\u0449\u0430\u043D\u0441\u043A\u043E\u0433\u043E \u043F\u0440\u043E\u0438\u0441\u0445\u043E\u0436\u0434\u0435\u043D\u0438\u044F, \u0430\u0432\u0442\u043E\u0440 \xAB\u0417\u0430\u043C\u0435\u0447\u0430\u043D\u0438\u0439 \u043E \u0436\u0438\u0437\u043D\u0438 \u042F\u043D\u0430 \u0417\u0430\u043C\u043E\u0439\u0441\u043A\u043E\u0433\u043E\xBB \u0441 \u043F\u0440\u043E\u0435\u043A\u0442\u043E\u043C \u0438\u0441\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F \u0433\u043E\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0430"], 2, ["Staszic", "ksi\u0105dz Staszic"], ["\u0421\u0442\u0430\u0448\u0438\u0446", "\u043A\u0441\u0451\u043D\u0434\u0437 \u0421\u0442\u0430\u0448\u0438\u0446"]),
  named2("klasycyzm", ["klasycyzm", "\u043A\u043B\u0430\u0441\u0441\u0438\u0446\u0438\u0437\u043C"], ["styl w sztuce drugiej po\u0142owy XVIII wieku na\u015Bladuj\u0105cy prostot\u0119 i symetri\u0119 budowli antycznych", "\u0441\u0442\u0438\u043B\u044C \u0432 \u0438\u0441\u043A\u0443\u0441\u0441\u0442\u0432\u0435 \u0432\u0442\u043E\u0440\u043E\u0439 \u043F\u043E\u043B\u043E\u0432\u0438\u043D\u044B XVIII \u0432\u0435\u043A\u0430, \u043F\u043E\u0434\u0440\u0430\u0436\u0430\u044E\u0449\u0438\u0439 \u043F\u0440\u043E\u0441\u0442\u043E\u0442\u0435 \u0438 \u0441\u0438\u043C\u043C\u0435\u0442\u0440\u0438\u0438 \u0430\u043D\u0442\u0438\u0447\u043D\u044B\u0445 \u043F\u043E\u0441\u0442\u0440\u043E\u0435\u043A"], 1, ["styl klasycystyczny"], ["\u043A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0441\u0442\u0438\u043B\u044C"]),
  named2("oswiecenie-pl", ["o\u015Bwiecenie w Polsce", "\u041F\u0440\u043E\u0441\u0432\u0435\u0449\u0435\u043D\u0438\u0435 \u0432 \u041F\u043E\u043B\u044C\u0448\u0435"], ["epoka drugiej po\u0142owy XVIII wieku, w kt\xF3rej rozum, nauka i naprawa pa\u0144stwa sta\u0142y si\u0119 has\u0142ami polskich elit", "\u044D\u043F\u043E\u0445\u0430 \u0432\u0442\u043E\u0440\u043E\u0439 \u043F\u043E\u043B\u043E\u0432\u0438\u043D\u044B XVIII \u0432\u0435\u043A\u0430, \u043A\u043E\u0433\u0434\u0430 \u0440\u0430\u0437\u0443\u043C, \u043D\u0430\u0443\u043A\u0430 \u0438 \u0438\u0441\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0433\u043E\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0430 \u0441\u0442\u0430\u043B\u0438 \u043B\u043E\u0437\u0443\u043D\u0433\u0430\u043C\u0438 \u043F\u043E\u043B\u044C\u0441\u043A\u0438\u0445 \u044D\u043B\u0438\u0442"], 1, ["o\u015Bwiecenie", "polskie o\u015Bwiecenie"], ["\u041F\u0440\u043E\u0441\u0432\u0435\u0449\u0435\u043D\u0438\u0435", "\u043F\u043E\u043B\u044C\u0441\u043A\u043E\u0435 \u041F\u0440\u043E\u0441\u0432\u0435\u0449\u0435\u043D\u0438\u0435"])
