    subtopic: "kolejno\u015B\u0107 wykonywania dzia\u0142a\u0144",
    difficulty,
    question: `${t.calc}: $${a} + ${b} \\cdot ${c}$`,
    verifyExpression: `${a} + ${b} * ${c}`,
    hint: t.hint,
